#: любой глубине, включая ту, которую статический свидетель не видит.
#:
#: Она же служит стопором. При выставленной переменной прибор дочерних
#: прогонов не заводит вовсе, и потому рекурсия ограничена ПО ПОСТРОЕНИЮ, а
