#: свидетель этот КОСВЕННЫЙ, и его собственная слепота обязана быть названа,
#: а не подразумеваться. Полноту даёт не он, а отметка :data:`REENTRY_ENV`.
STATIC_WITNESS_DEPTH = 1

#: Имена ступени: вход в любое из них и есть замыкание на себя. Зов одной
#: КООРДИНАТЫ модуля ступенью не является — координата не собирает документ.
STEP_ENTRYPOINTS = ("measure", "run", "main")


def _flatten_doc(value: object, prefix: str = "") -> Dict[str, str]:
    """Документ — в плоскую карту «путь через точку → repr значения».

    ``repr`` намеренно: сравниваются ЗНАЧЕНИЯ, а не тождество объектов, и
    перечень потребителей обязан считаться изменившимся, когда в него
    добавили место. Словари разворачиваются, списки — нет: путь внутрь
    элемента списка назвал бы координатой ИНДЕКС, а индекс не есть имя поля.
    """
    out: Dict[str, str] = {}
    if isinstance(value, dict):
        if not value and prefix:
            out[prefix] = "{}"
            return out
        for key, item in value.items():
            path = f"{prefix}.{key}" if prefix else str(key)
            out.update(_flatten_doc(item, path))
        return out
    out[prefix] = repr(value)
    return out


#: Предел глубины ВТОРОГО правила уплощения (заказ G72 п. 2). Объявлен ДО
#: замера и числом: правило, разворачивающее списки, обязано иметь конец, а
#: путь, упёршийся в этот конец, обязан уходить в ТРЕТИЙ исход — не в «поля
#: нет» и не в «значение такое» (инв. #17).
DEEP_FLATTEN_MAX_DEPTH = 40

#: Чьим свойством оказалась многозначность хвостов — вердикты заказа G72 п. 2.
#: Три, а не два: «списков в документе нет вовсе» есть ОТДЕЛЬНЫЙ исход, и
#: выдавать его за «правило ничего не стоит» значило бы объявить пустоту по
#: построению отсутствием расхождения.
FLATTEN_NO_LISTS = "no_lists_in_doc"
FLATTEN_RULE_DEPENDENT = "property_of_the_flattening_rule"
FLATTEN_DOC_PROPERTY = "property_of_the_document"

#: Индекс элемента списка именем поля не является: `findings[0]` читателю
#: недоступен по имени, а `findings` — доступен.
_INDEX_SUFFIX = re.compile(r"(\[\d+\])+$")

#: Сколько путей многозначного хвоста показывать в документе. Полный перечень
#: у хвоста вроде `file` есть сотни строк; счёт хранится ВСЕГДА, образец —
#: усечение ПОКАЗА, и оно названо своим полем, а не молчанием.
AMBIGUOUS_PATH_SAMPLE = 3


def _name_tail(path: str) -> str:
    """Хвост пути как ИМЯ поля.

    Отличается от `path.rsplit(".", 1)[-1]` ровно одним: снимает индекс
    элемента списка. `findings[0].file` → `file`, `findings[0]` → `findings`.
    На путях правила :func:`_flatten_doc` (индексов там нет по построению)
    обе формы дают одно и то же — поэтому старое правило и не переписано.
    """
    return _INDEX_SUFFIX.sub("", path.rsplit(".", 1)[-1])


def _flatten_doc_deep(value: object, prefix: str = "",
                      depth: int = 0) -> Tuple[Dict[str, str], List[str]]:
    """Документ — в плоскую карту, разворачивая И словари, И СПИСКИ.

    Спутник :func:`_flatten_doc`, а НЕ замена ему (заказ G72 п. 2). Старое
    правило списки не разворачивает намеренно: путь внутрь элемента назвал бы
    координатой индекс. Но у этого выбора есть цена, и до этого заказа её не
    мерил никто: хвосты, живущие ТОЛЬКО внутри элементов списка (`file`,
    `line`, `kind`), в счёт хвостов документа не входили вовсе — а читатель,
    обходящий список, читает именно их.

    Возвращает ПАРУ «карта, перечень упершихся в предел путей». Предел есть
    третий исход, и растворять его в карте запрещено (инв. #17).
    """
    out: Dict[str, str] = {}
    capped: List[str] = []
    if depth > DEEP_FLATTEN_MAX_DEPTH:
        capped.append(prefix)
        return out, capped
    if isinstance(value, dict):
        if not value and prefix:
            return {prefix: "{}"}, capped
        for key, item in value.items():
            path = f"{prefix}.{key}" if prefix else str(key)
            sub, sub_capped = _flatten_doc_deep(item, path, depth + 1)
            out.update(sub)
            capped.extend(sub_capped)
        return out, capped
    if isinstance(value, list):
        if not value and prefix:
            return {prefix: "[]"}, capped
        for index, item in enumerate(value):
            path = f"{prefix}[{index}]" if prefix else f"[{index}]"
            sub, sub_capped = _flatten_doc_deep(item, path, depth + 1)
            out.update(sub)
            capped.extend(sub_capped)
        return out, capped
    out[prefix] = repr(value)
    return out, capped


def _list_census(value: object, depth: int = 0) -> Tuple[int, int]:
    """Сколько в документе списков и сколько в них элементов.

    Нужно ровно для одного: отличить «правило уплощения ничего не стоит» от
    «разворачивать было НЕЧЕГО». Без этого числа ноль расхождения читался бы
    как свойство документа, будучи пустотой по построению.
    """
    if depth > DEEP_FLATTEN_MAX_DEPTH:
        return 0, 0
    lists = elements = 0
    if isinstance(value, dict):
        for item in value.values():
            sub_lists, sub_elements = _list_census(item, depth + 1)
            lists += sub_lists
            elements += sub_elements
    elif isinstance(value, list):
        lists += 1
        elements += len(value)
        for item in value:
            sub_lists, sub_elements = _list_census(item, depth + 1)
            lists += sub_lists
            elements += sub_elements
    return lists, elements



def _import_line(tree: ast.AST, census: str) -> int:
    """Строка, на которой файл ВВОЗИТ перепись; 0 — ввоза не нашлось.

    Нужна не для отбора, а для ВТОРОЙ формы расширения: у синтезированного
    места строки нет, а область (`scope`) читателя разрешается именно по ней.
    Нулевая строка сама есть выбор, и выбор обязан быть проверяемым.
    """
    for node in ast.walk(tree):
        if isinstance(node, ast.ImportFrom) and node.module:
            if node.module.split(".")[-1] == census:
                return node.lineno
            if any(alias.name == census for alias in node.names):
                return node.lineno
        elif isinstance(node, ast.Import):
            if any(alias.name.split(".")[-1] == census for alias in node.names):
                return node.lineno
    return 0


def _widened_population(root: Path, sites: List[dict], *,
                        shape: str) -> List[dict]:
    """Население соседа, расширенное ровно на ИЗМЕРЕННЫЕ невидимые места.

    Расширение — самое дешёвое из возможных: место ввоза отрисовщика
    признаётся зовущим класса ``by_name``. Потребителей оно не выдумывает:
    перечень ``sites`` целиком приходит из :func:`invisible_consumer_scale`.

    ``root_argument`` оставлен ``None`` НАМЕРЕННО: у ввозящего отрисовщик
    аргумента `root` нет вовсе, а подставить сюда строку значило бы сдвинуть
    ещё и согласие о значении `root` — то есть измерить вред от собственной
    подстановки.
    """
    out: List[dict] = []
    trees: Dict[str, Optional[ast.AST]] = {}
    for site in sites:
        rel = site.get("file") or ""
        line = 0
        if shape == SHAPE_AT_IMPORT_LINE:
            if rel not in trees:
                try:
                    trees[rel] = ast.parse(
                        (root / rel).read_text(encoding="utf-8"))
                except (OSError, SyntaxError, UnicodeDecodeError):
                    trees[rel] = None
            tree = trees[rel]
            line = (_import_line(tree, site.get("census") or "")
                    if tree is not None else 0)
        out.append({"file": rel, "line": line,
                    "callee": site.get("census"), "root_argument": None})
    return out


def _parent_map(tree: ast.AST) -> Dict[int, ast.AST]:
    """Обратные ссылки дерева: без них «куда уехало значение» не спросить."""
    parents: Dict[int, ast.AST] = {}
    for node in ast.walk(tree):
        for child in ast.iter_child_nodes(node):
            parents[id(child)] = node
    return parents


def _name_loads(tree: ast.AST) -> Dict[str, List[ast.AST]]:
    """Где имя ЧИТАЕТСЯ. Цель присваивания — тоже узел ``Name``, и считать её
    чтением значило бы сделать ветку «читателя нет» недостижимой."""
    out: Dict[str, List[ast.AST]] = {}
    for node in ast.walk(tree):
        if isinstance(node, ast.Name) and isinstance(node.ctx, ast.Load):
            out.setdefault(node.id, []).append(node)
    return out


def _decision_form(parents: Dict[int, ast.AST], node: ast.AST,
                   loads: Dict[str, List[ast.AST]], depth: int = 0) -> str:
    """Доходит ли значение до РЕШЕНИЯ — или только до печати.

    Решением считается позиция ПРОВЕРКИ: ``assert``, условие ``if``/``while``,
    сравнение, охрана в переборе, аргумент ``self.assert*``. Печатью — ``print``
    и f-строка. Всё остальное есть ТРЕТИЙ исход (:data:`TOUCH_UNRESOLVED`):
    значение уехало дальше, и где оно решает, здесь не разобрано. Объявить
    такое «не решает» и был бы тот fail-OPEN, который перепись ищет у других.

    Одно связывание проходится насквозь: ``files = {s["file"] for s in
    doc["consumers"]["by_name"]}`` с последующим ``assertIn(…, files)`` есть
    ОДНО чтение с решением, и разорвать их значило бы объявить решающий тест
    только печатающим. Глубина ограничена одним шагом НАМЕРЕННО: цепочка
    переприсваиваний уводит от предмета, и её честное имя — третий исход.
    """
    current = node
    while True:
        parent = parents.get(id(current))
        if parent is None:
            return TOUCH_UNRESOLVED
        if isinstance(parent, (ast.Assert, ast.Compare)):
            return TOUCH_DECIDES
        if isinstance(parent, (ast.If, ast.While, ast.IfExp)):
            if parent.test is current:
                return TOUCH_DECIDES
        if isinstance(parent, ast.comprehension):
            # Охрана перебора решает; ИСТОЧНИК перебора — нет, и остановиться
            # на нём значило бы потерять `files = {… for s in doc[…]}` с
            # последующим `assertIn(…, files)`: решение там ниже по связыванию.
            if current in parent.ifs:
                return TOUCH_DECIDES
        if isinstance(parent, ast.Call):
            func = parent.func
            if (isinstance(func, ast.Attribute)
                    and func.attr.startswith("assert")):
                return TOUCH_DECIDES
            if isinstance(func, ast.Name) and func.id == "print":
                return TOUCH_PRINTS
        if isinstance(parent, ast.JoinedStr):
            return TOUCH_PRINTS
        if isinstance(parent, ast.Assign):
            if depth >= 1:
                return TOUCH_UNRESOLVED
            for target in parent.targets:
                if not isinstance(target, ast.Name):
                    continue
                for use in loads.get(target.id, []):
                    got = _decision_form(parents, use, loads, depth + 1)
                    if got != TOUCH_UNRESOLVED:
                        return got
            return TOUCH_UNRESOLVED
        current = parent


def _is_doc_read(node: ast.AST) -> bool:
    """Узел, который ЧИТАЕТ координату документа, — и только он.

    Подстрочник и названные формы зова (``.get(…)``, :data:`_DOC_READERS`).
    Считать чтением ЛЮБОЙ зов значило бы посчитать обёртку вокруг чтения
    вторым чтением: ``print(doc["counts"]["critical"])`` даёт координату
    `critical` и самому `print`, и тогда одно чтение ехало бы в отчёт дважды
    — один раз как печать, другой как «не разобрано».
    """
    if isinstance(node, ast.Subscript):
        return True
    if not isinstance(node, ast.Call):
        return False
    func = node.func
    if isinstance(func, ast.Attribute) and func.attr == "get":
        return True
    return isinstance(func, ast.Name) and func.id in _DOC_READERS


def _neighbour_names(tree: ast.AST, module: str,
                    consts: Dict[str, str]) -> dict:
    """Под какими именами читатель видит соседа — ПЯТЬЮ формами ввоза.

    Четыре статические формы разбираются одним правилом, потому что вопрос у
    них один (тот же порядок, что у :func:`_census_imports`): пакетная форма
    ``from spa_core.monitoring import X`` полного имени в тексте не оставляет
    вовсе, и текстовое правило потеряло бы именно её.

    Пятая форма — ``importlib.import_module(…)``. Спросить только статические
    значило бы повторить ровно ту слепоту, которую мерит эта координата: сам
    производитель достаёт соседа именно так, и его два читателя (те, чьё
    решение и есть предмет заказа) на первом заходе замера были невидимы.

    ``symbols`` — карта «имя у читателя → имя у соседа»: ввоз
    ``import format_report as _ccc_report`` называет отрисовщик ЧУЖИМ именем,
    и сверка по имени читателя объявила бы ввоз отрисовщика отсутствующим.
    """
    tail = module.split(".")[-1]
    out: dict = {"aliases": set(), "dynamic": set()}
    symbols: Dict[str, str] = {}
    for node in ast.walk(tree):
        if isinstance(node, ast.ImportFrom) and node.module:
            if node.module.split(".")[-1] == tail:
                for alias in node.names:
                    symbols[alias.asname or alias.name] = alias.name
            else:
                for alias in node.names:
                    if alias.name == tail:
                        out["aliases"].add(alias.asname or alias.name)
        elif isinstance(node, ast.Import):
            for alias in node.names:
                if alias.name.split(".")[-1] == tail:
                    out["aliases"].add(
                        alias.asname or alias.name.split(".")[-1])
        elif isinstance(node, ast.Call):
            func = node.func
            named = ((isinstance(func, ast.Attribute)
                      and func.attr == "import_module")
                     or (isinstance(func, ast.Name)
                         and func.id == "import_module"))
            if not named or not node.args:
                continue
            got = _literal_key(node.args[0], consts)
            if got is None or got.split(".")[-1] != tail:
                continue
            out["dynamic"].add(got)
    out["symbols"] = symbols
    return out


def _reader_touches(rel: str, tree: ast.AST, module: str, artifact: str,
                    renderers: Tuple[str, ...]) -> dict:
    """Дороги ОДНОГО читателя к населению соседа и форма каждого чтения."""
    consts = _module_string_consts(tree)
    seen = _neighbour_names(tree, module, consts)
    symbols: Dict[str, str] = seen["symbols"]
    parents = _parent_map(tree)
    loads = _name_loads(tree)
    aliases: set = set(seen["aliases"])
    roads: set = set()
    touches: List[dict] = []
    anchors: set = set()

    if seen["dynamic"]:
        roads.add(ROAD_DYNAMIC)
        # Имя, которому присвоен результат `import_module`, есть такое же имя
        # модуля у читателя, как и ввезённое `import`: не связать их значило бы
        # найти дорогу и потерять все чтения по ней.
        for node in ast.walk(tree):
            if not isinstance(node, ast.Call):
                continue
            func = node.func
            named = ((isinstance(func, ast.Attribute)
                      and func.attr == "import_module")
                     or (isinstance(func, ast.Name)
                         and func.id == "import_module"))
            if not named or not node.args:
                continue
            if _literal_key(node.args[0], consts) not in seen["dynamic"]:
                continue
            parent = parents.get(id(node))
            if isinstance(parent, ast.Assign):
                for target in parent.targets:
                    if isinstance(target, ast.Name):
                        aliases.add(target.id)

    for node in ast.walk(tree):
        if not isinstance(node, ast.Call):
            continue
        func = node.func
        called: Optional[str] = None
        if (isinstance(func, ast.Attribute) and isinstance(func.value, ast.Name)
                and func.value.id in aliases):
            called = func.attr
        elif isinstance(func, ast.Name) and func.id in symbols:
            # Имя У СОСЕДА, а не у читателя: ввоз `as` переименовывает, и
            # сверка по имени читателя потеряла бы и искатель, и отрисовщик.
            called = symbols[func.id]
        if called is None:
            continue
        if called in ("run", "measure"):
            roads.add(ROAD_RUN)
            parent = parents.get(id(node))
            if isinstance(parent, ast.Assign):
                for target in parent.targets:
                    if isinstance(target, ast.Name):
                        anchors.add(target.id)
        elif called in POPULATION_FINDERS:
            roads.add(ROAD_FINDER)
            touches.append({"road": ROAD_FINDER, "line": node.lineno,
                            "field": _FINDER_FIELD[called],
                            "field_path": _FINDER_FIELD_PATH[called],
                            "field_path_outcome": PATH_DECLARED,
                            "form": _decision_form(parents, node, loads)})
        elif called in renderers:
            # Ввоз отрисовщика есть дорога сам по себе: зова `run` у такого
            # читателя нет ПО ПОСТРОЕНИЮ, и именно этим он невидим соседу.
            roads.add(ROAD_RENDERER)
            touches.append({"road": ROAD_RENDERER, "line": node.lineno,
                            "field": None, "field_path": None,
                            "field_path_outcome": PATH_NOT_A_READ,
                            "form": TOUCH_PRINTS})
    if set(symbols.values()) & set(renderers):
        roads.add(ROAD_RENDERER)
    if artifact:
        for node in ast.walk(tree):
            if (isinstance(node, ast.Constant) and isinstance(node.value, str)
                    and node.value == artifact):
                roads.add(ROAD_ARTIFACT)
                break

    if anchors:
        binding = {name: None for name in anchors}
        for node in ast.walk(tree):
            if not _is_doc_read(node):
                continue
            # Внутреннее звено цепи `doc["counts"]["critical"]` отдельным
            # чтением НЕ является: координата значения — ПОСЛЕДНИЙ применённый
            # ключ, и считать `counts` вторым чтением значило бы приписать
            # читателю контейнер вместе с каждым его элементом.
            outer = parents.get(id(node))
            if isinstance(outer, ast.Subscript) and outer.value is node:
                continue
            if not _derives_from_census(node, anchors,
                                        producer_aliases=frozenset(aliases)):
                continue
            field = _terminal_coordinate(node, consts, binding)
            if field is None:
                continue
            # Хвост и путь берутся у ОДНОГО И ТОГО ЖЕ узла и расходятся только
            # правилом разбора: иначе разница между ними была бы разницей
            # населений, а не разницей правил (заказ G71 п. 2).
            path, path_outcome = _coordinate_path(
                node, consts, anchors, makers=frozenset(aliases))
            touches.append({"road": ROAD_RUN,
                            "line": getattr(node, "lineno", 0),
                            "field": field,
                            "field_path": path,
                            "field_path_outcome": path_outcome,
                            "form": _decision_form(parents, node, loads)})
    return {"file": rel, "channel": _channel_of(rel),
            "roads": sorted(roads), "touches": touches}


def _decision_projection(doc: dict) -> dict:
    """Что СЧИТАЕТСЯ решением читателя при сверке двух прогонов.

    Проекция, а не весь документ: сверять документ целиком значило бы
    объявлять решение изменившимся всякий раз, когда в отчёте сдвинулось
    число мест. Решение читателя — его вердикт, счётчики вердикта и РОДА его
    находок.
    """
    # Инв. #17: «счётчиков нет» и «счётчики нулевые» — разные утверждения, и
    # второе вместо первого приравняло бы ДВА РАЗНЫХ решения. Форма
    # `doc.get("counts") or {}` именно это и делала: документ без счётчиков
    # становился неотличим от документа с пустыми, а сверка — зелёной.
    counts = observed(doc, "counts", kind=dict)
    findings = observed(doc, "findings", kind=list)
    unseen = observed(doc, "declared_unseen", kind=list)
    return {
        "status": doc.get("status"),
        "counts_observed": counts is not None,
        "findings_observed": findings is not None,
        "unseen_observed": unseen is not None,
        "seen_by_neighbour": (None if counts is None
                              else counts.get("seen_by_neighbour")),
        "declared_unseen_by_neighbour": (
            None if counts is None
            else counts.get("declared_unseen_by_neighbour")),
        "finding_kinds": (None if findings is None else
                          sorted(str(item.get("kind")) for item in findings
                                 if isinstance(item, dict))),
        "unseen_reasons": (None if unseen is None else sorted(
            f"{item.get('key')}:{item.get('reason')}" for item in unseen
            if isinstance(item, dict))),
    }


def _scale_projection(doc: dict) -> dict:
    """Что считается решением читателя :func:`invisible_consumer_scale`.

    Отдельная проекция, а не общая с :func:`_decision_projection`: документы
    у двух читателей разной формы, и общая проекция вернула бы у этого
    сплошной ``None`` — то есть объявила бы «решение не изменилось» из
    ПУСТОТЫ. Пустая проекция ловится :func:`_projection_is_vacuous` и уходит
    в ТРЕТИЙ исход.

    Инв. #17 здесь тот же, что у соседней проекции: «счётчиков нет» и
    «счётчики нулевые» — разные утверждения, и признак наблюдённости стои́т
    рядом со значением, а не вместо него.
    """
    counts = observed(doc, "counts", kind=dict)
    findings = observed(doc, "findings", kind=list)
    understated = observed(doc, "understated", kind=list)
    blanked = observed(doc, "blanked_to_zero", kind=list)
    return {
        "status": doc.get("status") if isinstance(doc, dict) else None,
        "counts_observed": counts is not None,
        "findings_observed": findings is not None,
        "understated_observed": understated is not None,
        "blanked_observed": blanked is not None,
        "understated_count": (None if counts is None
                              else counts.get("understated")),
        "understated_upper_bound": (None if counts is None
                                    else counts.get("understated_upper_bound")),
        "blanked_to_zero_count": (None if counts is None
                                  else counts.get("blanked_to_zero")),
        "finding_kinds": (None if findings is None else
                          sorted(str(item.get("kind")) for item in findings
                                 if isinstance(item, dict))),
        "understated": None if understated is None else sorted(
            str(name) for name in understated),
        "blanked_to_zero": None if blanked is None else sorted(
            str(name) for name in blanked),
    }


#: Проекции решения по ИМЕНИ, объявленному в :data:`_EXECUTABLE_READERS`.
_PROJECTORS = {"registry": _decision_projection, "scale": _scale_projection}


def _projection_is_vacuous(projection: dict) -> bool:
    """Сравнивать было НЕЧЕГО: в проекции не наблюдено ни одного поля.

    Без этой проверки два пустых документа дают равные проекции, и прибор
    объявил бы «решение не изменилось» — вердикт из пустоты, ровно тот
    вырожденный сторож, которого перепись ищет у других. Наблюдённость
    читается по признакам ``*_observed``; их отсутствие в проекции — тоже
    вырожденность, а не «признаков не требуется».
    """
    flags = [value for key, value in projection.items()
             if key.endswith("_observed")]
    if not flags:
        return True
    return not any(flags) and projection.get("status") is None


def _tact_seconds(root: Path) -> Tuple[Optional[float], str, Optional[str]]:
    """Такт ступени в СЕКУНДАХ — прочитанный у объявителя, а не вписанный сюда.

    Бюджет пересчёта есть период агента, который производит артефакт этой
    переписи. Перепечатать «6 ч» числом значило бы завести вторую копию
    правила — ровно то, что перепись ищет у других, и ровно то, чем прежде
    была цена ``35 с``.

    Возвращает ``(секунды, источник, причина отказа)``. Такт не прочитан ⇒
    секунды ``None`` и причина НАЗВАНА: «не измерено» никогда не выдаётся за
    «уложились».
    """
    path = root / BUDGET_MANIFEST
    try:
        manifest = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, ValueError) as exc:
        return None, BUDGET_MANIFEST, f"{BUDGET_MANIFEST} не прочитан ({exc})"
    agents = manifest.get("agents") if isinstance(manifest, dict) else None
    if not isinstance(agents, list):
        return None, BUDGET_MANIFEST, f"в {BUDGET_MANIFEST} нет списка агентов"
    for agent in agents:
        if not isinstance(agent, dict):
            continue
        produces = agent.get("produces")
        if not isinstance(produces, list):
            continue
        names = {item.get("artifact") for item in produces
                 if isinstance(item, dict)}
        if BUDGET_ARTIFACT not in names:
            continue
        label = str(agent.get("label"))
        schedule = agent.get("schedule")
        if not isinstance(schedule, str) or not schedule.startswith("interval:"):
            return None, label, (
                f"у производителя {label} расписание `{schedule}` — не "
                f"интервал, и такта из него не взять")
        digits = schedule[len("interval:"):].rstrip("s")
        try:
            seconds = float(digits)
        except ValueError:
            return None, label, (
                f"интервал `{schedule}` у {label} не разбирается в число")
        if seconds <= 0:
            return None, label, (
                f"интервал `{schedule}` у {label} не положителен")
        return seconds, f"{label} · {schedule}", None
    return None, BUDGET_MANIFEST, (
        f"в {BUDGET_MANIFEST} нет агента, производящего {BUDGET_ARTIFACT} — "
        f"такта у ступени не объявлено")


def recompute_cost_budget(root: Path, harm: Optional[dict]) -> dict:
    """Цена пересчёта — ИЗМЕРЕННАЯ, и укладывается ли она в такт (**заказ G69 п. 1**).

    ADR-446 оставил остаток «прогон не оплачен» и назвал ему цену **35 с**.
    Заказ ставит вопрос дословно:

    > Исход ``not_executed`` объявлен ценой 35 с, и число это взято ЗАМЕРОМ
    > ОДНОГО прогона на одном дереве, а не свойством читателя. Спросить
    > числом: сколько стои́т пересчёт КАЖДОГО из читателей, и укладывается ли
    > полный пересчёт в такт ступени. Если укладывается, «не оплачено»
    > перестаёт быть остатком и становится отказом от замера, который был по
    > карману.

    Отвечается тремя величинами, и ни одна не объявляется здесь литералом:

    1. **Цена** — секунды, ИЗМЕРЕННЫЕ часами вокруг настоящего пересчёта
       (:func:`neighbour_population_harm` кладёт их в ``cost_s_measured``).
       Прежнее объявленное число сохранено рядом как ПРЕТЕНЗИЯ
       (``cost_s_declared``) и сверяется с замером: литерал, который никто не
       сверял, и был предметом заказа.
    2. **Бюджет** — такт агента-производителя, прочитанный из манифеста
       (:func:`_tact_seconds`). Своя копия такта была бы второй копией
       правила.
    3. **Запас** — отношение бюджета к цене. Он объявлен ДО замера
       (:data:`REQUIRED_COST_MARGIN`, запрет G62), потому что цена сама
       измерена на одной машине: ответ имеет право не зависеть от её
       точности, и запас говорит, во сколько раз.

    **Цена — МАРЖИНАЛЬНАЯ, и это сказано вслух.** Чистый прогон читателя
    ступень считает для себя и так; прибор оплачивает только расширенный.
    Именно маржинальное число и есть ответ на вопрос «было ли по карману».

    ADVISORY: порог не вводится, ни один вердикт переписи этой координатой не
    меняется (``applied`` ложно).
    """
    head = {
        "question": ("сколько стои́т пересчёт решения каждого читателя и "
                     "укладывается ли полный пересчёт в такт ступени"),
        "order": "G69.1",
        "required_margin_declared": REQUIRED_COST_MARGIN,
        "claim_tolerance_declared": COST_CLAIM_TOLERANCE,
        "applied": False,
    }
    executed = observed(harm, "executed", kind=list) if harm else None
    if executed is None:
        return {**head, "status": "UNMEASURED", "verdict": BUDGET_UNMEASURED,
                "reason": ("вред занижения не измерен — пересчёта, цену "
                           "которого мерить, не было; это НЕ «уложились»")}
    budget_s, budget_source, budget_refused = _tact_seconds(root)

    costs: List[dict] = []
    for entry in executed:
        if not isinstance(entry, dict):
            continue
        measured = observed(entry, "cost_s_measured", kind=(int, float))
        declared = observed(entry, "cost_s_declared", kind=(int, float))
        runs = observed(entry, "runs_timed", kind=int)
        # Объявленная цена (ADR-446) была ценой ОДНОГО прогона, а измеряется
        # здесь весь пересчёт — один прогон или два. Сверять их напрямую
        # значило бы сравнить числа с разными знаменателями и назвать разницу
        # ошибкой претензии; поэтому претензия сверяется с ценой ПРОГОНА.
        per_run = (None if measured is None or not runs
                   else round(float(measured) / runs, 2))
        row = {
            "key": entry.get("key"),
            "outcome": entry.get("outcome"),
            "cost_s_declared": declared,
            "cost_s_measured": (None if measured is None
                                else round(float(measured), 2)),
            "cost_s_per_run": per_run,
            "cost_basis": entry.get("cost_basis"),
            "runs_timed": runs,
        }
        if measured is None:
            row["claim"] = "unmeasured"
            row["claim_reason"] = (
                "прогон не состоялся — цену мерить нечем; это НЕ нулевая цена")
        elif per_run is None:
            row["claim"] = "unmeasured"
            row["claim_reason"] = (
                "число прогонов не записано — цену прогона не вывести, а "
                "сверять полную цену с ценой одного было бы сравнением "
                "разных знаменателей")
        elif declared is None:
            row["claim"] = "undeclared"
            row["claim_reason"] = (
                "объявленной цены у читателя нет — сверять замер не с чем")
        else:
            error = abs(per_run - float(declared))
            row["claim_error_s"] = round(error, 2)
            row["claim_error_ratio"] = (
                None if not per_run else round(error / per_run, 3))
            row["claim"] = (
                "confirmed" if row["claim_error_ratio"] is not None
                and row["claim_error_ratio"] <= COST_CLAIM_TOLERANCE
                else "refuted")
        costs.append(row)

    priced = [row for row in costs if row["cost_s_measured"] is not None]
    unpriced = [row for row in costs if row["cost_s_measured"] is None]
    total_cost_s = round(sum(row["cost_s_measured"] for row in priced), 2)

    if budget_s is None:
        verdict, margin = BUDGET_UNMEASURED, None
    elif not priced:
        verdict, margin = BUDGET_UNMEASURED, None
        budget_refused = ("ни у одного читателя цена не измерена — делить "
                          "бюджет не на что")
    elif total_cost_s <= 0:
        # Нулевая цена не бывает ответом: часы такого не мерят, а «уложились»
        # из нуля есть вердикт из пустоты.
        verdict, margin = BUDGET_UNMEASURED, None
        budget_refused = ("измеренная цена не положительна — часы дали "
                          f"{total_cost_s} с, и запаса из этого не построить")
    else:
        margin = round(budget_s / total_cost_s, 1)
        if margin >= REQUIRED_COST_MARGIN:
            verdict = BUDGET_FITS
        elif total_cost_s > budget_s:
            verdict = BUDGET_DOES_NOT_FIT
        else:
            verdict = BUDGET_TOO_CLOSE

    findings: List[dict] = []
    remainder = [row for row in costs
                 if row["outcome"] == DECISION_NOT_EXECUTED]
    if remainder and verdict == BUDGET_FITS:
        findings.append({
            "kind": "unpaid_recompute_was_affordable",
            "file": PRODUCER, "channel": CHANNEL_CODE,
            "fields": sorted(str(row["key"]) for row in remainder),
            "why": ("прогон объявлен неоплаченным по цене, а полный пересчёт "
                    f"стои́т {total_cost_s} с при такте {budget_s} с (запас "
                    f"{margin}×): «не оплачено» здесь есть ОТКАЗ ОТ ЗАМЕРА, "
                    "который был по карману, а не остаток")})
    for row in costs:
        if row.get("claim") == "refuted":
            findings.append({
                "kind": "declared_cost_refuted_by_measurement",
                "file": PRODUCER, "channel": CHANNEL_CODE,
                "fields": [str(row["key"])],
                "why": (f"объявленная цена {row['cost_s_declared']} с "
                        f"разошлась с измеренной ценой прогона "
                        f"{row['cost_s_per_run']} с "
                        f"на {row['claim_error_ratio']} доли — литерал "
                        "свойством читателя не является")})

    counts = {
        "readers": len(costs),
        "priced": len(priced),
        "unpriced": len(unpriced),
        "claims_confirmed": len([r for r in costs if r.get("claim") == "confirmed"]),
        "claims_refuted": len([r for r in costs if r.get("claim") == "refuted"]),
        "claims_unmeasured": len([r for r in costs
                                  if r.get("claim") == "unmeasured"]),
        "remainder": len(remainder),
    }

    return {
        **head,
        "status": ("UNMEASURED" if verdict == BUDGET_UNMEASURED
                   else ("CRITICAL" if verdict == BUDGET_DOES_NOT_FIT
                         else "MEASURED")),
        "verdict": verdict,
        "budget_s": budget_s,
        "budget_source": budget_source,
        "budget_refused": budget_refused,
        "total_cost_s": total_cost_s if priced else None,
        "margin": margin,
        "costs": costs,
        "counts": counts,
        "findings": findings,
        "blind": [
            "цена МАРЖИНАЛЬНАЯ: чистый прогон читателя ступень считает для "
            "себя и так, прибор оплачивает только расширенный — и именно это "
            "число отвечает на вопрос «было ли по карману», а не цена двух "
            "прогонов с нуля",
            "часы меряют ЭТУ машину и ЭТО дерево; ответ имеет право не "
            f"зависеть от их точности, и запас {margin}× говорит, во сколько "
            f"раз замер обязан ошибиться, чтобы вердикт сменился (порог "
            f"{REQUIRED_COST_MARGIN}× объявлен ДО замера)",
            "читатели канала ТЕСТА этой координатой НЕ оценены — их цену "
            "и их замыкание на ступень меряет СОСЕДНЯЯ координата "
            "`reader_cost_of_test_channel` (заказ G70 п. 1): прежде здесь стоял "
            "отказ с ПРИЧИНОЙ («вложенный прогон»), и причина эта ни разу не "
            "была померена",
            "такт прочитан у производителя артефакта; смена расписания агента "
            "меняет бюджет САМА, и второй копии числа у прибора нет",
        ],
    }


def _reentry_note(where: str) -> None:
    """Отметить вход в ступень, если прибор пометил этот процесс.

    Пишется ОДНОЙ строкой в файл, названный :data:`REENTRY_ENV`, и только
    когда переменная выставлена: в обычном прогоне ступени побочного действия
    нет вовсе. Отметка ставится ПЕРВЫМ делом — до любой работы и до любого
    отказа, — потому что вопрос «замкнулся ли прогон на ступень» не зависит
    от того, довела ли ступень работу до конца.

    Отказ записи проглатывается НАМЕРЕННО и это не молчание о наблюдении:
    файл отметок держит ПРИБОР, и его недоступность прибор видит сам —
    ноль строк при заведённом прогоне он объявляет третьим исходом
    (:data:`RECURSION_UNMEASURED`), а не «замыкания нет». Уронить же ступень
    из-за собственного журнала прибора значило бы поменять предмет замера.
    """
    path = os.environ.get(REENTRY_ENV)
    if not path:
        return
    try:
        with open(path, "a", encoding="utf-8") as handle:
            handle.write(f"{where}\t{os.getpid()}\n")
    except OSError:
        return


def _pytest_available() -> Tuple[Optional[bool], str]:
    """Есть ли инструмент — ОТДЕЛЬНЫЙ вопрос, и задаётся он отдельно.

    Код возврата рабочего прогона на него не отвечает: pytest выходит
    ненулевым, когда нашёл падение, и ноль падений от «инструмента нет»
    этим кодом не отличается. Поэтому спрашивается ``--version``.
    """
    try:
        proc = subprocess.run([sys.executable, "-m", "pytest", "--version"],
                              capture_output=True, text=True, timeout=120)
    except (OSError, subprocess.SubprocessError) as exc:
        return None, f"инструмент не опрошен ({exc})"
    if proc.returncode != 0:
        return False, (f"`{sys.executable} -m pytest --version` вышел "
                       f"{proc.returncode}")
    spoken = ((proc.stdout or "") + (proc.stderr or "")).strip().splitlines()
    return True, (spoken[0] if spoken else "pytest отвечает без версии")


def _static_reaches_step(root: Path, rel: str,
                         depth: int = STATIC_WITNESS_DEPTH) -> dict:
    """КОСВЕННЫЙ свидетель замыкания: зовёт ли файл ступень этой переписи.

    Свидетель читает текст, и полноты у него нет ПО ПОСТРОЕНИЮ: он видит
    прямой ввоз файла плюс :data:`STATIC_WITNESS_DEPTH` уровень ввезённых им
    модулей дерева, а замыкание через ``importlib`` или через третий модуль
    не видит вовсе — ровно та слепота, которую ADR-446 нашёл у самого себя.
    Полноту даёт не он, а отметка :data:`REENTRY_ENV`; здесь он нужен
    вторым голосом, и его НЕСОГЛАСИЕ с наблюдением само есть находка.

    Возвращает словарь с ``reaches`` (``True``/``False``/``None``),
    ``why`` и перечнем разобранных модулей.
    """
    seen: set[str] = set()
    examined: List[str] = []
    unreadable: List[str] = []

    def _module_path(module: str) -> Optional[Path]:
        candidate = root / (module.replace(".", "/") + ".py")
        return candidate if candidate.is_file() else None

    def _walk(path: Path, label: str, level: int) -> Optional[bool]:
        if label in seen:
            return False
        seen.add(label)
        try:
            tree = ast.parse(path.read_text(encoding="utf-8"))
        except (OSError, SyntaxError, UnicodeDecodeError) as exc:
            unreadable.append(f"{label}: {exc}")
            return None
        examined.append(label)
        aliases: set[str] = set()
        imported_modules: List[str] = []
        for node in ast.walk(tree):
            if isinstance(node, ast.Import):
                for alias in node.names:
                    if alias.name == CENSUS_MODULE:
                        aliases.add(alias.asname or alias.name.split(".")[0])
                    elif alias.name.startswith(("spa_core.", "scripts.")):
                        imported_modules.append(alias.name)
            elif isinstance(node, ast.ImportFrom) and node.module:
                if node.module == CENSUS_MODULE:
                    for alias in node.names:
                        if alias.name in STEP_ENTRYPOINTS:
                            return True
                    continue
                for alias in node.names:
                    full = f"{node.module}.{alias.name}"
                    if full == CENSUS_MODULE:
                        aliases.add(alias.asname or alias.name)
                    elif node.module.startswith(("spa_core", "scripts")):
                        imported_modules.append(full)
        for node in ast.walk(tree):
            if not isinstance(node, ast.Attribute):
                continue
            if node.attr not in STEP_ENTRYPOINTS:
                continue
            base = node.value
            if isinstance(base, ast.Name) and base.id in aliases:
                return True
        if level >= depth:
            return False
        partial_unknown = False
        for module in imported_modules:
            target = _module_path(module)
            if target is None:
                continue
            answer = _walk(target, module, level + 1)
            if answer is True:
                return True
            if answer is None:
                partial_unknown = True
        return None if partial_unknown else False

    path = root / rel
    if not path.is_file():
        return {"reaches": None, "examined": [], "unreadable": [],
                "why": f"файла {rel} нет в дереве — свидетеля не опросить"}
    verdict = _walk(path, rel, 0)
    if verdict is None:
        why = ("разобрать не вышло: " + "; ".join(unreadable[:3])
               or "разбор не завершён")
    elif verdict:
        why = (f"файл зовёт ступень переписи ({', '.join(STEP_ENTRYPOINTS)}) "
               f"в пределах глубины {depth}")
    else:
        why = (f"в пределах глубины {depth} ни одного зова ступени "
               f"({', '.join(STEP_ENTRYPOINTS)}) не найдено; "
               f"разобрано модулей {len(examined)}")
    return {"reaches": verdict, "examined": examined,
            "unreadable": unreadable, "why": why}


def _run_test_file(root: Path, rel: str, *,
                   timeout: float = CHILD_RUN_TIMEOUT_S) -> dict:
    """Цена прогона ОДНОГО файла канала теста — часами вокруг прогона.

    Отказ от вложенности стои́т ЗДЕСЬ и назван исходом: если ступень позвана
    изнутри pytest (или изнутри уже помеченного дочернего прогона), второй
    прогон был бы вложенным, и прибор его не заводит. Это ровно тот случай,
    о котором говорила причина отказа ADR-447, — и теперь он ИЗМЕРЕН
    (``refused_nested`` с названной причиной), а не предположен.

    Дочерний прогон уводится с живого состояния НАМЕРЕННО: свой каталог
    данных (``SPA_DATA_DIR``), закреплённый ``--rootdir`` и выключенный
    перемешиватель. Прогон, писавший бы в живой ``data/``, отвечал бы на
    вопрос о цене ценой порчи состояния.
    """
    entry = {"file": rel, "cost_s": None, "exit_code": None,
             "reentries": None, "recursion": RECURSION_UNMEASURED}
    if os.environ.get(REENTRY_ENV):
        return {**entry, "outcome": CHILD_REFUSED_NESTED,
                "why": ("прибор уже работает внутри помеченного дочернего "
                        "прогона — второго уровня вложенности он не заводит "
                        "ПО ПОСТРОЕНИЮ")}
    if os.environ.get("PYTEST_CURRENT_TEST"):
        return {**entry, "outcome": CHILD_REFUSED_NESTED,
                "why": ("ступень позвана ИЗНУТРИ pytest — дочерний прогон был "
                        "бы вложенным; причина отказа ADR-447 верна для этого "
                        "зова и измерена, а не предположена")}
    target = root / rel
    if not target.is_file():
        return {**entry, "outcome": CHILD_UNMEASURED,
                "why": f"файла {rel} нет в дереве — мерить нечего"}
    available, tool_why = _pytest_available()
    if available is not True:
        return {**entry, "outcome": CHILD_UNMEASURED,
                "why": f"инструмента нет или он не опрошен: {tool_why}"}

    with tempfile.TemporaryDirectory(prefix="spa-census-child-") as tmp:
        ledger = Path(tmp) / "reentry.log"
        ledger.write_text("", encoding="utf-8")
        env = dict(os.environ)
        env.update({
            REENTRY_ENV: str(ledger),
            "SPA_ENV": "ci",
            "PYTHONHASHSEED": "0",
            "SPA_DATA_DIR": str(Path(tmp) / "data"),
        })
        (Path(tmp) / "data").mkdir(parents=True, exist_ok=True)
        argv = [sys.executable, "-m", "pytest", rel, "-q", "--tb=no",
                "-p", "no:randomly", f"--rootdir={root}"]
        started = time.monotonic()
        try:
            proc = subprocess.run(argv, cwd=str(root), env=env,
                                  capture_output=True, text=True,
                                  timeout=timeout)
        except subprocess.TimeoutExpired:
            return {**entry, "outcome": CHILD_UNMEASURED,
                    "why": (f"дочерний прогон не уложился в {timeout} с — "
                            "цена НЕ измерена, и это не «дорого»")}
        except (OSError, subprocess.SubprocessError) as exc:
            return {**entry, "outcome": CHILD_UNMEASURED,
                    "why": f"дочерний прогон не состоялся ({exc})"}
        cost = round(time.monotonic() - started, 2)
        try:
            marks = [line for line in
                     ledger.read_text(encoding="utf-8").splitlines() if line]
            reentries: Optional[int] = len(marks)
        except OSError as exc:
            marks, reentries = [], None
            entry["reentry_unreadable"] = str(exc)

    if cost <= 0:
        return {**entry, "exit_code": proc.returncode,
                "outcome": CHILD_UNMEASURED,
                "why": (f"часы дали {cost} с — не положительная цена ценой "
                        "не является")}
    if reentries is None:
        recursion = RECURSION_UNMEASURED
    else:
        recursion = (RECURSION_OBSERVED if reentries
                     else RECURSION_NOT_OBSERVED)
    # `**entry` ПЕРВЫМ, а не вместо явных ключей: в нём лежит причина, по
    # которой журнал отметок не прочитался (`reentry_unreadable`), и до цикла
    # #669 она записывалась в словарь, который никто не возвращал. Третий
    # исход обязан быть записан ТАМ, ГДЕ РЕШЕН: `recursion=unmeasured` без
    # причины неотличим от «прибор так решил», а с причиной — измерение.
    unreadable = entry.get("reentry_unreadable")
    return {**entry, "file": rel, "cost_s": cost,
            "exit_code": proc.returncode,
            "reentries": reentries, "recursion": recursion,
            "outcome": (CHILD_RAN_GREEN if proc.returncode == 0
                        else CHILD_RAN_RED),
            "why": (f"прогон завершился кодом {proc.returncode} за {cost} с; "
                    + (f"журнал отметок НЕ ПРОЧИТАН ({unreadable}) — "
                       "замыкание не измерено, и это не «не наблюдено»"
                       if unreadable
                       else f"отметок входа в ступень {reentries}"))}


def reader_cost_of_test_channel(root: Path, harm: Optional[dict],
                             budget: Optional[dict], *,
                             run_file=None) -> dict:
    """Цена читателей канала ТЕСТА и их замыкание на ступень (**заказ G70 п. 1**).

    ADR-447 объявил цену этих читателей неизмеримой ПО ПРИЧИНЕ: «прогон
    pytest изнутри ступени породил бы вложенный прогон». Заказ ставит вопрос
    дословно:

    > Это утверждение о МЕХАНИЗМЕ, и у него нет ни одного замера: ни один из
    > двух файлов не зовёт ``measure()`` этой переписи, то есть рекурсии может
    > не быть вовсе. Спросить числом: сколько стои́т прогон каждого из двух
    > файлов, замкнётся ли он на собственную ступень (замер, а не догадка) и
    > укладывается ли сумма в тот же такт. Отказ, чья причина не померена,
    > ничем не лучше цены, которую никто не делил на бюджет.

    Отвечается тремя величинами, и ни одна не объявлена здесь литералом:

    1. **Население** — не список в коде, а ВЫВОД соседней координаты: файлы,
       у которых :func:`neighbour_population_harm` нашёл решение по
       сдвинувшемуся полю И чей канал — тест. Перечень именами был бы второй
       копией правила о населении, ровно тем классом, который перепись ищет
       у других.
    2. **Цена** — секунды, измеренные часами вокруг НАСТОЯЩЕГО прогона
       каждого файла (:func:`_run_test_file`).
    3. **Замыкание** — ДВА свидетеля, и ни один не есть поправка к другому:
       наблюдение (отметка :data:`REENTRY_ENV`, ловит любую глубину) и разбор
       текста (:func:`_static_reaches_step`, глубина объявлена). Их
       НЕСОГЛАСИЕ само объявляется находкой.

    Сумма делится на ТОТ ЖЕ такт (:func:`_tact_seconds`) и на тот же
    объявленный ДО замера запас (:data:`REQUIRED_COST_MARGIN`) — своей копии
    ни у такта, ни у порога здесь нет.

    ADVISORY: порог не вводится, ни один вердикт переписи этой координатой не
    меняется (``applied`` ложно).
    """
    runner = run_file or _run_test_file
    head = {
        "question": ("сколько стои́т прогон читателя канала ТЕСТА, замыкается "
                     "ли он на собственную ступень и укладывается ли сумма в "
                     "такт ступени"),
        "order": "G70.1",
        "required_margin_declared": REQUIRED_COST_MARGIN,
        "static_witness_depth": STATIC_WITNESS_DEPTH,
        "applied": False,
    }
    readers = observed(harm, "readers", kind=list) if harm else None
    if readers is None:
        return {**head, "status": "UNMEASURED", "verdict": BUDGET_UNMEASURED,
                "reason": ("вред занижения не измерен — населения канала "
                           "теста здесь не из чего вывести; это НЕ «читателей "
                           "нет»")}

    population = []
    for item in readers:
        if not isinstance(item, dict):
            continue
        rel = item.get("file")
        if not isinstance(rel, str) or not item.get("decides_on_moved"):
            continue
        if _channel_of(rel) != CHANNEL_TEST:
            continue
        population.append(rel)
    population = sorted(set(population))

    budget_s, budget_source, budget_refused = _tact_seconds(root)
    rows: List[dict] = []
    for rel in population:
        row = dict(runner(root, rel))
        row["static"] = _static_reaches_step(root, rel)
        static_reaches = row["static"].get("reaches")
        observed_reaches = {RECURSION_OBSERVED: True,
                            RECURSION_NOT_OBSERVED: False}.get(
                                row.get("recursion"))
        if static_reaches is None or observed_reaches is None:
            row["witnesses"] = "incomplete"
        elif static_reaches == observed_reaches:
            row["witnesses"] = "agree"
        else:
            row["witnesses"] = "disagree"
        rows.append(row)

    priced = [r for r in rows if isinstance(r.get("cost_s"), (int, float))]
    unpriced = [r for r in rows if r not in priced]
    total_cost_s = round(sum(r["cost_s"] for r in priced), 2) if priced else None

    # Сумма, которую ступень платит В ОДИН ТАКТ: этот канал ПЛЮС уже
    # измеренный пересчёт читателей-кода (ADR-447). Отдельное число было бы
    # ответом не на тот вопрос: такт у них общий.
    prior_cost = observed(budget, "total_cost_s", kind=(int, float)) if budget \
        else None
    if total_cost_s is None or prior_cost is None:
        combined_cost_s = None
    else:
        combined_cost_s = round(total_cost_s + prior_cost, 2)

    refused = [r for r in rows if r.get("outcome") == CHILD_REFUSED_NESTED]
    if budget_s is None:
        verdict, margin = BUDGET_UNMEASURED, None
    elif not population:
        verdict, margin = BUDGET_UNMEASURED, None
        budget_refused = ("читателей канала ТЕСТА, решающих по сдвинувшемуся "
                          "полю, сосед не назвал ни одного — делить нечего")
    elif combined_cost_s is None:
        verdict, margin = BUDGET_UNMEASURED, None
        budget_refused = budget_refused or (
            "цена канала или цена пересчёта не измерена — суммы, которую "
            "делить на такт, не существует"
            + (f"; прогонов не заводилось: {len(refused)}" if refused else ""))
    elif combined_cost_s <= 0:
        verdict, margin = BUDGET_UNMEASURED, None
        budget_refused = (f"измеренная сумма не положительна ({combined_cost_s} "
                          "с) — запаса из неё не построить")
    else:
        margin = round(budget_s / combined_cost_s, 1)
        if margin >= REQUIRED_COST_MARGIN:
            verdict = BUDGET_FITS
        elif combined_cost_s > budget_s:
            verdict = BUDGET_DOES_NOT_FIT
        else:
            verdict = BUDGET_TOO_CLOSE

    recursion_observed = [r for r in rows
                          if r.get("recursion") == RECURSION_OBSERVED]
    recursion_absent = [r for r in rows
                        if r.get("recursion") == RECURSION_NOT_OBSERVED]
    findings: List[dict] = []
    if (verdict == BUDGET_FITS and recursion_absent and not recursion_observed
            and len(recursion_absent) == len(rows)):
        findings.append({
            "kind": "refusal_reason_refuted_by_measurement",
            "file": PRODUCER, "channel": CHANNEL_CODE,
            "fields": sorted(r["file"] for r in recursion_absent),
            "why": ("цена объявлена неизмеримой ПО ПРИЧИНЕ «вложенный "
                    f"прогон»; замер: замыкания на ступень не наблюдено ни у "
                    f"одного из {len(rows)} файлов, а сумма с пересчётом "
                    f"стои́т {combined_cost_s} с при такте {budget_s} с "
                    f"(запас {margin}×) — причина отказа не подтвердилась, "
                    "и отказ был по карману")})
    for row in rows:
        if row.get("witnesses") == "disagree":
            findings.append({
                "kind": "recursion_witnesses_disagree",
                "file": PRODUCER, "channel": CHANNEL_CODE,
                "fields": [str(row.get("file"))],
                "why": (f"разбор текста говорит "
                        f"`{row['static'].get('reaches')}`, наблюдение — "
                        f"`{row.get('recursion')}`; свидетели косвенный и "
                        "прямой, и расхождение есть предмет, а не шум")})
    if recursion_observed:
        findings.append({
            "kind": "test_channel_closes_on_own_step",
            "file": PRODUCER, "channel": CHANNEL_CODE,
            "fields": sorted(r["file"] for r in recursion_observed),
            "why": ("дочерний прогон вошёл в ступень переписи — замыкание "
                    "НАБЛЮДЕНО, и причина отказа ADR-447 подтверждается "
                    "замером для этих файлов")})
    for row in rows:
        if row.get("outcome") == CHILD_RAN_RED:
            findings.append({
                "kind": "test_channel_reader_is_red",
                "file": PRODUCER, "channel": CHANNEL_TEST,
                "fields": [str(row.get("file"))],
                "why": (f"файл канала теста вышел кодом {row.get('exit_code')}: "
                        "цена измерена, но читатель, о чьём решении идёт речь, "
                        "сегодня красный")})

    counts = {
        "readers": len(rows),
        "priced": len(priced),
        "unpriced": len(unpriced),
        "refused_nested": len(refused),
        "ran_green": len([r for r in rows
                          if r.get("outcome") == CHILD_RAN_GREEN]),
        "ran_red": len([r for r in rows if r.get("outcome") == CHILD_RAN_RED]),
        "unmeasured": len([r for r in rows
                           if r.get("outcome") == CHILD_UNMEASURED]),
        "recursion_observed": len(recursion_observed),
        "recursion_not_observed": len(recursion_absent),
        "recursion_unmeasured": len([r for r in rows if r.get("recursion")
                                     == RECURSION_UNMEASURED]),
        "witnesses_agree": len([r for r in rows
                                if r.get("witnesses") == "agree"]),
        "witnesses_disagree": len([r for r in rows
                                   if r.get("witnesses") == "disagree"]),
        "witnesses_incomplete": len([r for r in rows
                                     if r.get("witnesses") == "incomplete"]),
    }

    return {
        **head,
        "status": ("UNMEASURED" if verdict == BUDGET_UNMEASURED
                   else ("CRITICAL" if verdict == BUDGET_DOES_NOT_FIT
                         else "MEASURED")),
        "verdict": verdict,
        "budget_s": budget_s,
        "budget_source": budget_source,
        "budget_refused": budget_refused,
        "population": population,
        "total_cost_s": total_cost_s,
        "prior_cost_s": prior_cost,
        "combined_cost_s": combined_cost_s,
        "margin": margin,
        "rows": rows,
        "counts": counts,
        "findings": findings,
        "blind": [
            "население взято у СОСЕДНЕЙ координаты, а не списком имён: "
            "перечень в коде был бы второй копией правила о населении; зато "
            "и ошибка соседа приезжает сюда целиком",
            "отметка входа ловит ступень (" + ", ".join(STEP_ENTRYPOINTS)
            + "), а не любой зов модуля: файл вправе звать ОДНУ координату и "
              "ступенью это не будет",
            f"разбор текста — свидетель КОСВЕННЫЙ глубины "
            f"{STATIC_WITNESS_DEPTH}: замыкание через `importlib` или через "
            "третий модуль он не видит, и полноту даёт не он, а наблюдение",
            "цена измерена на ЭТОЙ машине и этом дереве; ответ имеет право не "
            f"зависеть от её точности, и запас {margin}× говорит, во сколько "
            f"раз замер обязан ошибиться, чтобы вердикт сменился (порог "
            f"{REQUIRED_COST_MARGIN}× объявлен ДО замера)",
            "прогон, который не заводился (отказ от вложенности), отметок не "
            "даёт ПО ПОСТРОЕНИЮ — его ноль есть третий исход, а не "
            "«замыкания нет»",
        ],
    }


def _coordinate_scope(flat_clean: Dict[str, str], changed: List[str],
                      readers: List[dict]) -> dict:
    """Насколько население читателей — свойство ПРАВИЛА, а не дерева.

    Заказ G71 п. 2. Население ``decides_on_moved`` объявляется сверкой ХВОСТА
    координаты читателя с хвостами сдвинувшихся полей документа. Хвост не есть
    имя поля: у соседа в одном документе живут и ``callees``, и
    ``counts.callees``. Здесь то же население считается ВТОРОЙ раз — сверкой
    по ПОЛНОМУ пути, — и разница двух чисел есть цена правила.

    Разность делится на ДВА класса, и слить их значило бы повторить дефект,
    который прибор ищет (инв. #17):

    * **доказанно лишний** — путь разобран до якоря и в разность документа НЕ
      попал: хвост впустил читателя поля, которое не двигалось;
    * **НЕ ИЗМЕРЕНО** — путь до якоря не разобран (чужое имя, нелитеральный
      ключ). Про такого читателя не сказано ничего, и «не сдвинулось» про него
      не утверждается.

    Направление вложенности не постулируется, а МЕРЯЕТСЯ: у разобранного пути
    хвост обязан быть в хвостах разности всякий раз, когда путь в разности, —
    то есть «впущенных только путём» обязан быть ноль. Если их не ноль, неверно
    рассуждение прибора, и число скажет об этом раньше прозы.
    """
    changed_set = set(changed)
    changed_tails = {key.rsplit(".", 1)[-1] for key in changed_set}

    tail_owners: Dict[str, List[str]] = {}
    for key in flat_clean:
        tail_owners.setdefault(key.rsplit(".", 1)[-1], []).append(key)
    ambiguous = {tail: sorted(paths) for tail, paths in tail_owners.items()
                 if len(paths) > 1}

    by_tail: set = set()
    by_path: set = set()
    tail_only: List[dict] = []
    path_only: List[dict] = []
    unmeasured: List[dict] = []
    unmeasured_all: List[dict] = []
    outcomes: Dict[str, int] = {}
    for reader in readers:
        for touch in reader["touches"]:
            outcome = str(touch.get("field_path_outcome"))
            outcomes[outcome] = outcomes.get(outcome, 0) + 1
            if touch["form"] != TOUCH_DECIDES:
                continue
            row = {"file": reader["file"], "line": touch.get("line"),
                   "field": touch.get("field"),
                   "field_path": touch.get("field_path"),
                   "path_outcome": outcome}
            admitted_tail = bool(touch.get("could_change"))
            admitted_path = bool(touch.get("could_change_by_path"))
            if admitted_tail:
                by_tail.add(reader["file"])
            if admitted_path:
                by_path.add(reader["file"])
            if touch.get("field_path") is None:
                unmeasured_all.append(row)
                if admitted_tail:
                    unmeasured.append(row)
                continue
            if admitted_tail and not admitted_path:
                tail_only.append(row)
            elif admitted_path and not admitted_tail:
                path_only.append(row)

    return {
        "question": ("сколько читателей попало бы в население при сверке по "
                     "ПОЛНОМУ пути поля и сколько по ХВОСТУ, и совпадают ли "
                     "множества"),
        "order": "G71.2",
        "doc_tails": len(tail_owners),
        "ambiguous_tails_total": len(ambiguous),
        "ambiguous_tails": ambiguous,
        "ambiguous_tails_among_moved": sorted(t for t in ambiguous
                                              if t in changed_tails),
        "readers_by_tail": len(by_tail),
        "readers_by_path": len(by_path),
        "sets_coincide": by_tail == by_path,
        "files_only_by_tail": sorted(by_tail - by_path),
        "files_only_by_path": sorted(by_path - by_tail),
        "touches_admitted_by_tail_only": tail_only,
        "touches_admitted_by_path_only": path_only,
        "deciding_admitted_by_tail_path_unmeasured": unmeasured,
        "deciding_path_unmeasured_total": unmeasured_all,
        "path_outcomes": outcomes,
    }


def _flatten_rule_scope(clean: dict, widened: dict,
                        flat_clean: Dict[str, str], changed: List[str],
                        readers: List[dict]) -> dict:
    """Чьё свойство — «хвостов 115, многозначен 1»: документа или ПРАВИЛА.

    Заказ G72 п. 2. Число, которым цикл #673 объяснил свой ноль, снято
    правилом :func:`_flatten_doc`, а оно разворачивает словари и НЕ
    разворачивает списки. Значит, всё, что живёт внутри элементов списка, в
    счёт хвостов не вошло ВОВСЕ — и «один многозначный из 115» может быть
    свойством уплощения, а не документа. Здесь тот же документ уплощается
    ВТОРЫМ правилом (:func:`_flatten_doc_deep`), и разница двух счётов есть
    цена первого.

    Три вещи меряются порознь, и слить их значило бы потерять ответ:

    * **население хвостов** — сколько имён видит каждое правило, и какие
      имена видит только глубокое (`tails_only_deep`);
    * **цена глубокого правила** — какие имена оно, наоборот, ТЕРЯЕТ
      (`tails_only_shallow`): развернув список, оно перестаёт называть сам
      список. Молчать об этом значило бы выдать «точнее» за «строго больше»;
    * **вред у потребителя** — решающие чтения, которые допустило бы
      глубокое правило и НЕ допускает нынешнее (`admitted_by_deep_only`).
      Это и есть читатели, невидимые населению ``decides_on_moved`` сегодня.

    Вердикт о происхождении многозначности имеет ТРИ исхода, а не два:
    списков в документе может не быть вовсе, и такой ноль есть пустота по
    построению, а не свойство документа.

    ADVISORY: правило уплощения НЕ заменяется, ни одно население не
    пересчитывается этим замером (``applied`` ложно у всего шага).
    """
    deep_clean, capped_clean = _flatten_doc_deep(clean)
    deep_widened, capped_widened = _flatten_doc_deep(widened)
    capped = sorted(set(capped_clean) | set(capped_widened))
    lists_total, list_elements = _list_census(clean)

    tails_shallow: Dict[str, List[str]] = {}
    for key in flat_clean:
        tails_shallow.setdefault(_name_tail(key), []).append(key)
    tails_deep: Dict[str, List[str]] = {}
    for key in deep_clean:
        tails_deep.setdefault(_name_tail(key), []).append(key)

    def _ambiguous(owners: Dict[str, List[str]]) -> Dict[str, dict]:
        return {tail: {"paths": len(paths),
                       "sample": sorted(paths)[:AMBIGUOUS_PATH_SAMPLE]}
                for tail, paths in owners.items() if len(paths) > 1}

    amb_shallow = _ambiguous(tails_shallow)
    amb_deep = _ambiguous(tails_deep)

    changed_deep = sorted(key for key in set(deep_clean) | set(deep_widened)
                          if deep_clean.get(key) != deep_widened.get(key))
    changed_tails_shallow = {_name_tail(key) for key in changed}
    changed_tails_deep = {_name_tail(key) for key in changed_deep}

    deep_only: List[dict] = []
    shallow_only: List[dict] = []
    unmeasured: List[dict] = []
    files_deep: set = set()
    files_shallow: set = set()
    for reader in readers:
        for touch in reader["touches"]:
            if touch["form"] != TOUCH_DECIDES:
                continue
            field = touch.get("field")
            row = {"file": reader["file"], "line": touch.get("line"),
                   "field": field}
            if field is None:
                unmeasured.append(row)
                continue
            admitted_deep = field in changed_tails_deep
            admitted_shallow = field in changed_tails_shallow
            if admitted_deep:
                files_deep.add(reader["file"])
            if admitted_shallow:
                files_shallow.add(reader["file"])
            if admitted_deep and not admitted_shallow:
                deep_only.append(row)
            elif admitted_shallow and not admitted_deep:
                shallow_only.append(row)

    only_deep = sorted(set(tails_deep) - set(tails_shallow))
    only_shallow = sorted(set(tails_shallow) - set(tails_deep))
    amb_only_deep = sorted(set(amb_deep) - set(amb_shallow))

    if lists_total == 0:
        verdict = FLATTEN_NO_LISTS
    elif amb_only_deep:
        verdict = FLATTEN_RULE_DEPENDENT
    else:
        verdict = FLATTEN_DOC_PROPERTY

    def _share(part: int, whole: int) -> Optional[float]:
        return None if not whole else round(100.0 * part / whole, 2)

    return {
        "question": ("сколько хвостов появилось бы при развёртывании списков "
                     "и сколько из них многозначны — и не есть ли «один из "
                     "115» свойство правила уплощения, а не документа"),
        "order": "G72.2",
        "applied": False,
        "verdict": verdict,
        "max_depth_declared": DEEP_FLATTEN_MAX_DEPTH,
        "lists_in_doc": lists_total,
        "list_elements": list_elements,
        "doc_fields_shallow": len(flat_clean),
        "doc_fields_deep": len(deep_clean),
        "tails_shallow": len(tails_shallow),
        "tails_deep": len(tails_deep),
        "tails_only_deep": only_deep,
        "tails_only_shallow": only_shallow,
        "ambiguous_shallow": len(amb_shallow),
        "ambiguous_deep": len(amb_deep),
        "ambiguous_only_deep": amb_only_deep,
        "ambiguous_tails_deep": amb_deep,
        "ambiguous_share_shallow_pct": _share(len(amb_shallow),
                                              len(tails_shallow)),
        "ambiguous_share_deep_pct": _share(len(amb_deep), len(tails_deep)),
        "moved_fields_deep": len(changed_deep),
        "moved_tails_only_deep": sorted(changed_tails_deep
                                        - changed_tails_shallow),
        "readers_admitted_by_deep": len(files_deep),
        "readers_admitted_by_shallow": len(files_shallow),
        "files_only_by_deep": sorted(files_deep - files_shallow),
        "touches_admitted_by_deep_only": deep_only,
        "touches_admitted_by_shallow_only": shallow_only,
        "deciding_field_unmeasured": unmeasured,
        "paths_depth_capped": capped,
    }



#: Реестр документов, у которых спрашивается доля многозначных хвостов
#: (**заказ G73 п. 2**). Имя реестра и его содержимое берутся ВВОЗОМ у моста:
#: второй копии списка переписей здесь не заводится — это ровно тот дефект,
#: который сама перепись и ищет («одно правило — две копии»).
REGISTRY_OWNER = "spa_core.monitoring.findings_bridge"
REGISTRY_ATTR = "CENSUS_PRODUCT"

#: Почему документ реестра НЕ измерен. Причина обязана быть НАЗВАНА, а не
#: слита с нулём и не выдана за «многозначности нет» (инв. #17).
DOC_ABSENT = "artifact_absent"
DOC_NOT_JSON = "artifact_not_a_json_document"
DOC_UNREADABLE = "artifact_unreadable"
DOC_NOT_A_MAPPING = "artifact_not_a_mapping"
DOC_PRODUCER_UNREADABLE = "producer_unreadable"

#: Чего стоит читателю многозначность хвоста ЕГО координаты. Четыре исхода, и
#: третий от второго отличается тем, что именно спрашивал заказ: хвост может
#: быть многозначен у ДОКУМЕНТА и при этом ничего не стоить ЧИТАТЕЛЮ, чей
#: полный путь разобран. Слить их значило бы назвать ценой то, что ею не
#: является, — и завысить ответ в девять раз (замер: 344 против 38).
COST_TAIL_UNAMBIGUOUS = "tail_unambiguous"
COST_PATH_RESOLVES = "path_resolves_the_tail"
COST_DECIDES_AMBIGUOUS = "ambiguous_tail_unresolved_path"
COST_FIELD_UNMEASURED = "deciding_field_unmeasured"

#: Документ, на котором пред-фильтр кандидатов проверяется ПОЛНЫМ обходом
#: дерева. Объявлен ДО замера и по имени: контроль, выбранный по результату,
#: есть украшение. Расхождение полного обхода с фильтрованным отменяет ВЕСЬ
#: шаг (fail-CLOSED), а не правится молча.
FILTER_CONTROL_CENSUS = "rule_second_copy_census"

#: Сколько стоящих читателю чтений показывать у документа. Счёт хранится
#: ВСЕГДА; усечение есть усечение ПОКАЗА и названо своим полем.
COSTED_SAMPLE = 3

REGISTRY_COSTS_READER = "ambiguity_costs_a_reader_today"
REGISTRY_COSTS_NOBODY = "ambiguity_costs_no_reader_today"


def _median(values: List[float]) -> Optional[float]:
    """Медиана без внешней зависимости; пустому набору — `None`, не ноль."""
    if not values:
        return None
    ordered = sorted(values)
    mid = len(ordered) // 2
    if len(ordered) % 2:
        return round(float(ordered[mid]), 2)
    return round((ordered[mid - 1] + ordered[mid]) / 2.0, 2)


def _tail_owners(flat: Dict[str, str]) -> Dict[str, List[str]]:
    """Хвост имени → все пути документа, которые им кончаются."""
    owners: Dict[str, List[str]] = {}
    for key in flat:
        owners.setdefault(_name_tail(key), []).append(key)
    return owners


def _artifact_path(root: Path, artifact: str,
                   data_dir: Optional[Path]) -> Path:
    """Куда лёг артефакт переписи.

    Реестр объявляет путь ОТ КОРНЯ дерева (``data/x.json``). В рабочем дереве
    живого ``data/`` нет по построению, поэтому каталог данных есть ВХОД: без
    него замер ответил бы «артефакта нет» про каждый документ и выдал бы
    свойство дерева за свойство реестра.
    """
    rel = Path(artifact)
    if data_dir is None:
        return root / rel
    parts = rel.parts
    if parts and parts[0] == "data":
        return Path(data_dir).joinpath(*parts[1:])
    return Path(data_dir) / rel


def _document_ambiguity(doc: dict) -> dict:
    """Хвосты одного документа по ОБОИМ правилам уплощения.

    Считает ровно то, что цикл #674 посчитал у одного соседа, — и ничего
    больше: счёт хвостов, счёт многозначных и доля, порознь по нынешнему
    правилу (:func:`_flatten_doc`) и по глубокому (:func:`_flatten_doc_deep`).
    Вердикт о происхождении многозначности берётся теми же тремя константами,
    что и у соседа: второго словаря исходов здесь не заводится.
    """
    shallow = _flatten_doc(doc)
    deep, capped = _flatten_doc_deep(doc)
    lists_total, list_elements = _list_census(doc)
    owners_shallow = _tail_owners(shallow)
    owners_deep = _tail_owners(deep)
    amb_shallow = {t for t, p in owners_shallow.items() if len(p) > 1}
    amb_deep = {t for t, p in owners_deep.items() if len(p) > 1}
    amb_only_deep = sorted(amb_deep - amb_shallow)

    if lists_total == 0:
        verdict = FLATTEN_NO_LISTS
    elif amb_only_deep:
        verdict = FLATTEN_RULE_DEPENDENT
    else:
        verdict = FLATTEN_DOC_PROPERTY

    def _share(part: int, whole: int) -> Optional[float]:
        return None if not whole else round(100.0 * part / whole, 2)

    return {
        "verdict": verdict,
        "tails_shallow": len(owners_shallow),
        "tails_deep": len(owners_deep),
        "ambiguous_shallow": len(amb_shallow),
        "ambiguous_deep": len(amb_deep),
        "ambiguous_share_shallow_pct": _share(len(amb_shallow),
                                              len(owners_shallow)),
        "ambiguous_share_deep_pct": _share(len(amb_deep), len(owners_deep)),
        "ambiguous_only_deep": len(amb_only_deep),
        "lists_in_doc": lists_total,
        "list_elements": list_elements,
        "paths_depth_capped": len(capped),
        "_owners_shallow": owners_shallow,
        "_ambiguous_shallow": amb_shallow,
        # Плоская карта отдаётся ВМЕСТЕ с хвостами (заказ G74 п. 1): значения
        # по путям сравнивает сосед, и уплощать документ второй раз ради
        # этого значило бы завести вторую копию правила уплощения.
        "_flat_shallow": shallow,
    }


def _read_at(item: dict) -> str:
    """«файл:строка» стоящего чтения — материал НАЗВАННОГО отказа.

    Отказ, который не говорит У КОГО не измерено, снова превращает третий
    исход в счётчик: читателю нечего проверить и нечего починить.
    """
    return f"{item.get('file')}:{item.get('line')}"


def _costed_touches(readers: List[dict],
                    owners: Dict[str, List[str]],
                    ambiguous: set,
                    flat: Optional[Dict[str, str]] = None,
                    reach_of: Optional[Callable[[str, Optional[int]], dict]]
                    = None) -> Tuple[List[dict], Dict[str, int]]:
    """Чего многозначность хвоста стоит РЕШАЮЩИМ чтениям этого документа.

    Вопрос заказа — «стоит ли она читателю РЕШЕНИЯ», и ответ на него не есть
    «читатель упомянул многозначный хвост». Читатель, чей полный путь разобран
    (``field_path``), назвал координату однозначно: многозначность хвоста
    стоит тогда ПРИБОРУ, а не ему. Стоит она ровно там, где координатой
    решения служит хвост И путь до якоря НЕ разобран — тогда сказать, каким
    из нескольких значений решение движется, нельзя вообще.
    """
    costed: List[dict] = []
    counts = {COST_TAIL_UNAMBIGUOUS: 0, COST_PATH_RESOLVES: 0,
              COST_DECIDES_AMBIGUOUS: 0, COST_FIELD_UNMEASURED: 0}
    for reader in readers:
        for touch in reader["touches"]:
            if touch["form"] != TOUCH_DECIDES:
                continue
            field = touch.get("field")
            if field is None:
                counts[COST_FIELD_UNMEASURED] += 1
                continue
            if field not in ambiguous:
                counts[COST_TAIL_UNAMBIGUOUS] += 1
                continue
            if touch.get("field_path") is not None:
                counts[COST_PATH_RESOLVES] += 1
                continue
            counts[COST_DECIDES_AMBIGUOUS] += 1
            entry = {"file": reader["file"], "line": touch.get("line"),
                     "field": field, "paths": len(owners[field]),
                     "sample": sorted(owners[field])[:COSTED_SAMPLE],
                     "path_outcome": touch.get("field_path_outcome")}
            # --- заказ G74 п. 1 -----------------------------------------
            # Многозначность координаты и РАСХОЖДЕНИЕ значений по ней суть
            # разные утверждения, и второе снимается здесь же: населением
            # обоих служит ровно это чтение, и заводить ему вторую дорогу
            # значило бы завести вторую копию правила «кто решает».
            if flat is not None:
                entry.update(_value_divergence(sorted(owners[field]), flat))
            if reach_of is not None:
                reach = reach_of(reader["file"], touch.get("line"))
                entry["reach"] = reach["reach"]
                entry["test"] = reach.get("test")
                entry["reach_reason"] = reach["reason"]
            costed.append(entry)
    return costed, counts


#: --- заказ G74 п. 1 ---------------------------------------------------
#: Расходятся ли ЗНАЧЕНИЯ по путям многозначного хвоста. Цикл #675 измерил,
#: что у 38 решающих чтений координата МНОГОЗНАЧНА, и на этом остановился.
#: Многозначность сама по себе решения не искажает: хвост `denominator`,
#: живущий по пяти путям с ОДНИМ И ТЕМ ЖЕ значением, даёт читателю один
#: ответ, каким бы путём он ни пошёл. Искажает РАСХОЖДЕНИЕ значений.
#:
#: Исходов четыре, и четвёртый — третий по смыслу (инв. #17). Сравнение
#: идёт ДВУМЯ правилами, и второе не есть уточнение первого: `5000000` и
#: `5000000.0` суть разный ТЕКСТ и одно ЧИСЛО, и назвать это расхождением
#: значило бы выдать свойство печати за свойство значения.
VALUE_AGREE = "values_agree"
VALUE_DIFFER = "values_differ"
VALUE_TEXT_ONLY = "values_differ_in_text_only"
VALUE_OPAQUE = "value_not_a_literal"
_VALUE_OUTCOMES = (VALUE_AGREE, VALUE_DIFFER, VALUE_TEXT_ONLY, VALUE_OPAQUE)

#: Доходит ли ЖИВОЙ документ до вердикта того теста, который им решает.
#: Вторая половина заказа просит подставить соседний путь и посмотреть,
#: сменится ли вердикт. Прежде чем подставлять, надо знать, ДОСТИЖИМ ли
#: вердикт этой подстановкой вообще: `spa_core/tests/conftest.py`
#: autouse-фикстурой уводит `SPA_DATA_DIR` каждого теста в одноразовый
#: каталог, и отказываются от этого только тесты с меткой `live_data`.
#: Прогнать подстановку, не спросив об этом, значило бы получить ноль
#: смен вердикта и объявить его свойством МНОГОЗНАЧНОСТИ, тогда как он
#: есть свойство ФИКСТУРЫ — ровно тот класс, против которого написан инв. #17.
REACH_LIVE = "reads_the_live_document"
REACH_ISOLATED = "isolated_from_the_live_document_by_the_harness"
REACH_NO_TEST = "deciding_line_outside_any_test"
REACH_FILE_UNPARSED = "reader_file_unparsed"
_REACH_OUTCOMES = (REACH_LIVE, REACH_ISOLATED, REACH_NO_TEST,
                   REACH_FILE_UNPARSED)

#: --- заказ G75 п. 4 ---------------------------------------------------
#: У ОТКАЗА тоже обязано быть имя. Два непрочтения достижимости различны по
#: предмету и чинятся разным: «производитель не записал» — дыра в письме,
#: «записал класс вне объявленных» — расхождение словарей. Отказ, который их
#: сливает, снова превращает третий исход в счётчик, только на уровень выше.
UNMEASURED_REACH_ABSENT = "reach_not_observed"
UNMEASURED_REACH_UNDECLARED = "reach_class_undeclared"

#: --- заказ G76 п. 1 ---------------------------------------------------
#: Счётчик, открытый ЛЮБОЙ строке. Наследник снял класс у ОДНОГО поля одного
#: прибора (`reaches[reach] = reaches.get(reach, 0) + 1`, ADR-459), и на этом
#: население класса кончилось: сколько таких счётчиков ЕЩЁ, не спрашивал никто.
#: Правило поиска объявлено ЗДЕСЬ, до замера, и проверяется на уже известном
#: случае — иначе ноль был бы неотличим от «искали не той формой».
OPEN_COUNTER_DIRS = ("spa_core/monitoring", "scripts")
OPEN_COUNTER_SKIP = ("scripts/archive",)

#: Происхождение КЛЮЧА. Классов четыре, и четвёртый — не «прочее»: ключ,
#: чьё происхождение не разобрано, НЕ есть ключ безопасный.
KEY_LITERAL = "key_is_a_literal"
KEY_DECLARED = "key_from_a_declared_enumeration"
KEY_ARTIFACT = "key_from_an_artifact"
KEY_UNRESOLVED = "key_provenance_unresolved"
_KEY_OUTCOMES = (KEY_LITERAL, KEY_DECLARED, KEY_ARTIFACT, KEY_UNRESOLVED)

#: Имена, чтение которых ЕСТЬ чтение данных. Список объявлен, а не угадан:
#: расширять его — решение, а не умолчание.
OPEN_COUNTER_ARTIFACT_CALLS = ("observed", "load", "loads", "read_json",
                               "json_load", "read_text")

#: Вердикт шага. Разделяет их не сила, а ПРЕДМЕТ.
OPEN_COUNTER_NONE = "no_counter_is_open_to_an_unnamed_class"
OPEN_COUNTER_GUARDED = "open_counters_exist_but_every_key_is_checked"
OPEN_COUNTER_FOUND = "counters_open_to_a_class_nobody_declared"

#: Отказы шага. У каждого своё имя: чинятся они разным.
UNMEASURED_CONTROL_MISSED = "declared_form_missed_the_known_case"
UNMEASURED_NO_TREE = "no_file_parsed_in_the_declared_dirs"

#: Сцена положительного контроля — ФОРМА обеих строк известного случая
#: (`spa_core/monitoring/rule_second_copy_census.py` на 84150c7cb, до ADR-459).
#: Дословной она быть НЕ МОЖЕТ и это не небрежность: сосед
#: `test_tail_value_divergence.py` держит сторожа, требующего, чтобы
#: отставленное имя `reach_outcome` в коде этого модуля не встречалось вовсе
#: (ADR-459), — и сторож ПРАВ. Воспроизводится то, что составляет класс:
#: `str()` поверх возможного отсутствия, ключ из артефакта, счётчик без
#: сверки с перечнем. Отставленное имя классом не является, и возвращать его
#: сюда ради буквальности значило бы погасить чужого сторожа своей сценой.
#: Правило обязано найти ОБА счётчика, назвать ключ пришедшим из артефакта,
#: сказать «сверки с перечнем нет» и увидеть `str()` поверх возможного
#: отсутствия. Не нашло — шаг ОТКАЗЫВАЕТ целиком: ноль, полученный формой,
#: которая промахивается по известному случаю, есть свойство формы, а не
#: population. Предзаполнение словаря объявленным перечнем (`_VALUE_OUTCOMES`)
#: присутствует в сцене НАМЕРЕННО: оно сторожем НЕ является, и контроль обязан
#: это подтвердить.
OPEN_COUNTER_CONTROL_SOURCE = '''
_VALUE_OUTCOMES = ("differ", "agree")
_REACH_OUTCOMES = ("live", "isolated")


def scene(rows):
    values = {cls: 0 for cls in _VALUE_OUTCOMES}
    reaches = {cls: 0 for cls in _REACH_OUTCOMES}
    for row in rows:
        costed = observed(row, "costed_all", kind=list)
        for item in costed:
            outcome = str(item.get("value_outcome"))
            values[outcome] = values.get(outcome, 0) + 1
            reach = str((item.get("reach_cell") or {}).get("reach")
                        if isinstance(item.get("reach_cell"), dict)
                        else item.get("reach"))
            reaches[reach] = reaches.get(reach, 0) + 1
'''

#: Отрицательная половина той же сцены: тот же оператор, но ключ пробегает
#: ОБЪЯВЛЕННЫЙ перечень, а соседний — сверен принадлежностью. Без неё
#: «контроль нашёл 2» было бы неотличимо от «правило считает открытым любой
#: счётчик»: контроль обязан ещё и ПРОМАХНУТЬСЯ там, где промахнуться должен.
OPEN_COUNTER_CONTROL_CLEAN = '''
_VALUE_OUTCOMES = ("differ", "agree")


def clean(doc):
    counts = {}
    for cls in _VALUE_OUTCOMES:
        counts[cls] = counts.get(cls, 0) + 1
    for item in doc:
        name = item.get("verdict")
        if name not in _VALUE_OUTCOMES:
            continue
        counts[name] = counts.get(name, 0) + 1
'''

#: Метка, которой тест отказывается от изоляции каталога данных, и сторож,
#: который эту изоляцию делает. Имя метки — ОДНО, и берётся оно отсюда,
#: чтобы у правила не завелось второй копии у читателя.
ISOLATION_MARKER = "live_data"
ISOLATION_GUARD = "spa_core/tests/data_dir_guard.py::isolate"

#: Вердикт заказа G74 п. 1. Четыре, и разделяет их не сила, а ПРЕДМЕТ:
#: расхождение может быть настоящим и при этом не иметь ни одного вердикта,
#: до которого оно способно дойти, — и это не «вреда нет», а «вред лежит у
#: АРТЕФАКТА, а не у прогона».
DIVERGENCE_REACHES = "divergence_reaches_a_live_verdict"
DIVERGENCE_ARTIFACT_ONLY = "divergence_real_but_no_verdict_can_see_it"
DIVERGENCE_NONE = "no_costing_read_diverges"
DIVERGENCE_NOTHING_COSTED = "no_costing_read_at_all"


def _typed_value(rendered: str) -> Tuple[bool, object]:
    """`repr` обратно в значение. Неразбираемое — ТРЕТИЙ исход, не `None`.

    `float('nan')` печатается как `nan` и литералом не является; выдать его
    за `None` значило бы слить «значения нет» с «значение не прочитано».
    """
    try:
        return True, ast.literal_eval(rendered)
    except (ValueError, SyntaxError, MemoryError, RecursionError, TypeError):
        return False, None


def _value_kind(value: object) -> Tuple[str, str]:
    """Род значения и его каноническая запись.

    Род, а не `type().__name__`: `5000000` и `5000000.0` суть одно ЧИСЛО,
    и различать их родом значило бы называть расхождением разницу печати.
    `bool` отделён от числа намеренно — `True` и `1` решают по-разному.
    """
    if isinstance(value, bool):
        return "bool", repr(value)
    if isinstance(value, (int, float)):
        return "number", repr(float(value))
    if value is None:
        return "null", "None"
    try:
        return (type(value).__name__,
                json.dumps(value, sort_keys=True, default=repr))
    except (TypeError, ValueError):
        return type(value).__name__, repr(value)


def _value_divergence(paths: List[str], flat: Dict[str, str]) -> dict:
    """Расходятся ли значения по ПУТЯМ одного хвоста в живом документе."""
    texts = {flat[p] for p in paths}
    kinds: set = set()
    canonical: set = set()
    opaque: List[str] = []
    for path in paths:
        ok, value = _typed_value(flat[path])
        if not ok:
            opaque.append(path)
            continue
        kind, canon = _value_kind(value)
        kinds.add(kind)
        canonical.add((kind, canon))
    if len(texts) == 1:
        outcome = VALUE_AGREE
    elif opaque:
        outcome = VALUE_OPAQUE
    elif len(canonical) == 1:
        outcome = VALUE_TEXT_ONLY
    else:
        outcome = VALUE_DIFFER
    return {
        "value_outcome": outcome,
        "distinct_text": len(texts),
        "distinct_value": (None if opaque else len(canonical)),
        "kinds": sorted(kinds),
        "kinds_differ": len(kinds) > 1,
        # Счёт хранится ВСЕГДА, образец усечён и назван своим именем: иначе
        # «показано три» читалось бы как «нечитаемых путей три».
        "opaque_total": len(opaque),
        "opaque_paths": opaque[:COSTED_SAMPLE],
    }


def _pytest_mark_names(nodes: Iterable[ast.AST]) -> set:
    """Имена меток `pytest.mark.X` у перечня декораторов или выражений."""
    names: set = set()
    for node in nodes:
        target = node.func if isinstance(node, ast.Call) else node
        parts: List[str] = []
        while isinstance(target, ast.Attribute):
            parts.append(target.attr)
            target = target.value
        if isinstance(target, ast.Name):
            parts.append(target.id)
        parts.reverse()
        if len(parts) >= 3 and parts[0] == "pytest" and parts[1] == "mark":
            names.add(parts[2])
        elif len(parts) >= 2 and parts[0] == "mark":
            names.add(parts[1])
    return names


def _module_marks(tree: ast.AST) -> set:
    """Метки уровня модуля (`pytestmark = ...`).

    Фикстура спрашивает ``get_closest_marker``, а он видит метку на любом из
    трёх уровней. Прочитать только декораторы функции значило бы объявить
    изолированным тест, который от изоляции отказался целым модулем.
    """
    marks: set = set()
    for node in getattr(tree, "body", []):
        if not isinstance(node, (ast.Assign, ast.AnnAssign)):
            continue
        targets = (node.targets if isinstance(node, ast.Assign)
                   else [node.target])
        if not any(isinstance(t, ast.Name) and t.id == "pytestmark"
                   for t in targets):
            continue
        value = node.value
        if value is None:
            continue
        items = (list(value.elts)
                 if isinstance(value, (ast.List, ast.Tuple)) else [value])
        marks |= _pytest_mark_names(items)
    return marks


def _locate_test(tree: ast.AST, line: int) -> Optional[dict]:
    """Тест, внутри которого стои́т решающая строка, и его метки."""
    module_marks = _module_marks(tree)

    def _covers(fn: ast.AST) -> bool:
        end = getattr(fn, "end_lineno", None) or fn.lineno
        return fn.lineno <= line <= end

    for node in ast.walk(tree):
        if not isinstance(node, ast.ClassDef):
            continue
        for fn in node.body:
            if (isinstance(fn, (ast.FunctionDef, ast.AsyncFunctionDef))
                    and fn.name.startswith("test") and _covers(fn)):
                return {"test": f"{node.name}::{fn.name}",
                        "marks": sorted(module_marks
                                        | _pytest_mark_names(node.decorator_list)
                                        | _pytest_mark_names(fn.decorator_list))}
    for fn in getattr(tree, "body", []):
        if (isinstance(fn, (ast.FunctionDef, ast.AsyncFunctionDef))
                and fn.name.startswith("test") and _covers(fn)):
            return {"test": fn.name,
                    "marks": sorted(module_marks
                                    | _pytest_mark_names(fn.decorator_list))}
    return None


def _reach_of(tree: Optional[ast.AST], line: Optional[int]) -> dict:
    """Способна ли подстановка в ЖИВОЙ документ сдвинуть вердикт этого теста."""
    if tree is None:
        return {"reach": REACH_FILE_UNPARSED, "test": None,
                "reason": "файл читателя не разобран — тест не найден"}
    if line is None:
        return {"reach": REACH_NO_TEST, "test": None,
                "reason": "у решающего чтения не измерена строка"}
    located = _locate_test(tree, int(line))
    if located is None:
        return {"reach": REACH_NO_TEST, "test": None,
                "reason": ("решающая строка стои́т вне тела теста "
                           "(помощник, фикстура, уровень модуля)")}
    if ISOLATION_MARKER in located["marks"]:
        return {"reach": REACH_LIVE, "test": located["test"],
                "marks": located["marks"],
                "reason": (f"тест помечен `{ISOLATION_MARKER}` и от изоляции "
                           f"каталога данных отказался — подстановка до его "
                           f"вердикта дойти МОЖЕТ")}
    return {"reach": REACH_ISOLATED, "test": located["test"],
            "marks": located["marks"],
            "reason": (f"`{ISOLATION_GUARD}` уводит `SPA_DATA_DIR` этого "
                       f"теста в одноразовый каталог (метки "
                       f"`{ISOLATION_MARKER}` у него нет) — живой документ до "
                       f"его вердикта не доходит ПО ПОСТРОЕНИЮ")}


def tail_value_divergence(scope: Optional[dict]) -> dict:
    """Расходятся ли значения у 38 стоящих чтений (**заказ G74 п. 1**).

    Заказ ставит вопрос дословно:

    > У скольких из 38 значения по путям хвоста РАЗЛИЧНЫ в живом документе и
    > сколько из них меняют вердикт своего теста при подстановке соседнего пути.

    Отвечается ДВУМЯ замерами, и второй не есть уточнение первого:

    1. **Расхождение значений** — свойство живого документа, снимаемое точно
       и без прогона. Двумя правилами: по тексту и по значению.
    2. **Достижимость вердикта** — прежде чем подставлять соседний путь, надо
       знать, способна ли подстановка дойти. Вердикт теста, у которого
       `SPA_DATA_DIR` уведён autouse-фикстурой, живому документу недоступен
       ПО ПОСТРОЕНИЮ, и ноль смен вердикта у такого теста есть свойство
       фикстуры, а не многозначности.

    Третий исход обязателен у обоих замеров. Шаг ЧИСТЫЙ: население берётся у
    :func:`registry_ambiguity_scope`, второй дороги к читателю здесь не
    заводится, ни одного файла не читается и ни один прогон не запускается.

    ADVISORY: ничего не правится, `applied` ложно.
    """
    head = {
        "question": ("у скольких из стоящих решающих чтений значения по "
                     "путям многозначного хвоста РАЗЛИЧНЫ в живом документе "
                     "и сколько из них способны сдвинуть вердикт своего теста"),
        "order": "G74.1",
        "applied": False,
        "isolation_marker": ISOLATION_MARKER,
        "isolation_guard": ISOLATION_GUARD,
    }
    if not isinstance(scope, dict):
        return {**head, "status": "UNMEASURED",
                "reason": ("населения нет: шаг многозначности реестра не "
                           "отдал словаря — это НЕ «стоящих чтений нет»")}
    if str(scope.get("status")) != "MEASURED":
        return {**head, "status": "UNMEASURED",
                "reason": (f"шаг многозначности реестра сам НЕ ИЗМЕРЕН "
                           f"({scope.get('reason') or scope.get('status')}) — "
                           f"делить нечего")}
    rows = observed(scope, "rows", kind=list)
    if rows is None:
        return {**head, "status": "UNMEASURED",
                "reason": ("в замере многозначности нет перечня документов — "
                           "это НЕ «ни один документ не стоит читателю»")}

    values: Dict[str, int] = {cls: 0 for cls in _VALUE_OUTCOMES}
    reaches: Dict[str, int] = {cls: 0 for cls in _REACH_OUTCOMES}
    diverging: List[dict] = []
    kinds_differ = 0
    measured_rows = 0
    rows_without_population: List[str] = []
    reads_without_reach: List[str] = []
    reads_with_alien_reach: List[str] = []
    for row in rows:
        if not row.get("costs_a_reader"):
            continue
        costed = observed(row, "costed_all", kind=list)
        if costed is None:
            # Инв. #17: строка сказала «стои́т читателю», а перечня нет.
            # Это НЕ ноль расхождений — это непрочитанное население.
            rows_without_population.append(str(row.get("census")))
            continue
        measured_rows += 1
        for item in costed:
            outcome = str(item.get("value_outcome"))
            values[outcome] = values.get(outcome, 0) + 1
            if item.get("kinds_differ"):
                kinds_differ += 1
            # --- заказ G75 п. 4 -----------------------------------------
            # Достижимость читается ОДНИМ именем и только ИЗВЕСТНЫМ классом.
            # Прежде здесь стояло второе имя (`reach_outcome`), которого не
            # писал ни один производитель — второе имя одного предмета ВНУТРИ
            # прибора, который ищет вторые копии, — а `str()` поверх
            # отсутствующего значения заводил в счётчик класс с именем
            # `"None"`: инв. #17 наизнанку, НЕ ИЗМЕРЕНО под видом исхода.
            # Хуже счётчика был ВЕРДИКТ: `reaching` считает только
            # REACH_LIVE, поэтому ненаблюдённая достижимость молча
            # становилась «до вердикта не доходит» — ровно тем ответом, на
            # котором стои́т ADR-458. Оба исхода теперь отказ, и отказ НАЗВАН.
            reach = observed(item, "reach", kind=str)
            if reach is None:
                reads_without_reach.append(_read_at(item))
                continue
            if reach not in _REACH_OUTCOMES:
                reads_with_alien_reach.append(f"{_read_at(item)}={reach}")
                continue
            reaches[reach] += 1
            if outcome == VALUE_DIFFER:
                diverging.append({
                    "census": row.get("census"),
                    "file": item.get("file"), "line": item.get("line"),
                    "field": item.get("field"), "paths": item.get("paths"),
                    "distinct_text": item.get("distinct_text"),
                    "distinct_value": item.get("distinct_value"),
                    "kinds": item.get("kinds"),
                    "reach": reach, "test": item.get("test"),
                })
    if rows_without_population:
        return {**head, "status": "UNMEASURED",
                "reason": (f"у {len(rows_without_population)} документ(ов) "
                           f"строка объявила цену читателю, но перечня "
                           f"стоящих чтений в ней нет "
                           f"({', '.join(sorted(rows_without_population)[:5])})"
                           f" — расхождение НЕ ИЗМЕРЕНО, и это не ноль")}
    if reads_without_reach:
        # Заказ G75 п. 4. Ноль смен вердикта держит весь вывод ADR-458, и
        # держит он его ТОЛЬКО пока достижимость измерена у каждого чтения.
        return {**head, "status": "UNMEASURED",
                "unmeasured_class": UNMEASURED_REACH_ABSENT,
                "reason": (f"у {len(reads_without_reach)} стоящ(их) чтений "
                           f"достижимость НЕ НАБЛЮДЕНА "
                           f"({', '.join(sorted(reads_without_reach)[:5])}) — "
                           f"это НЕ «до вердикта не доходит»: вердикт "
                           f"«{DIVERGENCE_ARTIFACT_ONLY}» означает измеренную "
                           f"недостижимость, а не отсутствующую")}
    if reads_with_alien_reach:
        # Класс, которого прибор не знает, молча не является REACH_LIVE и
        # потому молча же попадал бы в «не доходит». Имя без объявления —
        # тот же исход без имени, только с другой стороны.
        return {**head, "status": "UNMEASURED",
                "unmeasured_class": UNMEASURED_REACH_UNDECLARED,
                "reason": (f"у {len(reads_with_alien_reach)} стоящ(их) чтений "
                           f"достижимость названа классом вне объявленных "
                           f"({', '.join(sorted(reads_with_alien_reach)[:5])}) "
                           f"— сосчитать его «не доходит» значило бы принять "
                           f"незнакомый исход за измеренный")}

    costed_total = sum(values.values())
    reaching = [d for d in diverging if d["reach"] == REACH_LIVE]
    if not costed_total:
        verdict = DIVERGENCE_NOTHING_COSTED
    elif not diverging:
        verdict = DIVERGENCE_NONE
    elif reaching:
        verdict = DIVERGENCE_REACHES
    else:
        verdict = DIVERGENCE_ARTIFACT_ONLY
    return {
        **head,
        "status": "MEASURED",
        "verdict": verdict,
        "documents_costing": measured_rows,
        "costed_total": costed_total,
        "value_counts": values,
        "reach_counts": reaches,
        "kinds_differ": kinds_differ,
        "diverging": len(diverging),
        "diverging_reaching_a_verdict": len(reaching),
        "diverging_sample": diverging[:COSTED_SAMPLE],
        "blind": [
            ("подстановка соседнего пути НЕ ЗАПУСКАЛАСЬ ни разу: у чтений с "
             f"исходом `{REACH_ISOLATED}` она до вердикта не доходит по "
             "построению, и прогон дал бы ноль, который есть свойство "
             "autouse-фикстуры, а не многозначности"),
            ("расхождение снято у документа В ТОМ ВИДЕ, в каком он лежит "
             "СЕГОДНЯ: совпавшие значения завтра могут разойтись, и "
             f"`{VALUE_AGREE}` есть замер дня, а не свойство хвоста"),
            ("род значения не разделяет `int` и `float` намеренно — иначе "
             "разницей значений была бы названа разница печати; `bool` от "
             "числа отделён, потому что `True` и `1` решают по-разному"),
        ],
    }



def _counter_target_key(node: ast.AST) -> Optional[Tuple[ast.AST, ast.AST, str]]:
    """Счётчик ли это и какой формы. Форма ОБЪЯВЛЕНА, а не угадана.

    Две формы, и разделяет их не удобство, а то, чем открыт счётчик:

    * ``form_get`` — ``X[k] = X.get(k, D) + S``. Дословно та, которую назвал
      заказ: ``.get`` с умолчанием заводит класс ``k``, какой бы строкой он
      ни оказался, и объявленный перечень, которым словарь предзаполнили,
      этому не мешает НИКАК.
    * ``form_aug`` — ``X[k] += S``. Открыт он не всегда (на голом ``dict``
      падает ``KeyError``), но на ``Counter``/``defaultdict`` открыт ровно так
      же, и не спросить о нём значило бы сузить население до формы.

    Третья форма — ``Counter(...)`` / ``.update(...)`` над перечнем ключей —
    ЗДЕСЬ НЕ ИЩЕТСЯ, и это сказано вслух в ``blind`` шага: ненайденное ею
    население не есть ноль.

    Возвращает ``(цель, ключ, форма)`` либо ``None``.
    """
    if isinstance(node, ast.AugAssign) and isinstance(node.op, ast.Add):
        if isinstance(node.target, ast.Subscript):
            return node.target.value, node.target.slice, "form_aug"
        return None
    if not isinstance(node, ast.Assign) or len(node.targets) != 1:
        return None
    target = node.targets[0]
    if not isinstance(target, ast.Subscript):
        return None
    value = node.value
    if not (isinstance(value, ast.BinOp) and isinstance(value.op, ast.Add)):
        return None
    call = value.left
    if not (isinstance(call, ast.Call)
            and isinstance(call.func, ast.Attribute)
            and call.func.attr == "get"
            and len(call.args) == 2):
        return None
    # И цель, и ключ обязаны быть ОДНИМ И ТЕМ ЖЕ выражением слева и справа:
    # `a[i] = b.get(j, 0) + 1` счётчиком не является.
    if ast.dump(target.value) != ast.dump(call.func.value):
        return None
    if ast.dump(target.slice) != ast.dump(call.args[0]):
        return None
    return target.value, target.slice, "form_get"


def _scope_bindings(fn: ast.AST) -> Dict[str, List[ast.AST]]:
    """Все выражения, которыми в этой области связано каждое имя."""
    binds: Dict[str, List[ast.AST]] = {}

    def _bind(name: str, expr: Optional[ast.AST]) -> None:
        if expr is not None:
            binds.setdefault(name, []).append(expr)

    def _bound_names(target: ast.AST) -> List[str]:
        """Имена, которые оператор действительно СВЯЗЫВАЕТ.

        `ast.walk` по цели тут не годится и это не мелочь: у `counts[cls] = …`
        он вернул бы и `counts`, и `cls`, то есть объявил бы КЛЮЧ связанным
        правой частью — а правая часть счётчика всегда читает данные
        (`counts.get(cls, 0)`), и ключ из объявленного перечня оказался бы
        «пришедшим из артефакта». Ровно это и поймала отрицательная половина
        сцены контроля.
        """
        if isinstance(target, ast.Name):
            return [target.id]
        if isinstance(target, (ast.Tuple, ast.List)):
            out: List[str] = []
            for el in target.elts:
                out.extend(_bound_names(el))
            return out
        if isinstance(target, ast.Starred):
            return _bound_names(target.value)
        return []

    for node in ast.walk(fn):
        if isinstance(node, ast.Assign):
            for tgt in node.targets:
                for name in _bound_names(tgt):
                    _bind(name, node.value)
        elif isinstance(node, (ast.AnnAssign, ast.AugAssign)):
            if isinstance(node.target, ast.Name):
                _bind(node.target.id, node.value)
        elif isinstance(node, (ast.For, ast.AsyncFor)):
            for name in _bound_names(node.target):
                _bind(name, node.iter)
        elif isinstance(node, ast.comprehension):
            for name in _bound_names(node.target):
                _bind(name, node.iter)
        elif isinstance(node, ast.NamedExpr):
            if isinstance(node.target, ast.Name):
                _bind(node.target.id, node.value)
        elif isinstance(node, ast.withitem):
            if node.optional_vars is not None:
                for name in _bound_names(node.optional_vars):
                    _bind(name, node.context_expr)
    return binds


def _reads_data(expr: ast.AST) -> bool:
    """Читает ли выражение ДАННЫЕ (а не объявленный перечень).

    Свидетель ОДНОСТОРОННИЙ и назван вслух: ``.get``/индекс/объявленный вызов
    чтения. Чего он не видит — ключ, собранный из кусков в рантайме, — остаётся
    третьим исходом, а не нулём.
    """
    for node in ast.walk(expr):
        if isinstance(node, ast.Call):
            func = node.func
            if isinstance(func, ast.Attribute) and func.attr == "get":
                return True
            if (isinstance(func, ast.Attribute)
                    and func.attr in OPEN_COUNTER_ARTIFACT_CALLS):
                return True
            if (isinstance(func, ast.Name)
                    and func.id in OPEN_COUNTER_ARTIFACT_CALLS):
                return True
        if isinstance(node, ast.Subscript):
            return True
    return False


def _literal_enumeration(expr: ast.AST) -> bool:
    """Перечень ли это ЛИТЕРАЛОВ, объявленный на месте."""
    if isinstance(expr, (ast.Tuple, ast.List, ast.Set)):
        return all(isinstance(el, ast.Constant) for el in expr.elts)
    if isinstance(expr, ast.Dict):
        return all(isinstance(k, ast.Constant) for k in expr.keys)
    return False


def _key_origin(expr: ast.AST, binds: Dict[str, List[ast.AST]],
                module_binds: Dict[str, List[ast.AST]],
                params: Set[str], seen: Set[str]) -> str:
    """Происхождение ключа — до неподвижной точки, с ОБЪЯВЛЕННЫМ третьим исходом."""
    if isinstance(expr, ast.Constant):
        return KEY_LITERAL
    if _reads_data(expr):
        return KEY_ARTIFACT
    names = sorted({n.id for n in ast.walk(expr) if isinstance(n, ast.Name)})
    if not names:
        return KEY_UNRESOLVED
    verdicts: Set[str] = set()
    for name in names:
        if name in seen:
            continue
        if name in params:
            verdicts.add(KEY_UNRESOLVED)
            continue
        sources = binds.get(name) or module_binds.get(name) or []
        if not sources:
            verdicts.add(KEY_UNRESOLVED)
            continue
        for src in sources:
            if _literal_enumeration(src):
                verdicts.add(KEY_DECLARED)
                continue
            verdicts.add(_key_origin(src, binds, module_binds, params,
                                     seen | {name}))
    if KEY_ARTIFACT in verdicts:
        return KEY_ARTIFACT
    if KEY_UNRESOLVED in verdicts or not verdicts:
        return KEY_UNRESOLVED
    if verdicts == {KEY_LITERAL}:
        return KEY_LITERAL
    return KEY_DECLARED


def _membership_checked(fn: ast.AST, site: ast.AST, key: ast.AST) -> bool:
    """Сверен ли ключ принадлежностью к перечню ДО этого счётчика.

    Сторожем считается ТОЛЬКО проверка ``in``/``not in`` над самим ключом:

    * объемлющий ``if <ключ> in <перечень>``;
    * предшествующий в том же блоке ``if <ключ> not in <перечень>:`` с
      ``continue`` / ``return`` / ``raise`` в теле.

    **Предзаполнение словаря объявленным перечнем сторожем НЕ является** — и
    это не придирка: ровно так был устроен известный случай
    (``values = {cls: 0 for cls in _VALUE_OUTCOMES}`` рядом с
    ``values.get(outcome, 0)``), и перечень не помешал классу ``'None'``
    войти в счётчик.
    """
    key_dump = ast.dump(key)
    key_names = {n.id for n in ast.walk(key) if isinstance(n, ast.Name)}

    def _tests_key(test: ast.AST) -> bool:
        for node in ast.walk(test):
            if not isinstance(node, ast.Compare):
                continue
            if not any(isinstance(op, (ast.In, ast.NotIn))
                       for op in node.ops):
                continue
            left = node.left
            if ast.dump(left) == key_dump:
                return True
            if isinstance(left, ast.Name) and left.id in key_names:
                return True
        return False

    # --- родители и предшествующие братья ------------------------------
    parents: Dict[int, ast.AST] = {}
    for node in ast.walk(fn):
        for child in ast.iter_child_nodes(node):
            parents[id(child)] = node

    node: Optional[ast.AST] = site
    while node is not None:
        parent = parents.get(id(node))
        if isinstance(parent, ast.If) and node in parent.body:
            if _tests_key(parent.test):
                return True
        node = parent

    for block in ast.walk(fn):
        body = getattr(block, "body", None)
        if not isinstance(body, list):
            continue
        # индекс оператора, внутри которого лежит счётчик
        index = None
        for pos, stmt in enumerate(body):
            if any(sub is site for sub in ast.walk(stmt)):
                index = pos
                break
        if index is None:
            continue
        for stmt in body[:index]:
            if (isinstance(stmt, ast.If) and _tests_key(stmt.test)
                    and any(isinstance(inner, (ast.Continue, ast.Return,
                                               ast.Raise))
                            for inner in stmt.body)):
                return True
    return False


def _str_over_absence(expr: ast.AST, binds: Dict[str, List[ast.AST]],
                      seen: Set[str]) -> bool:
    """``str()`` ли поверх возможного отсутствия — третья половина заказа.

    Именно она заводит класс, БУКВАЛЬНО названный ``'None'``: ``str(None)``
    молча даёт строку, а строка молча становится именем исхода.
    """
    def _is_str_over_gap(node: ast.AST) -> bool:
        if not (isinstance(node, ast.Call) and isinstance(node.func, ast.Name)
                and node.func.id == "str" and node.args):
            return False
        for sub in ast.walk(node.args[0]):
            if isinstance(sub, ast.BoolOp) and isinstance(sub.op, ast.Or):
                return True
            if isinstance(sub, ast.Call):
                func = sub.func
                if isinstance(func, ast.Attribute) and func.attr == "get":
                    return True
                if (isinstance(func, ast.Name)
                        and func.id in OPEN_COUNTER_ARTIFACT_CALLS):
                    return True
            if isinstance(sub, ast.Subscript):
                return True
        return False

    for node in ast.walk(expr):
        if _is_str_over_gap(node):
            return True
    for name in sorted({n.id for n in ast.walk(expr)
                        if isinstance(n, ast.Name)}):
        if name in seen:
            continue
        for src in binds.get(name) or []:
            if _str_over_absence(src, binds, seen | {name}):
                return True
    return False


def _counter_owner_scopes(tree: ast.AST) -> Dict[int, ast.AST]:
    """Для каждого узла — БЛИЖАЙШАЯ объемлющая функция (или сам модуль).

    Имя НЕ `_enclosing_scope`: так уже зовётся сосед по модулю (строка ~5778),
    который отвечает на ДРУГОЙ вопрос — «как называется область на такой-то
    строке» — и берёт два аргумента. Второе определение того же имени молча
    победило бы первое, и сосед упал бы `TypeError` на живом дереве; так он и
    упал, пока имя было общим. Одно имя — один объект (`.claude/rules/adapters.md`).

    Обход модуля `ast.walk`-ом видит и тела функций, поэтому «разобрать
    сначала модуль, потом функции» привязало бы всякий счётчик к области
    МОДУЛЯ: параметры функции остались бы неизвестны, а связывания —
    общемодульными. Область считается ОДИН раз и от ближайшего родителя.
    """
    owner: Dict[int, ast.AST] = {}

    def _descend(node: ast.AST, scope: ast.AST) -> None:
        for child in ast.iter_child_nodes(node):
            inner = (child
                     if isinstance(child, (ast.FunctionDef,
                                           ast.AsyncFunctionDef))
                     else scope)
            owner[id(child)] = inner
            _descend(child, inner)

    owner[id(tree)] = tree
    _descend(tree, tree)
    return owner


def _open_counter_sites(rel: str, tree: ast.AST) -> List[dict]:
    """Все счётчики объявленных форм в одном разобранном файле."""
    module_binds = _scope_bindings(tree)
    owner_of = _counter_owner_scopes(tree)
    scope_cache: Dict[int, Tuple[Dict[str, List[ast.AST]], Set[str], str]] = {}

    def _scope_of(scope: ast.AST):
        cached = scope_cache.get(id(scope))
        if cached is not None:
            return cached
        if isinstance(scope, (ast.FunctionDef, ast.AsyncFunctionDef)):
            args = scope.args
            params = {a.arg for a in (list(args.posonlyargs) + list(args.args)
                                      + list(args.kwonlyargs))}
            if args.vararg:
                params.add(args.vararg.arg)
            if args.kwarg:
                params.add(args.kwarg.arg)
            made = (_scope_bindings(scope), params, scope.name)
        else:
            made = (module_binds, set(), "<module>")
        scope_cache[id(scope)] = made
        return made

    found: List[dict] = []
    for node in ast.walk(tree):
        shape = _counter_target_key(node)
        if shape is None:
            continue
        target, key, form = shape
        scope = owner_of.get(id(node), tree)
        binds, params, owner = _scope_of(scope)
        found.append({
            "file": rel,
            "line": getattr(node, "lineno", None),
            "owner": owner,
            "form": form,
            "counter": ast.unparse(target)[:60],
            "key": ast.unparse(key)[:60],
            "key_origin": _key_origin(key, binds, module_binds, params, set()),
            "membership_checked": _membership_checked(scope, node, key),
            "str_over_absence": _str_over_absence(key, binds, set()),
        })
    return sorted(found, key=lambda item: (item["file"], item["line"] or 0))


def _open_counter_control() -> dict:
    """Проба объявленного правила на УЖЕ ИЗВЕСТНОМ случае — до замера.

    Две половины, и вторая не есть украшение первой: правило обязано не только
    НАЙТИ известный счётчик, но и ПРОМАХНУТЬСЯ там, где промахнуться должно.
    Без второй «нашло 2» было бы неотличимо от «считает открытым что угодно».
    """
    try:
        hit = _open_counter_sites("<control>",
                                  ast.parse(OPEN_COUNTER_CONTROL_SOURCE))
        clean = _open_counter_sites("<control-clean>",
                                    ast.parse(OPEN_COUNTER_CONTROL_CLEAN))
    except SyntaxError as exc:
        return {"passed": False,
                "reason": f"сцена контроля не разобрана: {exc}"}
    open_hits = [s for s in hit
                 if s["key_origin"] == KEY_ARTIFACT
                 and not s["membership_checked"]]
    if len(open_hits) != 2:
        return {"passed": False, "found": len(hit), "open": len(open_hits),
                "reason": (f"правило нашло {len(open_hits)} открыт(ых) "
                           f"счётчик(ов) из 2 в ИЗВЕСТНОМ случае "
                           f"(ADR-459) — ноль от такой формы был бы "
                           f"свойством формы, а не населения")}
    if not all(s["str_over_absence"] for s in open_hits):
        return {"passed": False, "open": len(open_hits),
                "reason": ("в известном случае оба ключа приходят через "
                           "`str()` поверх возможного отсутствия, а правило "
                           "этого не увидело")}
    unchecked_clean = [s for s in clean
                       if s["key_origin"] == KEY_ARTIFACT
                       and not s["membership_checked"]]
    if unchecked_clean:
        return {"passed": False, "clean_false_positives": len(unchecked_clean),
                "reason": ("на отрицательной половине сцены (ключ из "
                           "объявленного перечня · ключ, сверенный "
                           "принадлежностью) правило объявило открытыми "
                           f"{len(unchecked_clean)} счётчик(ов)")}
    if not any(s["key_origin"] == KEY_DECLARED for s in clean):
        return {"passed": False,
                "reason": ("правило не признало КЛЮЧ ИЗ ОБЪЯВЛЕННОГО "
                           "ПЕРЕЧНЯ таковым ни разу — значит, «не открыт» "
                           "оно говорит по другой причине")}
    return {"passed": True, "known_case_open": len(open_hits),
            "clean_sites": len(clean),
            "clean_false_positives": 0}


def open_class_counter_census(root: Path) -> dict:
    """Сколько счётчиков открыто классу, которого никто не объявлял (**заказ G76 п. 1**).

    ADR-459 снял класс с ИМЕНЕМ ``'None'`` у одного поля одного прибора:
    ``reaches[reach] = reaches.get(reach, 0) + 1``, где ``reach`` приходил
    через ``str()`` поверх отсутствующего ключа. Вред лежал не в счётчике —
    ненаблюдённая достижимость молча проваливалась в «до вердикта не
    доходит», и шаг отвечал ``MEASURED`` вердиктом, на котором стоял весь
    вывод ADR-458. Население же класса не спросили ни разу.

    Заказ ставит вопрос дословно:

    > Сколько таких счётчиков в ``spa_core/monitoring`` и ``scripts``, у
    > скольких из них предшествует проверка принадлежности, и у скольких ключ
    > приходит через ``str()`` поверх возможного отсутствия.

    **Правило поиска объявлено ДО замера** (:func:`_counter_target_key`,
    :data:`OPEN_COUNTER_CONTROL_SOURCE`) и проверяется на уже известном
    случае ОБЕИМИ сторонами: обязано найти его и обязано промахнуться по
    счётчику с объявленным ключом. Контроль не прошёл ⇒ шаг ОТКАЗЫВАЕТ
    целиком: ноль, полученный формой, которая промахивается по известному
    случаю, есть свойство формы.

    Третий исход обязателен у ключа (``key_provenance_unresolved`` — НЕ
    «ключ безопасен») и у файла (не разобран — НЕ «счётчиков нет»).

    ADVISORY: ни одного счётчика не правит, ``applied`` ложно.
    """
    head = {
        "question": ("сколько счётчиков в объявленных каталогах открыто "
                     "классу, которого не объявлял никто, у скольких из них "
                     "ключ сверен принадлежностью и у скольких он приходит "
                     "через `str()` поверх возможного отсутствия"),
        "order": "G76.1",
        "applied": False,
        "dirs": list(OPEN_COUNTER_DIRS),
        "skipped_dirs": list(OPEN_COUNTER_SKIP),
        "forms": ["form_get: X[k] = X.get(k, D) + S",
                  "form_aug: X[k] += S"],
    }
    control = _open_counter_control()
    head["control"] = control
    if not control.get("passed"):
        return {**head, "status": "UNMEASURED",
                "unmeasured_class": UNMEASURED_CONTROL_MISSED,
                "reason": (f"объявленное правило поиска не прошло контроль на "
                           f"известном случае: {control.get('reason')}")}

    sites: List[dict] = []
    unreadable: List[dict] = []
    scanned = 0
    for sub in OPEN_COUNTER_DIRS:
        base = root / sub
        if not base.is_dir():
            unreadable.append({"file": sub, "reason": "каталога нет в дереве"})
            continue
        for path in sorted(base.rglob("*.py")):
            rel = path.relative_to(root).as_posix()
            if any(rel.startswith(skip) for skip in OPEN_COUNTER_SKIP):
                continue
            scanned += 1
            try:
                tree = ast.parse(path.read_text(encoding="utf-8"))
            except (OSError, SyntaxError, UnicodeDecodeError) as exc:
                unreadable.append({"file": rel,
                                   "reason": f"{type(exc).__name__}: {exc}"})
                continue
            sites.extend(_open_counter_sites(rel, tree))
    if not scanned:
        return {**head, "status": "UNMEASURED",
                "unmeasured_class": UNMEASURED_NO_TREE,
                "reason": (f"в {OPEN_COUNTER_DIRS} не разобран ни один файл — "
                           f"это НЕ «счётчиков нет»")}

    origins = {cls: 0 for cls in _KEY_OUTCOMES}
    for site in sites:
        origins[site["key_origin"]] = origins.get(site["key_origin"], 0) + 1
    from_artifact = [s for s in sites if s["key_origin"] == KEY_ARTIFACT]
    checked = [s for s in from_artifact if s["membership_checked"]]
    open_now = [s for s in from_artifact if not s["membership_checked"]]
    by_str = [s for s in open_now if s["str_over_absence"]]
    unresolved = [s for s in sites if s["key_origin"] == KEY_UNRESOLVED]

    if open_now:
        verdict = OPEN_COUNTER_FOUND
    elif from_artifact:
        verdict = OPEN_COUNTER_GUARDED
    else:
        verdict = OPEN_COUNTER_NONE
    return {
        **head,
        "status": "MEASURED",
        "verdict": verdict,
        "files_scanned": scanned,
        "files_unreadable": unreadable,
        "counters_total": len(sites),
        "by_form": {form: sum(1 for s in sites if s["form"] == form)
                    for form in ("form_get", "form_aug")},
        "key_origin_counts": origins,
        "key_from_artifact": len(from_artifact),
        "membership_checked": len(checked),
        "open_to_an_unnamed_class": len(open_now),
        "open_via_str_over_absence": len(by_str),
        "key_unresolved": len(unresolved),
        "open_sample": open_now[:COSTED_SAMPLE],
        "unresolved_sample": unresolved[:COSTED_SAMPLE],
        "blind": [
            ("форма `Counter(...)` / `.update(...)` над перечнем ключей "
             "ЗДЕСЬ НЕ ИЩЕТСЯ: правило объявлено двумя формами, и ненайденное "
             "третьей не есть ноль"),
            ("`form_aug` (`X[k] += S`) открыт не всегда — на голом `dict` он "
             "падает `KeyError`, а на `Counter`/`defaultdict` открыт так же; "
             "род накопителя здесь НЕ доказывается"),
            ("`membership_checked` ищет сверку ТОЛЬКО над самим ключом; "
             "предзаполнение словаря объявленным перечнем сторожем не "
             "считается намеренно — в известном случае оно было и не помогло"),
            (f"`{KEY_UNRESOLVED}` есть третий исход, а не «ключ безопасен»: "
             "происхождение ключа, собранного в рантайме, не разбирает "
             "никакой AST"),
            ("шаг НЕ доказывает, что открытый счётчик вредит СЕГОДНЯ: вред "
             "известного случая лежал не в счётчике, а у его читателя"),
        ],
    }


# ---------------------------------------------------------------------------
# ЧИТАТЕЛЬ ОТКРЫТОГО СЧЁТЧИКА — заказ G77 п. 1
# ---------------------------------------------------------------------------

#: Вердикт ЧИТАТЕЛЯ открытого счётчика. Три, и разделяет их не сила, а
#: ПРЕДМЕТ: «незнакомый класс молча становится другим исходом» и «незнакомый
#: класс — лишняя строка отчёта» суть разный ВРЕД при одной и той же
#: поверхности, а «читатель не измерен» не есть ни то, ни другое.
READER_SPLITS_DECLARED = "unknown_class_silently_becomes_another_outcome"
READER_WHOLESALE_ONLY = "unknown_class_is_only_an_extra_line"
READER_UNRESOLVED = "reader_of_the_counter_not_measured"
_READER_OUTCOMES = (READER_SPLITS_DECLARED, READER_WHOLESALE_ONLY,
                    READER_UNRESOLVED)

#: Почему читатель НЕ измерен. Имя у каждой причины своё: чинятся они разным —
#: убежавший счётчик требует межпроцедурного разбора, нечитаемый ключ —
#: расширения правила, а «чтения нет вовсе» не требует ничего, кроме честности.
READER_GAP_ESCAPES = "counter_leaves_its_scope_the_reader_lives_elsewhere"
READER_GAP_DYNAMIC = "counter_is_read_by_a_key_the_rule_cannot_resolve"
READER_GAP_NO_READ = "no_read_of_the_counter_inside_its_scope"
_READER_GAPS = (READER_GAP_ESCAPES, READER_GAP_DYNAMIC, READER_GAP_NO_READ)

#: ЧЕМ доказан раскол. Три формы, и они не равнозначны по силе доказательства:
#: первые две видны прямо у счётчика и у класса, третья держится на ОДНОМ
#: шаге переноса значения через поле — поэтому в отчёте они идут РАЗДЕЛЬНО, а
#: не одним числом.
SPLIT_AT_COUNTER = "counter_is_read_by_a_declared_key"
SPLIT_AT_CLASS = "class_value_is_compared_with_a_declared_class"
SPLIT_VIA_FIELD = "class_value_is_carried_by_a_field_and_compared_there"
_SPLIT_FORMS = (SPLIT_AT_COUNTER, SPLIT_AT_CLASS, SPLIT_VIA_FIELD)

#: Имена, чтение которыми есть чтение счётчика ЦЕЛИКОМ: незнакомый класс
#: проходит такого читателя лишней строкой и ничьего исхода не меняет.
READER_WHOLE_ATTRS = ("items", "keys", "values", "most_common", "copy")
READER_WHOLE_BUILTINS = ("sum", "len", "sorted", "dict", "list", "set",
                         "tuple", "any", "all", "max", "min", "reversed")

#: Отказы шага. Три, и каждый — не ноль.
UNMEASURED_READER_CENSUS = "open_counter_census_is_absent_or_unmeasured"
UNMEASURED_READER_POPULATION = "second_walk_disagrees_with_the_census"
UNMEASURED_READER_CONTROL = "declared_reader_rule_missed_the_known_case"

#: Сцена ПОЛОЖИТЕЛЬНОГО контроля читателя — ФОРМА известного случая
#: (`tail_value_divergence` до ADR-459). Дословной она быть НЕ МОЖЕТ по той же
#: причине, что и сцена соседа: отставленное имя `reach_outcome` сосед-сторож
#: в этом модуле запрещает, и возвращать его сюда ради буквальности значило бы
#: погасить чужого сторожа своей сценой.
#:
#: Воспроизводится то, что составляет ВРЕД, а не поверхность: у известного
#: случая класс `reach` ложился в открытый счётчик, уезжал полем `reach` в
#: список находок и ТАМ сравнивался с объявленным классом — после чего
#: незнакомая строка молча оказывалась «до вердикта не доходит». Рядом —
#: две более простые формы того же вреда: класс сравнён прямо по имени и
#: счётчик прочитан объявленным ключом. Правило обязано найти ВСЕ ТРИ.
READER_HARM_CONTROL_SOURCE = '''
REACH_LIVE = "live"
_VALUE_OUTCOMES = ("differ", "agree")


def scene(rows):
    values = {cls: 0 for cls in _VALUE_OUTCOMES}
    reaches = {}
    diverging = []
    for row in rows:
        for item in observed(row, "costed_all", kind=list):
            outcome = str(item.get("value_outcome"))
            values[outcome] = values.get(outcome, 0) + 1
            if outcome == "differ":
                diverging.append({"at": item.get("at"), "reach": reach})
            reach = str((item.get("reach_cell") or {}).get("reach"))
            reaches[reach] = reaches.get(reach, 0) + 1
    reaching = [d for d in diverging if d["reach"] == REACH_LIVE]
    return {"differing": values.get("differ", 0), "reaching": len(reaching)}
'''

#: Отрицательная половина той же сцены. Без неё «правило нашло раскол у всех
#: трёх» было бы неотличимо от «правило объявляет расколотым любой счётчик»:
#: два счётчика здесь открыты ровно так же, но их читатель НЕ делит класса —
#: один пробегает счётчик целиком в отчёт, второй счётчик из области УБЕГАЕТ
#: и его читатель этим шагом не измерен (третий исход, а не «вреда нет»).
READER_HARM_CONTROL_CLEAN = '''
def benign(rows, report):
    counts = {}
    for row in rows:
        cls = str(row.get("outcome"))
        counts[cls] = counts.get(cls, 0) + 1
    for name, hits in sorted(counts.items()):
        report.append(f"{name}: {hits}")
    return len(counts)


def escaping(rows):
    tally = {}
    for row in rows:
        cls = str(row.get("outcome"))
        tally[cls] = tally.get(cls, 0) + 1
    return {"tally": tally}
'''


def _declared_constant_names(tree: ast.AST) -> Set[str]:
    """Имена модуля, связанные КОНСТАНТОЙ или перечнем литералов.

    Плюс соглашение о ЗАГЛАВНЫХ: имя вида ``REACH_LIVE``, пришедшее импортом
    из соседнего модуля, здесь не разрешается — и не признать его объявленным
    классом значило бы ЗАНИЗИТЬ вред ровно на импортированных константах,
    которыми известный случай и пользовался. Соглашение названо вслух: это
    правило чтения имён, а не доказательство значения.
    """
    out: Set[str] = set()
    body = getattr(tree, "body", []) if isinstance(tree, ast.Module) else []
    for node in body:
        targets: List[ast.AST] = []
        value: Optional[ast.AST] = None
        if isinstance(node, ast.Assign):
            targets, value = list(node.targets), node.value
        elif isinstance(node, ast.AnnAssign) and node.value is not None:
            targets, value = [node.target], node.value
        if value is None:
            continue
        if not (isinstance(value, ast.Constant) or _literal_enumeration(value)):
            continue
        for tgt in targets:
            if isinstance(tgt, ast.Name):
                out.add(tgt.id)
    return out


def _is_declared_class(node: Optional[ast.AST], declared: Set[str]) -> bool:
    """Объявленный ли это класс: литерал, имя-константа модуля или ЗАГЛАВНОЕ имя."""
    if isinstance(node, ast.Constant):
        return isinstance(node.value, str)
    if isinstance(node, ast.Name):
        return node.id in declared or (node.id.isupper() and len(node.id) > 1)
    if isinstance(node, ast.Attribute):
        return node.attr in declared or (node.attr.isupper()
                                         and len(node.attr) > 1)
    return False


def _counter_write_nodes(scope: ast.AST, target_dump: str) -> Set[int]:
    """Узлы, принадлежащие ЗАПИСЯМ в тот же счётчик.

    Читателем запись не является, и это не мелочь: правая часть всякого
    счётчика содержит ``X.get(k, 0)``, а соседний счётчик того же словаря
    может писать литеральный класс (``X['total'] = X.get('total', 0) + 1``).
    Не исключив записи, шаг объявил бы «счётчик прочитан объявленным ключом»
    у всякого словаря, у которого есть хоть один литеральный счётчик, —
    то есть мерил бы ПИСАТЕЛЯ под именем читателя.
    """
    out: Set[int] = set()
    for node in ast.walk(scope):
        shape = _counter_target_key(node)
        if shape is None:
            continue
        if ast.dump(shape[0]) != target_dump:
            continue
        for sub in ast.walk(node):
            out.add(id(sub))
    return out


def _field_carriers(scope: ast.AST, key_dump: str,
                    key_names: Set[str]) -> Tuple[Set[str], Set[str]]:
    """Поля словарей-литералов, которыми класс УЕЗЖАЕТ из счётчика.

    Один шаг переноса и не больше: ``{"reach": reach}``. Возвращает
    ``(однозначные поля, неоднозначные поля)`` — поле, под которым в той же
    области лежит ЕЩЁ и другое значение, объявляется неоднозначным и вреда им
    не доказывают: связь идёт по ИМЕНИ ПОЛЯ, и на неоднозначном имени она
    приписала бы чужому сравнению наш класс.
    """
    carried: Dict[str, List[ast.AST]] = {}
    for node in ast.walk(scope):
        if not isinstance(node, ast.Dict):
            continue
        for field, value in zip(node.keys, node.values):
            if (isinstance(field, ast.Constant)
                    and isinstance(field.value, str)):
                carried.setdefault(field.value, []).append(value)
    ours: Set[str] = set()
    ambiguous: Set[str] = set()
    for field, values in carried.items():
        mine = [v for v in values
                if ast.dump(v) == key_dump
                or (isinstance(v, ast.Name) and v.id in key_names)]
        if not mine:
            continue
        if len({ast.dump(v) for v in values}) > 1:
            ambiguous.add(field)
        else:
            ours.add(field)
    return ours, ambiguous


def _key_literal_by_unpacking(scope: ast.AST, key: ast.AST) -> Optional[str]:
    """Не ЛИТЕРАЛ ли ключ на самом деле — разобранный кортежем.

    Найдено ЗАПУСКОМ, а не перечитыванием: сосед-перепись (ADR-460) связывает
    имя, разобранное кортежем, ВСЕЙ правой частью, а не своим элементом. У
    `bucket, why = "unmeasured", f"…{observed(doc, …)}"` ключ `bucket` есть
    литерал, но соседняя половина кортежа читает данные — и ключ объявляется
    пришедшим ИЗ АРТЕФАКТА. Это ровно тот класс, который ADR-460 поймал у
    себя внутри (ключ, связанный правой частью), одним уровнем выше: там
    правой частью была подписка, здесь — кортеж.

    Шаг соседа НЕ правится (его батарея 26/26 этой правкой не переделывается):
    класс НАЗВАН и померен, и число вреда печатается вместе с ним, чтобы
    читатель видел, на сколько оно завышено сверху.

    Возвращает ``"literal_by_unpacking"``, если ВСЕ связывания имени в области
    суть распаковка кортежа с КОНСТАНТОЙ на месте ключа; ``"mixed"``, если
    такие связывания есть, но не все; ``None``, если их нет вовсе.
    """
    if not isinstance(key, ast.Name):
        return None
    name = key.id
    literal_bindings = 0
    other_bindings = 0
    for node in ast.walk(scope):
        targets: List[ast.AST] = []
        value: Optional[ast.AST] = None
        if isinstance(node, ast.Assign):
            targets, value = list(node.targets), node.value
        elif isinstance(node, (ast.AnnAssign, ast.AugAssign)):
            targets, value = [node.target], node.value
        elif isinstance(node, (ast.For, ast.AsyncFor)):
            targets, value = [node.target], node.iter
        if value is None:
            continue
        for tgt in targets:
            if isinstance(tgt, ast.Name) and tgt.id == name:
                other_bindings += 1
                continue
            if not isinstance(tgt, (ast.Tuple, ast.List)):
                continue
            for pos, element in enumerate(tgt.elts):
                if not (isinstance(element, ast.Name) and element.id == name):
                    continue
                if (isinstance(value, (ast.Tuple, ast.List))
                        and pos < len(value.elts)
                        and isinstance(value.elts[pos], ast.Constant)):
                    literal_bindings += 1
                else:
                    other_bindings += 1
    if not literal_bindings:
        return None
    return "literal_by_unpacking" if not other_bindings else "mixed"


WHOLE_USE_WHOLESALE = "wholesale"
WHOLE_USE_ESCAPE = "escape"


def _counter_whole_use(node: ast.AST,
                       parent: Optional[ast.AST]) -> Optional[str]:
    """Счётчик ушёл ЦЕЛИКОМ — пробегом или побегом. Одно правило — одна копия.

    Выделено из :func:`_counter_reader_touches` заказом G78 п. 1 БЕЗ смены
    поведения: тот же вопрос («счётчик ушёл целиком — куда?») задаёт и шаг
    одного межпроцедурного разбора, а вторая копия правила внутри прибора,
    который ищет вторые копии правил, — дефект, уже дважды случившийся в этом
    файле (ADR-460 поймал его у подписки, ADR-461 у кортежа).

    ``None`` — использование счётчиком целиком НЕ является: запись, чтение
    подпиской или обращение к полю разбираются раньше и своими ветками.
    """
    if isinstance(node, ast.expr) and not isinstance(
            getattr(node, "ctx", ast.Load()), ast.Load):
        return None
    if parent is None:
        return None
    if isinstance(parent, (ast.Subscript, ast.Attribute)):
        return None
    if isinstance(parent, ast.Call):
        func = parent.func
        if isinstance(func, ast.Name) and func.id in READER_WHOLE_BUILTINS:
            return WHOLE_USE_WHOLESALE
        return WHOLE_USE_ESCAPE
    if isinstance(parent, (ast.For, ast.AsyncFor)) and parent.iter is node:
        return WHOLE_USE_WHOLESALE
    if isinstance(parent, ast.comprehension) and parent.iter is node:
        return WHOLE_USE_WHOLESALE
    if isinstance(parent, ast.Compare) and any(
            isinstance(op, (ast.In, ast.NotIn)) for op in parent.ops):
        return WHOLE_USE_WHOLESALE
    return WHOLE_USE_ESCAPE


def _counter_reader_touches(scope: ast.AST, target: ast.AST, key: ast.AST,
                            declared: Set[str]) -> dict:
    """Читатели ОДНОГО открытого счётчика внутри его области.

    Правило объявлено здесь, до замера, и проверяется обеими половинами
    (:func:`_reader_harm_control`). Односторонность названа: шаг доказывает
    РАСКОЛ, а «раскола не нашли» не есть «раскола нет» — потому и третий исход
    отдельным вердиктом, а не тихим зачислением в безвредные.
    """
    target_dump = ast.dump(target)
    key_dump = ast.dump(key)
    key_names = {n.id for n in ast.walk(key) if isinstance(n, ast.Name)}
    written = _counter_write_nodes(scope, target_dump)
    parents = _parent_map(scope)
    fields, ambiguous_fields = _field_carriers(scope, key_dump, key_names)

    splits: List[dict] = []
    wholesale: List[int] = []
    dynamic: List[int] = []
    escapes: List[int] = []

    def _at(node: ast.AST) -> int:
        return int(getattr(node, "lineno", 0) or 0)

    def _split(form: str, node: ast.AST, how: str) -> None:
        splits.append({"form": form, "line": _at(node), "how": how})

    def _same_key(node: Optional[ast.AST]) -> bool:
        if node is None:
            return False
        if ast.dump(node) == key_dump:
            return True
        return isinstance(node, ast.Name) and node.id in key_names

    for node in ast.walk(scope):
        if id(node) in written:
            continue
        # --- чтение самого счётчика -----------------------------------
        if (isinstance(node, ast.Subscript)
                and ast.dump(node.value) == target_dump
                and isinstance(node.ctx, ast.Load)):
            if _is_declared_class(node.slice, declared):
                _split(SPLIT_AT_COUNTER, node, ast.unparse(node)[:60])
            else:
                dynamic.append(_at(node))
            continue
        if (isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute)
                and ast.dump(node.func.value) == target_dump):
            attr = node.func.attr
            if attr == "get":
                first = node.args[0] if node.args else None
                if _is_declared_class(first, declared):
                    _split(SPLIT_AT_COUNTER, node, ast.unparse(node)[:60])
                else:
                    dynamic.append(_at(node))
            elif attr in READER_WHOLE_ATTRS:
                wholesale.append(_at(node))
            else:
                dynamic.append(_at(node))
            continue
        # --- сравнение самого КЛАССА с объявленным --------------------
        if isinstance(node, ast.Compare) and any(
                isinstance(op, (ast.Eq, ast.NotEq)) for op in node.ops):
            sides = [node.left] + list(node.comparators)
            for pos, side in enumerate(sides):
                if not _same_key(side):
                    continue
                others = [s for idx, s in enumerate(sides) if idx != pos]
                if any(_is_declared_class(other, declared) for other in others):
                    _split(SPLIT_AT_CLASS, node, ast.unparse(node)[:60])
                    break
            else:
                # --- класс уехал ПОЛЕМ и сравнивается там -------------
                for pos, side in enumerate(sides):
                    field = _field_read(side)
                    if field is None or field not in fields:
                        continue
                    others = [s for idx, s in enumerate(sides) if idx != pos]
                    if any(_is_declared_class(o, declared) for o in others):
                        _split(SPLIT_VIA_FIELD, node, ast.unparse(node)[:60])
                        break
            continue
        # --- счётчик целиком ------------------------------------------
        if ast.dump(node) != target_dump:
            continue
        use = _counter_whole_use(node, parents.get(id(node)))
        if use == WHOLE_USE_WHOLESALE:
            wholesale.append(_at(node))
        elif use == WHOLE_USE_ESCAPE:
            escapes.append(_at(node))

    if splits:
        verdict, gap = READER_SPLITS_DECLARED, None
    elif escapes:
        verdict, gap = READER_UNRESOLVED, READER_GAP_ESCAPES
    elif dynamic:
        verdict, gap = READER_UNRESOLVED, READER_GAP_DYNAMIC
    elif wholesale:
        verdict, gap = READER_WHOLESALE_ONLY, None
    else:
        verdict, gap = READER_UNRESOLVED, READER_GAP_NO_READ
    return {
        "verdict": verdict,
        "gap": gap,
        "splits": splits,
        "split_forms": sorted({s["form"] for s in splits}),
        "wholesale_reads": len(wholesale),
        "dynamic_reads": len(dynamic),
        "escapes": len(escapes),
        "ambiguous_fields": sorted(ambiguous_fields),
    }


def _field_read(node: ast.AST) -> Optional[str]:
    """Имя поля, если выражение есть чтение ``X['поле']`` или ``X.get('поле')``."""
    if isinstance(node, ast.Subscript) and isinstance(node.slice, ast.Constant):
        if isinstance(node.slice.value, str):
            return node.slice.value
        return None
    if (isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute)
            and node.func.attr == "get" and node.args
            and isinstance(node.args[0], ast.Constant)
            and isinstance(node.args[0].value, str)):
        return node.args[0].value
    return None


def _reader_sites(rel: str, tree: ast.AST) -> List[dict]:
    """Открытые счётчики ОДНОГО файла вместе с вердиктом их читателя.

    Тонкая обёртка над :func:`_reader_site_nodes`: строки те же, узлы
    отброшены. Обход ОДИН, читателей у него два — сосед G77 берёт строки,
    шаг одного межпроцедурного разбора (G78 п. 1) берёт ещё и узлы.
    """
    return [site for site, _t, _k, _s in _reader_site_nodes(rel, tree)]


def _reader_site_nodes(
        rel: str, tree: ast.AST
) -> Iterable[Tuple[dict, Optional[ast.AST], Optional[ast.AST],
                    Optional[ast.AST]]]:
    """То же, что :func:`_reader_sites`, но с УЗЛАМИ счётчика: строка, цель,
    ключ, область. Узлы нужны шагу одного межпроцедурного разбора, и добывать
    их вторым обходом значило бы завести вторую копию правила.

    Население берётся у соседа (:func:`_open_counter_sites`) — второй копии
    правила «какой счётчик открыт» здесь НЕТ и быть не должно: шаг спрашивает
    про ЧИТАТЕЛЯ, а не про счётчик. Узел счётчика доискивается по той же
    объявленной форме (:func:`_counter_target_key`) и сверяется со строкой и
    ключом, названными соседом; не сошлось — счётчик уходит третьим исходом,
    а не пропадает.
    """
    population = [s for s in _open_counter_sites(rel, tree)
                  if s["key_origin"] == KEY_ARTIFACT
                  and not s["membership_checked"]]
    if not population:
        return
    declared = _declared_constant_names(tree)
    owner_of = _counter_owner_scopes(tree)
    by_line: Dict[Tuple[int, str], Tuple[ast.AST, ast.AST, ast.AST]] = {}
    for node in ast.walk(tree):
        shape = _counter_target_key(node)
        if shape is None:
            continue
        line = int(getattr(node, "lineno", 0) or 0)
        by_line[(line, ast.unparse(shape[1])[:60])] = (node, shape[0], shape[1])

    for site in population:
        found = by_line.get((int(site["line"] or 0), site["key"]))
        if found is None:
            yield ({**site, "verdict": READER_UNRESOLVED,
                    "gap": READER_GAP_NO_READ,
                    "reason": ("узел счётчика не найден по строке и ключу "
                               "соседа — читатель НЕ измерен"),
                    "splits": [], "split_forms": [],
                    "key_literal_by_unpacking": None,
                    "wholesale_reads": 0, "dynamic_reads": 0,
                    "escapes": 0, "ambiguous_fields": []},
                   None, None, None)
            continue
        node, target, key = found
        scope = owner_of.get(id(node), tree)
        yield ({**site,
                "key_literal_by_unpacking": _key_literal_by_unpacking(
                    scope, key),
                **_counter_reader_touches(scope, target, key, declared)},
               target, key, scope)


def _reader_harm_control() -> dict:
    """Проба объявленного правила читателя на ИЗВЕСТНОМ случае — до замера.

    Половин две, и вторая не есть украшение первой. Первая требует найти вред
    во ВСЕХ ТРЁХ формах (у счётчика, у класса, через поле). Вторая требует
    ПРОМАХНУТЬСЯ там, где промахнуться должно: счётчик, пробегаемый целиком в
    отчёт, вредным не объявляется, а счётчик, УБЕГАЮЩИЙ из области, не
    объявляется ни вредным, ни безвредным — его читатель не измерен.

    Любая половина не сошлась ⇒ шаг ОТКАЗЫВАЕТ целиком: число, полученное
    правилом, которое промахивается по известному случаю, есть свойство
    ПРАВИЛА, а не населения.
    """
    try:
        harm = _reader_sites("<control>",
                             ast.parse(READER_HARM_CONTROL_SOURCE))
        clean = _reader_sites("<control-clean>",
                              ast.parse(READER_HARM_CONTROL_CLEAN))
    except SyntaxError as exc:
        return {"passed": False,
                "reason": f"сцена контроля не разобрана: {exc}"}
    if len(harm) != 2:
        return {"passed": False, "reason": (
            f"в сцене известного случая правило нашло {len(harm)} открыт(ых) "
            f"счётчик(ов) из 2 — читателя мерить не у чего")}
    split = [s for s in harm if s["verdict"] == READER_SPLITS_DECLARED]
    if len(split) != 2:
        return {"passed": False, "reason": (
            f"раскол доказан у {len(split)} из 2 счётчиков известного случая: "
            f"вердикты {[s['verdict'] for s in harm]}")}
    forms = sorted({form for s in split for form in s["split_forms"]})
    if sorted(_SPLIT_FORMS) != forms:
        return {"passed": False, "forms": forms, "reason": (
            f"правило доказало раскол формами {forms}, а известный случай "
            f"несёт все три: {sorted(_SPLIT_FORMS)} — ненайденная форма есть "
            f"слепота правила, а не отсутствие вреда")}
    if len(clean) != 2:
        return {"passed": False, "reason": (
            f"в отрицательной половине сцены правило нашло {len(clean)} "
            f"открыт(ых) счётчик(ов) из 2")}
    benign = [s for s in clean if s["verdict"] == READER_WHOLESALE_ONLY]
    gone = [s for s in clean if s["gap"] == READER_GAP_ESCAPES]
    if len(benign) != 1 or len(gone) != 1:
        return {"passed": False, "reason": (
            f"на отрицательной половине сцены ожидались один безвредный "
            f"читатель и один убежавший счётчик, а вышло "
            f"{[(s['verdict'], s['gap']) for s in clean]}")}
    return {"passed": True, "known_case_split": len(split),
            "split_forms": forms, "clean_false_harm": 0,
            "clean_sites": len(clean)}


def open_counter_reader_harm(root: Path,
                             opened: Optional[dict]) -> dict:
    """У скольких открытых счётчиков ЧИТАТЕЛЬ делит класс (**заказ G77 п. 1**).

    ADR-460 померил ПОВЕРХНОСТЬ: 158 счётчиков открыты классу, которого никто
    не объявлял. Вреда это не доказывает и шаг соседа говорит это вслух: у
    известного случая (ADR-459) вред лежал не в счётчике, а у его ЧИТАТЕЛЯ —
    ``reaching`` считал только ``REACH_LIVE``, и незнакомый класс молча
    оказывался в другом исходе, а не лишней строкой отчёта.

    Заказ ставит вопрос дословно:

    > У скольких из 158 есть читатель, который делит счётчик по ОБЪЯВЛЕННЫМ
    > классам — то есть у скольких незнакомый класс молча становится другим
    > исходом. Ответ обязан быть замером ЧИТАТЕЛЯ, а не счётчика.

    Население берётся у соседа и СВЕРЯЕТСЯ с его числом: свой обход — вторая
    дорога к тому же населению, и разойдясь с первой, он отвечал бы на другой
    вопрос. Разошлись ⇒ шаг ОТКАЗЫВАЕТ (``UNMEASURED``), а не выбирает себе
    удобное число.

    Третий исход обязателен и у читателя: счётчик, убежавший из области,
    прочитанный неразрешимым ключом или не прочитанный в своей области вовсе,
    есть **читатель НЕ ИЗМЕРЕН**, а не «вреда нет».

    ADVISORY: ни одного счётчика и ни одного читателя не правит,
    ``applied`` ложно.
    """
    head = {
        "question": ("у скольких открытых счётчиков есть читатель, у которого "
                     "незнакомый класс молча становится ДРУГИМ ИСХОДОМ, а не "
                     "лишней строкой отчёта"),
        "order": "G77.1",
        "applied": False,
        "dirs": list(OPEN_COUNTER_DIRS),
        "skipped_dirs": list(OPEN_COUNTER_SKIP),
    }
    if not isinstance(opened, dict) or str(opened.get("status")) != "MEASURED":
        return {**head, "status": "UNMEASURED",
                "unmeasured_class": UNMEASURED_READER_CENSUS,
                "reason": ("перепись открытых счётчиков не измерена — мерить "
                           "читателя не у чего; это НЕ «вредных читателей нет»")}
    declared_population = observed(opened, "open_to_an_unnamed_class", kind=int)
    if declared_population is None:
        return {**head, "status": "UNMEASURED",
                "unmeasured_class": UNMEASURED_READER_CENSUS,
                "reason": ("сосед не назвал числа открытых счётчиков — "
                           "сверять свой обход не с чем")}
    control = _reader_harm_control()
    head["control"] = control
    if not control.get("passed"):
        return {**head, "status": "UNMEASURED",
                "unmeasured_class": UNMEASURED_READER_CONTROL,
                "reason": (f"объявленное правило читателя не прошло контроль "
                           f"на известном случае: {control.get('reason')}")}

    rows: List[dict] = []
    unreadable: List[dict] = []
    scanned = 0
    for sub in OPEN_COUNTER_DIRS:
        base = root / sub
        if not base.is_dir():
            unreadable.append({"file": sub, "reason": "каталога нет в дереве"})
            continue
        for path in sorted(base.rglob("*.py")):
            rel = path.relative_to(root).as_posix()
            if any(rel.startswith(skip) for skip in OPEN_COUNTER_SKIP):
                continue
            scanned += 1
            try:
                tree = ast.parse(path.read_text(encoding="utf-8"))
            except (OSError, SyntaxError, UnicodeDecodeError) as exc:
                unreadable.append({"file": rel,
                                   "reason": f"{type(exc).__name__}: {exc}"})
                continue
            rows.extend(_reader_sites(rel, tree))

    if len(rows) != declared_population:
        return {**head, "status": "UNMEASURED",
                "unmeasured_class": UNMEASURED_READER_POPULATION,
                "walked": len(rows), "census": declared_population,
                "files_unreadable": unreadable,
                "reason": (f"свой обход нашёл {len(rows)} открыт(ых) "
                           f"счётчик(ов), сосед — {declared_population}: "
                           f"замер читателя по ДРУГОМУ населению отвечал бы "
                           f"на другой вопрос")}

    verdicts = {cls: sum(1 for r in rows if r["verdict"] == cls)
                for cls in _READER_OUTCOMES}
    gaps = {gap: sum(1 for r in rows if r.get("gap") == gap)
            for gap in _READER_GAPS}
    by_form = {form: sum(1 for r in rows if form in (r.get("split_forms") or []))
               for form in _SPLIT_FORMS}
    harmed = [r for r in rows if r["verdict"] == READER_SPLITS_DECLARED]
    ambiguous = [r for r in rows if r.get("ambiguous_fields")]
    # Завышение НАСЕЛЕНИЯ соседом, найденное запуском этого шага: ключ,
    # разобранный кортежем, есть литерал, а сосед зовёт его артефактным.
    # Число вреда печатается ВМЕСТЕ с ним — иначе читатель принял бы потолок
    # за замер.
    unpacked = [r for r in rows
                if r.get("key_literal_by_unpacking") == "literal_by_unpacking"]
    unpacked_harmed = [r for r in harmed
                       if r.get("key_literal_by_unpacking")
                       == "literal_by_unpacking"]
    return {
        **head,
        "status": "MEASURED",
        "population": len(rows),
        "files_scanned": scanned,
        "files_unreadable": unreadable,
        "reader_verdicts": verdicts,
        "unmeasured_reader_reasons": gaps,
        "split_by_form": by_form,
        "splits_only_via_field": sum(
            1 for r in harmed if r["split_forms"] == [SPLIT_VIA_FIELD]),
        "ambiguous_field_sites": len(ambiguous),
        "census_key_literal_by_unpacking": len(unpacked),
        "harm_on_a_key_that_is_a_literal": len(unpacked_harmed),
        "harm_net_of_unpacking": len(harmed) - len(unpacked_harmed),
        "harm_sample": [
            {"file": r["file"], "line": r["line"], "owner": r["owner"],
             "counter": r["counter"], "key": r["key"],
             "forms": r["split_forms"],
             "split": (r["splits"] or [{}])[0].get("how")}
            for r in harmed[:COSTED_SAMPLE]],
        "unresolved_sample": [
            {"file": r["file"], "line": r["line"], "owner": r["owner"],
             "counter": r["counter"], "gap": r.get("gap")}
            for r in rows
            if r["verdict"] == READER_UNRESOLVED][:COSTED_SAMPLE],
        "blind": [
            (f"население взято у соседа и завышено СВЕРХУ: у "
             f"{len(unpacked)} счётчик(ов) ключ на деле ЛИТЕРАЛ, разобранный "
             f"кортежем, — сосед связывает имя всей правой частью (ADR-460 "
             f"поймал тот же класс у себя внутри, здесь он уровнем выше); "
             f"из них с доказанным расколом {len(unpacked_harmed)}"),
            ("шаг доказывает РАСКОЛ, а не его отсутствие: свидетель "
             "односторонний, и «раскола не нашли» уходит третьим исходом, "
             "а не в безвредные"),
            ("читатель ищется ВНУТРИ области счётчика: счётчик, убежавший "
             "возвратом или аргументом, уходит в "
             f"`{READER_GAP_ESCAPES}` — межпроцедурного разбора здесь НЕТ"),
            ("объявленным классом считается литерал, имя-константа модуля "
             "или ЗАГЛАВНОЕ имя; имя, разрешаемое только импортом, сильнее "
             "соглашения о заглавных здесь не разбирается"),
            ("перенос класса ПОЛЕМ — ровно ОДИН шаг (`{'поле': класс}`), и "
             "поле, под которым в той же области лежит ещё и другое "
             "значение, вредом НЕ считается: связь идёт по имени поля"),
            ("`match`/`case` над классом и сравнение через `startswith`/"
             "регулярное выражение правилом не разбираются — их население "
             "НЕ ИЗМЕРЕНО"),
        ],
    }


# ---------------------------------------------------------------------------
# ОДИН ШАГ МЕЖПРОЦЕДУРНОГО РАЗБОРА У УБЕЖАВШЕГО СЧЁТЧИКА (заказ G78 п. 1)
# ---------------------------------------------------------------------------

#: КУДА уезжает счётчик. Маршрут — не украшение вердикта: возврат и аргумент
#: разрешаются ОДНИМ шагом, контейнер и чужой вызов — нет, и чинятся они
#: разным. Слить их в одно «убежал» значило бы вернуть тот самый счётчик,
#: открытый любой строке, ради которого весь ряд ADR-459…461 и написан.
ROUTE_RETURNED = "counter_is_returned_from_its_scope"
ROUTE_ARGUMENT_LOCAL = "counter_is_passed_to_a_function_defined_in_this_file"
ROUTE_ARGUMENT_FOREIGN = "counter_is_passed_to_a_callee_this_file_does_not_define"
ROUTE_CONTAINER = "counter_is_placed_inside_a_container_first"
#: Счётчик НЕ УЕХАЛ НИКУДА: его целиком проверили на истинность или напечатали
#: в строку. Найдено ЗАПУСКОМ, а не перечитыванием: правило соседа перечисляет
#: пробег поимённо (`for`, `in`, `items()`, builtins) и всякое ОСТАЛЬНОЕ
#: использование целиком зовёт побегом — поэтому `if not counts:` и
#: `f"{counts}"` попали в класс «убежал из области». Это завышает соседское
#: население СВЕРХУ, и число печатается рядом с ним, а не вместо него.
ROUTE_NOT_A_DEPARTURE = "counter_does_not_leave_the_scope_at_all"
ROUTE_UNKNOWN = "escape_route_unrecognised"
_ESCAPE_ROUTES = (ROUTE_RETURNED, ROUTE_ARGUMENT_LOCAL,
                  ROUTE_ARGUMENT_FOREIGN, ROUTE_CONTAINER,
                  ROUTE_NOT_A_DEPARTURE, ROUTE_UNKNOWN)

#: Исход ОДНОГО шага. Третий исход здесь не «остаток», а ГЛАВНЫЙ ответ заказа:
#: вопрос стоял «сколько разрешимо одним шагом», и назвать неразрешённое
#: безвредным значило бы выдать НЕ ИЗМЕРЕНО за измеренный исход (инв. #17).
ONE_STEP_SPLITS = "one_step_reaches_a_reader_that_splits_the_class"
ONE_STEP_WHOLESALE = "one_step_reaches_only_wholesale_readers"
ONE_STEP_UNRESOLVED = "one_step_does_not_reach_a_reader"
_ONE_STEP_OUTCOMES = (ONE_STEP_SPLITS, ONE_STEP_WHOLESALE, ONE_STEP_UNRESOLVED)

#: ПОЧЕМУ один шаг не дошёл. Имя у каждой причины своё — чинятся они разным:
#: контейнеру нужен ещё один разбор (переноса полем), чужому вызову — разбор
#: импортов, «зовущего нет в этом файле» — обход всего дерева, а
#: `escapes_again` не чинится вовсе одним шагом: счётчик уехал ДАЛЬШЕ.
STEP_GAP_CONTAINER = "counter_travels_by_a_field_before_it_travels_by_a_call"
STEP_GAP_FOREIGN_CALLEE = "callee_is_not_defined_in_this_file"
STEP_GAP_AMBIGUOUS_CALLEE = "callee_name_is_defined_more_than_once_in_this_file"
STEP_GAP_NO_CALLER = "no_caller_of_the_scope_in_this_file"
STEP_GAP_RESULT_UNBOUND = "returned_value_is_not_bound_to_a_name"
STEP_GAP_ARG_UNMAPPED = "argument_does_not_map_to_a_parameter"
STEP_GAP_ESCAPES_AGAIN = "counter_escapes_again_at_the_next_scope"
STEP_GAP_NO_READ = "next_scope_never_reads_the_counter"
STEP_GAP_NOT_A_DEPARTURE = "counter_is_used_whole_without_leaving_its_scope"
STEP_GAP_ROUTE_UNKNOWN = "escape_route_unrecognised"
STEP_GAP_SITES_DISAGREE = "escape_sites_disagree_with_the_reader_rule"
_STEP_GAPS = (STEP_GAP_CONTAINER, STEP_GAP_FOREIGN_CALLEE,
              STEP_GAP_AMBIGUOUS_CALLEE, STEP_GAP_NO_CALLER,
              STEP_GAP_RESULT_UNBOUND, STEP_GAP_ARG_UNMAPPED,
              STEP_GAP_ESCAPES_AGAIN, STEP_GAP_NO_READ,
              STEP_GAP_NOT_A_DEPARTURE,
              STEP_GAP_ROUTE_UNKNOWN, STEP_GAP_SITES_DISAGREE,
              READER_GAP_DYNAMIC)

#: Отказы шага. Три, и ни один не есть ноль.
UNMEASURED_STEP_HARM = "reader_harm_is_absent_or_unmeasured"
UNMEASURED_STEP_POPULATION = "second_walk_disagrees_with_the_escape_census"
UNMEASURED_STEP_CONTROL = "declared_one_step_rule_missed_the_known_case"

#: ПОЛОЖИТЕЛЬНАЯ половина контроля — обе разрешимые формы побега сразу.
#: Счётчик здесь открыт ровно так же, как у соседа (ключ из артефакта, без
#: сверки принадлежностью), убегает из своей области — и ОДИН шаг обязан
#: дойти до читателя, который делит класс объявленным ключом. Форм две, и
#: правило обязано доказать ОБЕ: найдя одну, оно ответило бы на половину
#: вопроса заказа, а число выдало бы за полный ответ.
ONE_STEP_CONTROL_SOURCE = '''
REACH_LIVE = "live"


def tally(rows):
    counts = {}
    for row in rows:
        cls = str(row.get("reach"))
        counts[cls] = counts.get(cls, 0) + 1
    return counts


def verdict(rows):
    totals = tally(rows)
    return totals[REACH_LIVE] > 0


def handed(rows):
    seen = {}
    for row in rows:
        cls = str(row.get("reach"))
        seen[cls] = seen.get(cls, 0) + 1
    return judge(seen)


def judge(counted):
    return counted.get(REACH_LIVE, 0)
'''

#: ОТРИЦАТЕЛЬНАЯ половина. Без неё «шаг разрешил всё» было бы неотличимо от
#: «шаг объявляет разрешённым что угодно». ПЯТЬ счётчиков числятся у соседа
#: убежавшими одинаково, и шаг обязан развести их ЧЕТЫРЬМЯ разными исходами:
#: одному довести читателя (пробег целиком — безвредно), одному отказать
#: «уехал сперва полем», одному — «зовомого этот файл не определяет», одному —
#: «никуда не уехал вовсе» (истинность и f-строка), а ПЯТЫЙ (`spread or {}`)
#: уезжает по-настоящему и обязан остаться НЕРАЗОБРАННЫМ: приняв его за
#: «никуда не уехал», правило спрятало бы настоящий побег под новым именем.
#: Отказ, слитый с «безвредно», и есть та самая подмена третьего исхода.
ONE_STEP_CONTROL_CLEAN = '''
def boxed(rows):
    tally = {}
    for row in rows:
        cls = str(row.get("outcome"))
        tally[cls] = tally.get(cls, 0) + 1
    return {"tally": tally}


def shipped(rows):
    counts = {}
    for row in rows:
        cls = str(row.get("outcome"))
        counts[cls] = counts.get(cls, 0) + 1
    publish(counts)


def printed(rows):
    seen = {}
    for row in rows:
        cls = str(row.get("outcome"))
        seen[cls] = seen.get(cls, 0) + 1
    return listed(seen)


def listed(counted):
    return sorted(counted.items())


def tested(rows):
    kinds = {}
    for row in rows:
        cls = str(row.get("outcome"))
        kinds[cls] = kinds.get(cls, 0) + 1
    if not kinds:
        return "пусто"
    return f"классов: {kinds}"


def defaulted(rows):
    spread = {}
    for row in rows:
        cls = str(row.get("outcome"))
        spread[cls] = spread.get(cls, 0) + 1
    return spread or {}
'''


def _module_function_defs(tree: ast.AST) -> Dict[str, List[ast.AST]]:
    """Функции файла по имени — СПИСКОМ, а не одной.

    Имя, определённое в файле дважды, разрешать нельзя: «какое из двух»
    есть третий исход, а не выбор. Молчаливый выбор первого дал бы читателя,
    которого на этом пути может не быть вовсе.
    """
    out: Dict[str, List[ast.AST]] = {}
    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            out.setdefault(node.name, []).append(node)
    return out


def _escape_sites(scope: ast.AST, target: ast.AST) -> List[ast.AST]:
    """Узлы, которыми счётчик УБЕГАЕТ из своей области.

    Правило побега здесь НЕ переписано: зовётся тот же
    :func:`_counter_whole_use`, которым отвечает сосед. Вторая копия правила
    внутри прибора, который ищет вторые копии правил, — дефект, уже дважды
    случившийся в этом файле (ADR-460 у подписки, ADR-461 у кортежа), и
    третьего раза здесь не будет.
    """
    target_dump = ast.dump(target)
    written = _counter_write_nodes(scope, target_dump)
    parents = _parent_map(scope)
    out: List[ast.AST] = []
    for node in ast.walk(scope):
        if id(node) in written:
            continue
        if ast.dump(node) != target_dump:
            continue
        if _counter_whole_use(node, parents.get(id(node))) == WHOLE_USE_ESCAPE:
            out.append(node)
    return out


def _callee_name(func: ast.AST) -> str:
    try:
        return ast.unparse(func)[:60]
    except Exception:  # pragma: no cover — на разобранном дереве не случается
        return "<не разобран>"


def _escape_route(node: ast.AST, parents: Dict[int, ast.AST],
                  defs: Dict[str, List[ast.AST]]) -> dict:
    """Каким маршрутом счётчик покинул область. Маршрут ОБЪЯВЛЕН, не угадан."""
    parent = parents.get(id(node))
    if isinstance(parent, ast.Return) and parent.value is node:
        return {"route": ROUTE_RETURNED}
    call: Optional[ast.AST] = None
    position: Optional[int] = None
    keyword: Optional[str] = None
    if isinstance(parent, ast.Call):
        args = list(parent.args)
        for idx, arg in enumerate(args):
            if arg is node:
                call, position = parent, idx
                break
    elif isinstance(parent, ast.keyword) and parent.value is node:
        grand = parents.get(id(parent))
        if isinstance(grand, ast.Call):
            call, keyword = grand, parent.arg
    if call is not None:
        func = call.func
        name = func.id if isinstance(func, ast.Name) else None
        found = defs.get(name or "", [])
        if name is None or not found:
            return {"route": ROUTE_ARGUMENT_FOREIGN,
                    "callee": _callee_name(func)}
        if len(found) > 1:
            return {"route": ROUTE_ARGUMENT_FOREIGN, "callee": name,
                    "ambiguous": True}
        return {"route": ROUTE_ARGUMENT_LOCAL, "callee": name,
                "callee_def": found[0], "position": position,
                "keyword": keyword}
    if isinstance(parent, ast.FormattedValue):
        return {"route": ROUTE_NOT_A_DEPARTURE}
    if isinstance(parent, ast.UnaryOp) and isinstance(parent.op, ast.Not):
        return {"route": ROUTE_NOT_A_DEPARTURE}
    if (isinstance(parent, (ast.If, ast.While, ast.IfExp, ast.Assert))
            and getattr(parent, "test", None) is node):
        return {"route": ROUTE_NOT_A_DEPARTURE}
    if isinstance(parent, (ast.Dict, ast.List, ast.Tuple, ast.Set)):
        return {"route": ROUTE_CONTAINER}
    if isinstance(parent, ast.Assign) and any(
            isinstance(t, (ast.Subscript, ast.Attribute))
            for t in parent.targets):
        return {"route": ROUTE_CONTAINER}
    return {"route": ROUTE_UNKNOWN}


def _one_step_reader(scope: ast.AST, target: ast.AST,
                     declared: Set[str]) -> dict:
    """Читатель счётчика в СЛЕДУЮЩЕЙ области — правило УЖЕ соседского.

    И это сказано вслух, а не спрятано: через границу вызова уезжает
    СЧЁТЧИК, а выражение класса не уезжает. Поэтому формы
    ``class_value_is_compared_with_a_declared_class`` и
    ``class_value_is_carried_by_a_field_and_compared_there`` здесь
    недоказуемы — их население НЕ ИЗМЕРЕНО, а не пусто, и найденный раскол
    есть доказанный МИНИМУМ, а не замер вреда на следующем шаге.

    Запись в счётчик читателем не является (:func:`_counter_write_nodes`) —
    иначе шаг мерил бы ПИСАТЕЛЯ под именем читателя, ровно как ловил себя
    сосед.
    """
    target_dump = ast.dump(target)
    written = _counter_write_nodes(scope, target_dump)
    parents = _parent_map(scope)
    splits: List[dict] = []
    wholesale: List[int] = []
    dynamic: List[int] = []
    escapes: List[int] = []

    def _at(node: ast.AST) -> int:
        return int(getattr(node, "lineno", 0) or 0)

    for node in ast.walk(scope):
        if id(node) in written:
            continue
        if (isinstance(node, ast.Subscript)
                and ast.dump(node.value) == target_dump
                and isinstance(node.ctx, ast.Load)):
            if _is_declared_class(node.slice, declared):
                splits.append({"line": _at(node),
                               "how": ast.unparse(node)[:60]})
            else:
                dynamic.append(_at(node))
            continue
        if (isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute)
                and ast.dump(node.func.value) == target_dump):
            attr = node.func.attr
            if attr == "get":
                first = node.args[0] if node.args else None
                if _is_declared_class(first, declared):
                    splits.append({"line": _at(node),
                                   "how": ast.unparse(node)[:60]})
                else:
                    dynamic.append(_at(node))
            elif attr in READER_WHOLE_ATTRS:
                wholesale.append(_at(node))
            else:
                dynamic.append(_at(node))
            continue
        if ast.dump(node) != target_dump:
            continue
        use = _counter_whole_use(node, parents.get(id(node)))
        if use == WHOLE_USE_WHOLESALE:
            wholesale.append(_at(node))
        elif use == WHOLE_USE_ESCAPE:
            escapes.append(_at(node))

    if splits:
        return {"verdict": ONE_STEP_SPLITS, "gap": None, "splits": splits}
    if escapes:
        return {"verdict": ONE_STEP_UNRESOLVED, "gap": STEP_GAP_ESCAPES_AGAIN,
                "splits": []}
    if dynamic:
        return {"verdict": ONE_STEP_UNRESOLVED, "gap": READER_GAP_DYNAMIC,
                "splits": []}
    if wholesale:
        return {"verdict": ONE_STEP_WHOLESALE, "gap": None, "splits": []}
    return {"verdict": ONE_STEP_UNRESOLVED, "gap": STEP_GAP_NO_READ,
            "splits": []}


def _param_names(fn: ast.AST) -> List[str]:
    args = fn.args
    return [a.arg for a in (list(args.posonlyargs) + list(args.args))]


def _callers_binding_the_result(tree: ast.AST, parents: Dict[int, ast.AST],
                                owner_of: Dict[int, ast.AST],
                                scope: ast.AST) -> dict:
    """Зовущие области, где результат вызова СВЯЗАН именем. Одно правило — одна копия.

    Выделено из :func:`_next_scope_of_return` заказом G79 п. 1 БЕЗ смены
    поведения: тот же вопрос («кто зовёт эту область и куда кладёт результат»)
    задаёт и шаг переноса ПОЛЕМ, а вторая копия правила внутри прибора,
    который ищет вторые копии правил, — дефект, уже трижды случившийся в этом
    файле (ADR-460 у подписки, ADR-461 у кортежа, ADR-462 у правила побега).

    Зовущим считается ТОЛЬКО голый вызов по имени (``f(...)``): ``obj.f(...)``
    здесь не разрешается, потому что совпадение имени метода не есть
    доказательство, что зовут именно эту функцию. Строгость ошибается в
    сторону третьего исхода, а не в сторону выдуманного читателя.

    Возвращает ``{"gap": <имя отказа или None>, "sites": [(область, имя), …]}``.
    """
    if not isinstance(scope, (ast.FunctionDef, ast.AsyncFunctionDef)):
        return {"gap": STEP_GAP_NO_CALLER, "sites": []}
    callers = [node for node in ast.walk(tree)
               if isinstance(node, ast.Call)
               and isinstance(node.func, ast.Name)
               and node.func.id == scope.name]
    if not callers:
        return {"gap": STEP_GAP_NO_CALLER, "sites": []}
    sites: List[Tuple[ast.AST, str]] = []
    for call in callers:
        parent = parents.get(id(call))
        name: Optional[str] = None
        if isinstance(parent, ast.Assign) and len(parent.targets) == 1:
            if isinstance(parent.targets[0], ast.Name):
                name = parent.targets[0].id
        elif isinstance(parent, ast.AnnAssign) and isinstance(parent.target,
                                                              ast.Name):
            name = parent.target.id
        if name is None:
            continue
        sites.append((owner_of.get(id(call), tree), name))
    if not sites:
        return {"gap": STEP_GAP_RESULT_UNBOUND, "sites": []}
    return {"gap": None, "sites": sites}


def _next_scope_of_return(tree: ast.AST, parents: Dict[int, ast.AST],
                          owner_of: Dict[int, ast.AST], scope: ast.AST,
                          declared: Set[str]) -> dict:
    """Читатель возвращённого счётчика — У ЗОВУЩЕГО, и зовущий ищется в ЭТОМ файле.

    Правило «кто зовущий и связан ли результат» здесь НЕ переписано: зовётся
    :func:`_callers_binding_the_result`, которым отвечает и шаг переноса полем.
    """
    found = _callers_binding_the_result(tree, parents, owner_of, scope)
    if found["gap"] is not None:
        return {"verdict": ONE_STEP_UNRESOLVED, "gap": found["gap"],
                "splits": []}
    seen = [_one_step_reader(next_scope,
                             ast.Name(id=name, ctx=ast.Load()), declared)
            for next_scope, name in found["sites"]]
    return _merge_step_reads(seen)


def _merge_step_reads(seen: List[dict]) -> dict:
    """Свод по нескольким читателям одного побега.

    Порядок НЕ произволен: раскол доказан хотя бы одним читателем ⇒ он
    доказан (свидетель односторонний). Не доказан, но хоть один читатель НЕ
    ИЗМЕРЕН ⇒ весь побег не измерен: объявить его безвредным по измеренной
    половине значило бы ровно ту подмену, против которой шаг написан.
    """
    if not seen:
        return {"verdict": ONE_STEP_UNRESOLVED, "gap": STEP_GAP_NO_CALLER,
                "splits": []}
    split = [s for s in seen if s["verdict"] == ONE_STEP_SPLITS]
    if split:
        return {"verdict": ONE_STEP_SPLITS, "gap": None,
                "splits": [item for s in split for item in s["splits"]]}
    unresolved = [s for s in seen if s["verdict"] == ONE_STEP_UNRESOLVED]
    if unresolved:
        return {"verdict": ONE_STEP_UNRESOLVED, "gap": unresolved[0]["gap"],
                "splits": []}
    return {"verdict": ONE_STEP_WHOLESALE, "gap": None, "splits": []}


def _resolve_escape(tree: ast.AST, parents: Dict[int, ast.AST],
                    owner_of: Dict[int, ast.AST], defs: Dict[str, List[ast.AST]],
                    declared: Set[str], scope: ast.AST,
                    node: ast.AST) -> dict:
    """ОДИН шаг для ОДНОГО побега: маршрут → следующая область → читатель."""
    route = _escape_route(node, parents, defs)
    kind = route["route"]
    if kind == ROUTE_RETURNED:
        out = _next_scope_of_return(tree, parents, owner_of, scope, declared)
    elif kind == ROUTE_ARGUMENT_LOCAL:
        callee = route["callee_def"]
        params = _param_names(callee)
        param: Optional[str] = None
        if route.get("keyword") is not None:
            kw = route["keyword"]
            names = params + [a.arg for a in callee.args.kwonlyargs]
            param = kw if kw in names else None
        elif route.get("position") is not None:
            pos = int(route["position"])
            param = params[pos] if pos < len(params) else None
        if param is None:
            out = {"verdict": ONE_STEP_UNRESOLVED,
                   "gap": STEP_GAP_ARG_UNMAPPED, "splits": []}
        else:
            out = _one_step_reader(callee,
                                   ast.Name(id=param, ctx=ast.Load()),
                                   declared)
    elif kind == ROUTE_ARGUMENT_FOREIGN:
        out = {"verdict": ONE_STEP_UNRESOLVED,
               "gap": (STEP_GAP_AMBIGUOUS_CALLEE if route.get("ambiguous")
                       else STEP_GAP_FOREIGN_CALLEE), "splits": []}
    elif kind == ROUTE_CONTAINER:
        out = {"verdict": ONE_STEP_UNRESOLVED, "gap": STEP_GAP_CONTAINER,
               "splits": []}
    elif kind == ROUTE_NOT_A_DEPARTURE:
        out = {"verdict": ONE_STEP_UNRESOLVED,
               "gap": STEP_GAP_NOT_A_DEPARTURE, "splits": []}
    else:
        out = {"verdict": ONE_STEP_UNRESOLVED, "gap": STEP_GAP_ROUTE_UNKNOWN,
               "splits": []}
    return {**out, "route": kind, "line": int(getattr(node, "lineno", 0) or 0),
            "callee": route.get("callee")}


def _one_step_site_nodes(
        rel: str, tree: ast.AST
) -> Iterator[Tuple[dict, Optional[ast.AST], Optional[ast.AST]]]:
    """Убежавшие счётчики ОДНОГО файла вместе с исходом ОДНОГО шага и УЗЛАМИ.

    Население НЕ пересобирается: берутся строки соседа
    (:func:`_reader_site_nodes`) и отбираются те, у кого читатель не измерен
    ИМЕННО побегом. Второй копии правила «какой счётчик открыт» и «что есть
    побег» здесь нет ни одной.

    Отдаёт ``(строка, счётчик, его область)``. Узлы нужны шагу переноса полем
    (заказ G79 п. 1), и второй обход населения ради них был бы второй копией
    правила — того самого, что этот прибор и ищет. Плоский список строк —
    :func:`_one_step_sites`.
    """
    parents: Optional[Dict[int, ast.AST]] = None
    owner_of: Optional[Dict[int, ast.AST]] = None
    defs: Optional[Dict[str, List[ast.AST]]] = None
    declared: Optional[Set[str]] = None
    for site, target, key, scope in _reader_site_nodes(rel, tree):
        if site.get("gap") != READER_GAP_ESCAPES or target is None:
            continue
        if parents is None:
            parents = _parent_map(tree)
            owner_of = _counter_owner_scopes(tree)
            defs = _module_function_defs(tree)
            declared = _declared_constant_names(tree)
        found = _escape_sites(scope, target)
        if len(found) != int(site.get("escapes") or 0):
            yield ({**site, "one_step": ONE_STEP_UNRESOLVED,
                    "step_gap": STEP_GAP_SITES_DISAGREE,
                    "routes": [], "step_splits": [],
                    "reason": (f"своё правило побега нашло {len(found)} "
                               f"мест(а), соседское — "
                               f"{site.get('escapes')}")}, target, scope)
            continue
        steps = [_resolve_escape(tree, parents, owner_of, defs, declared,
                                 scope, node) for node in found]
        merged = _merge_step_reads(steps)
        yield ({**site, "one_step": merged["verdict"],
                "step_gap": merged["gap"],
                "routes": sorted({s["route"] for s in steps}),
                "step_splits": merged["splits"],
                "steps": [{"route": s["route"], "line": s["line"],
                           "verdict": s["verdict"], "gap": s["gap"],
                           "callee": s.get("callee")} for s in steps]},
               target, scope)


def _one_step_sites(rel: str, tree: ast.AST) -> List[dict]:
    """Плоский список строк одного файла — обёртка над генератором выше."""
    return [row for row, _target, _scope in _one_step_site_nodes(rel, tree)]


def _one_step_control() -> dict:
    """Проба объявленного правила ОДНОГО шага — до замера, обеими половинами.

    Первая половина требует дойти до расколотого читателя ОБЕИМИ разрешимыми
    формами побега (возврат и аргумент). Вторая требует ОТКАЗАТЬ там, где
    отказать должно, и отказать РАЗНЫМИ именами — иначе «шаг разрешил N» было
    бы неотличимо от «шаг объявляет разрешённым что угодно». Любая половина
    не сошлась ⇒ шаг отказывает целиком: число, полученное правилом, которое
    промахивается по известной форме, есть свойство ПРАВИЛА, а не населения.
    """
    try:
        source = _one_step_sites("<control>",
                                 ast.parse(ONE_STEP_CONTROL_SOURCE))
        clean = _one_step_sites("<control-clean>",
                                ast.parse(ONE_STEP_CONTROL_CLEAN))
    except SyntaxError as exc:
        return {"passed": False,
                "reason": f"сцена контроля не разобрана: {exc}"}
    if len(source) != 2:
        return {"passed": False, "reason": (
            f"в положительной сцене правило нашло {len(source)} убежавш(их) "
            f"счётчик(ов) из 2 — разрешать одним шагом нечего")}
    split = [s for s in source if s["one_step"] == ONE_STEP_SPLITS]
    if len(split) != 2:
        return {"passed": False, "reason": (
            f"один шаг довёл до расколотого читателя {len(split)} из 2 "
            f"счётчиков: исходы {[(s['one_step'], s['step_gap']) for s in source]}")}
    routes = sorted({r for s in split for r in s["routes"]})
    if routes != sorted((ROUTE_ARGUMENT_LOCAL, ROUTE_RETURNED)):
        return {"passed": False, "routes": routes, "reason": (
            f"раскол доказан маршрутами {routes}, а сцена несёт обе "
            f"разрешимые формы: {sorted((ROUTE_ARGUMENT_LOCAL, ROUTE_RETURNED))}"
            f" — ненайденная форма есть слепота правила, а не отсутствие "
            f"разрешимых побегов")}
    if len(clean) != 5:
        return {"passed": False, "reason": (
            f"в отрицательной сцене правило нашло {len(clean)} убежавш(их) "
            f"счётчик(ов) из 5")}
    false_splits = [s for s in clean if s["one_step"] == ONE_STEP_SPLITS]
    benign = [s for s in clean if s["one_step"] == ONE_STEP_WHOLESALE]
    gaps = sorted({s["step_gap"] for s in clean if s["step_gap"]})
    want = sorted((STEP_GAP_CONTAINER, STEP_GAP_FOREIGN_CALLEE,
                   STEP_GAP_NOT_A_DEPARTURE, STEP_GAP_ROUTE_UNKNOWN))
    if false_splits or len(benign) != 1 or gaps != want:
        return {"passed": False, "reason": (
            f"на отрицательной сцене ожидались ноль расколов, один "
            f"безвредный читатель и ЧЕТЫРЕ разных отказа ({want}), "
            f"а вышло {[(s['one_step'], s['step_gap']) for s in clean]}")}
    return {"passed": True, "known_case_resolved": len(split),
            "routes": routes, "clean_false_splits": 0,
            "clean_refusal_names": gaps, "clean_benign": len(benign)}


def escaped_counter_one_step(root: Path, harm: Optional[dict]) -> dict:
    """Сколько убежавших счётчиков разрешает ОДИН шаг (**заказ G78 п. 1**).

    ADR-461 назвал главным числом **95** — столько открытых счётчиков имеют
    читателя, которого шаг соседа НЕ ИЗМЕРИЛ, — и разложил их: **66** убегают
    из области возвратом или аргументом, 21 читается неразрешимым ключом, 8 не
    читаются в своей области вовсе. Заказ ставит вопрос дословно:

    > Сколько из 66 разрешимо межпроцедурным разбором ОДНОГО шага (счётчик
    > возвращён — читатель у зовущего), и сколько остаётся третьим исходом
    > навсегда.

    Ответ обязан быть ПАРОЙ чисел, и вторая половина пары — не остаток
    первой: «шаг не дошёл» чинится разным в зависимости от того, ПОЧЕМУ не
    дошёл, и потому у каждой причины своё машинное имя.

    Население берётся у соседа и СВЕРЯЕТСЯ с его числом: свой обход есть
    вторая дорога к тому же населению, и разойдясь с первой, он отвечал бы на
    другой вопрос.

    ADVISORY: ни одного счётчика и ни одного читателя не правит,
    ``applied`` ложно.
    """
    head = {
        "question": ("сколько из убежавших счётчиков разрешает ОДИН шаг "
                     "межпроцедурного разбора и сколько остаётся третьим "
                     "исходом"),
        "order": "G78.1",
        "applied": False,
        "dirs": list(OPEN_COUNTER_DIRS),
        "skipped_dirs": list(OPEN_COUNTER_SKIP),
    }
    if not isinstance(harm, dict) or str(harm.get("status")) != "MEASURED":
        return {**head, "status": "UNMEASURED",
                "unmeasured_class": UNMEASURED_STEP_HARM,
                "reason": ("вред у читателя не измерен — разрешать одним "
                           "шагом нечего; это НЕ «убежавших счётчиков нет»")}
    gaps = observed(harm, "unmeasured_reader_reasons", kind=dict)
    declared_population = (None if gaps is None
                           else observed(gaps, READER_GAP_ESCAPES, kind=int))
    if declared_population is None:
        return {**head, "status": "UNMEASURED",
                "unmeasured_class": UNMEASURED_STEP_HARM,
                "reason": ("сосед не назвал числа счётчиков, убежавших из "
                           "области, — сверять свой обход не с чем")}
    control = _one_step_control()
    head["control"] = control
    if not control.get("passed"):
        return {**head, "status": "UNMEASURED",
                "unmeasured_class": UNMEASURED_STEP_CONTROL,
                "reason": (f"объявленное правило одного шага не прошло "
                           f"контроль: {control.get('reason')}")}

    rows: List[dict] = []
    unreadable: List[dict] = []
    scanned = 0
    for sub in OPEN_COUNTER_DIRS:
        base = root / sub
        if not base.is_dir():
            unreadable.append({"file": sub, "reason": "каталога нет в дереве"})
            continue
        for path in sorted(base.rglob("*.py")):
            rel = path.relative_to(root).as_posix()
            if any(rel.startswith(skip) for skip in OPEN_COUNTER_SKIP):
                continue
            scanned += 1
            try:
                tree = ast.parse(path.read_text(encoding="utf-8"))
            except (OSError, SyntaxError, UnicodeDecodeError) as exc:
                unreadable.append({"file": rel,
                                   "reason": f"{type(exc).__name__}: {exc}"})
                continue
            rows.extend(_one_step_sites(rel, tree))

    if len(rows) != declared_population:
        return {**head, "status": "UNMEASURED",
                "unmeasured_class": UNMEASURED_STEP_POPULATION,
                "walked": len(rows), "census": declared_population,
                "files_unreadable": unreadable,
                "reason": (f"свой обход нашёл {len(rows)} убежавш(их) "
                           f"счётчик(ов), сосед — {declared_population}: "
                           f"замер одного шага по ДРУГОМУ населению отвечал "
                           f"бы на другой вопрос")}

    outcomes = {cls: sum(1 for r in rows if r["one_step"] == cls)
                for cls in _ONE_STEP_OUTCOMES}
    reasons = {gap: sum(1 for r in rows if r.get("step_gap") == gap)
               for gap in _STEP_GAPS}
    routes = {route: sum(1 for r in rows if route in (r.get("routes") or []))
              for route in _ESCAPE_ROUTES}
    resolved = outcomes[ONE_STEP_SPLITS] + outcomes[ONE_STEP_WHOLESALE]
    split_rows = [r for r in rows if r["one_step"] == ONE_STEP_SPLITS]
    # Сколько раз шаг ДОШЁЛ до следующей области и разобрал там читателя.
    # Число публикуется рядом с нулём разрешённых намеренно: ноль от живой
    # проводки и ноль от непроведённой выглядят одинаково, и различить их
    # обязан замер, а не уверенность автора.
    reached = sum(1 for r in rows
                  if r["one_step"] in (ONE_STEP_SPLITS, ONE_STEP_WHOLESALE)
                  or r.get("step_gap") in (READER_GAP_DYNAMIC,
                                           STEP_GAP_ESCAPES_AGAIN,
                                           STEP_GAP_NO_READ))
    return {
        **head,
        "status": "MEASURED",
        "population": len(rows),
        "files_scanned": scanned,
        "files_unreadable": unreadable,
        "one_step_outcomes": outcomes,
        "unresolved_reasons": reasons,
        "routes": routes,
        "resolved_by_one_step": resolved,
        "next_scope_reached": reached,
        "still_unmeasured": outcomes[ONE_STEP_UNRESOLVED],
        # Завышение соседского класса СВЕРХУ, найденное запуском: счётчик,
        # целиком проверенный на истинность или напечатанный в строку, никуда
        # не уезжает — а правило соседа зовёт это побегом. Оба числа рядом:
        # читатель обязан видеть потолок, а не принимать его за замер.
        "does_not_leave_the_scope_at_all": reasons[STEP_GAP_NOT_A_DEPARTURE],
        "departing_population_net": (len(rows)
                                     - reasons[STEP_GAP_NOT_A_DEPARTURE]),
        "sites_disagreed_with_the_reader_rule": reasons[STEP_GAP_SITES_DISAGREE],
        "harm_sample": [
            {"file": r["file"], "line": r["line"], "owner": r["owner"],
             "counter": r["counter"], "routes": r["routes"],
             "split": (r["step_splits"] or [{}])[0].get("how")}
            for r in split_rows[:COSTED_SAMPLE]],
        "unresolved_sample": [
            {"file": r["file"], "line": r["line"], "owner": r["owner"],
             "counter": r["counter"], "gap": r.get("step_gap"),
             "routes": r.get("routes")}
            for r in rows
            if r["one_step"] == ONE_STEP_UNRESOLVED][:COSTED_SAMPLE],
        "blind": [
            ("шаг ровно ОДИН: счётчик, убежавший и на следующей области "
             f"(`{STEP_GAP_ESCAPES_AGAIN}`), остаётся НЕ ИЗМЕРЕННЫМ — это не "
             "«вреда нет», а «нужен ещё шаг»"),
            ("правило читателя на следующей области УЖЕ соседского: через "
             "границу вызова уезжает счётчик, а выражение класса не уезжает, "
             "поэтому раскол доказывается только формой «счётчик прочитан "
             "объявленным ключом»; найденное есть доказанный МИНИМУМ"),
            ("зовущий ищется ТОЛЬКО в том же файле и только голым вызовом по "
             f"имени: `obj.f(...)` не разрешается (`{STEP_GAP_NO_CALLER}`), "
             "потому что совпадение имени метода не доказывает, что зовут "
             "именно эту функцию"),
            ("контейнер — не маршрут одного шага: счётчик, уехавший сперва "
             "полем (`return {'tally': tally}`), требует ВТОРОГО разбора — "
             "переноса полем, и это отдельный вопрос, а не поправка к этому"),
            ("население взято у соседа и наследует ВЕСЬ его потолок сверху "
             "(ADR-461: ключ, разобранный кортежем, назван артефактным) — "
             "своего замера населения у этого шага нет по построению"),
            ("к тому потолку этот шаг добавляет СВОЙ замер: часть населения "
             "не уезжает из области вовсе (истинность целиком, f-строка) — "
             "правило соседа перечисляет пробег поимённо и всякое остальное "
             "использование целиком зовёт побегом; число названо ключом "
             "`does_not_leave_the_scope_at_all` и вычтено рядом, а не вместо"),
            ("`counts or {}` уезжает по-настоящему, но маршрутом, который "
             f"правило не разбирает (`{ROUTE_UNKNOWN}`), — и принять его за "
             "«никуда не уехал» значило бы спрятать настоящий побег под "
             "новым именем; отрицательная половина контроля требует именно "
             "этого различения"),
        ],
    }


# --- ОДИН шаг ПЕРЕНОСА ПОЛЕМ (заказ G79 п. 1) ------------------------------
#
# ADR-462 померил маршруты 66 убежавших счётчиков и нашёл, что премисса заказа
# G78 была неверна: возвратом уходит 7, аргументом 0, а 53 уезжают СПЕРВА
# КОНТЕЙНЕРОМ (`return {'tally': counts}`). Восемьдесят процентов населения
# путешествует ПОЛЕМ, а не вызовом, и приём «счётчик возвращён — читатель у
# зовущего» на них не отвечает. Вопрос заказа G79 п. 1 дословно: сколько из 53
# разрешает ОДИН шаг переноса полем и сколько остаётся третьим исходом.

#: ПОЧЕМУ шаг переноса полем не дошёл. Имена новые там, где чинится новым, и
#: СОСЕДСКИЕ там, где чинится тем же самым: «зовущего нет в файле» и «результат
#: никуда не связан» — ровно те же вопросы, что у шага одного вызова, и заводить
#: им вторые имена значило бы развести один класс по двум счётчикам.
FIELD_GAP_NO_FIELD_NAME = "counter_is_placed_in_a_container_without_a_field_name"
FIELD_GAP_AMBIGUOUS_FIELD = "field_name_carries_more_than_one_value"
FIELD_GAP_CONTAINER_NOT_RETURNED = "container_holding_the_counter_is_not_returned"
#: Зовущий связал результат именем, но ИМЕННО ЭТОГО поля не читает. Имя своё,
#: а не соседское `next_scope_never_reads_the_counter`: сказать «не читает
#: счётчик» там, где зовущий читает соседнее поле того же словаря, значило бы
#: соврать в имени отказа — а имя здесь и есть то, чем отказ чинится.
FIELD_GAP_FIELD_NEVER_READ = "next_scope_never_reads_that_field"
_FIELD_GAPS = (FIELD_GAP_NO_FIELD_NAME, FIELD_GAP_AMBIGUOUS_FIELD,
               FIELD_GAP_CONTAINER_NOT_RETURNED, FIELD_GAP_FIELD_NEVER_READ,
               STEP_GAP_NO_CALLER,
               STEP_GAP_RESULT_UNBOUND, STEP_GAP_NO_READ,
               STEP_GAP_ESCAPES_AGAIN, STEP_GAP_SITES_DISAGREE,
               READER_GAP_DYNAMIC)

#: ФОРМА переноса. Их две, и обе обязана доказать положительная половина
#: контроля: найдя одну, правило ответило бы на половину вопроса, а число выдало
#: бы за полный ответ — ровно та ошибка, которую ADR-462 сделал бы, проверь он
#: побег одной формой.
FIELD_FORM_DIRECT = "container_is_returned_directly"
FIELD_FORM_BOUND = "container_is_bound_to_a_name_and_returned"
#: Третья форма, найденная ЗАПУСКОМ, а не перечитыванием: `doc["outcomes"] =
#: counts` кладёт счётчик под ИМЕНЕМ ПОЛЯ ровно так же, как словарь-литерал, —
#: и это дословно та форма, о которой спрашивает заказ. Отказать ей именем
#: «контейнер без имени поля» значило бы соврать в самом имени отказа: имя поля
#: там есть. Приём соседа (:func:`_field_carriers`) разбирает только
#: словари-литералы, и ПРАВИТЬ его нельзя (чужая батарея, п. 2 правила
#: приёмки), поэтому форма разбирается своим правилом и названа отдельно.
FIELD_FORM_SUBSCRIPT = "counter_is_stored_into_a_returned_mapping_by_subscript"
_FIELD_FORMS = (FIELD_FORM_DIRECT, FIELD_FORM_BOUND, FIELD_FORM_SUBSCRIPT)

#: Отказы шага. Три, и ни один не есть ноль.
UNMEASURED_FIELD_NEIGHBOUR = "one_step_census_is_absent_or_unmeasured"
UNMEASURED_FIELD_POPULATION = "second_walk_disagrees_with_the_container_census"
UNMEASURED_FIELD_CONTROL = "declared_field_step_rule_missed_the_known_case"

#: ПОЛОЖИТЕЛЬНАЯ половина контроля — ОБЕ формы переноса полем сразу. Счётчик
#: здесь открыт ровно так же, как у соседа (ключ из артефакта), уезжает в
#: словарь под именем поля, словарь покидает область — и шаг обязан довести до
#: читателя, который делит класс объявленным ключом, ОБЕИМИ формами: и когда
#: словарь возвращён прямо, и когда он сперва связан именем.
FIELD_STEP_CONTROL_SOURCE = '''
REACH_LIVE = "live"


def boxed(rows):
    counts = {}
    for row in rows:
        cls = str(row.get("reach"))
        counts[cls] = counts.get(cls, 0) + 1
    return {"tally": counts}


def verdict(rows):
    found = boxed(rows)
    return found["tally"][REACH_LIVE] > 0


def bagged(rows):
    seen = {}
    for row in rows:
        cls = str(row.get("reach"))
        seen[cls] = seen.get(cls, 0) + 1
    out = {"seen": seen}
    return out


def judged(rows):
    got = bagged(rows)
    return got.get("seen").get(REACH_LIVE, 0)


def filed(rows):
    doc = {}
    counts = {}
    for row in rows:
        cls = str(row.get("reach"))
        counts[cls] = counts.get(cls, 0) + 1
    doc["kept"] = counts
    return doc


def ruled(rows):
    made = filed(rows)
    return made["kept"][REACH_LIVE] > 0
'''

#: ОТРИЦАТЕЛЬНАЯ половина. Без неё «шаг разрешил N» было бы неотличимо от «шаг
#: объявляет разрешённым что угодно». ПЯТЬ счётчиков уезжают у соседа
#: КОНТЕЙНЕРОМ одинаково, и шаг обязан развести их ЧЕТЫРЬМЯ разными именами
#: отказа плюс ОДНИМ безвредным читателем: контейнер без имени поля (список),
#: имя поля, несущее ещё и чужое значение, контейнер, который область не
#: покидает, и область, которую в этом файле никто не зовёт. Отказ, слитый с
#: «безвредно», и есть подмена третьего исхода измеренным.
FIELD_STEP_CONTROL_CLEAN = '''
def listed(rows):
    counts = {}
    for row in rows:
        cls = str(row.get("outcome"))
        counts[cls] = counts.get(cls, 0) + 1
    return [counts]


def mixed(rows):
    counts = {}
    for row in rows:
        cls = str(row.get("outcome"))
        counts[cls] = counts.get(cls, 0) + 1
    other = {"tally": len(rows)}
    return {"tally": counts, "extra": other}


def kept(rows):
    counts = {}
    for row in rows:
        cls = str(row.get("outcome"))
        counts[cls] = counts.get(cls, 0) + 1
    bag = {"tally": counts}
    publish(bag)


def orphan(rows):
    counts = {}
    for row in rows:
        cls = str(row.get("outcome"))
        counts[cls] = counts.get(cls, 0) + 1
    return {"tally": counts}


def whole(rows):
    counts = {}
    for row in rows:
        cls = str(row.get("outcome"))
        counts[cls] = counts.get(cls, 0) + 1
    return {"tally": counts}


def sums(rows):
    got = whole(rows)
    return sorted(got["tally"].items())


def missed(rows):
    counts = {}
    for row in rows:
        cls = str(row.get("outcome"))
        counts[cls] = counts.get(cls, 0) + 1
    return {"tally": counts, "n": len(rows)}


def uses(rows):
    made = missed(rows)
    return made["n"]
'''


def _returned_container_fields(scope: ast.AST) -> Dict[str, Set[str]]:
    """Поля словарей-литералов, которые ПОКИДАЮТ область возвратом, и КАК.

    Вопрос здесь ДРУГОЙ, чем у :func:`_field_carriers` («какое поле несёт наш
    счётчик»), поэтому это не вторая копия правила, а второе правило: тот
    отвечает «что уехало полем», этот — «уехал ли сам контейнер». Разведены
    они намеренно: словарь, собранный и НЕ покинувший область, читателя у
    зовущего не имеет вовсе, и принять его за уехавший значило бы выдумать
    читателя.

    Шаг ровно ОДИН: словарь либо возвращается прямо (``return {...}``), либо
    связан именем в той же области и возвращается этим именем. Имя, связанное
    в области не одним значением, НЕ разрешается — «какое из двух» есть третий
    исход, а не выбор (то же правило, что у :func:`_module_function_defs`).
    """
    bound: Dict[str, List[ast.AST]] = {}
    for node in ast.walk(scope):
        if (isinstance(node, ast.Assign) and len(node.targets) == 1
                and isinstance(node.targets[0], ast.Name)):
            bound.setdefault(node.targets[0].id, []).append(node.value)
        elif (isinstance(node, ast.AnnAssign)
                and isinstance(node.target, ast.Name)
                and node.value is not None):
            bound.setdefault(node.target.id, []).append(node.value)
    out: Dict[str, Set[str]] = {}
    for node in ast.walk(scope):
        if not isinstance(node, ast.Return) or node.value is None:
            continue
        pairs: List[Tuple[ast.AST, str]] = []
        if isinstance(node.value, ast.Dict):
            pairs.append((node.value, FIELD_FORM_DIRECT))
        elif isinstance(node.value, ast.Name):
            values = bound.get(node.value.id, [])
            if len(values) == 1 and isinstance(values[0], ast.Dict):
                pairs.append((values[0], FIELD_FORM_BOUND))
        for container, form in pairs:
            for field in container.keys:
                if (isinstance(field, ast.Constant)
                        and isinstance(field.value, str)):
                    out.setdefault(field.value, set()).add(form)
    return out


def _subscript_field_carriers(scope: ast.AST, target_dump: str,
                              target_names: Set[str]
                              ) -> Tuple[Set[Tuple[str, str]], Set[str]]:
    """Поля, под которые счётчик положен ПОДПИСКОЙ: ``doc["outcomes"] = counts``.

    Это НЕ вторая копия :func:`_field_carriers`: тот разбирает словарь-ЛИТЕРАЛ
    (``{"outcomes": counts}``), этот — присваивание в подписку, и формы
    синтаксически разные. Правило соседа не правится (чужая батарея, п. 2
    правила приёмки), а форма без своего разбора получала бы ЛОЖНОЕ имя
    отказа — «контейнер без имени поля» там, где имя поля есть.

    Возвращает ``({(имя контейнера, поле)}, {неоднозначные поля})``. Поле, под
    которое в той же области кладут ЕЩЁ и другое значение, неоднозначно: связь
    идёт по ИМЕНИ ПОЛЯ, и на неоднозначном имени она приписала бы чужому
    сравнению наш класс — то же правило, что у соседа.
    """
    seen: Dict[Tuple[str, str], List[ast.AST]] = {}
    for node in ast.walk(scope):
        if not (isinstance(node, ast.Assign) and len(node.targets) == 1):
            continue
        tgt = node.targets[0]
        if not (isinstance(tgt, ast.Subscript)
                and isinstance(tgt.value, ast.Name)
                and isinstance(tgt.slice, ast.Constant)
                and isinstance(tgt.slice.value, str)):
            continue
        seen.setdefault((tgt.value.id, tgt.slice.value), []).append(node.value)
    ours: Set[Tuple[str, str]] = set()
    ambiguous: Set[str] = set()
    for (holder, field), values in seen.items():
        mine = [v for v in values
                if ast.dump(v) == target_dump
                or (isinstance(v, ast.Name) and v.id in target_names)]
        if not mine:
            continue
        if len({ast.dump(v) for v in values}) > 1:
            ambiguous.add(field)
        else:
            ours.add((holder, field))
    return ours, ambiguous


def _returned_names(scope: ast.AST) -> Set[str]:
    """Имена, которые область возвращает как есть (``return doc``).

    Вопрос тот же, что у :func:`_returned_container_fields` («покинул ли
    контейнер область»), но предмет другой: там контейнер есть
    словарь-литерал, здесь — имя, наполняемое подпиской.
    """
    return {node.value.id for node in ast.walk(scope)
            if isinstance(node, ast.Return)
            and isinstance(node.value, ast.Name)}


def _field_read_targets(scope: ast.AST, holder: str,
                        field: str) -> List[ast.AST]:
    """Места, которыми зовущий читает ПОЛЕ: ``R['X']`` и ``R.get('X'…)``.

    Узлы ИЩУТСЯ в области, а не синтезируются. Разница не косметическая:
    читателя разбирает :func:`_one_step_reader`, который сверяет узлы по
    ``ast.dump``, и синтетический ``R['X']`` не совпал бы ни с ``R.get('X')``,
    ни с ``R.get('X', {})`` — форма чтения у каждого своя. Правило, знающее
    ровно одну форму, объявило бы «поля никто не читает» там, где его читают
    другой формой, — то есть выдало бы НЕ ИЗМЕРЕНО за измеренный исход.

    Возвращает по ОДНОМУ узлу на различную форму: дальше каждый разбирается
    отдельно, а исходы сводит :func:`_merge_step_reads`.
    """
    out: List[ast.AST] = []
    seen: Set[str] = set()
    for node in ast.walk(scope):
        hit = False
        if (isinstance(node, ast.Subscript)
                and isinstance(node.value, ast.Name)
                and node.value.id == holder
                and isinstance(node.slice, ast.Constant)
                and node.slice.value == field
                and isinstance(node.ctx, ast.Load)):
            hit = True
        elif (isinstance(node, ast.Call)
                and isinstance(node.func, ast.Attribute)
                and node.func.attr == "get"
                and isinstance(node.func.value, ast.Name)
                and node.func.value.id == holder
                and node.args
                and isinstance(node.args[0], ast.Constant)
                and node.args[0].value == field):
            hit = True
        if not hit:
            continue
        dump = ast.dump(node)
        if dump in seen:
            continue
        seen.add(dump)
        out.append(node)
    return out


def _field_step(tree: ast.AST, parents: Dict[int, ast.AST],
                owner_of: Dict[int, ast.AST], declared: Set[str],
                scope: ast.AST, target: ast.AST) -> dict:
    """ОДИН шаг переноса ПОЛЕМ для ОДНОГО счётчика, уехавшего контейнером.

    Правило объявлено здесь, до замера, и состоит из трёх звеньев, у каждого
    свой отказ:

    1. счётчик лежит в словаре-литерале под ИМЕНЕМ ПОЛЯ
       (:func:`_field_carriers` — приём соседа, взятый как есть; второй копии
       правила «что уехало полем» в этом файле не будет);
    2. этот словарь ПОКИДАЕТ область возвратом
       (:func:`_returned_container_fields`);
    3. зовущий связывает результат именем
       (:func:`_callers_binding_the_result`) и читает ``имя['поле']``; читателя
       разбирает :func:`_one_step_reader` — правило читателя УЖЕ соседского, и
       найденный раскол есть доказанный МИНИМУМ.

    Связь идёт ПО ИМЕНИ ПОЛЯ, и на неоднозначном имени она приписала бы чужому
    сравнению наш класс — потому неоднозначное поле есть ОТКАЗ, а не находка.
    """
    target_dump = ast.dump(target)
    names = {n.id for n in ast.walk(target) if isinstance(n, ast.Name)}
    fields, ambiguous = _field_carriers(scope, target_dump, names)
    stored, stored_ambiguous = _subscript_field_carriers(scope, target_dump,
                                                         names)
    if not fields and not stored:
        unclear = ambiguous | stored_ambiguous
        return {"verdict": ONE_STEP_UNRESOLVED,
                "gap": (FIELD_GAP_AMBIGUOUS_FIELD if unclear
                        else FIELD_GAP_NO_FIELD_NAME),
                "splits": [], "fields": sorted(unclear), "forms": []}
    leaving = _returned_container_fields(scope)
    returned = _returned_names(scope)
    by_form: Dict[str, Set[str]] = {}
    for field in fields & set(leaving):
        by_form.setdefault(field, set()).update(leaving[field])
    for holder, field in stored:
        if holder in returned:
            by_form.setdefault(field, set()).add(FIELD_FORM_SUBSCRIPT)
    carried = sorted(by_form)
    if not carried:
        return {"verdict": ONE_STEP_UNRESOLVED,
                "gap": FIELD_GAP_CONTAINER_NOT_RETURNED, "splits": [],
                "fields": sorted(fields | {f for _h, f in stored}),
                "forms": []}
    forms = sorted({form for field in carried for form in by_form[field]})
    found = _callers_binding_the_result(tree, parents, owner_of, scope)
    if found["gap"] is not None:
        return {"verdict": ONE_STEP_UNRESOLVED, "gap": found["gap"],
                "splits": [], "fields": carried, "forms": forms}
    seen = [_one_step_reader(next_scope, node, declared)
            for next_scope, name in found["sites"]
            for field in carried
            for node in _field_read_targets(next_scope, name, field)]
    if not seen:
        return {"verdict": ONE_STEP_UNRESOLVED,
                "gap": FIELD_GAP_FIELD_NEVER_READ, "splits": [],
                "fields": carried, "forms": forms}
    merged = _merge_step_reads(seen)
    return {**merged, "fields": carried, "forms": forms}


def _field_step_sites(rel: str, tree: ast.AST) -> List[dict]:
    """Счётчики ОДНОГО файла, уехавшие КОНТЕЙНЕРОМ, с исходом шага полем.

    Население НЕ пересобирается: берутся строки шага одного вызова
    (:func:`_one_step_site_nodes`) и отбираются те, кому он отказал ИМЕННО
    «уехал сперва полем». Своего правила «какой счётчик открыт», «что есть
    побег» и «каким маршрутом» здесь нет ни одного.
    """
    rows: List[dict] = []
    parents: Optional[Dict[int, ast.AST]] = None
    owner_of: Optional[Dict[int, ast.AST]] = None
    declared: Optional[Set[str]] = None
    for site, target, scope in _one_step_site_nodes(rel, tree):
        if site.get("step_gap") != STEP_GAP_CONTAINER or target is None:
            continue
        if parents is None:
            parents = _parent_map(tree)
            owner_of = _counter_owner_scopes(tree)
            declared = _declared_constant_names(tree)
        out = _field_step(tree, parents, owner_of, declared, scope, target)
        rows.append({**site, "field_step": out["verdict"],
                     "field_gap": out["gap"], "fields": out["fields"],
                     "forms": out["forms"], "field_splits": out["splits"]})
    return rows


def _field_step_control() -> dict:
    """Проба объявленного правила переноса полем — до замера, обеими половинами.

    Первая половина требует дойти до расколотого читателя ОБЕИМИ формами
    переноса (словарь возвращён прямо и словарь связан именем). Вторая требует
    ОТКАЗАТЬ там, где отказать должно, и отказать РАЗНЫМИ именами — иначе
    «шаг разрешил N» было бы неотличимо от «шаг объявляет разрешённым что
    угодно». Любая половина не сошлась ⇒ шаг отказывает целиком: число,
    полученное правилом, которое промахивается по известной форме, есть
    свойство ПРАВИЛА, а не населения.
    """
    try:
        source = _field_step_sites("<control>",
                                   ast.parse(FIELD_STEP_CONTROL_SOURCE))
        clean = _field_step_sites("<control-clean>",
                                  ast.parse(FIELD_STEP_CONTROL_CLEAN))
    except SyntaxError as exc:
        return {"passed": False,
                "reason": f"сцена контроля не разобрана: {exc}"}
    if len(source) != len(_FIELD_FORMS):
        return {"passed": False, "reason": (
            f"в положительной сцене правило нашло {len(source)} счётчик(ов), "
            f"уехавш(их) контейнером, из {len(_FIELD_FORMS)} — разрешать "
            f"переносом полем нечего")}
    split = [s for s in source if s["field_step"] == ONE_STEP_SPLITS]
    if len(split) != len(_FIELD_FORMS):
        return {"passed": False, "reason": (
            f"шаг переноса полем довёл до расколотого читателя {len(split)} "
            f"из {len(_FIELD_FORMS)} счётчиков: исходы "
            f"{[(s['field_step'], s['field_gap']) for s in source]}")}
    forms = sorted({f for s in split for f in s["forms"]})
    if forms != sorted(_FIELD_FORMS):
        return {"passed": False, "forms": forms, "reason": (
            f"раскол доказан формами {forms}, а сцена несёт обе: "
            f"{sorted(_FIELD_FORMS)} — ненайденная форма есть слепота "
            f"правила, а не отсутствие разрешимых переносов")}
    if len(clean) != 6:
        return {"passed": False, "reason": (
            f"в отрицательной сцене правило нашло {len(clean)} счётчик(ов), "
            f"уехавш(их) контейнером, из 6")}
    false_splits = [s for s in clean if s["field_step"] == ONE_STEP_SPLITS]
    benign = [s for s in clean if s["field_step"] == ONE_STEP_WHOLESALE]
    gaps = sorted({s["field_gap"] for s in clean if s["field_gap"]})
    want = sorted((FIELD_GAP_NO_FIELD_NAME, FIELD_GAP_AMBIGUOUS_FIELD,
                   FIELD_GAP_CONTAINER_NOT_RETURNED, STEP_GAP_NO_CALLER,
                   FIELD_GAP_FIELD_NEVER_READ))
    if false_splits or len(benign) != 1 or gaps != want:
        return {"passed": False, "reason": (
            f"на отрицательной сцене ожидались ноль расколов, один "
            f"безвредный читатель и ПЯТЬ разных отказов ({want}), а вышло "
            f"{[(s['field_step'], s['field_gap']) for s in clean]}")}
    return {"passed": True, "known_case_resolved": len(split),
            "forms": forms, "clean_false_splits": 0,
            "clean_refusal_names": gaps, "clean_benign": len(benign)}


def container_counter_field_step(root: Path, step: Optional[dict]) -> dict:
    """Сколько счётчиков-контейнеров разрешает перенос ПОЛЕМ (**заказ G79 п. 1**).

    ADR-462 ответил на заказ G78 нулём и назвал главным содержанием замера
    неверную премиссу: из 66 убежавших счётчиков возвратом уходит 7,
    аргументом 0, а **53** уезжают сперва КОНТЕЙНЕРОМ. Заказ G79 п. 1 дословно:

    > Сколько из 53 разрешает ОДИН шаг переноса полем (счётчик положен в
    > словарь под именем ``X``, вызывающий читает ``результат['X']``), и
    > сколько остаётся третьим исходом.

    Ответ обязан быть ПАРОЙ чисел, и вторая половина пары не есть остаток
    первой: «шаг не дошёл» чинится разным в зависимости от того, ПОЧЕМУ не
    дошёл, и потому у каждой причины своё машинное имя.

    Население берётся у соседа и СВЕРЯЕТСЯ с его числом: свой обход есть
    вторая дорога к тому же населению, и разойдясь с первой, он отвечал бы на
    другой вопрос.

    ADVISORY: ни одного счётчика и ни одного читателя не правит,
    ``applied`` ложно.
    """
    head = {
        "question": ("сколько из счётчиков, уехавших КОНТЕЙНЕРОМ, разрешает "
                     "ОДИН шаг переноса полем и сколько остаётся третьим "
                     "исходом"),
        "order": "G79.1",
        "applied": False,
        "dirs": list(OPEN_COUNTER_DIRS),
        "skipped_dirs": list(OPEN_COUNTER_SKIP),
    }
    if not isinstance(step, dict) or str(step.get("status")) != "MEASURED":
        return {**head, "status": "UNMEASURED",
                "unmeasured_class": UNMEASURED_FIELD_NEIGHBOUR,
                "reason": ("шаг одного вызова не измерен — населения «уехал "
                           "полем» не существует; это НЕ «таких счётчиков "
                           "нет»")}
    reasons = observed(step, "unresolved_reasons", kind=dict)
    declared_population = (None if reasons is None
                           else observed(reasons, STEP_GAP_CONTAINER,
                                         kind=int))
    if declared_population is None:
        return {**head, "status": "UNMEASURED",
                "unmeasured_class": UNMEASURED_FIELD_NEIGHBOUR,
                "reason": ("сосед не назвал числа счётчиков, уехавших "
                           "контейнером, — сверять свой обход не с чем")}
    control = _field_step_control()
    head["control"] = control
    if not control.get("passed"):
        return {**head, "status": "UNMEASURED",
                "unmeasured_class": UNMEASURED_FIELD_CONTROL,
                "reason": (f"объявленное правило переноса полем не прошло "
                           f"контроль: {control.get('reason')}")}

    rows: List[dict] = []
    unreadable: List[dict] = []
    scanned = 0
    for sub in OPEN_COUNTER_DIRS:
        base = root / sub
        if not base.is_dir():
            unreadable.append({"file": sub, "reason": "каталога нет в дереве"})
            continue
        for path in sorted(base.rglob("*.py")):
            rel = path.relative_to(root).as_posix()
            if any(rel.startswith(skip) for skip in OPEN_COUNTER_SKIP):
                continue
            scanned += 1
            try:
                tree = ast.parse(path.read_text(encoding="utf-8"))
            except (OSError, SyntaxError, UnicodeDecodeError) as exc:
                unreadable.append({"file": rel,
                                   "reason": f"{type(exc).__name__}: {exc}"})
                continue
            rows.extend(_field_step_sites(rel, tree))

    if len(rows) != declared_population:
        return {**head, "status": "UNMEASURED",
                "unmeasured_class": UNMEASURED_FIELD_POPULATION,
                "walked": len(rows), "census": declared_population,
                "files_unreadable": unreadable,
                "reason": (f"свой обход нашёл {len(rows)} счётчик(ов), "
                           f"уехавш(их) контейнером, сосед — "
                           f"{declared_population}: замер переноса полем по "
                           f"ДРУГОМУ населению отвечал бы на другой вопрос")}

    outcomes = {cls: sum(1 for r in rows if r["field_step"] == cls)
                for cls in _ONE_STEP_OUTCOMES}
    gaps = {gap: sum(1 for r in rows if r.get("field_gap") == gap)
            for gap in _FIELD_GAPS}
    forms = {form: sum(1 for r in rows if form in (r.get("forms") or []))
             for form in _FIELD_FORMS}
    resolved = outcomes[ONE_STEP_SPLITS] + outcomes[ONE_STEP_WHOLESALE]
    split_rows = [r for r in rows if r["field_step"] == ONE_STEP_SPLITS]
    # Два разных числа живости, и складывать их в одно было бы той же
    # подменой: ноль разрешённых от ЖИВОЙ проводки и ноль от непроведённого
    # шага выглядят одинаково (урок ADR-462), но «дошёл до области зовущего»
    # и «разобрал там ЧИТАТЕЛЯ» — разные достижения. Первое доказывает, что
    # звенья 1–3 правила отработали; второе — что отработало и четвёртое.
    reached = sum(1 for r in rows
                  if r["field_step"] in (ONE_STEP_SPLITS, ONE_STEP_WHOLESALE)
                  or r.get("field_gap") in (READER_GAP_DYNAMIC,
                                            STEP_GAP_ESCAPES_AGAIN,
                                            STEP_GAP_NO_READ,
                                            FIELD_GAP_FIELD_NEVER_READ))
    parsed = sum(1 for r in rows
                 if r["field_step"] in (ONE_STEP_SPLITS, ONE_STEP_WHOLESALE)
                 or r.get("field_gap") in (READER_GAP_DYNAMIC,
                                           STEP_GAP_ESCAPES_AGAIN,
                                           STEP_GAP_NO_READ))
    return {
        **head,
        "status": "MEASURED",
        "population": len(rows),
        "files_scanned": scanned,
        "files_unreadable": unreadable,
        "field_step_outcomes": outcomes,
        "unresolved_reasons": gaps,
        "forms": forms,
        "resolved_by_field_step": resolved,
        "next_scope_reached": reached,
        "reader_parsed_at_next_scope": parsed,
        "still_unmeasured": outcomes[ONE_STEP_UNRESOLVED],
        "harm_sample": [
            {"file": r["file"], "line": r["line"], "owner": r["owner"],
             "counter": r["counter"], "fields": r["fields"],
             "forms": r["forms"],
             "split": (r["field_splits"] or [{}])[0].get("how")}
            for r in split_rows[:COSTED_SAMPLE]],
        "unresolved_sample": [
            {"file": r["file"], "line": r["line"], "owner": r["owner"],
             "counter": r["counter"], "gap": r.get("field_gap"),
             "fields": r.get("fields")}
            for r in rows
            if r["field_step"] == ONE_STEP_UNRESOLVED][:COSTED_SAMPLE],
        "blind": [
            ("шаг ровно ОДИН: счётчик, уехавший полем и убежавший СНОВА у "
             f"зовущего (`{STEP_GAP_ESCAPES_AGAIN}`), остаётся НЕ ИЗМЕРЕННЫМ "
             "— это не «вреда нет», а «нужен ещё шаг»"),
            ("связь идёт ПО ИМЕНИ ПОЛЯ, и это приём соседа, взятый как есть: "
             "имя поля, несущее в области ещё и чужое значение, объявляется "
             "ОТКАЗОМ, потому что на нём шаг приписал бы чужому сравнению "
             "наш класс"),
            ("правило читателя у зовущего УЖЕ соседского: через границу "
             "вызова уезжает счётчик, а выражение класса не уезжает, поэтому "
             "раскол доказывается только формой «поле прочитано объявленным "
             "ключом»; найденное есть доказанный МИНИМУМ"),
            ("зовущий ищется ТОЛЬКО в том же файле и только голым вызовом по "
             f"имени (`{STEP_GAP_NO_CALLER}`) — правило то же, что у шага "
             "одного вызова, и оно ошибается в сторону третьего исхода"),
            ("контейнер, который область НЕ покидает, читателя у зовущего не "
             "имеет вовсе: такой счётчик требует разбора того, куда контейнер "
             "положили дальше, и это отдельный вопрос, а не поправка к этому"),
            ("население взято у соседа и наследует ВЕСЬ его потолок сверху "
             "(ADR-461 — ключ, разобранный кортежем; ADR-462 — счётчик, не "
             "уезжающий вовсе): своего замера населения у этого шага нет по "
             "построению"),
        ],
    }

# --- Разбор ПО ИМЕНИ ПОЛЯ ЧЕРЕЗ ГРАНИЦУ ФУНКЦИИ (заказ G80 п. 1) -----------
#
# ADR-463 ответил на заказ G79 нулём и назвал ГЛАВНЫМ числом 26 из 53: два
# имени отказа — `next_scope_never_reads_that_field` (16) и
# `returned_value_is_not_bound_to_a_name` (10) — суть ОДИН класс, названный с
# двух сторон. Счётчик кладут в ДОКУМЕНТ, документ возвращают, и поле его
# читают НЕ У ЗОВУЩЕГО, а много позже: другой функцией, другой точкой входа,
# из сохранённого артефакта. Шаг вызова и шаг поля не отвечают на это оба:
# первый идёт по вызову, второй — по вызову И полю, а документ доезжает до
# читателя БЕЗ вызова между ними.
#
# Вопрос заказа G80 п. 1 дословно: сколько из 26 разрешает разбор ПО ИМЕНИ
# ПОЛЯ ЧЕРЕЗ ГРАНИЦУ ФУНКЦИИ («кто в этом файле вообще читает ключ `X` у чего
# угодно»), и сколько остаётся третьим исходом.

#: ПОЧЕМУ разбор по имени поля не дошёл. Имена новые там, где чинится новым, и
#: СОСЕДСКИЕ там, где чинится тем же самым: «поле прочитано и уехало СНОВА» и
#: «ключ чтения не разрешается» — ровно те же вопросы, что у соседних шагов, и
#: заводить им вторые имена значило бы развести один класс по двум счётчикам.
DOC_GAP_MANY_FIELDS = "counter_travels_under_more_than_one_field_name"
#: ГЛАВНОЕ ограничение односторонности, и оно объявлено отказом, а не
#: оговоркой в тексте. «Нашли читателя ключа `X`» НЕ есть «читают НАШ
#: счётчик»: связь идёт по ИМЕНИ ПОЛЯ, а имя — не адрес. Если ключ `X` в этом
#: файле пишет больше одной области, чтение `что_угодно['X']` могло прийти от
#: ЧУЖОГО документа, и засчитать его нашим значило бы доказывать вред
#: совпадением имён. Такой счётчик есть ТРЕТИЙ ИСХОД, а не находка.
DOC_GAP_FIELD_WRITTEN_TWICE = "field_name_is_written_by_more_than_one_scope_in_this_file"
#: Ключ не читает в этом файле НИКТО. Это НЕ «вреда нет»: ровно так выглядит
#: документ, который пишут здесь, а читают в другом файле или другой точкой
#: входа — тот самый класс, ради которого шаг и написан. Прибор видит один
#: файл по построению, и «не вижу читателя» есть предел ПРИБОРА.
DOC_GAP_NO_READER_IN_FILE = "no_reader_of_that_field_anywhere_in_this_file"
_DOC_GAPS = (DOC_GAP_MANY_FIELDS, DOC_GAP_FIELD_WRITTEN_TWICE,
             DOC_GAP_NO_READER_IN_FILE, STEP_GAP_ESCAPES_AGAIN,
             READER_GAP_DYNAMIC, STEP_GAP_NO_READ)

#: ФОРМА чтения поля. Три, и все три обязана доказать положительная половина
#: контроля: правило, знающее одну, объявило бы «поля никто не читает» там, где
#: его читают другой формой, — то есть выдало бы НЕ ИЗМЕРЕНО за измеренный
#: исход. Формы разные синтаксически, а вопрос один.
DOC_READ_SUBSCRIPT = "field_is_read_by_subscript"
DOC_READ_GET = "field_is_read_by_get"
#: ТРЕТЬЯ форма, найденная ЗАПУСКОМ, а не перечитыванием: в этом дереве поле
#: документа читают ЧАЩЕ ВСЕГО не подпиской, а объявленным читателем
#: `observed(doc, "X", kind=dict)` — той самой честной формой, которую
#: предписывает инвариант #17 (`spa_core/utils/observation.py`). Правило,
#: знавшее две формы, объявило «поля не читает НИКТО» у 17 счётчиков из 26 —
#: и это было свойством ПРАВИЛА, а не населения: `key_origin_counts`, поимённо
#: названный ADR-463 как читаемый в `report` того же модуля, попал ровно в этот
#: отказ. Форма ограничена ИМЕНЕМ объявленного читателя: любой другой вызов с
#: тем же ключом в аргументе чтением не считается — совпадение строки в
#: произвольном вызове не есть чтение поля.
DOC_READ_OBSERVED = "field_is_read_by_the_declared_observation_helper"
DOC_READ_HELPER = "observed"
_DOC_READ_FORMS = (DOC_READ_SUBSCRIPT, DOC_READ_GET, DOC_READ_OBSERVED)

#: Отказы шага. Три, и ни один не есть ноль.
UNMEASURED_DOC_NEIGHBOUR = "field_step_census_is_absent_or_unmeasured"
UNMEASURED_DOC_POPULATION = "second_walk_disagrees_with_the_field_step_census"
UNMEASURED_DOC_CONTROL = "declared_document_reader_rule_missed_the_known_case"

#: ПОЛОЖИТЕЛЬНАЯ половина контроля — ТРИ формы прибытия счётчика в документ
#: (словарь возвращён прямо · словарь связан именем и возвращён · счётчик
#: положен подпиской) и ВСЕ ТРИ формы чтения поля (подписка · `.get` ·
#: объявленный читатель `observed`). У каждого
#: счётчика зовущий поле НЕ читает — иначе его разрешил бы сосед, и сцена
#: мерила бы чужое правило. Читатель стои́т в ТРЕТЬЕЙ области, до которой от
#: писателя нет ни одного вызова: ровно так выглядит живой случай
#: `open_class_counter_census` → `report`.
DOC_READER_CONTROL_SOURCE = '''
REACH_LIVE = "live"


def boxed(rows):
    counts = {}
    for row in rows:
        cls = str(row.get("reach"))
        counts[cls] = counts.get(cls, 0) + 1
    return {"tally": counts}


def caller(rows):
    doc = boxed(rows)
    return len(doc)


def report(doc):
    return doc["tally"][REACH_LIVE] > 0


def bagged(rows):
    seen = {}
    for row in rows:
        cls = str(row.get("reach"))
        seen[cls] = seen.get(cls, 0) + 1
    out = {"held": seen}
    return out


def drops(rows):
    print(bagged(rows))


def audit(bag):
    return bag.get("held", {})[REACH_LIVE] > 0


def filed(rows):
    doc = {}
    counts = {}
    for row in rows:
        cls = str(row.get("reach"))
        counts[cls] = counts.get(cls, 0) + 1
    doc["kept"] = counts
    return doc


def holder(rows):
    made = filed(rows)
    return sorted(made)


def summary(made):
    return made["kept"][REACH_LIVE] > 0


def stamped(rows):
    counts = {}
    for row in rows:
        cls = str(row.get("reach"))
        counts[cls] = counts.get(cls, 0) + 1
    return {"noted": counts}


def stamped_caller(rows):
    doc = stamped(rows)
    return len(doc)


def stamped_reader(doc):
    return observed(doc, "noted", kind=dict)[REACH_LIVE] > 0
'''

#: ОТРИЦАТЕЛЬНАЯ половина. Без неё «разбор разрешил N» было бы неотличимо от
#: «разбор объявляет разрешённым что угодно». ПЯТЬ счётчиков приезжают в
#: документ одинаково, и шаг обязан развести их ЧЕТЫРЬМЯ разными именами
#: отказа плюс ОДНИМ безвредным читателем: ключ пишут две области (и читатель
#: у него есть — засчитать его нашим значило бы доказать вред совпадением
#: имён), ключа не читает никто, читатель пробегает поле целиком, читатель
#: связывает поле именем и счётчик убегает СНОВА, читатель берёт класс ключом,
#: который правило не разрешает. Отказ, слитый с «безвредно», и есть подмена
#: третьего исхода измеренным.
DOC_READER_CONTROL_CLEAN = '''
REACH_LIVE = "live"


def dup_one(rows):
    counts = {}
    for row in rows:
        cls = str(row.get("reach"))
        counts[cls] = counts.get(cls, 0) + 1
    return {"dup": counts}


def dup_caller(rows):
    got = dup_one(rows)
    return len(got)


def dup_two(rows):
    other = {}
    for row in rows:
        cls = str(row.get("kind"))
        other[cls] = other.get(cls, 0) + 1
    return {"dup": other}


def dup_reader(doc):
    return doc["dup"][REACH_LIVE] > 0


def lost(rows):
    counts = {}
    for row in rows:
        cls = str(row.get("reach"))
        counts[cls] = counts.get(cls, 0) + 1
    return {"lost": counts}


def lost_caller(rows):
    doc = lost(rows)
    return len(doc)


def spent(rows):
    counts = {}
    for row in rows:
        cls = str(row.get("reach"))
        counts[cls] = counts.get(cls, 0) + 1
    return {"spent": counts}


def spent_caller(rows):
    doc = spent(rows)
    return len(doc)


def spent_reader(doc):
    return sorted(doc["spent"])


def again(rows):
    counts = {}
    for row in rows:
        cls = str(row.get("reach"))
        counts[cls] = counts.get(cls, 0) + 1
    return {"again": counts}


def again_caller(rows):
    doc = again(rows)
    return len(doc)


def again_reader(doc):
    c = doc["again"]
    return c.get(REACH_LIVE, 0)


def dyn(rows):
    counts = {}
    for row in rows:
        cls = str(row.get("reach"))
        counts[cls] = counts.get(cls, 0) + 1
    return {"dyn": counts}


def dyn_caller(rows):
    doc = dyn(rows)
    return len(doc)


def dyn_reader(doc, key):
    return doc["dyn"][key] > 0
'''


def _is_declared_reader(func: ast.AST) -> bool:
    """Это ли ОБЪЯВЛЕННЫЙ читатель наблюдения — ``observed(doc, "X", …)``.

    Имя одно и названо константой (:data:`DOC_READ_HELPER`), потому что форма
    опирается не на «вызов, среди аргументов которого есть наша строка» —
    такое правило считало бы чтением `log.info("X")`, — а на ЕДИНСТВЕННУЮ
    функцию, которой инвариант #17 предписывает читать поле документа
    (``spa_core/utils/observation.py``). Любой другой вызов с тем же ключом
    чтением НЕ считается: цена названа, и ошибается правило в сторону
    третьего исхода.
    """
    if isinstance(func, ast.Name):
        return func.id == DOC_READ_HELPER
    if isinstance(func, ast.Attribute):
        return func.attr == DOC_READ_HELPER
    return False


def _field_write_scopes(tree: ast.AST, owner_of: Dict[int, ast.AST],
                        field: str) -> List[ast.AST]:
    """Области файла, которые КЛАДУТ что-либо под ключом ``field``.

    Вопрос здесь не «какое поле несёт наш счётчик» (это :func:`_field_carriers`
    и :func:`_subscript_field_carriers`), а «сколько в файле ПИСАТЕЛЕЙ этого
    имени». Разница существенна: на ней держится единственное ограничение
    односторонности этого шага. Считаются обе формы записи — ключ
    словаря-литерала (``{"X": …}``) и присваивание в подписку
    (``doc["X"] = …``), потому что читателю всё равно, какой из них наполнил
    документ, а правилу — нет.

    Возвращает список ОБЛАСТЕЙ (по одной на область, а не на запись): две
    записи одного ключа внутри одной функции — это один писатель, и считать их
    двумя значило бы отказывать себе же.
    """
    seen: Dict[int, ast.AST] = {}
    for node in ast.walk(tree):
        hit = False
        if isinstance(node, ast.Dict):
            hit = any(isinstance(k, ast.Constant) and k.value == field
                      for k in node.keys)
        elif (isinstance(node, ast.Assign) and len(node.targets) == 1
                and isinstance(node.targets[0], ast.Subscript)
                and isinstance(node.targets[0].slice, ast.Constant)
                and node.targets[0].slice.value == field):
            hit = True
        if not hit:
            continue
        scope = owner_of.get(id(node), tree)
        seen.setdefault(id(scope), scope)
    return list(seen.values())


def _document_field_reads(tree: ast.AST, owner_of: Dict[int, ast.AST],
                          field: str, writer: ast.AST
                          ) -> List[Tuple[ast.AST, ast.AST, str]]:
    """Места файла, где ключ ``field`` ЧИТАЮТ у чего угодно, вне области-писателя.

    Держатель НЕ ограничен именем: в том и состоит шаг — документ доезжает до
    читателя без вызова между ним и писателем, поэтому имя держателя у
    читателя своё и связать его с писателем нечем, кроме имени ПОЛЯ. Цена
    этой свободы названа отказом :data:`DOC_GAP_FIELD_WRITTEN_TWICE`, а не
    оговоркой в тексте.

    Форм чтения две, и обе ИЩУТСЯ, а не синтезируются: читателя разбирает
    :func:`_one_step_reader`, который сверяет узлы по ``ast.dump``, и
    синтетический ``d['X']`` не совпал бы ни с ``d.get('X')``, ни с
    ``d.get('X', {})``.

    Возвращает ``[(область, узел чтения, форма), …]`` по одному узлу на
    различную форму в каждой области.
    """
    out: List[Tuple[ast.AST, ast.AST, str]] = []
    seen: Set[Tuple[int, str]] = set()
    for node in ast.walk(tree):
        form: Optional[str] = None
        if (isinstance(node, ast.Subscript)
                and isinstance(node.slice, ast.Constant)
                and node.slice.value == field
                and isinstance(node.ctx, ast.Load)):
            form = DOC_READ_SUBSCRIPT
        elif (isinstance(node, ast.Call)
                and isinstance(node.func, ast.Attribute)
                and node.func.attr == "get"
                and node.args
                and isinstance(node.args[0], ast.Constant)
                and node.args[0].value == field):
            form = DOC_READ_GET
        elif (isinstance(node, ast.Call)
                and _is_declared_reader(node.func)
                and len(node.args) >= 2
                and isinstance(node.args[1], ast.Constant)
                and node.args[1].value == field):
            form = DOC_READ_OBSERVED
        if form is None:
            continue
        scope = owner_of.get(id(node), tree)
        if scope is writer:
            continue
        key = (id(scope), ast.dump(node))
        if key in seen:
            continue
        seen.add(key)
        out.append((scope, node, form))
    return out


def _document_reader_step(tree: ast.AST, owner_of: Dict[int, ast.AST],
                          declared: Set[str], scope: ast.AST,
                          fields: List[str]) -> dict:
    """Разбор ПО ИМЕНИ ПОЛЯ для ОДНОГО счётчика, уехавшего в документ.

    Правило объявлено здесь, ДО замера, и состоит из четырёх звеньев, у
    каждого свой отказ:

    1. счётчик уехал под РОВНО ОДНИМ именем поля — два имени значат, что
       чтение нельзя приписать ни одному (:data:`DOC_GAP_MANY_FIELDS`);
    2. это имя в файле пишет РОВНО ОДНА область
       (:func:`_field_write_scopes`) — иначе найденное чтение могло прийти от
       чужого документа (:data:`DOC_GAP_FIELD_WRITTEN_TWICE`);
    3. в файле есть ЧТЕНИЕ этого ключа вне области-писателя
       (:func:`_document_field_reads`) — иначе документ читают не здесь, и это
       предел прибора, а не отсутствие вреда
       (:data:`DOC_GAP_NO_READER_IN_FILE`);
    4. читателя разбирает :func:`_one_step_reader` — правило читателя УЖЕ
       соседское, второй копии его здесь нет, и найденный раскол есть
       доказанный МИНИМУМ. Исходы нескольких читателей сводит
       :func:`_merge_step_reads`.
    """
    if len(fields) != 1:
        return {"verdict": ONE_STEP_UNRESOLVED, "gap": DOC_GAP_MANY_FIELDS,
                "splits": [], "field": None, "read_forms": [],
                "writers": None, "readers": 0}
    field = fields[0]
    writers = _field_write_scopes(tree, owner_of, field)
    if len(writers) != 1:
        return {"verdict": ONE_STEP_UNRESOLVED,
                "gap": DOC_GAP_FIELD_WRITTEN_TWICE, "splits": [],
                "field": field, "read_forms": [], "writers": len(writers),
                "readers": 0}
    reads = _document_field_reads(tree, owner_of, field, scope)
    if not reads:
        return {"verdict": ONE_STEP_UNRESOLVED,
                "gap": DOC_GAP_NO_READER_IN_FILE, "splits": [],
                "field": field, "read_forms": [], "writers": len(writers),
                "readers": 0}
    seen = [_one_step_reader(reader_scope, node, declared)
            for reader_scope, node, _form in reads]
    merged = _merge_step_reads(seen)
    return {**merged, "field": field,
            "read_forms": sorted({form for _s, _n, form in reads}),
            "writers": len(writers), "readers": len(reads)}


def _document_reader_sites(rel: str, tree: ast.AST) -> List[dict]:
    """Счётчики ОДНОГО файла, уехавшие в ДОКУМЕНТ, с исходом разбора по полю.

    Население НЕ пересобирается и правило соседа НЕ копируется: обход тот же
    (:func:`_one_step_site_nodes`), поле считает сам сосед
    (:func:`_field_step`), а отбираются строки, которым он отказал ИМЕННО
    двумя именами класса «документ читают не у зовущего». Своего правила
    «какой счётчик открыт», «что есть побег», «каким маршрутом» и «под каким
    полем» здесь нет ни одного.
    """
    rows: List[dict] = []
    parents: Optional[Dict[int, ast.AST]] = None
    owner_of: Optional[Dict[int, ast.AST]] = None
    declared: Optional[Set[str]] = None
    for site, target, scope in _one_step_site_nodes(rel, tree):
        if site.get("step_gap") != STEP_GAP_CONTAINER or target is None:
            continue
        if parents is None:
            parents = _parent_map(tree)
            owner_of = _counter_owner_scopes(tree)
            declared = _declared_constant_names(tree)
        field_out = _field_step(tree, parents, owner_of, declared, scope,
                                target)
        if field_out["gap"] not in (FIELD_GAP_FIELD_NEVER_READ,
                                    STEP_GAP_RESULT_UNBOUND):
            continue
        out = _document_reader_step(tree, owner_of, declared, scope,
                                    list(field_out["fields"]))
        rows.append({**site, "field_gap": field_out["gap"],
                     "fields": field_out["fields"],
                     "doc_step": out["verdict"], "doc_gap": out["gap"],
                     "field": out["field"], "read_forms": out["read_forms"],
                     "doc_splits": out["splits"], "writers": out["writers"],
                     "readers": out["readers"]})
    return rows


def _document_reader_control() -> dict:
    """Проба объявленного правила — до замера, обеими половинами.

    Первая половина требует довести до расколотого читателя КАЖДЫЙ счётчик
    положительной сцены и доказать это ВСЕМИ объявленными формами чтения
    поля. Вторая
    требует ОТКАЗАТЬ там, где отказать должно, и отказать РАЗНЫМИ именами —
    иначе «разбор разрешил N» было бы неотличимо от «разбор объявляет
    разрешённым что угодно». Любая половина не сошлась ⇒ шаг отказывает
    целиком: число, полученное правилом, которое промахивается по известной
    форме, есть свойство ПРАВИЛА, а не населения.
    """
    try:
        source = _document_reader_sites("<control>",
                                        ast.parse(DOC_READER_CONTROL_SOURCE))
        clean = _document_reader_sites("<control-clean>",
                                       ast.parse(DOC_READER_CONTROL_CLEAN))
    except SyntaxError as exc:
        return {"passed": False,
                "reason": f"сцена контроля не разобрана: {exc}"}
    if len(source) != len(_DOC_READ_FORMS) + 1:
        return {"passed": False, "reason": (
            f"в положительной сцене правило нашло {len(source)} счётчик(ов), "
            f"уехавш(их) в документ, из {len(_DOC_READ_FORMS) + 1} — "
            f"разрешать по имени поля нечего")}
    split = [s for s in source if s["doc_step"] == ONE_STEP_SPLITS]
    if len(split) != len(source):
        return {"passed": False, "reason": (
            f"разбор по имени поля довёл до расколотого читателя "
            f"{len(split)} из {len(source)} счётчиков: исходы "
            f"{[(s['doc_step'], s['doc_gap']) for s in source]}")}
    forms = sorted({f for s in split for f in s["read_forms"]})
    if forms != sorted(_DOC_READ_FORMS):
        return {"passed": False, "forms": forms, "reason": (
            f"раскол доказан формами чтения {forms}, а сцена несёт обе: "
            f"{sorted(_DOC_READ_FORMS)} — ненайденная форма есть слепота "
            f"правила, а не отсутствие читателей")}
    if len(clean) != 5:
        return {"passed": False, "reason": (
            f"в отрицательной сцене правило нашло {len(clean)} счётчик(ов), "
            f"уехавш(их) в документ, из 5")}
    false_splits = [s for s in clean if s["doc_step"] == ONE_STEP_SPLITS]
    benign = [s for s in clean if s["doc_step"] == ONE_STEP_WHOLESALE]
    gaps = sorted({s["doc_gap"] for s in clean if s["doc_gap"]})
    want = sorted((DOC_GAP_FIELD_WRITTEN_TWICE, DOC_GAP_NO_READER_IN_FILE,
                   STEP_GAP_ESCAPES_AGAIN, READER_GAP_DYNAMIC))
    if false_splits or len(benign) != 1 or gaps != want:
        return {"passed": False, "reason": (
            f"на отрицательной сцене ожидались ноль расколов, один "
            f"безвредный читатель и ЧЕТЫРЕ разных отказа ({want}), а вышло "
            f"{[(s['doc_step'], s['doc_gap']) for s in clean]}")}
    return {"passed": True, "known_case_resolved": len(split),
            "read_forms": forms, "clean_false_splits": 0,
            "clean_refusal_names": gaps, "clean_benign": len(benign)}


def document_field_reader_in_file(root: Path, field_step: Optional[dict]
                                  ) -> dict:
    """Сколько счётчиков, уехавших в ДОКУМЕНТ, разрешает разбор ПО ИМЕНИ ПОЛЯ (**заказ G80 п. 1**).

    ADR-463 ответил на заказ G79 нулём и назвал главным числом **26 из 53**:
    два имени отказа — «зовущий не читает ЭТО поле» (16) и «результат никуда
    не связан» (10) — суть ОДИН класс, названный с двух сторон. Счётчик
    кладут в документ, документ возвращают, а поле его читают не у зовущего,
    а много позже и другой точкой входа. Заказ G80 п. 1 дословно:

    > Сколько из 26 разрешает разбор ПО ИМЕНИ ПОЛЯ ЧЕРЕЗ ГРАНИЦУ ФУНКЦИИ (кто
    > в этом файле вообще читает ключ ``X`` у чего угодно) и сколько остаётся
    > третьим исходом; односторонность («нашли читателя ключа ``X``» не есть
    > «это НАШ счётчик») обязана быть названа вслух и ограничена.

    Ограничение односторонности — не оговорка, а ЗВЕНО правила с машинным
    именем: ключ, который в файле пишет больше одной области, объявляется
    третьим исходом (:data:`DOC_GAP_FIELD_WRITTEN_TWICE`), потому что
    найденное чтение могло прийти от чужого документа. Отрицательная половина
    контроля несёт ровно такой счётчик — с ГОТОВЫМ читателем, который правило
    обязано НЕ засчитать.

    Население берётся у соседа и СВЕРЯЕТСЯ с его числом: свой обход есть
    вторая дорога к тому же населению, и разойдясь с первой, он отвечал бы на
    другой вопрос.

    ADVISORY: ни одного счётчика, ни одного читателя и ни одного гейта эта
    работа не правит, ``applied`` ложно.
    """
    head = {
        "question": ("сколько из счётчиков, уехавших в ДОКУМЕНТ, разрешает "
                     "разбор по имени поля через границу функции и сколько "
                     "остаётся третьим исходом"),
        "order": "G80.1",
        "applied": False,
        "dirs": list(OPEN_COUNTER_DIRS),
        "skipped_dirs": list(OPEN_COUNTER_SKIP),
    }
    if (not isinstance(field_step, dict)
            or str(field_step.get("status")) != "MEASURED"):
        return {**head, "status": "UNMEASURED",
                "unmeasured_class": UNMEASURED_DOC_NEIGHBOUR,
                "reason": ("шаг переноса полем не измерен — населения «уехал "
                           "в документ» не существует; это НЕ «таких "
                           "счётчиков нет»")}
    reasons = observed(field_step, "unresolved_reasons", kind=dict)
    never_read = (None if reasons is None
                  else observed(reasons, FIELD_GAP_FIELD_NEVER_READ, kind=int))
    unbound = (None if reasons is None
               else observed(reasons, STEP_GAP_RESULT_UNBOUND, kind=int))
    if never_read is None or unbound is None:
        return {**head, "status": "UNMEASURED",
                "unmeasured_class": UNMEASURED_DOC_NEIGHBOUR,
                "reason": ("сосед не назвал числа счётчиков, уехавших в "
                           "документ, — сверять свой обход не с чем")}
    declared_population = never_read + unbound
    control = _document_reader_control()
    head["control"] = control
    if not control.get("passed"):
        return {**head, "status": "UNMEASURED",
                "unmeasured_class": UNMEASURED_DOC_CONTROL,
                "reason": (f"объявленное правило разбора по имени поля не "
                           f"прошло контроль: {control.get('reason')}")}

    rows: List[dict] = []
    unreadable: List[dict] = []
    scanned = 0
    for sub in OPEN_COUNTER_DIRS:
        base = root / sub
        if not base.is_dir():
            unreadable.append({"file": sub, "reason": "каталога нет в дереве"})
            continue
        for path in sorted(base.rglob("*.py")):
            rel = path.relative_to(root).as_posix()
            if any(rel.startswith(skip) for skip in OPEN_COUNTER_SKIP):
                continue
            scanned += 1
            try:
                tree = ast.parse(path.read_text(encoding="utf-8"))
            except (OSError, SyntaxError, UnicodeDecodeError) as exc:
                unreadable.append({"file": rel,
                                   "reason": f"{type(exc).__name__}: {exc}"})
                continue
            rows.extend(_document_reader_sites(rel, tree))

    if len(rows) != declared_population:
        return {**head, "status": "UNMEASURED",
                "unmeasured_class": UNMEASURED_DOC_POPULATION,
                "walked": len(rows), "census": declared_population,
                "files_unreadable": unreadable,
                "reason": (f"свой обход нашёл {len(rows)} счётчик(ов), "
                           f"уехавш(их) в документ, сосед — "
                           f"{declared_population}: разбор по имени поля по "
                           f"ДРУГОМУ населению отвечал бы на другой вопрос")}

    outcomes = {cls: sum(1 for r in rows if r["doc_step"] == cls)
                for cls in _ONE_STEP_OUTCOMES}
    gaps = {gap: sum(1 for r in rows if r.get("doc_gap") == gap)
            for gap in _DOC_GAPS}
    read_forms = {form: sum(1 for r in rows
                            if form in (r.get("read_forms") or []))
                  for form in _DOC_READ_FORMS}
    resolved = outcomes[ONE_STEP_SPLITS] + outcomes[ONE_STEP_WHOLESALE]
    split_rows = [r for r in rows if r["doc_step"] == ONE_STEP_SPLITS]
    # Два разных числа живости, и складывать их в одно было бы подменой
    # (урок ADR-462): «имя поля в файле однозначно» и «читатель этого имени в
    # файле НАЙДЕН» — разные достижения. Первое доказывает, что звенья 1–2
    # правила отработали, второе — что отработало и третье; четвёртое звено
    # видно по исходам.
    unique = sum(1 for r in rows
                 if r.get("doc_gap") not in (DOC_GAP_MANY_FIELDS,
                                             DOC_GAP_FIELD_WRITTEN_TWICE))
    reached = sum(1 for r in rows if int(r.get("readers") or 0) > 0)
    return {
        **head,
        "status": "MEASURED",
        "population": len(rows),
        "files_scanned": scanned,
        "files_unreadable": unreadable,
        "doc_step_outcomes": outcomes,
        "unresolved_reasons": gaps,
        "read_forms": read_forms,
        "resolved_by_document_step": resolved,
        "field_name_unique_in_file": unique,
        "reader_of_that_field_found": reached,
        "still_unmeasured": outcomes[ONE_STEP_UNRESOLVED],
        "harm_sample": [
            {"file": r["file"], "line": r["line"], "owner": r["owner"],
             "counter": r["counter"], "field": r.get("field"),
             "readers": r.get("readers"),
             "split": (r["doc_splits"] or [{}])[0].get("how")}
            for r in split_rows[:COSTED_SAMPLE]],
        "unresolved_sample": [
            {"file": r["file"], "line": r["line"], "owner": r["owner"],
             "counter": r["counter"], "gap": r.get("doc_gap"),
             "field": r.get("field"), "writers": r.get("writers")}
            for r in rows
            if r["doc_step"] == ONE_STEP_UNRESOLVED][:COSTED_SAMPLE],
        "blind": [
            ("связь идёт по ИМЕНИ ПОЛЯ, и имя не есть адрес: «в файле читают "
             f"ключ `X`» доказывает наш счётчик только потому, что ключ здесь "
             f"пишет РОВНО ОДНА область (`{DOC_GAP_FIELD_WRITTEN_TWICE}`) — "
             "снять это звено значило бы доказывать вред совпадением имён"),
            (f"файл ОДИН: `{DOC_GAP_NO_READER_IN_FILE}` есть предел прибора, "
             "а не отсутствие вреда — документ, который пишут здесь, а читают "
             "в другом файле, выглядит для шага ровно так же, как документ, "
             "который не читает никто"),
            ("читатель найден по имени поля, но ВЕЩЬ, у которой читают, не "
             "прослежена до писателя: между ними нет вызова по построению "
             "класса, и доказательства «это тот самый документ» у шага нет "
             "— свидетель односторонний"),
            ("правило читателя УЖЕ соседское: выражение класса через границу "
             "не уезжает, поэтому раскол доказывается только формой «поле "
             "прочитано объявленным ключом»; найденное есть доказанный "
             "МИНИМУМ"),
            (f"счётчик, прочитанный и убежавший СНОВА "
             f"(`{STEP_GAP_ESCAPES_AGAIN}`), остаётся НЕ ИЗМЕРЕННЫМ — это не "
             "«вреда нет», а «нужен ещё шаг»"),
            ("население взято у соседа и наследует ВЕСЬ его потолок сверху "
             "(ADR-461 — ключ, разобранный кортежем; ADR-462 — счётчик, не "
             "уезжающий вовсе; ADR-463 — форма переноса): своего замера "
             "населения у этого шага нет по построению"),
        ],
    }


def registry_ambiguity_scope(root: Path, *,
                             data_dir: Optional[Path] = None) -> dict:
    """Доля многозначных хвостов у КАЖДОГО документа реестра (**заказ G73 п. 2**).

    Цикл #674 измерил многозначность на ОДНОМ соседе и в ОДИН день — 16 хвостов
    из 121 (13,22 %) у ``census_consumer_census``, — а правило уплощения общее
    для всех. Заказ ставит вопрос дословно:

    > Какова доля многозначных хвостов у каждого документа реестра и есть ли
    > среди них тот, у кого она уже сегодня стоит читателю решения.

    Отвечается ДВУМЯ замерами, и второй не есть уточнение первого:

    1. **Доля у каждого** — по обоим правилам уплощения, с разбросом по
       населению. Одно число, снятое у одного документа, свойством РЕЕСТРА не
       является ровно так же, как счёт хвостов не был свойством документа.
    2. **Цена у читателя** — есть ли документ, чья многозначность уже сегодня
       лишает решающее чтение однозначной координаты. Читатели ищутся тем же
       :func:`_reader_touches`, что и у соседа: второй дороги к читателю здесь
       не заводится.

    Третий исход обязателен у обоих замеров: артефакта может не быть, он может
    оказаться не словарём и не JSON вовсе — и ни одно из этого не есть «у
    документа нет многозначности». Каталог данных — ВХОД, потому что в рабочем
    дереве живого ``data/`` нет по построению.

    **Пред-фильтр кандидатов объявлен и ПРОВЕРЯЕТСЯ.** Читатель ищется не во
    всём дереве, а среди файлов, чей текст вообще содержит имя переписи, её
    модуль или её артефакт; полный обход всех документов стоил бы часы. Фильтр
    есть НАДМНОЖЕСТВО по построению (ввоз, чтение файла и динамический ввоз по
    литералу оставляют имя в тексте), но «по построению» — не замер: у
    объявленного заранее документа (:data:`FILTER_CONTROL_CENSUS`) обход идёт
    ОБОИМИ способами, и расхождение отменяет весь шаг. Остаток, которого не
    видит и полный обход, назван вслух: имя, собранное из кусков в рантайме,
    невидимо любому разбору AST — им пользуется сам мост.

    ADVISORY: ни одно население не пересчитывается этим замером, правило
    уплощения не заменяется, ``applied`` ложно у всего шага.
    """
    head = {
        "question": ("какова доля многозначных хвостов у КАЖДОГО документа "
                     "реестра и есть ли среди них тот, у кого она уже сегодня "
                     "стоит читателю РЕШЕНИЯ"),
        "order": "G73.2",
        "applied": False,
        "registry_owner": REGISTRY_OWNER,
        "registry_attr": REGISTRY_ATTR,
        "filter_control_census": FILTER_CONTROL_CENSUS,
        "data_dir_declared": None if data_dir is None else str(data_dir),
    }
    try:
        bridge = importlib.import_module(REGISTRY_OWNER)
    except Exception as exc:                        # noqa: BLE001
        return {**head, "status": "UNMEASURED",
                "reason": (f"реестр {REGISTRY_OWNER} не ввезён "
                           f"({type(exc).__name__}: {exc})")}
    registry = getattr(bridge, REGISTRY_ATTR, None)
    if not isinstance(registry, dict) or not registry:
        return {**head, "status": "UNMEASURED",
                "reason": (f"у {REGISTRY_OWNER} нет непустого словаря "
                           f"`{REGISTRY_ATTR}` — население не объявлено")}

    # Каталоги читателей спрашиваются У СОСЕДА, а не перечисляются здесь:
    # второй список «где живёт код» и есть та самая вторая копия правила.
    try:
        neighbour = importlib.import_module(NEIGHBOUR_CENSUS)
        code_dirs = tuple(neighbour._CODE_DIRS)
    except Exception as exc:                        # noqa: BLE001
        return {**head, "status": "UNMEASURED",
                "reason": (f"каталоги читателей не спрошены у соседа "
                           f"{NEIGHBOUR_CENSUS} ({type(exc).__name__}: {exc}) "
                           f"— второй копии этого списка здесь не заводится")}
    if not code_dirs:
        return {**head, "status": "UNMEASURED",
                "reason": (f"сосед {NEIGHBOUR_CENSUS} объявил ПУСТОЙ "
                           f"`_CODE_DIRS` — обходить нечего, и это НЕ "
                           f"«читателей нет»")}

    # --- дерево читателей разбирается ОДИН раз ---------------------------
    sources: Dict[str, str] = {}
    trees: Dict[str, ast.AST] = {}
    unreadable: List[dict] = []
    for sub in code_dirs:
        base = root / sub
        if not base.is_dir():
            continue
        for path in sorted(base.rglob("*.py")):
            rel = path.relative_to(root).as_posix()
            try:
                text = path.read_text(encoding="utf-8")
                trees[rel] = ast.parse(text)
                sources[rel] = text
            except (OSError, SyntaxError, UnicodeDecodeError) as exc:
                unreadable.append({"file": rel,
                                   "reason": f"{type(exc).__name__}: {exc}"})
    if not trees:
        return {**head, "status": "UNMEASURED",
                "reason": (f"ни одного разобранного файла в {code_dirs} — "
                           f"читателя искать не в чем; это НЕ «читателей нет»")}

    def _candidates(name: str, dotted: str, artifact_name: str,
                    producer: str) -> List[str]:
        return [rel for rel, text in sources.items()
                if rel != producer
                and (dotted in text or artifact_name in text or name in text)]

    def _reach(rel: str, line: Optional[int]) -> dict:
        """Достижим ли вердикт этого чтения подстановкой в живой документ.

        Дерево берётся из уже разобранного набора: второго обхода файлов
        здесь не заводится, и файла, которого в наборе нет, не бывает по
        построению — но исход на этот случай всё равно назван, потому что
        «дерева нет» и «теста нет» суть разные утверждения.
        """
        return _reach_of(trees.get(rel), line)

    def _readers_of(rel_list: Iterable[str], dotted: str,
                    artifact_name: str, renderers: Tuple[str, ...],
                    producer: str) -> List[dict]:
        found: List[dict] = []
        for rel in rel_list:
            if rel == producer:
                continue
            item = _reader_touches(rel, trees[rel], dotted, artifact_name,
                                   renderers)
            if item["roads"]:
                found.append(item)
        return found

    rows: List[dict] = []
    unmeasured: List[dict] = []
    filter_control: Optional[dict] = None
    for name in sorted(registry):
        spec = registry[name]
        producer = str(spec.get("module") or "")
        artifact = str(spec.get("artifact") or "")
        if not producer or not artifact:
            unmeasured.append({"census": name, "outcome": DOC_ABSENT,
                               "reason": "реестр не объявил модуль или артефакт"})
            continue
        path = _artifact_path(root, artifact, data_dir)
        if not path.is_file():
            unmeasured.append({"census": name, "outcome": DOC_ABSENT,
                               "artifact": str(path),
                               "reason": f"артефакт не найден: {path}"})
            continue
        if path.suffix != ".json":
            unmeasured.append({"census": name, "outcome": DOC_NOT_JSON,
                               "artifact": str(path),
                               "reason": (f"артефакт не JSON-документ "
                                          f"(`{path.suffix or 'без суффикса'}`) "
                                          f"— уплощать нечего, и это НЕ "
                                          f"«многозначности нет»")})
            continue
        try:
            doc = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, ValueError, UnicodeDecodeError) as exc:
            unmeasured.append({"census": name, "outcome": DOC_UNREADABLE,
                               "artifact": str(path),
                               "reason": f"{type(exc).__name__}: {exc}"})
            continue
        if not isinstance(doc, dict):
            unmeasured.append({"census": name, "outcome": DOC_NOT_A_MAPPING,
                               "artifact": str(path),
                               "reason": (f"документ не словарь, а "
                                          f"`{type(doc).__name__}`")})
            continue
        producer_tree = trees.get(producer)
        if producer_tree is None:
            unmeasured.append({"census": name,
                               "outcome": DOC_PRODUCER_UNREADABLE,
                               "artifact": str(path),
                               "reason": (f"файл производителя {producer} не "
                                          f"разобран — дорогу ввоза "
                                          f"отрисовщика не построить")})
            continue

        measured = _document_ambiguity(doc)
        owners = measured.pop("_owners_shallow")
        ambiguous = measured.pop("_ambiguous_shallow")
        flat = measured.pop("_flat_shallow")
        dotted = producer[:-3].replace("/", ".") if producer.endswith(".py") \
            else producer.replace("/", ".")
        artifact_name = Path(artifact).name
        renderers = tuple(printed_by_producer(producer_tree))
        candidates = _candidates(name, dotted, artifact_name, producer)
        readers = _readers_of(candidates, dotted, artifact_name, renderers,
                              producer)
        costed, cost_counts = _costed_touches(readers, owners, ambiguous,
                                              flat, _reach)

        if name == FILTER_CONTROL_CENSUS:
            full = _readers_of(sorted(trees), dotted, artifact_name,
                               renderers, producer)
            lost = sorted({r["file"] for r in full}
                          - {r["file"] for r in readers})
            filter_control = {
                "census": name,
                "readers_filtered": len(readers),
                "readers_full_scan": len(full),
                "lost_by_filter": lost,
                "sound": not lost,
            }

        rows.append({
            "census": name,
            "producer": producer,
            "artifact": str(path),
            **measured,
            "readers": len(readers),
            "candidates": len(candidates),
            "cost_counts": cost_counts,
            "costs_a_reader": bool(costed),
            "costed_touches": len(costed),
            "costed_sample": costed[:COSTED_SAMPLE],
            # Полный перечень, а не образец: заказ G74 п. 1 делит ЭТИ чтения
            # по расхождению значений, и усечённое население ответило бы
            # числом меньше настоящего, не сказав об усечении ни слова.
            "costed_all": costed,
        })

    if filter_control is None:
        return {**head, "status": "UNMEASURED",
                "reason": (f"объявленный контроль фильтра "
                           f"`{FILTER_CONTROL_CENSUS}` не попал в замер — "
                           f"надмножественность пред-фильтра НЕ ПРОВЕРЕНА, и "
                           f"числа ниже не имеют основания")}
    if not filter_control["sound"]:
        return {**head, "status": "UNMEASURED",
                "filter_control": filter_control,
                "reason": (f"пред-фильтр кандидатов ПОТЕРЯЛ читателей у "
                           f"`{FILTER_CONTROL_CENSUS}`: "
                           f"{', '.join(filter_control['lost_by_filter'])} — "
                           f"надмножеством он не является, и население "
                           f"каждого документа занижено на неизвестную долю")}

    shares_shallow = [r["ambiguous_share_shallow_pct"] for r in rows
                      if r["ambiguous_share_shallow_pct"] is not None]
    shares_deep = [r["ambiguous_share_deep_pct"] for r in rows
                   if r["ambiguous_share_deep_pct"] is not None]
    costing = [r for r in rows if r["costs_a_reader"]]
    totals: Dict[str, int] = {COST_TAIL_UNAMBIGUOUS: 0, COST_PATH_RESOLVES: 0,
                              COST_DECIDES_AMBIGUOUS: 0,
                              COST_FIELD_UNMEASURED: 0}
    for row in rows:
        for key, value in row["cost_counts"].items():
            totals[key] = totals.get(key, 0) + value

    neighbour_stem = NEIGHBOUR_CENSUS.split(".")[-1]
    neighbour_row = next((r for r in rows if r["census"] == neighbour_stem),
                         None)
    neighbour_rank = None
    if neighbour_row is not None and shares_shallow:
        share = neighbour_row["ambiguous_share_shallow_pct"]
        neighbour_rank = (None if share is None else
                          1 + sum(1 for s in shares_shallow if s > share))

    return {
        **head,
        "status": "MEASURED",
        "verdict": (REGISTRY_COSTS_READER if costing
                    else REGISTRY_COSTS_NOBODY),
        "documents_declared": len(registry),
        "documents_measured": len(rows),
        "documents_unmeasured": len(unmeasured),
        "unmeasured": unmeasured,
        "files_parsed": len(trees),
        "files_unreadable": unreadable,
        "filter_control": filter_control,
        "share_shallow_min_pct": min(shares_shallow) if shares_shallow else None,
        "share_shallow_median_pct": _median(shares_shallow),
        "share_shallow_max_pct": max(shares_shallow) if shares_shallow else None,
        "share_deep_min_pct": min(shares_deep) if shares_deep else None,
        "share_deep_median_pct": _median(shares_deep),
        "share_deep_max_pct": max(shares_deep) if shares_deep else None,
        "neighbour_census": neighbour_stem,
        "neighbour_share_shallow_pct": (
            None if neighbour_row is None
            else neighbour_row["ambiguous_share_shallow_pct"]),
        "neighbour_rank_by_share": neighbour_rank,
        "documents_costing_a_reader": len(costing),
        "cost_totals": totals,
        "rows": rows,
        "blind": [
            "имя переписи, собранное из кусков в рантайме, невидимо любому "
            "разбору AST — им пользуется сам мост, и такой читатель не "
            "попадает ни в фильтрованный обход, ни в полный. Это ОСТАТОК, а "
            "не ноль",
            f"класс `{COST_FIELD_UNMEASURED}` сегодня ноль ПО ПОСТРОЕНИЮ "
            f"соседней дороги: `_reader_touches` решающее чтение без "
            f"разобранного поля не выпускает вовсе. Ноль здесь есть свойство "
            f"ДОРОГИ, а не документов реестра, и держится он ровно до тех "
            f"пор, пока дорога такого чтения не выпустит — класс заведён "
            f"затем, чтобы это было видно числом, а не молчанием (инв. #17)",
            "доля снята у документа В ТОМ ВИДЕ, в каком он лежит сегодня: "
            "перепись с пустым населением даёт мало хвостов не потому, что "
            "многозначности нет, а потому, что нечего уплощать — число "
            "`lists_in_doc` названо у каждой строки именно для этого",
        ],
    }


def neighbour_population_harm(root: Path, scale: Optional[dict],
                              registry: Optional[dict]) -> dict:
    """Меняет ли занижение населения зовущих хоть один ВЫВОД (**заказ G68 п. 1**).

    ADR-445 измерил ПОВЕРХНОСТЬ: у 43 переписей из 85 население зовущих
    занижено формой вопроса соседа :data:`NEIGHBOUR_CENSUS`. Заказ ставит
    следующий вопрос дословно:

    > Занижение измерено, а ВРЕД — нет. Сколько читателей соседнего документа
    > принимают решение по полю, куда невидимый потребитель не попал, — и у
    > скольких из них решение при его добавлении изменилось бы. Класс,
    > измеренный по поверхности и не спрошенный у ИСХОДА, есть та же
    > «структура вместо исхода», против которой написано правило приёмки.

    Отвечается ДВУМЯ замерами, и ни один не есть поправка к другому:

    1. **Что вообще сдвигается в документе соседа.** Сосед считается ДВАЖДЫ:
       как есть и с населением, расширенным ровно на измеренные места. Поле,
       не попавшее в разность, решения изменить не может НИ У КОГО — вход у
       читателя тождественно тот же. Это два прогона, а не рассуждение.
    2. **Кто по сдвинувшемуся полю РЕШАЕТ.** Читатели ищутся ПЯТЬЮ
       дорогами; спросить одну значило бы повторить слепоту соседа, чей
       вопрос не выражает ни искателя, ни читателя артефакта, ни ввозящего
       отрисовщик, ни достающего модуль ``importlib``. Пятая дорога добавлена
       ПОСЛЕ первого захода замера, который без неё не увидел собственных двух
       читателей — тех, чьё решение и есть предмет заказа.

    **Поля вердикта объявлены ДО замера** (:data:`NEIGHBOUR_VERDICT_FIELDS`,
    запрет G62): иначе «вердикт не сдвинулся» читалось бы как выбор удобного
    определения вердикта.

    **Форма расширения — предмет пробы, а не умолчание.** У синтезированного
    места нет строки, а область читателя разрешается по строке; поэтому
    прибор СЧИТАЕТ, у скольких мест форма вообще способна что-то изменить
    (спецификация реестра с объявленной областью), и второй формы требует
    ровно тогда, когда это число не ноль.

    **Цена прогона названа числом.** Пересчитать решение можно лишь у
    читателя, которого прибор способен позвать; у остальных исход ТРЕТИЙ, с
    названной ценой и названным полем, а не «решение не изменилось».

    ADVISORY: порог не вводится, ни один вердикт переписи этой координатой не
    меняется (``applied`` ложно).
    """
    head = {
        "question": ("меняет ли занижение населения зовущих хоть один ВЫВОД: "
                     "кто решает по сдвинувшемуся полю и у кого решение иное"),
        "order": "G68.1",
        "neighbour": NEIGHBOUR_CENSUS,
        "verdict_fields_declared": list(NEIGHBOUR_VERDICT_FIELDS),
        "applied": False,
    }
    if not isinstance(scale, dict) or scale.get("status") == "UNMEASURED":
        return {**head, "status": "UNMEASURED",
                "reason": ("масштаб невидимости не измерен — расширять "
                           "население нечем; это НЕ «вреда нет»")}
    sites = scale.get("sites")
    if not isinstance(sites, list):
        return {**head, "status": "UNMEASURED",
                "reason": ("у масштаба невидимости нет перечня мест — "
                           "расширение не построить; это НЕ «вреда нет»")}
    try:
        neighbour = importlib.import_module(NEIGHBOUR_CENSUS)
    except Exception as exc:                        # noqa: BLE001
        return {**head, "status": "UNMEASURED",
                "reason": (f"сосед {NEIGHBOUR_CENSUS} не ввезён "
                           f"({type(exc).__name__}: {exc})")}
    for name in ("measure", "find_callees", "find_by_name_consumers",
                 "OUTPUT_FILENAME", "_CODE_DIRS"):
        if not hasattr(neighbour, name):
            return {**head, "status": "UNMEASURED",
                    "reason": (f"у соседа нет имени `{name}` — сверить два "
                               f"прогона нечем")}

    neighbour_stem = NEIGHBOUR_CENSUS.split(".")[-1]
    widened = _widened_population(root, sites, shape=SHAPE_NO_LINE)
    real_callees = neighbour.find_callees
    real_by_name = neighbour.find_by_name_consumers
    widened_by_name = (
        lambda _root, _callees, _r=real_by_name, _extra=widened:
        list(_r(_root, _callees)) + list(_extra))
    try:
        callees = real_callees(root)
        # Одно и то же население переписей в ОБА прогона: разница обязана
        # приходить от расширения, а не от повторного обхода дерева.
        neighbour.find_callees = lambda _root, _c=callees: _c
        clean = neighbour.measure(root)
        neighbour.find_by_name_consumers = widened_by_name
        widened_doc = neighbour.measure(root)
    finally:
        neighbour.find_callees = real_callees
        neighbour.find_by_name_consumers = real_by_name

    if neighbour_stem not in callees:
        return {**head, "status": "UNMEASURED",
                "reason": ("сосед не числит переписью сам себя — его "
                           "отрисовщик не разрешить, и дорога ввоза "
                           "неизмерима")}
    producer_rel = callees[neighbour_stem]
    try:
        renderers = tuple(printed_by_producer(ast.parse(
            (root / producer_rel).read_text(encoding="utf-8"))))
    except (OSError, SyntaxError, UnicodeDecodeError) as exc:
        return {**head, "status": "UNMEASURED",
                "reason": (f"файл соседа {producer_rel} не прочитан ({exc}) — "
                           f"дорога ввоза отрисовщика неизмерима")}

    flat_clean = _flatten_doc(clean)
    flat_widened = _flatten_doc(widened_doc)
    changed = sorted(key for key in set(flat_clean) | set(flat_widened)
                     if flat_clean.get(key) != flat_widened.get(key))
    verdict_moved = [key for key in NEIGHBOUR_VERDICT_FIELDS if key in changed]
    # Совпадение по ПОСЛЕДНЕМУ применённому ключу: читатель пишет
    # `doc["consumers"]["by_name"]`, и координатой значения является `by_name`
    # (правило `_terminal_coordinate`: «контейнер привязкой не является»).
    changed_set = set(changed)
    changed_tails = {key.rsplit(".", 1)[-1] for key in changed}
    verdict_tails = {key.rsplit(".", 1)[-1]
                     for key in NEIGHBOUR_VERDICT_FIELDS}

    readers: List[dict] = []
    unreadable: List[dict] = []
    for sub in neighbour._CODE_DIRS:
        base = root / sub
        if not base.is_dir():
            continue
        for path in sorted(base.rglob("*.py")):
            rel = str(path.relative_to(root))
            if rel == producer_rel:
                continue
            try:
                tree = ast.parse(path.read_text(encoding="utf-8"))
            except (OSError, SyntaxError, UnicodeDecodeError) as exc:
                unreadable.append({"file": rel, "unreadable": str(exc)})
                continue
            item = _reader_touches(rel, tree, NEIGHBOUR_CENSUS,
                                   neighbour.OUTPUT_FILENAME, renderers)
            if not item["roads"]:
                continue
            for touch in item["touches"]:
                field = touch.get("field")
                touch["field_moved"] = (None if field is None
                                        else field in changed_tails)
                touch["field_is_verdict"] = (None if field is None
                                             else field in verdict_tails)
                touch["could_change"] = bool(touch["form"] == TOUCH_DECIDES
                                             and touch["field_moved"])
                # То же самое, но сверкой по ПОЛНОМУ пути (заказ G71 п. 2).
                # `None` у пути — третий исход, и он НЕ равен «не сдвинулось».
                path = touch.get("field_path")
                touch["field_path_moved"] = (None if path is None
                                             else path in changed_set)
                touch["could_change_by_path"] = bool(
                    touch["form"] == TOUCH_DECIDES
                    and touch["field_path_moved"])
            item["decides_on_moved"] = [t for t in item["touches"]
                                        if t["could_change"]]
            item["decides_on_moved_by_path"] = [
                t for t in item["touches"] if t["could_change_by_path"]]
            readers.append(item)
    could_change_readers = [r for r in readers if r["decides_on_moved"]]
    scope = _coordinate_scope(flat_clean, changed, readers)
    # Заказ G72 п. 2: само ПРАВИЛО уплощения, которым снят счёт хвостов
    # выше, списки не разворачивает — и цена этого выбора есть число.
    flatten = _flatten_rule_scope(clean, widened_doc, flat_clean,
                                  changed, readers)

    # Форма расширения: способна ли она вообще что-то изменить. Спецификация
    # реестра с ОБЪЯВЛЕННОЙ областью разрешает место по строке, а у
    # синтезированного места строки нет.
    scoped_paths = {spec["path"] for spec in CENSUS_CONSUMERS
                    if spec.get("scope")}
    shape_sensitive = sorted({site.get("file") for site in sites
                              if site.get("file") in scoped_paths})

    # Чистые прогоны, которые ступень уже посчитала для СЕБЯ: повторять их
    # значило бы платить дважды за один и тот же документ. Отсюда и цена
    # получается МАРЖИНАЛЬНОЙ — ровно та, которую стои́т оплата пересчёта.
    clean_docs = {"registry": registry}
    executed: List[dict] = []
    for spec in _EXECUTABLE_READERS:
        entry = {"key": spec["key"], "cost_s_declared": spec["cost_s_declared"],
                 "field": spec.get("field"), "why": spec["why"]}
        runner = _HARM_RUNNERS.get(spec["key"]) if spec.get("execute") else None
        project = _PROJECTORS.get(spec.get("project"))
        if runner is None or project is None:
            entry.update({
                "outcome": DECISION_NOT_EXECUTED,
                "reason": ("прогон не оплачен этим замером — объявленная цена "
                           f"{spec['cost_s_declared']} с; это ОСТАТОК, а не "
                           "«решение не изменилось»")})
            executed.append(entry)
            continue
        before = clean_docs.get(spec.get("clean_from"))
        reused = (isinstance(before, dict)
                  and before.get("status") not in (None, "UNMEASURED"))
        runs_timed = 1 if reused else 2
        started = time.monotonic()
        try:
            neighbour.find_callees = lambda _root, _c=callees: _c
            if not reused:
                before = runner(root)
            neighbour.find_by_name_consumers = widened_by_name
            after = runner(root)
        except Exception as exc:                    # noqa: BLE001 — причина важнее класса
            entry.update({"outcome": DECISION_UNMEASURED,
                          "cost_s_measured": round(time.monotonic() - started, 2),
                          "reason": f"{type(exc).__name__}: {exc}"})
            executed.append(entry)
            continue
        finally:
            neighbour.find_callees = real_callees
            neighbour.find_by_name_consumers = real_by_name
        entry["cost_s_measured"] = round(time.monotonic() - started, 2)
        entry["runs_timed"] = runs_timed
        entry["cost_basis"] = (COST_BASIS_WIDENED if reused
                               else COST_BASIS_BOTH)
        projection_before = project(before)
        projection_after = project(after)
        if (_projection_is_vacuous(projection_before)
                and _projection_is_vacuous(projection_after)):
            # Совпадение пустот не есть «решение то же»: сравнивать было
            # нечего, и молчаливое `unchanged` здесь и был бы вырожденный
            # сторож, которого перепись ищет у других.
            entry.update({
                "outcome": DECISION_UNMEASURED,
                "before": projection_before, "after": projection_after,
                "reason": ("проекция решения пуста в ОБОИХ прогонах — "
                           "сравнивать нечего; это НЕ «решение не изменилось»")})
            executed.append(entry)
            continue
        entry.update({
            "outcome": (DECISION_CHANGED
                        if projection_before != projection_after
                        else DECISION_UNCHANGED),
            "before": projection_before,
            "after": projection_after})
        executed.append(entry)

    findings: List[dict] = []
    if not verdict_moved:
        findings.append({
            "kind": "understatement_moves_no_verdict",
            "file": producer_rel, "channel": CHANNEL_CODE, "fields": [],
            "why": ("ни одно ОБЪЯВЛЕННОЕ поле вердикта соседа не сдвинулось "
                    "от расширения населения: у читателя, решающего по "
                    "вердикту, вход тождественно тот же, и решение измениться "
                    "не может. Сказано ДВУМЯ прогонами, а не выводом")})
    for reader in could_change_readers:
        findings.append({
            "kind": "reader_decides_on_moved_field",
            "file": reader["file"], "channel": reader["channel"],
            "fields": sorted({str(t["field"])
                              for t in reader["decides_on_moved"]}),
            "why": ("читатель решает по полю, которое от расширения населения "
                    "сдвигается — вход у него РАЗНЫЙ, и «решение то же» "
                    "требует прогона, а не вывода")})
    for row in scope["touches_admitted_by_tail_only"]:
        findings.append({
            "kind": "tail_match_admits_unmoved_field",
            "file": row["file"], "channel": _channel_of(row["file"]),
            "fields": [f"{row['field']} → {row['field_path']}"],
            "why": ("сверка по ХВОСТУ координаты впустила в население "
                    "читателя поля, которое от расширения НЕ сдвинулось: "
                    "полный путь разобран до якоря и в разность документа не "
                    "попал. Население — свойство правила, не дерева")})
    for row in scope["deciding_admitted_by_tail_path_unmeasured"]:
        findings.append({
            "kind": "coordinate_path_unmeasured",
            "file": row["file"], "channel": _channel_of(row["file"]),
            "fields": [f"{row['field']} ({row['path_outcome']})"],
            "why": ("читатель впущен в население по хвосту, а ПОЛНЫЙ путь его "
                    "координаты до якоря не разобран — про него не сказано ни "
                    "«лишний», ни «по делу». Это ТРЕТИЙ исход, а не ноль")})
    for row in scope["touches_admitted_by_path_only"]:
        findings.append({
            "kind": "path_admits_what_tail_missed",
            "file": row["file"], "channel": _channel_of(row["file"]),
            "fields": [f"{row['field']} → {row['field_path']}"],
            "why": ("сверка по ПОЛНОМУ пути впустила читателя, которого хвост "
                    "не впустил, — при разобранном пути это невозможно, и "
                    "значит неверно рассуждение самого прибора, а не дерево")})
    for entry in executed:
        if entry.get("outcome") == DECISION_CHANGED:
            findings.append({
                "kind": "reader_decision_changed",
                "file": PRODUCER, "channel": CHANNEL_CODE,
                "fields": [entry["key"]],
                "why": ("пересчитанное решение читателя ОТЛИЧАЕТСЯ: занижение "
                        "меняет не только число в отчёте, но и вывод")})

    if flatten["verdict"] == FLATTEN_RULE_DEPENDENT:
        findings.append({
            "kind": "tail_ambiguity_is_a_property_of_the_flatten_rule",
            "file": PRODUCER, "channel": CHANNEL_CODE,
            "fields": flatten["ambiguous_only_deep"],
            "why": (f"многозначных хвостов у документа "
                    f"{flatten['ambiguous_shallow']} из "
                    f"{flatten['tails_shallow']} по нынешнему правилу и "
                    f"{flatten['ambiguous_deep']} из "
                    f"{flatten['tails_deep']} при развёртывании списков — "
                    f"счёт, которым объяснён ноль разности, есть свойство "
                    f"ПРАВИЛА уплощения, а не документа")})
    if flatten["touches_admitted_by_deep_only"]:
        findings.append({
            "kind": "reader_invisible_to_the_flatten_rule",
            "file": PRODUCER, "channel": CHANNEL_CODE,
            "fields": sorted({str(row["field"]) for row
                              in flatten["touches_admitted_by_deep_only"]}),
            "why": ("решающее чтение сдвинувшегося поля НЕ попадает в "
                    "население `decides_on_moved`: его имя живёт только "
                    "внутри элемента списка, а нынешнее правило списки не "
                    "разворачивает")})

    counts = {
        "doc_fields": len(flat_clean),
        "doc_fields_moved": len(changed),
        "verdict_fields_declared": len(NEIGHBOUR_VERDICT_FIELDS),
        "verdict_fields_moved": len(verdict_moved),
        "widened_by": len(widened),
        "readers": len(readers),
        "readers_by_road": {},
        "touches": sum(len(r["touches"]) for r in readers),
        "touches_deciding": sum(1 for r in readers for t in r["touches"]
                                if t["form"] == TOUCH_DECIDES),
        "touches_printing": sum(1 for r in readers for t in r["touches"]
                                if t["form"] == TOUCH_PRINTS),
        "touches_unresolved": sum(1 for r in readers for t in r["touches"]
                                  if t["form"] == TOUCH_UNRESOLVED),
        "readers_deciding_on_moved": len(could_change_readers),
        "readers_decision_changed": len(
            [e for e in executed if e.get("outcome") == DECISION_CHANGED]),
        "readers_decision_unchanged": len(
            [e for e in executed if e.get("outcome") == DECISION_UNCHANGED]),
        "readers_not_executed": len(
            [e for e in executed if e.get("outcome") == DECISION_NOT_EXECUTED]),
        "readers_execution_unmeasured": len(
            [e for e in executed if e.get("outcome") == DECISION_UNMEASURED]),
        "shape_sensitive_sites": len(shape_sensitive),
        "files_unreadable": len(unreadable),
        "readers_deciding_on_moved_by_path": scope["readers_by_path"],
        "coordinate_sets_coincide": scope["sets_coincide"],
        "admitted_by_tail_only": len(scope["touches_admitted_by_tail_only"]),
        "admitted_by_path_only": len(scope["touches_admitted_by_path_only"]),
        "coordinate_path_unmeasured": len(
            scope["deciding_admitted_by_tail_path_unmeasured"]),
        "ambiguous_tails_total": scope["ambiguous_tails_total"],
        "ambiguous_tails_among_moved": len(scope["ambiguous_tails_among_moved"]),
        "flatten_verdict": flatten["verdict"],
        "tails_shallow": flatten["tails_shallow"],
        "tails_deep": flatten["tails_deep"],
        "ambiguous_tails_deep": flatten["ambiguous_deep"],
        "ambiguous_tails_only_deep": len(flatten["ambiguous_only_deep"]),
        "admitted_by_deep_only": len(
            flatten["touches_admitted_by_deep_only"]),
        "lists_in_doc": flatten["lists_in_doc"],
    }
    for reader in readers:
        for road in reader["roads"]:
            counts["readers_by_road"][road] = (
                counts["readers_by_road"].get(road, 0) + 1)

    return {
        **head,
        "status": ("CRITICAL" if counts["readers_decision_changed"]
                   else "MEASURED"),
        "counts": counts,
        "moved_fields": changed,
        "verdict_fields_moved": verdict_moved,
        "readers": readers,
        "executed": executed,
        "shape_sensitive_sites": shape_sensitive,
        "coordinate_scope": scope,
        "flatten_scope": flatten,
        "widened_shape": SHAPE_NO_LINE,
        "unreadable": unreadable,
        "findings": findings,
        "blind": [
            f"вопрос «изменилось бы решение» пересчитан только у читателей, "
            f"которых прибор способен позвать: исполнено "
            f"{counts['readers_decision_changed'] + counts['readers_decision_unchanged']}"
            f", не оплачено {counts['readers_not_executed']} — у "
            f"неоплаченного названы цена и поле, и это ОСТАТОК, а не "
            f"«решение то же»",
            f"сдвиг поля измерен ПО ЗНАЧЕНИЮ документа, а координата "
            f"читателя сверяется по ПОСЛЕДНЕМУ применённому ключу. С заказа "
            f"G71 п. 2 это НЕ проза, а число: хвостов документа "
            f"{scope['doc_tails']}, из них многозначных "
            f"{scope['ambiguous_tails_total']} "
            f"({scope['ambiguous_tails_among_moved']} среди сдвинувшихся); "
            f"население по хвосту {scope['readers_by_tail']}, по полному пути "
            f"{scope['readers_by_path']}, множества "
            f"{'совпадают' if scope['sets_coincide'] else 'НЕ совпадают'}. "
            f"Доказанно лишних чтений "
            f"{len(scope['touches_admitted_by_tail_only'])}, НЕ ИЗМЕРЕНО "
            f"{len(scope['deciding_admitted_by_tail_path_unmeasured'])} — "
            f"второе НЕ есть «не сдвинулось»",
            f"счёт хвостов выше снят правилом, которое разворачивает "
            f"словари и НЕ разворачивает списки. С заказа G72 п. 2 цена "
            f"этого выбора есть ЧИСЛО: списков в документе "
            f"{flatten['lists_in_doc']} ({flatten['list_elements']} "
            f"элемент(ов)), хвостов по нынешнему правилу "
            f"{flatten['tails_shallow']} против {flatten['tails_deep']} при "
            f"развёртывании, многозначных {flatten['ambiguous_shallow']} "
            f"против {flatten['ambiguous_deep']}; вердикт о происхождении "
            f"многозначности — {flatten['verdict']}. Правило НЕ заменено: "
            f"глубокое теряет имя самого списка у "
            f"{len(flatten['tails_only_shallow'])} хвост(ов), и это его "
            f"цена, а не оговорка",
            "расширение — самое ДЕШЁВОЕ из возможных (ввоз отрисовщика "
            "признаётся зовущим класса `by_name`); иная форма починки могла "
            "бы сдвинуть иные поля, и на её цену отвечает отдельный пункт "
            "заказа, а не эта координата",
            f"форма синтеза места (со строкой и без) способна изменить ответ "
            f"у {counts['shape_sensitive_sites']} мест — тех, что попадают на "
            f"спецификацию реестра с объявленной областью; при нуле ответ от "
            f"формы НЕ зависит, и это число, а не обещание",
            "третий исход чтения назван отдельно: значение, уехавшее дальше "
            "по коду, НЕ объявляется «не решающим» — про него не сказано "
            "ничего (инв. #17)",
            "дорог к населению пять, и все пять статические: читатель, "
            "достающий соседа `import_module(<переменная>)`, невидим ПО "
            "ПОСТРОЕНИЮ — у соседа это же место едет отдельным числом, а не "
            "нулём",
            "порог не введён: ни один вердикт переписи эта координата не "
            "меняет (`applied` ложно)",
        ],
    }


#: Чем зовётся читатель, чьё решение пересчитывается. Таблица ОТДЕЛЬНО от
#: :data:`_EXECUTABLE_READERS`: там объявлены цена и поле, здесь — способ
#: зова, и слить их значило бы позвать не того читателя, чьё имя объявлено.
_HARM_RUNNERS = {"consumer_registry_completeness":
                 lambda root: consumer_registry_completeness(root),
                 "invisible_consumer_scale":
                 lambda root: invisible_consumer_scale(root)}


def bilingual_reach(root: Path, rows: List[dict],
                    index: Dict[str, List[str]],
                    synonyms: Optional[dict] = None) -> dict:
    """Свод заказа **G60**: одноязычие — свойство ОДНОГО свидетеля или ВСЕХ.

    Сводится здесь, а не доливается в соседние координаты, по той же причине,
    по которой отдельны все пять прежних: «сколько объявлено» и «что прибавило
    бы двуязычие» суть разные вопросы, и общий ключ слил бы их ответы.
    """
    table = _TOKEN_SYNONYMS if synonyms is None else synonyms
    if not table:
        return {
            "verdict": BILINGUAL_NOTHING_TO_ASK,
            "reason": ("карта синонимов пуста — спрашивать двуязычие нечем; "
                       "это НЕ «одноязычие безвредно»"),
            "witnesses": {},
        }
    subject = bilingual_subject_reach(root, rows, table)
    names = bilingual_name_reach(root, index, table)
    coverage = synonym_map_coverage(root, table)
    witnesses = {WITNESS_SUBJECT: subject, WITNESS_NAME_CHANNEL: names}
    unmeasured = [who for who, what in witnesses.items()
                  if what.get("status") == BILINGUAL_UNMEASURED]
    if unmeasured:
        return {
            "verdict": BILINGUAL_UNMEASURED,
            "reason": "; ".join(
                f"{who}: {witnesses[who].get('reason')}" for who in unmeasured),
            "witnesses": witnesses,
            "map_coverage": coverage,
        }
    gained = subject["changed"] + names["authority_corroborated"]
    if gained:
        verdict = BILINGUAL_SHIFT
        reason = (
            f"двуязычие прибавляет свидетеля: у `{WITNESS_SUBJECT}` "
            f"{subject['changed']} пар(ы) из {subject['pairs_read']}, у канала "
            f"имени {names['authority_corroborated']} пар(ы) с подтверждающей "
            f"величиной из {names['authority_raw']} названных — одноязычие "
            f"свойство НЕ одной координаты")
    else:
        verdict = BILINGUAL_INERT
        reason = (
            f"карта спрошена и не сдвинула ни одного вердикта: у "
            f"`{WITNESS_SUBJECT}` карта применима к {subject['askable']} из "
            f"{subject['modules']} модулей населения, у канала имени "
            f"{names['candidates']} разрешимых имён — ноль ИЗМЕРЕН")
    return {
        "verdict": verdict,
        "reason": reason,
        "question": ("одноязычие — свойство ОДНОЙ координаты или ВСЕХ "
                     "свидетелей имени (заказ G60 пп. 1–2)"),
        "witnesses": witnesses,
        "map_coverage": coverage,
        "blind": [
            "подтверждение ВЕЛИЧИНОЙ есть фильтр обозримости, а НЕ доказательство "
            "тождества смысла: одно число называет несколько порогов (ADR-418), и "
            "названные пары проверяет человек, а не эта координата",
            "ноль у свидетеля предмета есть свойство КАРТЫ, а не дерева, ровно "
            "настолько, насколько мал `askable`: карту спросили не у всего населения",
            "полнота карты измерена ТОЛЬКО по порогам, уже известным переписи; "
            "порог, не объявленный ни одной поверхностью решения, этой мере не виден",
            "контроль мерит ЧАСТОТУ канала на абзацах без языка права изменения, а "
            "не верность найденной пары — это разные вопросы",
            "канал имени по ТОКЕНАМ строго слабее дословного: двуязычие его не "
            "усиливает, а расширяет население, и цена расширения названа числом",
        ],
    }


def measure(root: Path, *, now: Optional[dt.datetime] = None,
            probe_ledger: Optional[Path] = None,
            data_dir: Optional[Path] = None) -> dict:
    """Перепись пар «сторож × исполнитель × имя»."""
    # Отметка входа в СТУПЕНЬ — первым делом и до любого отказа: вопрос
    # «замкнулся ли дочерний прогон на ступень» (заказ G70 п. 1) не зависит
    # от того, довела ли ступень работу до конца. В обычном прогоне, где
    # прибор процесс не помечал, побочного действия нет вовсе.
    _reentry_note("measure")
    root = Path(root)
    if not root.is_dir():
        raise NotMeasured(f"корень дерева не прочитан: {root}")

    unreadable: List[dict] = []

    # --- сторона исполнителя: имя -> [(модуль, значение)] --------------------
    executors: Dict[str, List[Tuple[str, Optional[str]]]] = {}
    # Второе население — ВСЕ имена верхнего уровня, включая приватные: ось
    # «исполнитель × исполнитель» (заказ G52 п. 1) считает их копиями, и
    # основание этой разницы названо в докстринге `peer_pairs`.
    declared: Dict[str, List[Tuple[str, Optional[str]]]] = {}
    exec_imports: Dict[str, set] = {}
    executor_files = _executor_files(root)
    for path in executor_files:
        rel = path.relative_to(root).as_posix()
        try:
            tree = ast.parse(path.read_text(encoding="utf-8"))
        except Exception as exc:  # noqa: BLE001
            unreadable.append({"file": rel, "side": "executor",
                               "reason": f"{type(exc).__name__}: {exc}"})
            continue
        exec_imports[rel] = imported_modules(tree)
        for name, value in toplevel_constants(tree).items():
            declared.setdefault(name, []).append((rel, value))
            if name.startswith("_"):
                continue        # приватное имя правилом наружу не является
            executors.setdefault(name, []).append((rel, value))

    # --- сторона сторожа ----------------------------------------------------
    rows: List[dict] = []
    counts = {CLASS_TWO_COPIES: 0, CLASS_DELEGATES: 0, CLASS_VALUE_DIFFERS: 0,
              CLASS_NOT_CONSTANT: 0, CLASS_AMBIGUOUS: 0}
    surface: List[str] = []
    # Третья ось (заказ G53 п. 1) спрашивает сторожей о тех же именах, что и
    # ось исполнителей. Держатся ИМЯ и ЗНАЧЕНИЕ (дёшево), а текст сторожа
    # перечитывается лениво и только у кандидатов — тем же `_text`, что и у
    # соседней оси: вторая копия правила «как читать файл» здесь не заводится.
    guard_declared: Dict[str, List[Tuple[str, Optional[str]]]] = {}
    guard_imports_by_rel: Dict[str, set] = {}
    guard_files = _guard_files(root)
    # Пороги спрашиваются ПОСЛЕ корней населения и ДО разбора форм. Порядок
    # обоих отказов измерен тестами: «корень не прочитан» остаётся первым
    # (он отменяет перепись целиком), а «пороги не прочитаны» отменяет право
    # чинить — и ни один из них не выдаётся за пустой результат.
    thresholds = risk_policy_thresholds(root)
    for path in guard_files:
        rel = path.relative_to(root).as_posix()
        try:
            source = path.read_text(encoding="utf-8")
            tree = ast.parse(source)
        except Exception as exc:  # noqa: BLE001
            unreadable.append({"file": rel, "side": "guard",
                               "reason": f"{type(exc).__name__}: {exc}"})
            continue

        guard_imports = imported_modules(tree)
        guard_imports_by_rel[rel] = guard_imports
        touches_state = any(mark in source for mark in _REPO_STATE_MARKS)

        for name, guard_value in toplevel_constants(tree).items():
            if name.startswith("_") or name.startswith("test_"):
                continue
            guard_declared.setdefault(name, []).append((rel, guard_value))
            side = executors.get(name)
            if not side:
                continue
            if len(side) > 1:
                # Имя, объявленное многими исполнителями, не называет ОДНО
                # правило. Это не находка и не «сошлось» — это своя корзина.
                counts[CLASS_AMBIGUOUS] += 1
                continue
            exec_rel, exec_value = side[0]
            if guard_value is None or exec_value is None:
                counts[CLASS_NOT_CONSTANT] += 1
                continue
            if guard_value != exec_value:
                counts[CLASS_VALUE_DIFFERS] += 1
                continue
            if reaches(source, guard_imports, exec_rel):
                counts[CLASS_DELEGATES] += 1
                continue
            counts[CLASS_TWO_COPIES] += 1
            rows.append({
                "verdict": CLASS_TWO_COPIES,
                "guard": rel,
                "executor": exec_rel,
                "name": name,
                "value": guard_value,
            })

        # Сторож трогает состояние репозитория и НИ ОДНОЙ дверью не достаёт
        # дерева-предмета ⇒ каждое проверяемое им условие — его собственная
        # копия ПО ПОСТРОЕНИЮ. Переименованную копию правило имени не видит
        # никогда, и вот её верхняя граница.
        if touches_state and not _reaches_subject_tree(source):
            surface.append(rel)

    rows.sort(key=lambda r: (r["guard"], r["name"]))

    # --- форма починки у каждой находки (заказ G42 п. 1) --------------------
    # Витрина порогов читается ДО разбора форм: с заказа G54 п. 1 её
    # спрашивают ВСЕ ТРИ оси, а не одна лишь третья.
    constitution, constitution_unread = constitution_values(root)
    remedy_counts = {cls: 0 for cls in _REMEDY_CLASSES}
    text_cache: Dict[str, Optional[str]] = {}

    def _text(rel: str) -> Optional[str]:
        if rel not in text_cache:
            try:
                text_cache[rel] = (root / rel).read_text(encoding="utf-8")
            except OSError:
                text_cache[rel] = None
        return text_cache[rel]

    ledger, ledger_absent = load_probe_ledger(
        Path(probe_ledger) if probe_ledger is not None else root / PROBE_LEDGER)
    probe_stats = {"fresh": 0, "stale": 0, "missing": 0,
                   "ledger_absent": ledger_absent}

    for row in rows:
        if row["verdict"] not in _FINDING_CLASSES:
            continue
        probe = _probe_verdict(root, row, ledger, probe_stats)
        guard_text = _text(row["guard"])
        guard_loads: Optional[bool] = None
        if guard_text is not None:
            try:
                guard_loads = constant_is_loaded(ast.parse(guard_text), row["name"])
            except SyntaxError:
                guard_loads = None       # не разобрано ⇒ НЕ «не читается»
        row.update(classify_remedy(row, guard_text=guard_text,
                                   executor_text=_text(row["executor"]),
                                   thresholds=thresholds,
                                   constitution=constitution,
                                   constitution_unread=constitution_unread,
                                   probe=probe, guard_loads=guard_loads))
        remedy_counts[row["remedy"]] += 1

    # --- вторая ось: копия между двумя исполнителями (заказ G52 п. 1) ------
    # Текст стороны перечитывается лениво и только у кандидатов: держать в
    # памяти исходники всех исполнителей ради вопроса, который задаётся
    # шестистам именам, — цена без покупателя.
    peer_rows, peer_counts = peer_pairs(
        declared,
        source_of=_text,
        imports_of=lambda rel: exec_imports.get(rel, set()),
        thresholds=thresholds,
        constitution=constitution,
        constitution_unread=constitution_unread)

    # --- третья ось: ТРИ копии одного правила (заказ G53 п. 1) -------------
    triple_rows, triple_counts = triple_copies(
        peer_rows, guard_declared,
        source_of=_text,
        imports_of=lambda rel: guard_imports_by_rel.get(rel, set()),
        thresholds=thresholds,
        constitution=constitution,
        constitution_unread=constitution_unread)
    intersection = axes_intersection(rows, peer_rows, declared)

    # --- население ПОВЕРХНОСТЕЙ РЕШЕНИЯ (заказ G55 п. 1) -------------------
    # Спрашивается у находок ВСЕХ ТРЁХ осей разом: поверхность решения не
    # знает, какая ось нашла пару, и делить население по осям значило бы
    # ответить на вопрос об устройстве прибора вместо вопроса о репозитории.
    surface_population = (
        [r for r in rows if r["verdict"] in _FINDING_CLASSES]
        + [r for r in peer_rows if r["verdict"] == CLASS_PEER_TWO_COPIES]
        + [r for r in triple_rows if r["verdict"] == CLASS_TRIPLE])
    surfaces = decision_surfaces(root, surface_population)

    # --- канал ОБЪЯВЛЕНИЯ ИМЕНЕМ (заказ G56 п. 2) -------------------------
    # Мера выше ходит по ПУТЯМ и сама называет свою слепоту: объявление бывает
    # именем класса. Здесь у слепоты появляется число — население пути
    # перестаёт быть нижней границей с неизвестным зазором.
    definitions = toplevel_definitions(root)
    names = name_channel(
        root, surface_population,
        path_candidates=[s["path"] for s in (surfaces.get("surfaces") or [])],
        definitions=definitions)

    # --- канал ШИРОКОГО АБЗАЦА (заказ G57 п. 1) ---------------------------
    # Оба прежних канала молчат об абзаце, который мера пути отбрасывает как
    # широкий: канал пути его не читает, канал имени видит в нём только имена.
    # Здесь считается ПОТОЛОК зазора — и считается отдельной координатой,
    # которая в население объявленных поверхностей ничего не доливает.
    wide = wide_paragraph_channel(
        root, surface_population,
        path_candidates=[s["path"] for s in (surfaces.get("surfaces") or [])],
        name_candidates=[s["path"] for s in (names.get("surfaces") or [])]
        + list(names.get("already_declared_by_path") or []))

    # --- ФОРМА ШИРОКОЙ ТАБЛИЦЫ (заказ G58 п. 1) ---------------------------
    # Канал выше назвал ЦЕНУ широкого абзаца; заказ спрашивает, редка ли его
    # ФОРМА. Вопрос о выборке, поэтому меряется он и контролем — но контроль
    # каналом объявления не становится и в население поверхностей не входит.
    table_form = table_form_census(root)

    # --- ЧИСЛА ВНЕ КАНАЛА (заказ G59 п. 2) --------------------------------
    # Координата выше НАЗЫВАЕТ семь мест той же формы в `docs/**`; права
    # чинить у их чисел не спрашивает никто. Здесь спрашивается, пороги ли
    # это: если да — узка не форма, а ГРАНИЦА канала объявления.
    out_channel = out_of_channel_numbers(
        root, (table_form.get("channels", {})
               .get(TABLE_CHANNEL_DOCS, {})
               .get("long_line_hits") or []))

    # --- ДОСЯГАЕМОСТЬ ДВУЯЗЫЧИЯ (заказ G60 пп. 1–2) -----------------------
    # Координата выше нашла одноязычие У СЕБЯ и починила его картой. Здесь
    # спрашивается, класс это или единичный случай: населением служат ВСЕ три
    # оси переписи, а не та выборка, на которой одноязычие нашлось.
    bilingual = bilingual_reach(root, rows + peer_rows + triple_rows,
                                definitions[0])

    # --- ТОЧНОСТЬ КАНАЛА ИМЕНИ (заказ G61 п. 1) ---------------------------
    # Координата выше сказала, что двуязычие ПРИБАВЛЯЕТ пары. Сколько из них
    # настоящие — она не спрашивает, и «2 из 4» ADR-438 есть замер выборки
    # размера четыре. Здесь размечается ВСЁ население канала правилом,
    # записанным до разметки; в население объявленных поверхностей эта
    # координата ничего не доливает — она судит уже сделанный замер.
    name_channel_doc = (bilingual.get("witnesses") or {}).get(WITNESS_NAME_CHANNEL)
    name_precision = bilingual_name_precision(root, name_channel_doc)

    # --- ЦЕНА ТРЕБОВАНИЯ ДВУХ ТОКЕНОВ (заказ G62 п. 1) --------------------
    # Ширину интервала выше держит `UNDECIDED`, и заказ назвал кандидата:
    # потребовать у имени не один различающий токен, а два. Здесь считается
    # ЦЕНА кандидата в двух валютах и его независимость — сам порог не
    # вводится, поэтому координата ничего не гейтит и ни во что не входит.
    depth_price = token_depth_price(name_precision, name_channel_doc)

    # --- КАНДИДАТЫ В ТРЕТЬИ СВИДЕТЕЛИ (заказ G63 п. 1) --------------------
    # Координата выше доказала, что кандидат прежнего заказа читает ИМЯ и
    # потому свидетелем не является. Форма искомого названа — читать АБЗАЦ, —
    # и здесь кандидаты этой формы объявляются ДО разметки и меряются двумя
    # числами: решённые `UNDECIDED` и частота ошибки на контроле. Ни один
    # вердикт переписи эта координата не меняет.
    witness_price = paragraph_witness_price(root, name_precision)

    # --- ЦЕНА ДОПУСКА СВИДЕТЕЛЯ В ПРАВИЛО (заказ G64 п. 1) ---------------
    # Координата выше измерила у кандидатов два числа и прямо сказала, чего
    # не доказала: что кандидата стои́т ВВЕСТИ. Цена введения платится в
    # валюте книг — в парах, — и здесь считается именно она, вместе с обеими
    # границами интервала истины. Порог по-прежнему не вводится.
    admission_price = witness_admission_price(root, name_precision,
                                              name_channel_doc)

    # --- КАКУЮ БАЗУ БЕРЁТ ЧИТАТЕЛЬ (заказ G65 п. 1) ----------------------
    # Координата выше нашла расхождение у САМОЙ базы (пары книг ≠ `GENUINE`)
    # и честно сказала, чего не спрашивала: КТО из читателей какую базу берёт.
    # Здесь спрошены все три названных заказом читателя поимённо. Ни один
    # вердикт переписи эта координата не меняет — она мерит СЛОВАРЬ.
    base_naming = consumer_base_naming(root)

    # --- РЕЕСТР ЧИТАТЕЛЕЙ ПРОТИВ ЗАМЕРА ЗОВУЩИХ (заказ G66 п. 1) ---------
    # Координата выше мерила ИМЕНА у чисел трёх НАЗВАННЫХ читателей и честно
    # сказала, чего не спрашивала: полно ли само население читателей. Здесь
    # объявленное сводится с измеренным — и ни один вердикт переписи этой
    # координатой не меняется.
    registry_completeness = consumer_registry_completeness(root)

    # --- МАСШТАБ КЛАССА У ВСЕХ ПЕРЕПИСЕЙ (заказ G67 п. 1) ---------------
    # Координата выше нашла невидимого потребителя у ОДНОЙ переписи и честно
    # сказала, чего не спрашивала: у скольких ЕЩЁ население зовущих занижено
    # той же формой вопроса. Класс, найденный у одной и не померенный у
    # остальных, есть догадка о масштабе, а не замер.
    invisible_scale = invisible_consumer_scale(root)

    # --- ВРЕД ЗАНИЖЕНИЯ (заказ G68 п. 1) -------------------------------
    # Координата выше измерила ПОВЕРХНОСТЬ класса и честно сказала, чего не
    # спрашивала: меняет ли занижение хоть один ВЫВОД. Класс, измеренный по
    # поверхности и не спрошенный у ИСХОДА, есть та же «структура вместо
    # исхода», против которой написано правило приёмки. Чистый прогон
    # читателя `consumer_registry_completeness` берётся УЖЕ посчитанным —
    # второй его прогон стоил бы 21 с ни за что.
    population_harm = neighbour_population_harm(root, invisible_scale,
                                                registry_completeness)

    # --- ЦЕНА ПЕРЕСЧЁТА И ТАКТ (заказ G69 п. 1) ------------------------
    # Координата выше оставила остаток «прогон не оплачен» и назвала ему цену
    # ЛИТЕРАЛОМ. Литерал, снятый одним прогоном на одном дереве, свойством
    # читателя не является: цена меряется часами вокруг настоящего пересчёта,
    # а бюджет читается у производителя артефакта.
    cost_budget = recompute_cost_budget(root, population_harm)

    # --- ЦЕНА КАНАЛА ТЕСТА И ЗАМЫКАНИЕ (заказ G70 п. 1) ----------------
    # Координата выше оценила читателей-КОД, а читателей канала теста
    # объявила неизмеримыми ПО ПРИЧИНЕ («вложенный прогон»). Причина эта —
    # утверждение о механизме, и у него не было ни одного замера. Отказ, чья
    # причина не померена, ничем не лучше цены, которую никто не делил на
    # бюджет.
    test_channel_cost = reader_cost_of_test_channel(root, population_harm,
                                                 cost_budget)

    # --- ДОЛЯ МНОГОЗНАЧНЫХ ХВОСТОВ У ВСЕГО РЕЕСТРА (заказ G73 п. 2) -----
    # Координата выше измерила многозначность у ОДНОГО соседа и в ОДИН день,
    # а правило уплощения ОБЩЕЕ. Число, снятое у одного документа, свойством
    # реестра не является ровно так же, как счёт хвостов не был свойством
    # документа — и разница между 13,22 % соседа и разбросом по населению
    # есть замер, а не догадка.
    registry_ambiguity = registry_ambiguity_scope(root, data_dir=data_dir)

    # --- РАСХОЖДЕНИЕ ЗНАЧЕНИЙ У СТОЯЩИХ ЧТЕНИЙ (заказ G74 п. 1) --------
    # Шаг выше НАЗВАЛ 38 решающих чтений, у которых координата многозначна,
    # и на этом остановился. Многозначность решения не искажает — искажает
    # РАСХОЖДЕНИЕ значений по путям; хвост, живущий по пяти путям с одним и
    # тем же значением, даёт один ответ, каким бы путём читатель ни пошёл.
    # Шаг ЧИСТЫЙ: население берётся у соседа выше, файлов он не читает и
    # прогонов не запускает, поэтому цены такту не добавляет.
    value_divergence = tail_value_divergence(registry_ambiguity)

    # --- НАСЕЛЕНИЕ ОТКРЫТЫХ СЧЁТЧИКОВ (заказ G76 п. 1) -----------------
    # ADR-459 снял класс с именем `'None'` у ОДНОГО поля одного прибора и
    # населения класса не спросил. Правило поиска объявлено выше и
    # проверяется на том же известном случае обеими сторонами: ноль от
    # формы, промахивающейся по известному случаю, есть свойство ФОРМЫ.
    open_counters = open_class_counter_census(root)

    # --- ЧИТАТЕЛЬ открытого счётчика (заказ G77 п. 1) ------------------
    # Поверхность померена соседом выше; вред лежит не в счётчике, а у его
    # ЧИТАТЕЛЯ, и это РАЗНЫЕ вопросы: 158 открытых не значат 158 вредящих,
    # а «у счётчика есть читатель» не значит «читатель измерен». Население
    # берётся у соседа и сверяется с его числом — разойдясь, шаг отказывает.
    reader_harm = open_counter_reader_harm(root, open_counters)

    # --- ОДИН шаг межпроцедурного разбора (заказ G78 п. 1) -------------
    # ADR-461 назвал главным числом 95 НЕ ИЗМЕРЕННЫХ читателей и разложил
    # их; 66 из них убегают из области. Вопрос заказа — сколько из этих 66
    # разрешает ОДИН шаг. Ответ обязан быть парой чисел: «разрешено» и
    # «осталось третьим исходом», и вторая половина не есть остаток первой.
    one_step = escaped_counter_one_step(root, reader_harm)

    # --- ОДИН шаг ПЕРЕНОСА ПОЛЕМ (заказ G79 п. 1) ---------------------
    # ADR-462 нашёл, что премисса заказа G78 неверна: 53 из 66 убежавших
    # счётчиков уезжают сперва КОНТЕЙНЕРОМ, а не вызовом. Вопрос G79 —
    # сколько из этих 53 разрешает ОДИН шаг переноса полем. Население
    # берётся у шага одного вызова и сверяется с его числом.
    field_step = container_counter_field_step(root, one_step)

    # --- разбор ПО ИМЕНИ ПОЛЯ через границу функции (заказ G80 п. 1) ---
    # ADR-463 назвал главным числом 26 из 53: счётчик кладут в ДОКУМЕНТ, а
    # поле его читают не у зовущего, а много позже и другой точкой входа.
    # Вопрос G80 — сколько из этих 26 разрешает разбор по имени поля.
    # Население берётся у шага переноса полем и сверяется с его числом.
    doc_step = document_field_reader_in_file(root, field_step)

    scanned = len(guard_files) + len(executor_files)
    classified = scanned - len(unreadable)
    findings = [r for r in rows if r["verdict"] in _FINDING_CLASSES]
    return {
        "generated_at": (now or _utcnow()).isoformat(),
        "generated_by": PRODUCER,
        "invoked_by": call_provenance(tree_root=root),
        "status": "FINDING" if findings else "CLEAN",
        "question": "у скольких правил есть ИСПОЛНИТЕЛЬ и СТОРОЖ, проверяющие одно условие РАЗНЫМ кодом",
        "population_rule": (
            "сторож — собираемый pytest файл test_*.py из каталогов предписанного "
            "прогона; исполнитель — не-тестовый модуль spa_core/ + scripts/ (без "
            "scripts/archive/); координата — имя верхнего уровня с КОНСТАНТНЫМ "
            "значением, у которого исполнитель РОВНО ОДИН"
        ),
        "scanned": scanned,
        "guards": len(guard_files),
        "executors": len(executor_files),
        "counts": dict(counts, unreadable=len(unreadable)),
        "remedy_counts": remedy_counts,
        # Пара, у которой имя сторожа не читается, из населения не исчезает:
        # строка остаётся, меняется её форма. Число «на учёте» считается здесь,
        # чтобы «стало меньше» нельзя было выдать за «нашлось меньше».
        "findings_on_books": len(
            [r for r in rows if r["verdict"] in _FINDING_CLASSES
             and r.get("remedy") != REMEDY_UNUSED]),
        "probe": probe_stats,
        # Вторая ось — ЧИСЛО поверхности, а не перечень приговоров, и на
        # `status` она НАМЕРЕННО не влияет: 189 строк, влитые в находки,
        # утопили бы девять пар первой оси, а заказ просил числа. Читателем
        # числа служит строка отчёта шага 0-офис, печатаемая каждый прогон;
        # храповика у него сегодня нет, и это сказано вслух, а не подразумевается.
        "peer_counts": peer_counts,
        "peer_rows": peer_rows,
        "peer_owner_subject": len([r for r in peer_rows
                                   if r.get("remedy") == REMEDY_OWNER]),
        "peer_remedy_counts": {
            cls: len([r for r in peer_rows
                      if r.get("verdict") == CLASS_PEER_TWO_COPIES
                      and r.get("remedy") == cls])
            for cls in _PEER_REMEDY_CLASSES},
        # Сдвиг формы починки от вопроса к ВТОРОЙ поверхности решения
        # (заказ G54 п. 1) — по каждой соседней оси отдельно: числа разные,
        # и одно из них ноль, который обязан быть ИЗМЕРЕННЫМ, а не структурным.
        "constitution_shift": {
            "first_axis": constitution_shift(
                rows, finding_classes=_FINDING_CLASSES,
                constitution_unread=constitution_unread),
            "peer_axis": constitution_shift(
                peer_rows, finding_classes=(CLASS_PEER_TWO_COPIES,),
                constitution_unread=constitution_unread),
        },
        "peer_private_names": len([r for r in peer_rows
                                   if r.get("private_name")]),
        "risk_policy_thresholds": len(thresholds),
        # Пересечение осей ПО ИМЕНИ (заказ G53 п. 1) и — отдельным вопросом —
        # ПОЧЕМУ оно такое. Ноль без второго поля был бы не ответом.
        "axes_intersection": intersection,
        # Третья ось. На `status` не влияет по той же причине, что и вторая:
        # она мерит ПОВЕРХНОСТЬ числом, а не выносит приговор каждой строке.
        "triple_counts": triple_counts,
        "triple_rows": triple_rows,
        "triple_names": triple_name_count(triple_rows),
        "triple_remedy_counts": {
            cls: len([r for r in triple_rows if r.get("remedy") == cls])
            for cls in _TRIPLE_REMEDY_CLASSES},
        # Население ОБЪЯВЛЕННЫХ поверхностей решения (заказ G55 п. 1). На
        # `status` не влияет по той же причине, что вторая и третья оси: это
        # число о поверхности, а не приговор строке.
        "decision_surfaces": surfaces,
        # Канал объявления ИМЕНЕМ (заказ G56 п. 2). Отдельной координатой, а не
        # доливкой в `decision_surfaces`: там число есть ответ на вопрос «что
        # объявлено ПУТЁМ», и подмешать туда имена значило бы стереть разницу
        # между двумя каналами вместо того, чтобы её измерить.
        "name_channel": names,
        # Третья координата того же вопроса (заказ G57 п. 1). Отдельным
        # ключом, а не доливкой в две прежних: население объявленных
        # поверхностей и ПОТОЛОК зазора — разные числа, и предел
        # `MAX_DECLARING_PARAGRAPH` этой координатой не ослабляется.
        "wide_paragraph_channel": wide,
        # Четвёртая координата того же вопроса (заказ G58 п. 1). Отдельным
        # ключом по той же причине, что и три прежних: «сколько правил имеют
        # эту форму» и «что объявлено» — разные вопросы, и контроль здесь
        # объявлением не является.
        "table_form_census": table_form,
        # Пятая координата того же вопроса (заказ G59 п. 2). Отдельным
        # ключом: «какой формы абзац» и «порог ли стоящее в нём число» —
        # разные вопросы, и общий ключ слил бы их ответы.
        "out_of_channel_numbers": out_channel,
        # Шестая координата того же вопроса (заказ G60 пп. 1–2). Отдельным
        # ключом: «одноязычен ли ЭТОТ канал» и «одноязычны ли ВСЕ свидетели
        # имени» — разные вопросы, и ответ второго не является поправкой к
        # первому.
        "bilingual_reach": bilingual,
        "bilingual_name_precision": name_precision,
        "token_depth_price": depth_price,
        "paragraph_witness_price": witness_price,
        "witness_admission_price": admission_price,
        # Седьмая координата того же вопроса (заказ G65 п. 1). Отдельным
        # ключом: «разошлись ли базы» и «какую из них берёт читатель» —
        # разные вопросы, и ответ второго не является поправкой к первому.
        "consumer_base_naming": base_naming,
        # Восьмая координата того же вопроса (заказ G66 п. 1). Отдельным
        # ключом: «как читатель зовёт базу» и «все ли читатели названы» —
        # разные вопросы, и ответ второго не является поправкой к первому.
        "consumer_registry_completeness": registry_completeness,
        # Девятая координата того же вопроса (заказ G67 п. 1). Отдельным
        # ключом: «все ли читатели ОДНОЙ переписи названы» и «у скольких
        # переписей класс вообще есть» — разные вопросы, и ответ второго не
        # является поправкой к первому.
        "invisible_consumer_scale": invisible_scale,
        # Десятая координата того же вопроса (заказ G68 п. 1). Отдельным
        # ключом: «у скольких переписей класс есть» и «меняет ли он чей-нибудь
        # ВЫВОД» — разные вопросы, и ответ второго не является поправкой к
        # первому: занижение может быть повсеместным и безвредным разом.
        "neighbour_population_harm": population_harm,
        "recompute_cost_budget": cost_budget,
        # Двенадцатая координата того же вопроса (заказ G70 п. 1). Отдельным
        # ключом: «сколько стои́т пересчёт читателя-КОДА» и «сколько стои́т
        # читатель канала ТЕСТА и замыкается ли он на ступень» — разные
        # вопросы, и ответ второго не есть поправка к первому: у них разные
        # свидетели и разный третий исход.
        "reader_cost_of_test_channel": test_channel_cost,
        "registry_ambiguity_scope": registry_ambiguity,
        "tail_value_divergence": value_divergence,
        "open_class_counter_census": open_counters,
        # Отдельным ключом, а не поправкой к соседу: «сколько счётчиков
        # ОТКРЫТО» и «у скольких из них незнакомый класс молча становится
        # другим ИСХОДОМ» — разные вопросы с разным третьим исходом.
        "open_counter_reader_harm": reader_harm,
        # Отдельным ключом, а не поправкой к соседу: «у скольких читатель НЕ
        # ИЗМЕРЕН» и «скольких из них достаёт ОДИН шаг» — разные вопросы, и
        # ответ второго не отменяет первого.
        "escaped_counter_one_step": one_step,
        # Отдельным ключом, а не поправкой к соседу: «скольких достаёт шаг
        # ВЫЗОВА» и «скольких достаёт шаг ПОЛЯ» — разные вопросы с разным
        # третьим исходом, и ответ второго не отменяет первого.
        "container_counter_field_step": field_step,
        # Отдельным ключом, а не поправкой к соседу: «скольких достаёт шаг
        # ПОЛЯ у зовущего» и «скольких достаёт разбор ПО ИМЕНИ ПОЛЯ во всём
        # файле» — разные вопросы с разным третьим исходом, и ответ второго
        # не отменяет первого.
        "document_field_reader_in_file": doc_step,
        "constitution_values": len(constitution),
        "constitution_unread": constitution_unread,
        "classified": classified,
        "rows": rows,
        "unreadable": unreadable,
        # Доказанный МИНИМУМ переименованных копий: сторож, ни разу не
        # упомянувший дерево-предмет, держит свою копию наверняка. Потолком это
        # число не является — см. docstring.
        "renamed_copy_surface": sorted(surface),
        "what_it_does_not_prove": [
            "что у найденной пары копия вредит СЕГОДНЯ — вред приходит с правкой одной из копий",
            "что совпавшее значение имеет общее происхождение (SEED = 42 может быть совпадением)",
            "что население полно — переименованная копия невидима; renamed_copy_surface есть доказанный МИНИМУМ, а не потолок",
            "что сторож из delegates не держит второй копии рядом — дверь найдена, пользование ею не спрошено",
            "что пара subject_unproven есть СОВПАДЕНИЕ — свидетели общего предмета односторонние, «не доказан» третий исход",
            "что пара owner_subject есть ОДНА величина — равенство с порогом RiskPolicy отправляет её владельцу, а не выносит приговор",
            "что у пары subject_proven_by_behaviour общий ключ читается ИМЕННО из общего артефакта — статически связать их нечем, и прибор связи не выдумывает",
            "что пара independent_by_probe не имеет общего предмета — зонд мерит ЗАВИСИМОСТЬ ВЕРДИКТА от значения, а не происхождение числа; несогласие со свидетелем называется в строке",
            "что у пары ОСИ ИСПОЛНИТЕЛЕЙ (peer_*) копия вредна — ось мерит ПОВЕРХНОСТЬ числом; вреда у неё не спрашивали, и зонд независимости её пар не трогает",
            "что 189 у оси исполнителей есть потолок класса — переименованная копия невидима ей так же, как и первой оси, и ровно по той же причине",
            "что пустое пересечение осей означает отсутствие правил с ТРЕМЯ копиями — оно пусто ПО ПОСТРОЕНИЮ (1 исполнитель против 2), и на вопрос отвечает отдельная координата triple_copies",
            "что у находки третьей оси копия вредна СЕГОДНЯ — ось мерит поверхность; зонд независимости её строк не трогает так же, как и строк второй оси",
            "что право чинить спрошено у ВСЕХ поверхностей решения — население ОБЪЯВЛЕННЫХ правилами измерено (decision_surfaces) и есть доказанный минимум: поверхность, не названную ни одним правилом, мера не видит",
            "что объявленная поверхность решения ДЕЙСТВИТЕЛЬНО им является — объявлением считается абзац правила с языком права изменения, и ошибка отбора направлена в сторону «спросить», а не «чинить молча»",
            "что пара `constitution_subject` держит ТО ЖЕ число, что и витрина, — равенство величины не есть тождество смысла ровно так же, как у порога RiskPolicy; потому пара и уходит владельцу, а не чинится",
            "что нулевой сдвиг на первой оси есть свойство ДЕРЕВА — знаменатель там 5 сравнимых пар из 9, и это сказано числом, а не словом",
            "что население поверхностей решения ПОЛНО и после канала имени — объявление модулем через точку (`spa_core.risk.policy`) не ловится ни одним из двух каналов, и зазор остаётся, только теперь он МЕНЬШЕ и назван",
            "что имя, разрешённое единственным файлом, объявлено правилом ИМЕННО как поверхность решения — канал имени, как и канал пути, ошибается в сторону «спросить», а не «починить молча»",
            "что пара, найденная ДВУЯЗЫЧНЫМ каналом имени, есть вторая копия того же порога — совпадение величины в абзаце фильтрует пары для обозримости, а тождество смысла проверяет человек",
            "что нулевой сдвиг у свидетеля предмета есть свойство ДЕРЕВА — он ровно настолько свойство КАРТЫ, насколько мал `askable`, и это число едет рядом с нулём",
            "что карта синонимов ПОЛНА — её полнота измерена только по порогам, уже известным переписи, и число незакрытых токенов названо",
            "что читатель, назвавший базу ВЕРНО, печатает верное ЧИСЛО — мера про имя у числа, а не про его происхождение",
            "что население читателей полно — реестр `CENSUS_CONSUMERS` литерален по замыслу, и читатель, в нём не названный, прибору невидим",
            "что чтение вне f-строки отсутствует — оно НЕ разбирается, и его число едет отдельным полем у каждого читателя",
            "что население зовущих ПОЛНО и после сведения с соседом — у соседа четыре класса зова, и зов, не разрешимый статикой, едет у него ЧИСЛОМ; поверхность ввоза добавляет ввозящих, а не исчерпывает зовущих",
            "что неназванный читатель БЕЗВРЕДЕН — измерено «печатает ли он числа переписи», а не «верно ли он их понимает»",
            "что у переписи без разрешённого отрисовщика невидимых потребителей НЕТ — отрисовщик разрешается печатью у самого производителя, и 28 из 85 уходят в ТРЕТИЙ исход, о котором не сказано ничего",
            "что невидимый потребитель ЧИТАЕТ числа своей переписи — измерен ВВОЗ отрисовщика при отсутствии зова `run`, а не печать",
            "что занижение БЕЗВРЕДНО у всех читателей — решение пересчитано прогоном лишь у тех, кого прибор способен позвать; у неоплаченного названы цена и поле, и это ОСТАТОК, а не ноль",
            "что «вердикт не сдвинулся» верно при ЛЮБОЙ форме починки — сдвиг измерен на САМОМ ДЕШЁВОМ расширении населения, и иная форма могла бы сдвинуть иные поля",
        ],
    }


def _reaches_subject_tree(source: str) -> bool:
    """Достаёт ли сторож дерево-предмет хоть как-нибудь.

    Отдельная функция, а не выражение на месте: поверхность слепоты — второе
    по важности число прибора, и правило её отбора обязано быть одним и
    проверяемым тестом.
    """
    return ("spa_core" in source) or ("scripts" in source)


def report(doc: dict, *, max_rows: int = 20) -> List[str]:
    """Строки отчёта. Единственное место, где перепись превращается в текст."""
    status = str(doc.get("status"))
    if status == "UNMEASURED":
        return [f"НЕ ИЗМЕРЕНО — {observed(doc, 'reason', kind=str) or 'причина не записана'}"]
    counts = observed(doc, "counts", kind=dict) or {}
    out = [
        f"одно правило — две копии (заказ G41 п. 1): {status} · "
        f"две копии {counts.get(CLASS_TWO_COPIES)} · "
        f"сторож достаёт исполнителя {counts.get(CLASS_DELEGATES)} · "
        f"значения разные {counts.get(CLASS_VALUE_DIFFERS)} · "
        f"сравнить нечем {counts.get(CLASS_NOT_CONSTANT)} · "
        f"исполнитель не один {counts.get(CLASS_AMBIGUOUS)}",
        f"[ЗВАВШИЙ] {provenance_line(observed(doc, 'invoked_by', kind=dict))}",
        f"[УЧЁТ] осмотрено {doc.get('scanned')} = разобрано {doc.get('classified')} "
        f"+ не разобрано {counts.get('unreadable')} "
        f"(сторожей {doc.get('guards')}, исполнителей {doc.get('executors')})",
    ]
    remedy = observed(doc, "remedy_counts", kind=dict)
    if remedy is None:
        out.append("[ФОРМА ПОЧИНКИ] НЕ ИЗМЕРЕНА — перепись собрана без разбора форм")
    else:
        out.append(
            f"[ФОРМА ПОЧИНКИ] ввозом {remedy.get(REMEDY_IMPORT)} · "
            f"предмет владельца {remedy.get(REMEDY_OWNER)} · "
            f"предмет витрины порогов {remedy.get(REMEDY_CONSTITUTION)} · "
            f"право чинить НЕ ИЗМЕРЕНО {remedy.get(REMEDY_RIGHT_UNMEASURED)} · "
            f"предмет доказан поведением {remedy.get(REMEDY_BEHAVIOUR)} · "
            f"имя у сторожа не читается {remedy.get(REMEDY_UNUSED)} · "
            f"предмет НЕ доказан {remedy.get(REMEDY_UNPROVEN)} · "
            f"не разобрано {remedy.get(REMEDY_UNREADABLE)}")
        on_books = observed(doc, "findings_on_books", kind=int)
        out.append(
            f"[НА УЧЁТЕ] {on_books if on_books is not None else 'НЕ ИЗМЕРЕНО'} "
            f"из {counts.get(CLASS_TWO_COPIES)} пар — с учёта снимает ровно одно "
            f"основание (имя у сторожа не читается), и снятая пара из НАСЕЛЕНИЯ "
            f"не исчезает")
    probe = observed(doc, "probe", kind=dict)
    if probe is None:
        out.append("[ЗОНД] НЕ ИЗМЕРЕН — перепись собрана без чтения журнала зонда")
    else:
        absent = probe.get("ledger_absent")
        drift = {}
        for row in (doc.get("rows") or []):
            if row.get("drift"):
                drift[row["drift"]] = drift.get(row["drift"], 0) + 1
        out.append(
            f"[ЗОНД] годных записей {probe.get('fresh')} · протухших "
            f"{probe.get('stale')} · нет записи {probe.get('missing')}"
            + (f" · {absent}" if absent else "")
            + " — протухшая запись возвращает пару НА учёт, а не снимает с него")
        toothless = len([r for r in (doc.get("rows") or [])
                         if r.get("verdict_teeth") == "none"])
        out.append(
            f"[СНОС ВРОЗЬ] молча {drift.get(PROBE_DRIFT_SILENT, 0)} · с краснотой "
            f"{drift.get(PROBE_DRIFT_LOUD, 0)} · вердикт сторожа без зубов "
            f"{toothless} — это про ВРЕД, а не про предмет: ни один из трёх пару "
            f"с учёта НЕ снимает; снимает только СТАТИЧЕСКОЕ «имя не читается»")
    findings = [r for r in (doc.get("rows") or []) if r["verdict"] in _FINDING_CLASSES]
    for row in findings[:max_rows]:
        tail = ""
        if row.get("remedy"):
            tail = f" · {row['remedy']}: {row.get('remedy_evidence', 'основание не записано')}"
        out.append(
            f"[НАХОДКА] {row['name']} = {row['value']} — сторож {row['guard']} "
            f"против исполнителя {row['executor']}{tail}")
    if len(findings) > max_rows:
        # Умолчание об укорочении и есть способ соврать усечением.
        out.append(f"[…] показаны {max_rows} находки из {len(findings)}; "
                   f"полный перечень — в артефакте")
    peer = observed(doc, "peer_counts", kind=dict)
    if peer is None:
        out.append("[ПАРА ИСПОЛНИТЕЛЕЙ] НЕ ИЗМЕРЕНА — перепись собрана без второй оси")
    else:
        owner = observed(doc, "peer_owner_subject", kind=int)
        priv = observed(doc, "peer_private_names", kind=int)
        two = peer.get(CLASS_PEER_TWO_COPIES)
        out.append(
            f"[ПАРА ИСПОЛНИТЕЛЕЙ] копия между двумя исполнителями {two} · "
            f"дверь открыта {peer.get(CLASS_PEER_DELEGATES)} · значения разные "
            f"{peer.get(CLASS_PEER_VALUE_DIFFERS)} · сравнить нечем "
            f"{peer.get(CLASS_PEER_NOT_CONSTANT)} · имя у многих исполнителей "
            f"{peer.get(CLASS_PEER_MANY)} · дверь НЕ ИЗМЕРЕНА "
            f"{peer.get(CLASS_PEER_UNMEASURED)}")
        peer_remedy = observed(doc, "peer_remedy_counts", kind=dict) or {}
        out.append(
            f"[ПРАВО ЧИНИТЬ] из них величина равна порогу RiskPolicy у "
            f"{owner if owner is not None else 'НЕ ИЗМЕРЕНО'} · объявлена "
            f"витриной порогов сайта у {peer_remedy.get(REMEDY_CONSTITUTION)} · "
            f"НЕ ИЗМЕРЕНО {peer_remedy.get(REMEDY_RIGHT_UNMEASURED)} · "
            f"не возражает никто {peer_remedy.get(REMEDY_UNPROVEN)} — первые "
            f"две формы агент НЕ чинит; равенство числа не есть тождество "
            f"смысла, и сверка ошибается в сторону «спросить»")
        out.append(
            f"[ИМЯ] приватных {priv if priv is not None else 'НЕ ИЗМЕРЕНО'} из "
            f"{two} — на этой оси приватное имя из населения НЕ выбрасывается: "
            f"прочитать чужое `_X` нельзя, и копия от этого не мнимая, а "
            f"неизбежная; меняется лишь форма починки")
        peer_rows = [r for r in (doc.get("peer_rows") or [])
                     if r.get("verdict") == CLASS_PEER_TWO_COPIES]
        for row in peer_rows[:max_rows]:
            out.append(
                f"[ПАРА] {row['name']} = {row['value']} — {row['left']} × "
                f"{row['right']} · {row.get('remedy')}")
        if len(peer_rows) > max_rows:
            out.append(f"[…] показаны {max_rows} пар(ы) из {len(peer_rows)}; "
                       f"полный перечень — в артефакте")
        out.append(
            "[ПОЧЕМУ ОСЬ ЕСТЬ] молчание первой оси об этой паре было НЕ "
            "свидетельством: в сцене с ВОССТАНОВЛЕННОЙ второй копией её вердикт "
            "оставался побуквенно тем же (ADR-430). Ось не влияет на `status` — "
            "она мерит поверхность числом, а не выносит приговор каждой паре")
    shift = observed(doc, "constitution_shift", kind=dict)
    if shift is None:
        out.append("[ВТОРАЯ ПОВЕРХНОСТЬ] НЕ ИЗМЕРЕНА — перепись собрана без вопроса G54 п. 1")
    else:
        for key, label in (("first_axis", "сторож × исполнитель"),
                           ("peer_axis", "исполнитель × исполнитель")):
            ax = shift.get(key) or {}
            out.append(
                f"[ВТОРАЯ ПОВЕРХНОСТЬ · {label}] {ax.get('verdict')} · "
                f"сменили форму починки {ax.get('moved')} из "
                f"{ax.get('comparable')} сравнимых "
                f"(население {ax.get('population')} = порог RiskPolicy "
                f"{ax.get('owner_by_threshold')} + сравнимых "
                f"{ax.get('comparable')} + витрина молчит по построению "
                f"{ax.get('silent_by_construction')}); {ax.get('reason')}")
            for move, n in sorted((ax.get("transitions") or {}).items()):
                out.append(f"[СДВИГ] {move}: {n}")
            names = ax.get("moved_names") or []
            if names:
                out.append(f"[СДВИГ · имена] {', '.join(names[:max_rows])}"
                           + (f" … ещё {len(names) - max_rows}"
                              if len(names) > max_rows else ""))
    inter = observed(doc, "axes_intersection", kind=dict)
    if inter is None:
        out.append("[ПЕРЕСЕЧЕНИЕ ОСЕЙ] НЕ ИЗМЕРЕНО — перепись собрана без вопроса G53 п. 1")
    else:
        hist = inter.get("executors_per_name") or {}
        out.append(
            f"[ПЕРЕСЕЧЕНИЕ ОСЕЙ] имён, о которых говорят ОБЕ оси: "
            f"{inter.get('count')} — {inter.get('verdict')}; "
            f"{inter.get('reason')}")
        out.append(
            f"[ОСНОВАНИЕ] исполнителей у имён первой оси {hist.get('axis_one')} · "
            f"у имён второй {hist.get('axis_two')} — ноль читается по этим "
            f"числам, а не по слову «нет»")
    triple = observed(doc, "triple_counts", kind=dict)
    if triple is None:
        out.append("[ТРИ КОПИИ] НЕ ИЗМЕРЕНЫ — перепись собрана без третьей оси")
    else:
        names = observed(doc, "triple_names", kind=int)
        remedy3 = observed(doc, "triple_remedy_counts", kind=dict) or {}
        out.append(
            f"[ТРИ КОПИИ] сторож × два исполнителя {triple.get(CLASS_TRIPLE)} "
            f"пар(ы) на {names if names is not None else 'НЕ ИЗМЕРЕНО'} имён(и) · "
            f"дверь к одному {triple.get(CLASS_TRIPLE_DOOR_ONE)} · дверь к обоим "
            f"{triple.get(CLASS_TRIPLE_DOOR_BOTH)} · значения разные "
            f"{triple.get(CLASS_TRIPLE_VALUE_DIFFERS)} · сравнить нечем "
            f"{triple.get(CLASS_TRIPLE_NOT_CONSTANT)} · дверь НЕ ИЗМЕРЕНА "
            f"{triple.get(CLASS_TRIPLE_UNMEASURED)}")
        unread = doc.get("constitution_unread")
        out.append(
            f"[ПРАВО ЧИНИТЬ · 2 ПОВЕРХНОСТИ] предмет RiskPolicy "
            f"{remedy3.get(REMEDY_OWNER)} · предмет витрины порогов "
            f"{remedy3.get(REMEDY_CONSTITUTION)} · право НЕ ИЗМЕРЕНО "
            f"{remedy3.get(REMEDY_RIGHT_UNMEASURED)} · предмет не доказан "
            f"{remedy3.get(REMEDY_UNPROVEN)}"
            + (f" — {unread}" if unread else ""))
        triple_rows = [r for r in (doc.get("triple_rows") or [])
                       if r.get("verdict") == CLASS_TRIPLE]
        for row in triple_rows[:max_rows]:
            out.append(
                f"[ТРОЙКА] {row['name']} = {row['value']} — сторож "
                f"{row['guard']} против {row['left']} × {row['right']} · "
                f"{row.get('remedy')}: {row.get('remedy_evidence', 'основание не записано')}")
        if len(triple_rows) > max_rows:
            # Умолчание об укорочении и есть способ соврать усечением.
            out.append(f"[…] показаны {max_rows} тройки из {len(triple_rows)}; "
                       f"полный перечень — в артефакте")
        unmeasured = [r for r in (doc.get("triple_rows") or [])
                      if r.get("verdict") == CLASS_TRIPLE_UNMEASURED]
        for row in unmeasured[:max_rows]:
            out.append(f"[НЕ ИЗМЕРЕНО] {row['name']} — сторож {row['guard']}: "
                       f"{row.get('reason', 'причина не записана')}")
        out.append(
            "[ПОЧЕМУ ОСЬ ЕСТЬ] пересечение двух прежних осей пусто ПО "
            "ПОСТРОЕНИЮ и о трёх копиях не говорит ничего; храповика у этого "
            "числа сегодня НЕТ, рост виден только в этой строке (остаток G52 п. 2)")
    surfaces = observed(doc, "decision_surfaces", kind=dict)
    if surfaces is None:
        out.append("[ПОВЕРХНОСТИ РЕШЕНИЯ] НЕ ИЗМЕРЕНЫ — перепись собрана без "
                   "координаты населения (заказ G55 п. 1)")
    else:
        out.append(
            f"[ПОВЕРХНОСТИ РЕШЕНИЯ] {surfaces.get('verdict')} · объявлено "
            f"правилами {surfaces.get('candidates')} · из них шкафов чисел "
            f"{surfaces.get('shelves')} · сменили бы форму "
            f"{surfaces.get('would_move_total')} пар(ы); {surfaces.get('reason')}")
        for row in (surfaces.get("surfaces") or []):
            if row.get("kind") != SURFACE_SHELF:
                continue
            where = (row.get("declared_by") or [{}])[0]
            out.append(
                f"[ШКАФ] {row['path']} — чисел {row.get('numbers')} · называет "
                f"находок {row.get('matches')} · сменили бы форму "
                f"{row.get('would_move')} · спрашивается сегодня: "
                f"{'да' if row.get('asked_today') else 'НЕТ'} · объявлен "
                f"{where.get('text')}:{where.get('line')}")
            if row.get("would_move_names"):
                out.append(f"[ШКАФ · имена] {', '.join(row['would_move_names'][:8])}")
        for row in (surfaces.get("surfaces") or []):
            if row.get("kind") == SURFACE_SHELF:
                continue
            out.append(f"[НЕ ШКАФ] {row['path']} — {row.get('kind')}: "
                       f"{row.get('reason', 'причина не записана')}")
        for row in (surfaces.get("asked") or []):
            if row.get("declared_by_rules"):
                where = (row.get("evidence") or [{}])[0]
                out.append(f"[СПРАШИВАЕТСЯ] {row['path']} — объявлен правилом "
                           f"{where.get('text')}:{where.get('line')}")
            else:
                out.append(
                    f"[СПРАШИВАЕТСЯ, НО НЕ ОБЪЯВЛЕН ПУТЁМ] {row['path']} — "
                    f"правила не называют этого ПУТИ ни разу (упоминаний "
                    f"{row.get('mentions_in_rules')}). Про объявление ИМЕНЕМ "
                    f"эта строка не говорит ничего — его мерит координата "
                    f"`name_channel` ниже, и на 20.09 оно там НАШЛОСЬ "
                    f"(заказ G56 п. 2, ADR-434)")
        adr = surfaces.get("adr_channel") or {}
        out.append(
            f"[КАНАЛ ADR ОТВЕРГНУТ] в {adr.get('files')} ADR абзацы с языком "
            f"права изменения называют {adr.get('named_paths')} путь(ей), из них "
            f"артефактов data/ {adr.get('artifact_paths')}; реестр "
            f"{adr.get('registry')} исключён по замеру: "
            f"{adr.get('registry_long_lines')} из {adr.get('registry_lines')} "
            f"строк длиннее {MAX_DECLARING_LINE} символов — построчная мера там "
            f"совпадает со всем подряд")
        for blind in (surfaces.get("blind") or []):
            out.append(f"[СЛЕПОТА] {blind}")
    names = observed(doc, "name_channel", kind=dict)
    if names is None:
        out.append("[КАНАЛ ИМЕНИ] НЕ ИЗМЕРЕН — перепись собрана без координаты "
                   "объявления именем (заказ G56 п. 2)")
    elif names.get("verdict") == NAME_CHANNEL_UNMEASURED:
        out.append(f"[КАНАЛ ИМЕНИ] {NAME_CHANNEL_UNMEASURED}: {names.get('reason')}")
    else:
        out.append(
            f"[КАНАЛ ИМЕНИ] {names.get('verdict')} · абзацев с языком права "
            f"изменения {names.get('paragraphs_authority')} · из них БЕЗ ПУТИ "
            f"{names.get('paragraphs_without_path')} · зазор к населению пути "
            f"{names.get('gap')} поверхност(ь/ей) · сменили бы форму "
            f"{names.get('would_move_total')} пар(ы); {names.get('reason')}")
        outcomes = names.get("by_outcome") or {}
        out.append(
            f"[ИМЕНА] разрешено единственным файлом {outcomes.get(NAME_RESOLVED)} · "
            f"имя у многих {outcomes.get(NAME_AMBIGUOUS)} · имени в дереве нет "
            f"{outcomes.get(NAME_ABSENT)}; разобрано файлов дерева "
            f"{names.get('files_read')}, нечитаемых "
            f"{len(names.get('files_unreadable') or [])}")
        out.append(
            f"[ШИРОКИЕ АБЗАЦЫ] мера пути отбросила как широкие "
            f"{names.get('paragraphs_wide_with_authority')} из "
            f"{names.get('paragraphs_authority')} абзац(ев) с языком права "
            f"изменения — это и есть вторая половина зазора: не «имя вместо "
            f"пути», а абзац, до содержимого которого мера пути не доходит")
        ctl_p = names.get("control_paragraphs") or 0
        ctl_r = names.get("control_resolved_single") or 0
        auth_p = names.get("paragraphs_authority") or 0
        auth_r = outcomes.get(NAME_RESOLVED) or 0
        if ctl_p and auth_p:
            out.append(
                f"[ЧАСТОТА ОШИБКИ] контроль на абзацах БЕЗ языка права "
                f"изменения: {ctl_r} разрешённых имён на {ctl_p} абзац(ев) = "
                f"{ctl_r / ctl_p:.3f}/абзац против {auth_r / auth_p:.3f}/абзац "
                f"у отобранных — отбор обогащает в "
                f"{(auth_r / auth_p) / (ctl_r / ctl_p):.1f} раз(а), и пять "
                f"находок не есть базовая частота обратных кавычек")
        else:
            out.append(
                "[ЧАСТОТА ОШИБКИ] НЕ ИЗМЕРЕНА: контрольных абзацев нет, и "
                "обогащение отбора подтвердить нечем")
        for row in (names.get("surfaces") or []):
            where = (row.get("declared_by") or [{}])[0]
            if row.get("kind") != SURFACE_SHELF:
                out.append(f"[ИМЕНЕМ · НЕ ШКАФ] {row['path']} — {row.get('kind')}: "
                           f"{row.get('reason', 'причина не записана')}")
                continue
            out.append(
                f"[ИМЕНЕМ · ШКАФ] {row['path']} — объявлен как "
                f"`{where.get('named_as')}` в {where.get('text')}:"
                f"{where.get('line')} · чисел {row.get('numbers')} · называет "
                f"находок {row.get('matches')} · сменили бы форму "
                f"{row.get('would_move')} · спрашивается сегодня: "
                f"{'да' if row.get('asked_today') else 'НЕТ'}")
            if row.get("would_move_names"):
                out.append(f"[ИМЕНЕМ · имена] "
                           f"{', '.join(row['would_move_names'][:8])}")
        if names.get("already_declared_by_path"):
            out.append(f"[ИМЕНЕМ, УЖЕ ИЗВЕСТНО ПО ПУТИ] "
                       f"{', '.join(names['already_declared_by_path'][:6])} — "
                       f"к зазору не относятся")
        for blind in (names.get("blind") or []):
            out.append(f"[СЛЕПОТА] {blind}")
    wide = observed(doc, "wide_paragraph_channel", kind=dict)
    if wide is None:
        out.append("[ШИРОКИЙ АБЗАЦ] НЕ ИЗМЕРЕН — перепись собрана без "
                   "координаты потолка зазора (заказ G57 п. 1)")
    elif wide.get("verdict") == WIDE_CHANNEL_UNMEASURED:
        out.append(f"[ШИРОКИЙ АБЗАЦ] {WIDE_CHANNEL_UNMEASURED}: "
                   f"{wide.get('reason')}")
    else:
        out.append(
            f"[ШИРОКИЙ АБЗАЦ] {wide.get('verdict')} · абзацев "
            f"{wide.get('wide_authority_paragraphs')} · упоминаний пути "
            f"{wide.get('mentions')} · различных путей "
            f"{wide.get('distinct_paths')} (разрешилось "
            f"{wide.get('resolved_paths')}) · НОВЫХ к обоим прежним каналам "
            f"{wide.get('gap')} (шкафов {wide.get('shelves')}, сторожей "
            f"{wide.get('guards')}) · сменили бы форму "
            f"{wide.get('would_move_total')} пар(ы); {wide.get('reason')}")
        reasons = wide.get("wide_by_reason") or {}
        out.append(
            f"[ШИРОКИЙ ПОЧЕМУ] абзац длиннее предела "
            f"{reasons.get(WIDE_BY_LINES)} · строка длиннее предела "
            f"{reasons.get(WIDE_BY_LINE_LENGTH)} · оба "
            f"{reasons.get(WIDE_BY_BOTH)} — предел строки и предел абзаца "
            f"защищают от РАЗНОГО, и одно число о сумме ответило бы не на тот "
            f"вопрос")
        by_reason_move = wide.get("would_move_by_wide_reason") or {}
        by_reason_surf = wide.get("surfaces_by_wide_reason") or {}
        out.append(
            f"[КАКОЙ ПРЕДЕЛ ДЕРЖИТ ЦЕНУ] сменили бы форму: предел АБЗАЦА "
            f"{by_reason_move.get(WIDE_BY_LINES)} пар(ы) при "
            f"{by_reason_surf.get(WIDE_BY_LINES)} поверхност(и/ях) · предел "
            f"СТРОКИ {by_reason_move.get(WIDE_BY_LINE_LENGTH)} при "
            f"{by_reason_surf.get(WIDE_BY_LINE_LENGTH)} · оба "
            f"{by_reason_move.get(WIDE_BY_BOTH)} при "
            f"{by_reason_surf.get(WIDE_BY_BOTH)}. Заказ назвал "
            f"MAX_DECLARING_PARAGRAPH — посылка проверена, а не повторена")
        ratio = wide.get("enrichment_wide")
        narrow = wide.get("enrichment_narrow")
        if ratio is None:
            out.append(f"[ЧАСТОТА ОШИБКИ · ШИРОКИЙ] НЕ ИЗМЕРЕНА: "
                       f"{wide.get('enrichment_wide_reason')}")
        else:
            out.append(
                f"[ЧАСТОТА ОШИБКИ · ШИРОКИЙ] отбор «язык права изменения» "
                f"сгущает упоминания пути в {ratio:.1f} раз(а): "
                f"{wide.get('wide_authority_mentions')} на "
                f"{wide.get('wide_authority_paragraphs')} абзац(ев) против "
                f"{wide.get('wide_control_mentions')} на "
                f"{wide.get('wide_control_paragraphs')} контрольных")
        if narrow is None:
            out.append(f"[ЧАСТОТА ОШИБКИ · УЗКИЙ] НЕ ИЗМЕРЕНА: "
                       f"{wide.get('enrichment_narrow_reason')}")
        else:
            out.append(
                f"[ЧАСТОТА ОШИБКИ · УЗКИЙ] тот же отбор на абзацах, которые "
                f"мера пути ЧИТАЕТ, сгущает в {narrow:.1f} раз(а): "
                f"{wide.get('narrow_authority_mentions')} на "
                f"{wide.get('narrow_authority_paragraphs')} против "
                f"{wide.get('narrow_control_mentions')} на "
                f"{wide.get('narrow_control_paragraphs')} контрольных")
        out.append(
            f"[ЧАСТОТА ОШИБКИ · ПОСЛЕДСТВИЕ] контроль на ТОЙ ЖЕ ширине без "
            f"языка права изменения: шкафов {wide.get('control_shelves')} · "
            f"называют находок {wide.get('control_matches')} · сменили бы "
            f"форму {wide.get('control_would_move')} пар(ы) — против "
            f"{wide.get('would_move_total')} у отобранных")
        if ratio is not None:
            out.append(
                f"[ДВЕ ОСИ ОБОГАЩЕНИЯ, И ОНИ СПОРЯТ] по УПОМИНАНИЯМ отбор "
                f"сгущает в {ratio:.1f} раз(а) — сигнала почти нет; по "
                f"ПОСЛЕДСТВИЮ — {wide.get('would_move_total')} против "
                f"{wide.get('control_would_move')}. Вопрос заказа о "
                f"ПОСЛЕДСТВИИ, и ответ на него нельзя брать с первой оси: "
                f"широкий абзац называет пути и так, но шкафы, которые кусают, "
                f"стоят именно у языка права изменения")
        if ratio is not None and narrow is not None:
            out.append(
                f"[ПРЕДЕЛ НЕ ОСЛАБЛЕН] MAX_DECLARING_PARAGRAPH остаётся "
                f"{MAX_DECLARING_PARAGRAPH}: по упоминаниям широкий абзац "
                f"обогащается в {ratio:.1f} раз(а) против {narrow:.1f} у "
                f"узкого, то есть «путь рядом с фразой» там и правда не улика. "
                f"Эта координата не доливает найденное в население "
                f"объявленных поверхностей — она называет ПОТОЛОК зазора и "
                f"его цену в парах")
        for row in (wide.get("surfaces") or []):
            where = (row.get("declared_by") or [{}])[0]
            if row.get("kind") != SURFACE_SHELF:
                out.append(f"[ШИРОКИЙ · НЕ ШКАФ] {row['path']} — "
                           f"{row.get('kind')}: "
                           f"{row.get('reason', 'причина не записана')}")
                continue
            out.append(
                f"[ШИРОКИЙ · ШКАФ] {row['path']} — назван в "
                f"{where.get('text')}:{where.get('line')} (абзац "
                f"{where.get('paragraph_lines')} строк) · чисел "
                f"{row.get('numbers')} · называет находок "
                f"{row.get('matches')} · сменили бы форму "
                f"{row.get('would_move')}")
        for row in (wide.get("already_known") or []):
            out.append(
                f"[ШИРОКИЙ, УЖЕ ИЗВЕСТЕН] {row['path']} — знает канал "
                f"{row['known_by']}; называет находок {row.get('matches')} — "
                f"к зазору не относится, но укус мерит")
        for blind in (wide.get("blind") or []):
            out.append(f"[СЛЕПОТА] {blind}")
    form = observed(doc, "table_form_census", kind=dict)
    if form is None:
        out.append("[ФОРМА ТАБЛИЦЫ] НЕ ИЗМЕРЕНА — перепись собрана без "
                   "координаты формы (заказ G58 п. 1)")
    elif form.get("verdict") == TABLE_FORM_UNMEASURED:
        out.append(f"[ФОРМА ТАБЛИЦЫ] {TABLE_FORM_UNMEASURED}: "
                   f"{form.get('reason')}")
    else:
        out.append(
            f"[ФОРМА ТАБЛИЦЫ] {form.get('verdict')} · в объявленном канале "
            f"{form.get('sample_form_long_line')} · в контроле "
            f"{form.get('control_form_long_line')}; {form.get('reason')}")
        # `or {}` здесь был бы ровно тем, что запрещает инв. #17: отсутствие
        # ключа стало бы пустой долей, цикл не напечатал бы ни строки, и
        # «не измерено» сделалось бы неотличимо от «нечего показать».
        shares = observed(form, "table_share_of_wide_authority", kind=dict)
        if shares is None:
            out.append("[ФОРМА · ДОЛЯ] НЕ ИЗМЕРЕНА — координата собрана без "
                       "долей по каналам")
            shares = {}
        for name in _TABLE_CHANNELS:
            cell = observed(shares, name, kind=dict)
            if cell is None:
                out.append(f"[ФОРМА · ДОЛЯ] {name}: НЕ ИЗМЕРЕНА — канал в "
                           f"координате не назван")
                continue
            share = cell.get("share")
            printed = ("НЕ ИЗМЕРЕНА" if share is None
                       else f"{share * 100:.1f} %")
            out.append(
                f"[ФОРМА · ДОЛЯ] {name}: таблиц среди широких абзацев с "
                f"языком права изменения {cell.get('form_any_reason')} из "
                f"{cell.get('wide_authority_paragraphs')} = {printed}"
                + ("" if share is not None
                   else f" ({cell.get('share_reason')})"))
        channels = observed(form, "channels", kind=dict)
        if channels is None:
            out.append("[ФОРМА · ГДЕ] НЕ ИЗМЕРЕНО — координата собрана без "
                       "разбивки по каналам")
            channels = {}
        for name in _TABLE_CHANNELS:
            channel = observed(channels, name, kind=dict)
            if channel is None:
                continue
            for hit in (channel.get("long_line_hits") or [])[:6]:
                out.append(
                    f"[ФОРМА · ГДЕ] {name}: {hit.get('text')}:"
                    f"{hit.get('line')} — строк {hit.get('lines')}, "
                    f"длиннейшая {hit.get('longest_line')}")
            if channel.get("registry_hits"):
                out.append(
                    f"[ФОРМА · РЕЕСТР] {name}: {channel['registry_hits']} "
                    f"попадан(ие/ий) в объявленный реестр — считается "
                    f"отдельно и в утверждение о репозитории не входит")
        for blind in (form.get("blind") or []):
            out.append(f"[СЛЕПОТА] {blind}")
    # Секция вынесена ЗА блок формы намеренно: вложенная внутрь `else`, она
    # молчала бы у любого дерева, где координата формы не измерена, — ровно
    # та ошибка размещения, которую соседний сторож поймал у #655.
    channel = observed(doc, "out_of_channel_numbers", kind=dict)
    if channel is None:
        out.append("[ЧИСЛА ВНЕ КАНАЛА] НЕ ИЗМЕРЕНЫ — перепись собрана без "
                   "координаты (заказ G59 п. 2)")
    elif channel.get("verdict") == OUT_CHANNEL_UNMEASURED:
        out.append(f"[ЧИСЛА ВНЕ КАНАЛА] {OUT_CHANNEL_UNMEASURED}: "
                   f"{channel.get('reason')}")
    else:
        total = observed(channel, "numbers_total", kind=int)
        out.append(
            f"[ЧИСЛА ВНЕ КАНАЛА] {channel.get('verdict')} · таблиц "
            f"{channel.get('tables_read')} из {channel.get('tables')} · чисел "
            + ("НЕ ИЗМЕРЕНО" if total is None else str(total))
            + f" · совпало по величине {channel.get('matched_value')} · "
            f"НАЗВАНО порогом {channel.get('named')}; {channel.get('reason')}")
        evidence = observed(channel, "by_evidence", kind=dict)
        if evidence is None:
            out.append("[ЧИСЛА · СВИДЕТЕЛЬСТВО] НЕ ИЗМЕРЕНО — координата "
                       "собрана без разбивки по каналам")
        else:
            for name in _EV_ALL:
                cell = observed(evidence, name, kind=int)
                out.append(
                    f"[ЧИСЛА · СВИДЕТЕЛЬСТВО] {name}: "
                    + ("НЕ ИЗМЕРЕНО — канал в координате не назван"
                       if cell is None else str(cell)))
        reading = observed(channel, "by_reading", kind=dict)
        if reading is None:
            out.append("[ЧИСЛА · ПРОЧТЕНИЕ] НЕ ИЗМЕРЕНО — координата собрана "
                       "без прочтений")
        else:
            fraction = observed(reading, READ_AS_FRACTION, kind=int)
            out.append(
                f"[ЧИСЛА · ПРОЧТЕНИЕ] как написано "
                f"{observed(reading, READ_AS_WRITTEN, kind=int)} · как доля "
                + ("НЕ ИЗМЕРЕНО" if fraction is None else str(fraction))
                + " — второе прочтение существует потому, что один порог "
                "живёт у двух поверхностей в РАЗНЫХ единицах")
        rate = observed(channel, "enrichment", kind=float)
        out.append(
            "[ЧИСЛА · ЧАСТОТА ОШИБКИ] обогащение имени над голой величиной: "
            + (f"x{rate:.2f}" if rate is not None
               else f"НЕ ИЗМЕРЕНО — {channel.get('enrichment_reason')}"))
        for pair in (channel.get("pairs") or []):
            if pair.get("evidence") not in _EV_NAMED:
                continue
            out.append(
                f"[ЧИСЛА · НАЗВАНО] {pair.get('text')}:{pair.get('line')} "
                f"[{pair.get('number')}] -> {pair.get('threshold')} "
                f"({pair.get('evidence')}, {pair.get('reading')}) — "
                f"{pair.get('quote')}")
        for row in (channel.get("unreadable") or []):
            out.append(f"[ЧИСЛА · НЕ ПРОЧИТАНО] {row.get('text')}: "
                       f"{row.get('reason')}")
        for blind in (channel.get("blind") or []):
            out.append(f"[СЛЕПОТА] {blind}")
    # Секция вынесена ЗА блок чисел вне канала намеренно и закреплена тестом:
    # вложенная внутрь его `else`, она молчала бы у каждого дерева, где та
    # координата не измерена, — ошибка размещения, найденная у #655.
    reach = observed(doc, "bilingual_reach", kind=dict)
    if reach is None:
        out.append("[ДВУЯЗЫЧИЕ] НЕ ИЗМЕРЕНО — перепись собрана без координаты "
                   "(заказ G60 пп. 1–2)")
    elif reach.get("verdict") in (BILINGUAL_UNMEASURED, BILINGUAL_NOTHING_TO_ASK):
        out.append(f"[ДВУЯЗЫЧИЕ] {reach.get('verdict')}: {reach.get('reason')}")
    else:
        out.append(f"[ДВУЯЗЫЧИЕ] {reach.get('verdict')} · {reach.get('reason')}")
        witnesses = observed(reach, "witnesses", kind=dict) or {}
        subject = observed(witnesses, WITNESS_SUBJECT, kind=dict)
        if subject is None:
            out.append("[ДВУЯЗЫЧИЕ · ПРЕДМЕТ] НЕ ИЗМЕРЕНО — свидетель в "
                       "координате не назван")
        else:
            out.append(
                f"[ДВУЯЗЫЧИЕ · ПРЕДМЕТ] пар прочитано {subject.get('pairs_read')} "
                f"· сменили вердикт {subject.get('changed')} · карта применима к "
                f"{subject.get('askable')} из {subject.get('modules')} модулей "
                f"(задета у {subject.get('token_overlap')}) · по-русски написаны "
                f"{subject.get('cyrillic_sides')} — ноль без этих знаменателей "
                f"был бы утверждением о приборе")
            for row in (subject.get("changed_rows") or [])[:max_rows]:
                out.append(f"[ДВУЯЗЫЧИЕ · ПРЕДМЕТ · СДВИГ] {row.get('name')} = "
                           f"{row.get('value')} — {'; '.join(row.get('witness') or [])}")
        channel = observed(witnesses, WITNESS_NAME_CHANNEL, kind=dict)
        if channel is None:
            out.append("[ДВУЯЗЫЧИЕ · ИМЯ] НЕ ИЗМЕРЕНО — канал в координате не назван")
        else:
            rate = observed(channel, "enrichment", kind=float)
            out.append(
                f"[ДВУЯЗЫЧИЕ · ИМЯ] разрешимых имён {channel.get('candidates')} · "
                f"названо токенами {channel.get('authority_raw')} на "
                f"{channel.get('authority_paragraphs')} объявлениях · величиной "
                f"подтверждено {channel.get('authority_corroborated')}; контроль "
                f"{channel.get('control_raw')} на {channel.get('control_paragraphs')} "
                f"абзацах (подтверждено {channel.get('control_corroborated')}) · "
                f"обогащение "
                + (f"x{rate:.2f}" if rate is not None
                   else f"НЕ ИЗМЕРЕНО — {channel.get('enrichment_reason')}"))
            for pair in (channel.get("pairs") or []):
                out.append(
                    f"[ДВУЯЗЫЧИЕ · ИМЯ · НАЗВАНО] {pair.get('text')}:"
                    f"{pair.get('line')} -> {pair.get('resolved')} "
                    f"`{pair.get('named_as')}` = {pair.get('value')} — "
                    f"{pair.get('quote')}")
        coverage = observed(reach, "map_coverage", kind=dict)
        if coverage is None or coverage.get("status") != "MEASURED":
            out.append("[ДВУЯЗЫЧИЕ · КАРТА] НЕ ИЗМЕРЕНА — "
                       + str((coverage or {}).get("reason")
                             or "полнота карты в координате не названа"))
        else:
            out.append(
                f"[ДВУЯЗЫЧИЕ · КАРТА] порогов переписи {coverage.get('thresholds')} "
                f"· закрыты целиком {coverage.get('fully_covered')} · частично "
                f"{coverage.get('partly_covered')} · не закрыты вовсе "
                f"{coverage.get('not_covered')}; различающих токенов без русского "
                f"соответствия {coverage.get('tokens_without_russian')} из "
                f"{coverage.get('tokens')}: "
                + ", ".join((coverage.get("missing_tokens") or [])[:12]))
        for blind in (reach.get("blind") or []):
            out.append(f"[СЛЕПОТА] {blind}")
    # Секция стои́т ЗА блоком двуязычия на уровне тела функции, а не внутри
    # его `else`: вложенная туда, она молчала бы у каждого дерева, где карта
    # синонимов пуста, — то есть ровно там, где о точности спрашивать важнее
    # всего. Ошибка размещения найдена у #655 и закреплена тестом.
    precision = observed(doc, "bilingual_name_precision", kind=dict)
    if precision is None:
        out.append("[ТОЧНОСТЬ ИМЕНИ] НЕ ИЗМЕРЕНА — перепись собрана без "
                   "координаты (заказ G61 п. 1)")
    elif precision.get("status") != "MEASURED":
        out.append(f"[ТОЧНОСТЬ ИМЕНИ] НЕ ИЗМЕРЕНА: {precision.get('reason')}")
    else:
        out.append(f"[ТОЧНОСТЬ ИМЕНИ · ПРАВИЛО] {precision.get('rule')}")
        sides = observed(precision, "sides", kind=dict) or {}
        for side in ("authority", "control"):
            tally = observed(sides, side, kind=dict)
            if tally is None:
                out.append(f"[ТОЧНОСТЬ ИМЕНИ · {side}] НЕ ИЗМЕРЕНО — "
                           f"срабатываний этой стороны в населении нет")
                continue
            share = observed(tally, "false_share", kind=float)
            out.append(
                f"[ТОЧНОСТЬ ИМЕНИ · {side}] размечено {tally.get('labelled')} · "
                f"настоящих {tally.get(LABEL_GENUINE)} · ложных "
                f"{tally.get(LABEL_ARTEFACT)} · не решено "
                f"{tally.get(LABEL_UNDECIDED)} · доля ложных "
                + ("НЕ ИЗМЕРЕНА" if share is None else f"{share:.0%}")
                + f"; цена области (пункт против строки) {tally.get('wrap_cost')}")
            sizes = observed(tally, "by_token_count", kind=dict) or {}
            out.append(
                f"[ТОЧНОСТЬ ИМЕНИ · {side} · ТОКЕНОВ В ИМЕНИ] "
                + " · ".join(
                    f"{size}: настоящих {cell.get(LABEL_GENUINE)}, ложных "
                    f"{cell.get(LABEL_ARTEFACT)}, не решено {cell.get(LABEL_UNDECIDED)}"
                    for size, cell in sorted(sizes.items())))
        interval = observed(precision, "truth_interval", kind=dict)
        if interval is None:
            out.append("[ТОЧНОСТЬ ИМЕНИ · ИНТЕРВАЛ] НЕ ИЗМЕРЕН — размеченного "
                       "населения стороны объявления нет")
        else:
            out.append(
                f"[ТОЧНОСТЬ ИМЕНИ · ИНТЕРВАЛ] точность канала лежит в "
                f"[{interval['lower']:.1%}, {interval['upper']:.1%}] при "
                f"знаменателе {interval['denominator']} — ширину держит "
                f"`UNDECIDED`, и это ОТВЕТ заказа, а не его отсутствие: "
                f"независимого свидетеля хватило не на всех")
        enrich = observed(precision, "enrichment", kind=dict) or {}
        for key, what in (("per_paragraph", "на абзац объявления"),
                          ("per_hit", "на срабатывание канала")):
            rate = observed(enrich, key, kind=float)
            out.append(
                f"[ТОЧНОСТЬ ИМЕНИ · ОБОГАЩЕНИЕ {what}] "
                + (f"x{rate:.2f}" if rate is not None
                   else f"НЕ ИЗМЕРЕНО — {enrich.get(key + '_reason')}"))
        for row in (precision.get("rows") or []):
            if row.get("side") != "authority" or row.get("label") != LABEL_GENUINE:
                continue
            out.append(
                f"[ТОЧНОСТЬ ИМЕНИ · НАСТОЯЩАЯ] {row.get('text')}:"
                f"{row.get('w1_colocated_item_line')} -> {row.get('resolved')} "
                f"`{row.get('named_as')}` = {row.get('value')} "
                f"(модуль назван: {row.get('w2_subject_named')}, величина: "
                f"{row.get('w3_value_named')})")
        for row in (precision.get("unresolved") or []):
            out.append(f"[ТОЧНОСТЬ ИМЕНИ · НЕ РАЗМЕЧЕНО] {row.get('text')} "
                       f"`{row.get('named_as')}`: {row.get('reason')}")
        for blind in (precision.get("blind") or []):
            out.append(f"[СЛЕПОТА] {blind}")
    # Секция стои́т на уровне тела функции, а не внутри `else` соседней
    # координаты: вложенная туда, она молчала бы у каждого дерева, где
    # разметка не измерена, — то есть там, где цена сужения и так неизвестна,
    # но сказать об этом надо громко. Та же ошибка размещения найдена у #655.
    depth = observed(doc, "token_depth_price", kind=dict)
    if depth is None:
        out.append("[ЦЕНА ДВУХ ТОКЕНОВ] НЕ ИЗМЕРЕНА — перепись собрана без "
                   "координаты (заказ G62 п. 1)")
    elif depth.get("status") != "MEASURED":
        out.append(f"[ЦЕНА ДВУХ ТОКЕНОВ] НЕ ИЗМЕРЕНА: {depth.get('reason')}")
    else:
        out.append(
            f"[ЦЕНА ДВУХ ТОКЕНОВ · ПРАВИЛО] глубина {depth.get('depth')} · "
            f"порог введён: {'да' if depth.get('applied') else 'НЕТ'} · "
            f"{depth.get('rule')}")
        depth_sides = observed(depth, "sides", kind=dict) or {}
        for side in ("authority", "control"):
            tally = observed(depth_sides, side, kind=dict)
            if tally is None:
                out.append(f"[ЦЕНА ДВУХ ТОКЕНОВ · {side}] НЕ ИЗМЕРЕНО — "
                           f"срабатываний этой стороны в разметке нет")
                continue
            was = observed(tally, "before", kind=dict) or {}
            flt = observed(tally, "as_filter", kind=dict) or {}
            survive = observed(flt, "survive", kind=dict) or {}
            lost = observed(flt, "lost", kind=dict) or {}
            lost_total = sum(lost.get(key, 0) for key in
                             (LABEL_GENUINE, LABEL_ARTEFACT, LABEL_UNDECIDED))
            out.append(
                f"[ЦЕНА ДВУХ ТОКЕНОВ · {side} · СУЖЕНИЕ] было "
                f"{was.get('labelled')} срабатываний, исчезает {lost_total}, "
                f"остаётся {survive.get('labelled')}; ПОТЕРЯНО настоящих "
                f"{lost.get(LABEL_GENUINE)} из {was.get(LABEL_GENUINE)} · "
                f"ложных снято {lost.get(LABEL_ARTEFACT)} из "
                f"{was.get(LABEL_ARTEFACT)} · не решённых удалено "
                f"{lost.get(LABEL_UNDECIDED)}, РЕШЕНО "
                f"{flt.get('resolved_undecided')}")
            for key, what in (("before", "до"), ("as_filter", "после сужения")):
                cell = (survive if key == "as_filter"
                        else observed(tally, key, kind=dict) or {})
                share = observed(cell, "false_share", kind=float)
                span = observed(cell, "interval", kind=dict)
                out.append(
                    f"[ЦЕНА ДВУХ ТОКЕНОВ · {side} · {what}] доля ложных "
                    + ("НЕ ИЗМЕРЕНА" if share is None else f"{share:.0%}")
                    + " · интервал "
                    + ("НЕ ИЗМЕРЕН" if span is None
                       else f"[{span['lower']:.1%}, {span['upper']:.1%}] при "
                            f"знаменателе {span['denominator']}"))
            wit = observed(tally, "as_witness", kind=dict) or {}
            out.append(
                f"[ЦЕНА ДВУХ ТОКЕНОВ · {side} · КАК СВИДЕТЕЛЬ] решено "
                f"`UNDECIDED` {wit.get('resolved_undecided')} из "
                f"{was.get(LABEL_UNDECIDED)}; настоящих стало "
                f"{wit.get(LABEL_GENUINE)}, население не убывает")
        price = observed(depth, "price_in_pairs", kind=dict)
        if price is None or price.get("status") != "MEASURED":
            out.append("[ЦЕНА ДВУХ ТОКЕНОВ · В ПАРАХ] НЕ ИЗМЕРЕНА: "
                       + str((price or {}).get("reason")))
        else:
            lost_pairs = price.get("lost") or []
            out.append(
                f"[ЦЕНА ДВУХ ТОКЕНОВ · В ПАРАХ] подтверждённых величиной "
                f"{price.get('corroborated')} · ТЕРЯЕТСЯ {len(lost_pairs)} · "
                f"остаётся {len(price.get('kept') or [])} · вердикт неоднозначен "
                f"у {len(price.get('unmatched') or [])}")
            for pair in lost_pairs:
                out.append(
                    f"[ЦЕНА ДВУХ ТОКЕНОВ · ПОТЕРЯННАЯ ПАРА] {pair.get('text')} "
                    f"-> {pair.get('resolved')} `{pair.get('named_as')}` = "
                    f"{pair.get('value')} (различающих токенов "
                    f"{pair.get('token_count')})")
            for pair in (price.get("unmatched") or []):
                out.append(
                    f"[ЦЕНА ДВУХ ТОКЕНОВ · ПАРА НЕ РАЗОБРАНА] "
                    f"{pair.get('text')} `{pair.get('named_as')}`: "
                    f"{pair.get('reason')}")
        ind = observed(depth, "independence", kind=dict) or {}
        out.append(
            f"[ЦЕНА ДВУХ ТОКЕНОВ · ТРЕТИЙ СВИДЕТЕЛЬ] {ind.get('verdict')} — "
            f"{ind.get('reason')}"
            + (f"; имён в двух и более абзацах "
               f"{ind.get('names_in_two_paragraphs')}, из них вердикт меняется "
               f"у {ind.get('names_whose_verdict_varies')}"
               if ind.get("verdict") != DEPTH_INDEPENDENCE_UNMEASURED else ""))
        for row in (depth.get("unreadable") or []):
            out.append(f"[ЦЕНА ДВУХ ТОКЕНОВ · НЕ РАЗОБРАНО] {row.get('text')} "
                       f"`{row.get('named_as')}`: {row.get('reason')}")
        for blind in (depth.get("blind") or []):
            out.append(f"[СЛЕПОТА] {blind}")
    # Секция — на уровне тела функции, а не внутри `else` соседней координаты:
    # вложенная туда, она молчала бы у каждого дерева, где разметка не
    # измерена, то есть ровно там, где о кандидатах и надо сказать громко.
    wit = observed(doc, "paragraph_witness_price", kind=dict)
    if wit is None:
        out.append("[СВИДЕТЕЛИ АБЗАЦА] НЕ ИЗМЕРЕНЫ — перепись собрана без "
                   "координаты (заказ G63 п. 1)")
    elif wit.get("status") != "MEASURED":
        out.append(f"[СВИДЕТЕЛИ АБЗАЦА] НЕ ИЗМЕРЕНЫ: {wit.get('reason')}")
    else:
        out.append(
            f"[СВИДЕТЕЛИ АБЗАЦА · ПРАВИЛО] кандидатов "
            f"{len(wit.get('declared') or [])} · порог на частоту ошибки "
            f"введён: {'да' if wit.get('applied') else 'НЕТ'} · "
            f"{wit.get('rule')}")
        out.append(
            f"[СВИДЕТЕЛИ АБЗАЦА · НАСЕЛЕНИЕ] неразрешённых у стороны "
            f"объявлений {wit.get('undecided_population')} в "
            f"{wit.get('undecided_paragraphs')} разных абзац(ах) · "
            f"контрольных срабатываний с W1 {wit.get('control_population')} в "
            f"{wit.get('control_paragraphs')} абзац(ах) · `ARTEFACT` "
            f"не спрашивается: "
            + str(observed(wit, "artefact_skipped", kind=dict) or {}))
        cands = observed(wit, "candidates", kind=dict) or {}
        for key, cand in cands.items():
            got = observed(cand, "resolves_undecided", kind=dict) or {}
            err = observed(cand, "error_rate_on_control", kind=dict) or {}
            share = observed(got, "share", kind=float)
            rate = observed(err, "share", kind=float)
            out.append(
                f"[СВИДЕТЕЛЬ · {key}] "
                + ("ДЕЙСТВУЮЩИЙ" if cand.get("incumbent") else "кандидат")
                + f" · читает: {cand.get('reads')} · решает `UNDECIDED` "
                + ("НЕ ИЗМЕРЕНО" if share is None
                   else f"{got.get('fired')} из {got.get('askable')} "
                        f"({share:.0%}) в {got.get('paragraphs')} абзац(ах)")
                + " · частота ошибки на контроле "
                + ("НЕ ИЗМЕРЕНА" if rate is None
                   else f"{err.get('fired')} из {err.get('askable')} "
                        f"({rate:.0%}) в {err.get('paragraphs')} абзац(ах)")
                + " · в правило допустим: "
                + ("да" if cand.get("admissible_to_rule") else "НЕТ"))
            if got.get("unaskable") or err.get("unaskable"):
                out.append(
                    f"[СВИДЕТЕЛЬ · {key} · НЕ СПРОШЕН] неразрешённых "
                    f"{got.get('unaskable')}, контрольных "
                    f"{err.get('unaskable')} — причины: "
                    + "; ".join(f"{why} ×{n}" for why, n in
                                (cand.get("unaskable_reasons") or {}).items()))
            if cand.get("structural_zero"):
                out.append(f"[СВИДЕТЕЛЬ · {key} · НОЛЬ ПО ПОСТРОЕНИЮ] "
                           f"{cand.get('structural_zero')}")
            for row in (cand.get("contradictions") or []):
                out.append(
                    f"[СВИДЕТЕЛЬ · {key} · ПРОТИВОРЕЧИЕ] действующий свидетель "
                    f"сработал на `UNDECIDED` {row.get('text')} "
                    f"`{row.get('named_as')}` — разметка и эта мера спорят, и "
                    f"спор обязан быть разобран, а не усреднён")
            ind = observed(cand, "independence", kind=dict) or {}
            out.append(
                f"[СВИДЕТЕЛЬ · {key} · ЧИТАЕТ ЛИ АБЗАЦ] {ind.get('verdict')} — "
                f"{cand.get('independence_reading')}; охват "
                + str(cand.get("reach") or {}))
            for row in (cand.get("examples") or []):
                out.append(
                    f"[СВИДЕТЕЛЬ · {key} · РЕШЁННОЕ] {row.get('text')}:"
                    f"{row.get('block_start')} -> {row.get('resolved')} "
                    f"`{row.get('named_as')}` = {row.get('value')}")
        for row in (wit.get("unreadable") or []):
            out.append(f"[СВИДЕТЕЛИ АБЗАЦА · НЕ РАЗОБРАНО] {row.get('text')} "
                       f"`{row.get('named_as')}`: {row.get('reason')}")
        for row in (wit.get("unresolved") or []):
            out.append(f"[СВИДЕТЕЛИ АБЗАЦА · АБЗАЦ НЕ РАЗРЕШЁН] "
                       f"{row.get('text')} `{row.get('named_as')}`: "
                       f"{row.get('reason')}")
        for blind in (wit.get("blind") or []):
            out.append(f"[СЛЕПОТА] {blind}")
    # Секция — на уровне тела функции по той же причине, что и соседняя:
    # вложенная в `else` чужой координаты, она молчала бы ровно там, где о
    # цене и надо сказать громко.
    adm = observed(doc, "witness_admission_price", kind=dict)
    if adm is None:
        out.append("[ЦЕНА ДОПУСКА] НЕ ИЗМЕРЕНА — перепись собрана без "
                   "координаты (заказ G64 п. 1)")
    elif adm.get("status") != "MEASURED":
        out.append(f"[ЦЕНА ДОПУСКА] НЕ ИЗМЕРЕНА: {adm.get('reason')}")
    else:
        out.append(
            f"[ЦЕНА ДОПУСКА · ПРАВИЛО] порог введён: "
            f"{'да' if adm.get('applied') else 'НЕТ'} · {adm.get('rule')}")
        today = observed(adm, "pairs_today", kind=dict) or {}
        if today.get("status") != "MEASURED":
            out.append(f"[ЦЕНА ДОПУСКА · КНИГИ СЕГОДНЯ] НЕ ИЗМЕРЕНО: "
                       f"{today.get('reason')}")
        else:
            out.append(
                f"[ЦЕНА ДОПУСКА · КНИГИ СЕГОДНЯ] пар {today.get('pairs')} из "
                f"{today.get('paragraphs')} абзац(ев) · с меткой `GENUINE` "
                f"совпадают {today.get('genuine_overlap')} — совпадение ЧИСЕЛ "
                f"тождеством множеств не является, поэтому меряется "
                f"пересечение"
                + (f" · пара без `GENUINE`: {len(today.get('pairs_not_genuine') or [])}"
                   f" · `GENUINE` без пары: {len(today.get('genuine_not_pairs') or [])}"))
        for key, cand in (observed(adm, "candidates", kind=dict) or {}).items():
            prov = observed(cand, "pair_provenance", kind=dict) or {}
            sides = observed(cand, "sides", kind=dict) or {}
            auth = observed(sides, "authority", kind=dict) or {}
            ctl = observed(sides, "control", kind=dict) or {}
            out.append(
                f"[ЦЕНА ДОПУСКА · {key}] "
                + ("ДЕЙСТВУЮЩИЙ" if cand.get("incumbent") else "кандидат")
                + f" · {cand.get('admitted_rule')} · пар прибывает "
                + ("НЕ ИЗМЕРЕНО" if prov.get("status") != "MEASURED"
                   else f"{prov.get('added')} "
                        f"из {prov.get('paragraphs_added')} абзац(ев); из "
                        f"абзацев, уже плативших книгам: "
                        f"{prov.get('from_paragraph_already_paying')}; "
                        f"молчавших до сих пор: "
                        f"{prov.get('from_paragraph_silent_until_now')} в "
                        f"{prov.get('paragraphs_new_to_books')} абзац(ах))")
                + f" · на КОНТРОЛЕ прибывает {ctl.get('added')} — ложных ПО "
                  f"ПОСТРОЕНИЮ")
            for side_name, side in (("объявления", auth), ("контроль", ctl)):
                before = observed(side, "interval_before", kind=dict)
                after = observed(side, "interval_after", kind=dict)
                if side.get("status") != "MEASURED":
                    out.append(
                        f"[ЦЕНА ДОПУСКА · {key} · ИНТЕРВАЛ {side_name}] НЕ "
                        f"ИЗМЕРЕН: {side.get('reason') or 'стороны нет в разметке'}")
                    continue
                if before is None or after is None:
                    out.append(
                        f"[ЦЕНА ДОПУСКА · {key} · ИНТЕРВАЛ {side_name}] НЕ "
                        f"ИЗМЕРЕН: размеченного населения этой стороны нет")
                    continue
                out.append(
                    f"[ЦЕНА ДОПУСКА · {key} · ИНТЕРВАЛ {side_name}] "
                    f"[{before['lower']:.1%}, {before['upper']:.1%}] -> "
                    f"[{after['lower']:.1%}, {after['upper']:.1%}] при "
                    f"знаменателе {before['denominator']} · нижняя тронулась: "
                    + ("да" if side.get("lower_bound_moved") else "НЕТ")
                    + " · верхняя тронулась: "
                    + ("ДА — ПРОТИВОРЕЧИЕ ОПРЕДЕЛЕНИЮ"
                       if side.get("upper_bound_moved") else "нет"))
            if cand.get("structural_zero"):
                out.append(f"[ЦЕНА ДОПУСКА · {key} · НОЛЬ ПО ПОСТРОЕНИЮ] "
                           f"{cand.get('structural_zero')}")
            for item in (cand.get("contradicts_marking") or []):
                out.append(
                    f"[ЦЕНА ДОПУСКА · {key} · ПРОТИВОРЕЧИЕ] ДЕЙСТВУЮЩИЙ "
                    f"свидетель сработал на `UNDECIDED` {item.get('text')}:"
                    f"{item.get('block_start')} `{item.get('named_as')}` — "
                    f"ноль по построению ОПРОВЕРГНУТ замером, и спор обязан "
                    f"быть разобран, а не усреднён")
            for item in (cand.get("already_a_pair") or []):
                out.append(
                    f"[ЦЕНА ДОПУСКА · {key} · ПРОТИВОРЕЧИЕ] прибывшая пара "
                    f"{item.get('text')}:{item.get('block_start')} "
                    f"`{item.get('named_as')}` УЖЕ стои́т в парах канала — "
                    f"`UNDECIDED` означает «без W3», и спор обязан быть "
                    f"разобран, а не усреднён")
            for item in (cand.get("examples") or []):
                out.append(
                    f"[ЦЕНА ДОПУСКА · {key} · ПРИБЫЛО] {item.get('text')}:"
                    f"{item.get('block_start')} -> {item.get('resolved')} "
                    f"`{item.get('named_as')}` = {item.get('value')}")
        for item in (adm.get("unreadable") or []):
            out.append(f"[ЦЕНА ДОПУСКА · НЕ РАЗОБРАНО] {item.get('text')} "
                       f"`{item.get('named_as')}`: {item.get('reason')}")
        for item in (adm.get("unresolved") or []):
            out.append(f"[ЦЕНА ДОПУСКА · АБЗАЦ НЕ РАЗРЕШЁН] {item.get('text')} "
                       f"`{item.get('named_as')}`: {item.get('reason')}")
        for blind in (adm.get("blind") or []):
            out.append(f"[СЛЕПОТА] {blind}")
    # --- БАЗА ЧИТАТЕЛЯ (заказ G65 п. 1) ---------------------------------
    naming = observed(doc, "consumer_base_naming", kind=dict)
    if naming is None:
        out.append("[БАЗА ЧИТАТЕЛЯ] НЕ ИЗМЕРЕНА — перепись собрана без "
                   "разбора читателей")
    elif naming.get("status") != "MEASURED":
        out.append(f"[БАЗА ЧИТАТЕЛЯ] НЕ ИЗМЕРЕНА: {naming.get('reason')}")
    else:
        tally = naming.get("naming") or {}
        out.append(
            f"[БАЗА ЧИТАТЕЛЯ] читателей {len(naming.get('consumers') or [])} · "
            f"названо верно {tally.get(NAMING_SINGLE)} · "
            f"именем ДРУГОЙ базы {tally.get(NAMING_CROSS)} · "
            f"МНОГОЗНАЧНЫМ именем {tally.get(NAMING_AMBIGUOUS)} · "
            f"без имени {tally.get(NAMING_UNNAMED)}")
        for consumer in (naming.get("consumers") or []):
            if consumer.get("status") == CONSUMER_UNMEASURED:
                out.append(f"[БАЗА ЧИТАТЕЛЯ · {consumer.get('key')}] НЕ "
                           f"ИЗМЕРЕНО: {consumer.get('reason')}")
                continue
            if consumer.get("status") == CONSUMER_DELEGATES:
                out.append(
                    f"[БАЗА ЧИТАТЕЛЯ · {consumer.get('key')}] ДЕЛЕГИРУЕТ "
                    f"отрисовку производителю "
                    f"({', '.join(consumer.get('delegates_via') or [])}) — "
                    f"своей базы НЕТ, и это не ноль: он доносит до глаз чужую")
                continue
            if consumer.get("status") == CONSUMER_NO_READ:
                out.append(
                    f"[БАЗА ЧИТАТЕЛЯ · {consumer.get('key')}] НИ ОДНОЙ "
                    f"объявленной базы не читает и отрисовщик производителя не "
                    f"зовёт — объявлен читателем, а читает своё третье")
                continue
            out.append(
                f"[БАЗА ЧИТАТЕЛЯ · {consumer.get('key')}] базы "
                f"{', '.join(consumer.get('bases_read') or []) or '—'} · "
                f"чисел {len(consumer.get('numbers') or [])} · вне f-строки "
                f"{consumer.get('reads_outside_fstring')} (не разбирается)")
        for token, bases in sorted((naming.get("token_adjacency") or {}).items()):
            if len(bases) > 1:
                out.append(
                    f"[БАЗА ЧИТАТЕЛЯ · МНОГОЗНАЧНО] токен `{token}` стои́т "
                    f"рядом с {len(bases)} РАЗНЫМИ базами ({', '.join(bases)}) "
                    f"— читателю они этим словом не различаются ничем")
        for item in (naming.get("findings") or []):
            out.append(
                f"[БАЗА ЧИТАТЕЛЯ · {item.get('verdict')}] "
                f"{item.get('consumer')}:{item.get('line')} база "
                f"`{item.get('base')}` (координата `{item.get('coordinate')}`) "
                f"названа {item.get('tokens')}")
        carriers = naming.get("carries_ambiguity_by_delegation") or []
        if carriers:
            out.append(
                f"[БАЗА ЧИТАТЕЛЯ · ДОНОСИТ] {', '.join(carriers)} — своей базы "
                f"не имеет и потому несёт ЧУЖОЕ многозначное имя дальше: до "
                f"оркестратора доезжает именно эта строка")
        for blind in (naming.get("blind") or []):
            out.append(f"[СЛЕПОТА] {blind}")
    # --- РЕЕСТР ЧИТАТЕЛЕЙ (заказ G66 п. 1) ------------------------------
    completeness = observed(doc, "consumer_registry_completeness", kind=dict)
    if completeness is None:
        out.append("[РЕЕСТР ЧИТАТЕЛЕЙ] НЕ ИЗМЕРЕН — перепись собрана без "
                   "сведения двух населений")
    elif completeness.get("status") != "MEASURED":
        out.append(f"[РЕЕСТР ЧИТАТЕЛЕЙ] НЕ ИЗМЕРЕН: {completeness.get('reason')}")
    elif observed(completeness, "counts", kind=dict) is None:
        # Отсутствие счётчиков — ОТДЕЛЬНОЕ значение, а не пустой словарь
        # (инв. #17). Прежняя редакция писала `completeness.get("counts") or
        # {}`, и тогда «ключа нет» печаталось теми же `None`, что и «счётчик
        # равен None»: документ, объявивший себя измеренным без счётчиков,
        # выглядел бы измеренным с пустыми. Храповик
        # `test_absent_observation_ratchet` назвал эту строку новым членом
        # класса на предписанном прогоне — верно назвал.
        out.append("[РЕЕСТР ЧИТАТЕЛЕЙ] НЕ ИЗМЕРЕН: документ объявлен "
                   "MEASURED, но счётчиков в нём нет — это НЕ нулевые "
                   "счётчики и не пустое сведение")
    else:
        cnt = observed(completeness, "counts", kind=dict)
        out.append(
            f"[РЕЕСТР ЧИТАТЕЛЕЙ] объявлено {cnt.get('declared')} · мест "
            f"измерено {cnt.get('sites')} · названо {cnt.get('named')} · НЕ "
            f"названо {cnt.get('unnamed')} (кода {cnt.get('unnamed_code')}, "
            f"тестов {cnt.get('unnamed_test')}) · из них ПЕЧАТАЕТ числа "
            f"{cnt.get('unnamed_reading')}")
        out.append(
            f"[РЕЕСТР ЧИТАТЕЛЕЙ · СЛЕПОТА СОСЕДА] зовов, не разрешимых "
            f"статикой, у соседа {cnt.get('neighbour_dynamic_unresolved')}; "
            f"файлов ввоза не прочитано {cnt.get('import_files_unreadable')} "
            f"— это ЧИСЛА, а не ноль зовущих")
        for item in (completeness.get("declared_unseen") or []):
            out.append(
                f"[РЕЕСТР ЧИТАТЕЛЕЙ · СОСЕД НЕ ВИДИТ] `{item.get('key')}` "
                f"({item.get('path')}): {item.get('reason')} · поверхностью "
                f"ввоза виден: {item.get('seen_by_import_surface')}")
        for item in (completeness.get("findings") or [])[:max_rows]:
            out.append(
                f"[РЕЕСТР ЧИТАТЕЛЕЙ · НАХОДКА {item.get('kind')}] "
                f"{item.get('file')}:{item.get('line')} "
                f"(область {item.get('scope')}, канал {item.get('channel')}, "
                f"чисел {item.get('numbers')}) — {item.get('why')}")
        for item in (completeness.get("unreadable") or [])[:max_rows]:
            out.append(f"[РЕЕСТР ЧИТАТЕЛЕЙ · НЕ ПРОЧИТАНО] {item.get('file')}: "
                       f"{item.get('unreadable')}")
        for blind in (completeness.get("blind") or []):
            out.append(f"[СЛЕПОТА] {blind}")
    # --- МАСШТАБ НЕВИДИМОСТИ (заказ G67 п. 1) ---------------------------
    scale = observed(doc, "invisible_consumer_scale", kind=dict)
    if scale is None:
        out.append("[МАСШТАБ НЕВИДИМОСТИ] НЕ ИЗМЕРЕН — перепись собрана без "
                   "обхода населения переписей")
    elif scale.get("status") == "UNMEASURED":
        out.append(f"[МАСШТАБ НЕВИДИМОСТИ] НЕ ИЗМЕРЕН: {scale.get('reason')}")
    elif observed(scale, "counts", kind=dict) is None:
        # Инв. #17: «счётчиков нет» и «счётчики нулевые» — разные утверждения,
        # и второе, напечатанное вместо первого, есть ровно тот fail-OPEN,
        # который перепись ищет у других (регрессия #664 на соседней ветке).
        out.append("[МАСШТАБ НЕВИДИМОСТИ] НЕ ИЗМЕРЕН: документ объявлен "
                   "измеренным, но счётчиков в нём нет — это НЕ нулевые "
                   "счётчики")
    else:
        cnt = observed(scale, "counts", kind=dict)
        out.append(
            f"[МАСШТАБ НЕВИДИМОСТИ] переписей {cnt.get('censuses')} · "
            f"отрисовщик разрешён {cnt.get('renderer_resolved')} · население "
            f"зовущих ЗАНИЖЕНО у {cnt.get('understated')} "
            f"({cnt.get('understated_share_of_resolved')} % разрешённых) · "
            f"мест {cnt.get('sites')} (кода {cnt.get('sites_code')}, тестов "
            f"{cnt.get('sites_test')})")
        out.append(
            f"[МАСШТАБ НЕВИДИМОСТИ · ИНТЕРВАЛ] занижено от "
            f"{cnt.get('understated')} до {cnt.get('understated_upper_bound')} "
            f"переписей: нижняя граница опирается на отрисовщик, РАЗРЕШЁННЫЙ "
            f"печатью, верхняя добавляет тех, у кого печать его не решает — "
            f"это цена правила печати, а не оговорка")
        out.append(
            f"[МАСШТАБ НЕВИДИМОСТИ · ТРЕТИЙ ИСХОД] отрисовщик не разрешён у "
            f"{cnt.get('renderer_unresolved')}: отдавать нечего "
            f"{cnt.get('renderer_none_exists')} (класс не применим ПО "
            f"ПОСТРОЕНИЮ) · граница правила {cnt.get('renderer_not_printed')} "
            f"(текстовые функции есть, печать их не решает)")
        out.append(
            f"[МАСШТАБ НЕВИДИМОСТИ · ДО ОРКЕСТРАТОРА] читатель "
            f"`{scale.get('orchestrator_reader')}` невидим соседу у "
            f"{cnt.get('censuses_invisible_to_orchestrator_reader')} "
            f"переписей — это тот самый единственный, кто доносит их числа "
            f"до оркестратора")
        out.append(
            f"[МАСШТАБ НЕВИДИМОСТИ · ОБРАТНАЯ СТОРОНА] занижено ДО НУЛЯ у "
            f"{cnt.get('blanked_to_zero')} переписей: класс есть занижение "
            f"населения, а не его обнуление, и это измерено, а не "
            f"предположено")
        if cnt.get("vocabulary_missed"):
            out.append(
                f"[МАСШТАБ НЕВИДИМОСТИ · СЛОВАРЬ] отрисовщик ИЗМЕРЕН, а не "
                f"взят словарём ADR-444: имена "
                f"{scale.get('renderer_names')}; словарь "
                f"{list(_ADR444_RENDERER_VOCABULARY)} не назвал бы "
                f"{cnt.get('vocabulary_missed')} перепис(и) — "
                + ", ".join(f"{item.get('census')} ({','.join(item.get('renderers') or [])})"
                            for item in (scale.get("vocabulary_missed") or [])))
        for item in (scale.get("findings") or [])[:max_rows]:
            out.append(
                f"[МАСШТАБ НЕВИДИМОСТИ · НАХОДКА] `{item.get('census')}`: "
                f"{', '.join(item.get('consumers') or [])} — "
                f"{item.get('why')}"
                + (" · доносит до оркестратора"
                   if item.get("reaches_orchestrator") else ""))
        for item in (scale.get("renderer_unresolved") or [])[:max_rows]:
            out.append(f"[МАСШТАБ НЕВИДИМОСТИ · ОТРИСОВЩИК НЕ РАЗРЕШЁН] "
                       f"{item.get('census')}: {item.get('reason')}")
        for item in (scale.get("unreadable") or [])[:max_rows]:
            out.append(f"[МАСШТАБ НЕВИДИМОСТИ · НЕ ПРОЧИТАНО] "
                       f"{item.get('file')}: {item.get('unreadable')}")
        for blind in (scale.get("blind") or []):
            out.append(f"[СЛЕПОТА] {blind}")
    # --- ВРЕД ЗАНИЖЕНИЯ (заказ G68 п. 1) -------------------------------
    harm = observed(doc, "neighbour_population_harm", kind=dict)
    if harm is None:
        out.append("[ВРЕД ЗАНИЖЕНИЯ] НЕ ИЗМЕРЕН — перепись собрана без "
                   "сверки двух прогонов соседа")
    elif harm.get("status") == "UNMEASURED":
        out.append(f"[ВРЕД ЗАНИЖЕНИЯ] НЕ ИЗМЕРЕН: {harm.get('reason')}")
    elif observed(harm, "counts", kind=dict) is None:
        # Инв. #17: «счётчиков нет» и «счётчики нулевые» — разные утверждения,
        # и второе, напечатанное вместо первого, есть fail-OPEN (регрессия #664).
        out.append("[ВРЕД ЗАНИЖЕНИЯ] НЕ ИЗМЕРЕН: документ объявлен измеренным, "
                   "но счётчиков в нём нет — это НЕ нулевые счётчики")
    else:
        cnt = observed(harm, "counts", kind=dict)
        out.append(
            f"[ВРЕД ЗАНИЖЕНИЯ] население соседа расширено на "
            f"{cnt.get('widened_by')} измеренных мест · полей документа "
            f"{cnt.get('doc_fields')} · СДВИНУЛОСЬ {cnt.get('doc_fields_moved')}"
            f" ({', '.join(harm.get('moved_fields') or []) or '—'})")
        out.append(
            f"[ВРЕД ЗАНИЖЕНИЯ · ВЕРДИКТ] из {cnt.get('verdict_fields_declared')}"
            f" ОБЪЯВЛЕННЫХ до замера полей вердикта сдвинулось "
            f"{cnt.get('verdict_fields_moved')}"
            + (f" ({', '.join(harm.get('verdict_fields_moved') or [])})"
               if harm.get("verdict_fields_moved") else
               " — читатель, решающий по вердикту, получает тождественно тот "
               "же вход, и его решение измениться НЕ МОЖЕТ"))
        out.append(
            f"[ВРЕД ЗАНИЖЕНИЯ · ЧИТАТЕЛИ] {cnt.get('readers')} по дорогам "
            f"{cnt.get('readers_by_road')} · чтений {cnt.get('touches')} "
            f"(решают {cnt.get('touches_deciding')}, печатают "
            f"{cnt.get('touches_printing')}, НЕ РАЗОБРАНО "
            f"{cnt.get('touches_unresolved')})")
        out.append(
            f"[ВРЕД ЗАНИЖЕНИЯ · ОТВЕТ] решают по СДВИНУВШЕМУСЯ полю "
            f"{cnt.get('readers_deciding_on_moved')} читател(я/ей) · решение "
            f"пересчитано и ИЗМЕНИЛОСЬ у {cnt.get('readers_decision_changed')}"
            f", осталось тем же у {cnt.get('readers_decision_unchanged')}, "
            f"прогон не оплачен у {cnt.get('readers_not_executed')}")
        for entry in (harm.get("executed") or []):
            out.append(
                f"[ВРЕД ЗАНИЖЕНИЯ · ПЕРЕСЧЁТ] {entry.get('key')} "
                f"(поле `{entry.get('field')}`, цена измеренная "
                f"{entry.get('cost_s_measured')} с / объявленная "
                f"{entry.get('cost_s_declared')} с): "
                f"{entry.get('outcome')}"
                + (f" — {entry.get('reason')}" if entry.get("reason") else ""))
        scope = observed(harm, "coordinate_scope", kind=dict)
        if scope is None:
            out.append("[ВРЕД ЗАНИЖЕНИЯ · КООРДИНАТА] НЕ ИЗМЕРЕНА — документ "
                       "собран без сверки «хвост против полного пути»; это НЕ "
                       "«множества совпали»")
        else:
            out.append(
                f"[ВРЕД ЗАНИЖЕНИЯ · КООРДИНАТА] население по ХВОСТУ "
                f"{scope.get('readers_by_tail')} · по ПОЛНОМУ ПУТИ "
                f"{scope.get('readers_by_path')} · множества "
                + ("СОВПАДАЮТ" if scope.get("sets_coincide") else
                   f"НЕ СОВПАДАЮТ (только по хвосту: "
                   f"{', '.join(scope.get('files_only_by_tail') or []) or '—'}"
                   f"; только по пути: "
                   f"{', '.join(scope.get('files_only_by_path') or []) or '—'})")
                + f" · многозначных хвостов у документа "
                  f"{scope.get('ambiguous_tails_total')} из "
                  f"{scope.get('doc_tails')}, среди сдвинувшихся "
                  f"{len(scope.get('ambiguous_tails_among_moved') or [])}")
            # Инв. #17: у перечня «не измерено» подстановка `or []`
            # запрещена — «ключа нет» и «список пуст» суть разные
            # утверждения, и второе вместо первого есть fail-OPEN ровно в
            # том месте, которое про неизмеренное и написано.
            surplus = observed(scope, "touches_admitted_by_tail_only",
                               kind=list)
            unmeasured = observed(
                scope, "deciding_admitted_by_tail_path_unmeasured", kind=list)
            by_path_only = observed(scope, "touches_admitted_by_path_only",
                                    kind=list)
            out.append(
                "[ВРЕД ЗАНИЖЕНИЯ · КООРДИНАТА · РАЗНОСТЬ] доказанно лишних "
                "чтений "
                + ("НЕ ИЗМЕРЕНО" if surplus is None else str(len(surplus)))
                + " · путь до якоря НЕ РАЗОБРАН у "
                + ("НЕ ИЗМЕРЕНО" if unmeasured is None
                   else str(len(unmeasured)))
                + " (это НЕ «поле не сдвинулось») · впущенных только путём "
                + ("НЕ ИЗМЕРЕНО" if by_path_only is None
                   else str(len(by_path_only)))
                + " (при разобранном пути обязан быть ноль)")
        flat = observed(harm, "flatten_scope", kind=dict)
        if flat is None:
            out.append("[ВРЕД ЗАНИЖЕНИЯ · УПЛОЩЕНИЕ] НЕ ИЗМЕРЕНО — документ "
                       "собран без сверки двух правил уплощения; это НЕ "
                       "«списков нет» и НЕ «разницы нет»")
        else:
            out.append(
                f"[ВРЕД ЗАНИЖЕНИЯ · УПЛОЩЕНИЕ] хвостов по нынешнему правилу "
                f"{flat.get('tails_shallow')} (многозначных "
                f"{flat.get('ambiguous_shallow')}, "
                f"{flat.get('ambiguous_share_shallow_pct')} %) · при "
                f"развёртывании списков {flat.get('tails_deep')} "
                f"(многозначных {flat.get('ambiguous_deep')}, "
                f"{flat.get('ambiguous_share_deep_pct')} %) · списков в "
                f"документе {flat.get('lists_in_doc')} "
                f"({flat.get('list_elements')} элемент(ов)) · вердикт: "
                f"{flat.get('verdict')}")
            only_deep = observed(flat, "tails_only_deep", kind=list)
            only_shallow = observed(flat, "tails_only_shallow", kind=list)
            out.append(
                "[ВРЕД ЗАНИЖЕНИЯ · УПЛОЩЕНИЕ · РАЗНОСТЬ] видны только "
                "глубокому правилу: "
                + ("НЕ ИЗМЕРЕНО" if only_deep is None
                   else (", ".join(only_deep[:max_rows]) or "—"))
                + " · ТЕРЯЮТСЯ глубоким правилом (имя самого списка): "
                + ("НЕ ИЗМЕРЕНО" if only_shallow is None
                   else (", ".join(only_shallow[:max_rows]) or "—")))
            deep_only = observed(flat, "touches_admitted_by_deep_only",
                                 kind=list)
            capped = observed(flat, "paths_depth_capped", kind=list)
            out.append(
                "[ВРЕД ЗАНИЖЕНИЯ · УПЛОЩЕНИЕ · ПОТРЕБИТЕЛЬ] решающих чтений, "
                "невидимых нынешнему населению: "
                + ("НЕ ИЗМЕРЕНО" if deep_only is None else str(len(deep_only)))
                + " · путей, упершихся в объявленный предел глубины "
                + f"({flat.get('max_depth_declared')}): "
                + ("НЕ ИЗМЕРЕНО" if capped is None else str(len(capped)))
                + " (предел есть третий исход, а не «поля нет»)")
        out.append(
            f"[ВРЕД ЗАНИЖЕНИЯ · ФОРМА] мест, у которых форма синтеза "
            f"(со строкой и без) способна изменить ответ: "
            f"{cnt.get('shape_sensitive_sites')}"
            + ("" if cnt.get("shape_sensitive_sites") else
               " — ответ от формы НЕ зависит, и это число, а не обещание"))
        for item in (harm.get("findings") or [])[:max_rows]:
            out.append(
                f"[ВРЕД ЗАНИЖЕНИЯ · НАХОДКА] {item.get('kind')}: "
                f"{item.get('file')}"
                + (f" ({', '.join(item.get('fields') or [])})"
                   if item.get("fields") else "")
                + f" — {item.get('why')}")
        for item in (harm.get("unreadable") or [])[:max_rows]:
            out.append(f"[ВРЕД ЗАНИЖЕНИЯ · НЕ ПРОЧИТАНО] {item.get('file')}: "
                       f"{item.get('unreadable')}")
        for blind in (harm.get("blind") or []):
            out.append(f"[СЛЕПОТА] {blind}")
    # --- ЦЕНА ПЕРЕСЧЁТА И ТАКТ (заказ G69 п. 1) ------------------------
    budget = observed(doc, "recompute_cost_budget", kind=dict)
    if budget is None:
        out.append("[ЦЕНА ПЕРЕСЧЁТА] НЕ ИЗМЕРЕНА — перепись собрана без "
                   "замера цены и такта")
    elif budget.get("verdict") == BUDGET_UNMEASURED:
        out.append(f"[ЦЕНА ПЕРЕСЧЁТА] НЕ ИЗМЕРЕНА: "
                   f"{budget.get('budget_refused') or budget.get('reason')}")
    else:
        bcnt = observed(budget, "counts", kind=dict)
        out.append(
            f"[ЦЕНА ПЕРЕСЧЁТА] полный пересчёт {budget.get('total_cost_s')} с "
            f"при такте {budget.get('budget_s')} с "
            f"({budget.get('budget_source')}) · запас {budget.get('margin')}× "
            f"при объявленных до замера {budget.get('required_margin_declared')}× "
            f"⇒ {budget.get('verdict')}")
        for row in (budget.get("costs") or [])[:max_rows]:
            out.append(
                f"[ЦЕНА ПЕРЕСЧЁТА · ЧИТАТЕЛЬ] {row.get('key')}: измерено "
                f"{row.get('cost_s_measured')} с ({row.get('cost_basis')}, "
                f"прогонов {row.get('runs_timed')}, за прогон "
                f"{row.get('cost_s_per_run')} с) · объявлено "
                f"{row.get('cost_s_declared')} с · претензия "
                f"{row.get('claim')}"
                + (f" — {row.get('claim_reason')}" if row.get("claim_reason")
                   else ""))
        if bcnt is not None:
            out.append(
                f"[ЦЕНА ПЕРЕСЧЁТА · УЧЁТ] читателей {bcnt.get('readers')} = "
                f"с ценой {bcnt.get('priced')} + без цены "
                f"{bcnt.get('unpriced')} · претензия подтверждена "
                f"{bcnt.get('claims_confirmed')}, опровергнута "
                f"{bcnt.get('claims_refuted')}, не измерена "
                f"{bcnt.get('claims_unmeasured')} · остаток "
                f"{bcnt.get('remainder')}")
        for item in (budget.get("findings") or [])[:max_rows]:
            out.append(
                f"[ЦЕНА ПЕРЕСЧЁТА · НАХОДКА] {item.get('kind')}: "
                f"{', '.join(item.get('fields') or []) or item.get('file')} — "
                f"{item.get('why')}")
        for blind in (budget.get("blind") or []):
            out.append(f"[СЛЕПОТА] {blind}")
    # --- ЦЕНА КАНАЛА ТЕСТА И ЗАМЫКАНИЕ (заказ G70 п. 1) ----------------
    # Секция вынесена ЗА блок цены пересчёта НАМЕРЕННО: вложенная внутрь его
    # `else`, она молчала бы ровно там, где цена пересчёта не измерена, —
    # то есть в единственном состоянии, где отдельный вопрос о канале теста
    # и нужен громче всего.
    channel = observed(doc, "reader_cost_of_test_channel", kind=dict)
    if channel is None:
        out.append("[ЦЕНА КАНАЛА ТЕСТА] НЕ ИЗМЕРЕНА — перепись собрана без "
                   "замера цены канала теста")
    elif channel.get("verdict") == BUDGET_UNMEASURED:
        out.append(f"[ЦЕНА КАНАЛА ТЕСТА] НЕ ИЗМЕРЕНА: "
                   f"{channel.get('budget_refused') or channel.get('reason')}")
    else:
        ccnt = observed(channel, "counts", kind=dict)
        out.append(
            f"[ЦЕНА КАНАЛА ТЕСТА] канал {channel.get('total_cost_s')} с + "
            f"пересчёт {channel.get('prior_cost_s')} с = "
            f"{channel.get('combined_cost_s')} с при такте "
            f"{channel.get('budget_s')} с ({channel.get('budget_source')}) · "
            f"запас {channel.get('margin')}× при объявленных до замера "
            f"{channel.get('required_margin_declared')}× ⇒ "
            f"{channel.get('verdict')}")
        for row in (channel.get("rows") or [])[:max_rows]:
            static = row.get("static") or {}
            out.append(
                f"[ЦЕНА КАНАЛА ТЕСТА · ЧИТАТЕЛЬ] {row.get('file')}: "
                f"{row.get('cost_s')} с (исход {row.get('outcome')}, код "
                f"{row.get('exit_code')}) · замыкание {row.get('recursion')} "
                f"(отметок {row.get('reentries')}) · разбор текста "
                f"{static.get('reaches')} ⇒ свидетели {row.get('witnesses')}")
        if ccnt is not None:
            out.append(
                f"[ЦЕНА КАНАЛА ТЕСТА · УЧЁТ] читателей {ccnt.get('readers')} = "
                f"с ценой {ccnt.get('priced')} + без цены "
                f"{ccnt.get('unpriced')} · зелёных {ccnt.get('ran_green')}, "
                f"красных {ccnt.get('ran_red')}, не заводилось "
                f"{ccnt.get('refused_nested')}, не измерено "
                f"{ccnt.get('unmeasured')} · замыкание наблюдено "
                f"{ccnt.get('recursion_observed')}, не наблюдено "
                f"{ccnt.get('recursion_not_observed')}, не измерено "
                f"{ccnt.get('recursion_unmeasured')} · свидетели согласны "
                f"{ccnt.get('witnesses_agree')}, спорят "
                f"{ccnt.get('witnesses_disagree')}, неполны "
                f"{ccnt.get('witnesses_incomplete')}")
        for item in (channel.get("findings") or [])[:max_rows]:
            out.append(
                f"[ЦЕНА КАНАЛА ТЕСТА · НАХОДКА] {item.get('kind')}: "
                f"{', '.join(item.get('fields') or []) or item.get('file')} — "
                f"{item.get('why')}")
        for blind in (channel.get("blind") or []):
            out.append(f"[СЛЕПОТА] {blind}")
    reg = observed(doc, "registry_ambiguity_scope", kind=dict)
    if reg is None:
        out.append("[МНОГОЗНАЧНОСТЬ РЕЕСТРА] НЕ ИЗМЕРЕНА — перепись собрана "
                   "без обхода реестра; это НЕ «многозначности нет» и НЕ "
                   "«читателю она ничего не стоит»")
    elif str(reg.get("status")) == "UNMEASURED":
        out.append(f"[МНОГОЗНАЧНОСТЬ РЕЕСТРА] НЕ ИЗМЕРЕНА: "
                   f"{reg.get('reason')}")
    else:
        out.append(
            f"[МНОГОЗНАЧНОСТЬ РЕЕСТРА] документов объявлено "
            f"{reg.get('documents_declared')} · измерено "
            f"{reg.get('documents_measured')} · НЕ ИЗМЕРЕНО "
            f"{reg.get('documents_unmeasured')} (причина названа у каждого) · "
            f"доля многозначных хвостов по нынешнему правилу: минимум "
            f"{reg.get('share_shallow_min_pct')} %, медиана "
            f"{reg.get('share_shallow_median_pct')} %, максимум "
            f"{reg.get('share_shallow_max_pct')} % · при развёртывании "
            f"списков медиана {reg.get('share_deep_median_pct')} %")
        out.append(
            f"[МНОГОЗНАЧНОСТЬ РЕЕСТРА · СОСЕД] `{reg.get('neighbour_census')}`, "
            f"на котором число снято циклом #674, даёт "
            f"{reg.get('neighbour_share_shallow_pct')} % и стои́т "
            f"{reg.get('neighbour_rank_by_share')}-м из "
            f"{reg.get('documents_measured')} — одно число, снятое у одного "
            f"документа, свойством реестра не является")
        totals = observed(reg, "cost_totals", kind=dict)
        out.append(
            f"[МНОГОЗНАЧНОСТЬ РЕЕСТРА · ОТВЕТ] вердикт "
            f"{reg.get('verdict')} · документов, у кого многозначность СТОИТ "
            f"решающему читателю: {reg.get('documents_costing_a_reader')} "
            + ("· учёт решающих чтений НЕ ИЗМЕРЕН" if totals is None else
               f"· решающих чтений: по однозначному хвосту "
               f"{totals.get(COST_TAIL_UNAMBIGUOUS)}, по многозначному с "
               f"РАЗОБРАННЫМ путём {totals.get(COST_PATH_RESOLVES)} (не "
               f"стоит), по многозначному с НЕразобранным путём "
               f"{totals.get(COST_DECIDES_AMBIGUOUS)} (СТОИТ), поле решения "
               f"не разобрано {totals.get(COST_FIELD_UNMEASURED)}"))
        # Инв. #17 и заказ G73 п. 3: подстановка `or []` на перечень здесь
        # ЗАПРЕЩЕНА. «Ключа нет» и «список пуст» суть разные утверждения, и
        # второе вместо первого молча превратило бы «строк не собрано» в
        # «стоящих читателю документов нет».
        all_rows = observed(reg, "rows", kind=list)
        if all_rows is None:
            out.append("[МНОГОЗНАЧНОСТЬ РЕЕСТРА · ЦЕНА] НЕ ИЗМЕРЕНА — строк "
                       "по документам в отчёте нет вовсе; это НЕ «цены нет»")
        else:
            costing = [r for r in all_rows if r.get("costs_a_reader")]
            for row in sorted(costing,
                              key=lambda r: -int(r.get("costed_touches") or 0)
                              )[:max_rows]:
                sample = observed(row, "costed_sample", kind=list)
                first = sample[0] if sample else {}
                out.append(
                    f"[МНОГОЗНАЧНОСТЬ РЕЕСТРА · ЦЕНА] {row.get('census')}: "
                    f"многозначных {row.get('ambiguous_shallow')} из "
                    f"{row.get('tails_shallow')} "
                    f"({row.get('ambiguous_share_shallow_pct')} %) · стоит "
                    f"{row.get('costed_touches')} решающим чтениям · напр. "
                    f"{first.get('file')}:{first.get('line')} поле "
                    f"`{first.get('field')}` → путей {first.get('paths')}")
        unmeasured_rows = observed(reg, "unmeasured", kind=list)
        if unmeasured_rows is None:
            out.append("[МНОГОЗНАЧНОСТЬ РЕЕСТРА · НЕ ИЗМЕРЕНО] перечня нет в "
                       "документе — это НЕ «все документы измерены»")
        else:
            for item in unmeasured_rows[:max_rows]:
                out.append(
                    f"[МНОГОЗНАЧНОСТЬ РЕЕСТРА · НЕ ИЗМЕРЕНО] "
                    f"{item.get('census')} ({item.get('outcome')}): "
                    f"{item.get('reason')}")
        control = observed(reg, "filter_control", kind=dict)
        if control is None:
            out.append("[МНОГОЗНАЧНОСТЬ РЕЕСТРА · КОНТРОЛЬ] НЕ ИЗМЕРЕН — "
                       "надмножественность пред-фильтра не проверена")
        else:
            out.append(
                f"[МНОГОЗНАЧНОСТЬ РЕЕСТРА · КОНТРОЛЬ] пред-фильтр против "
                f"полного обхода на `{control.get('census')}`: "
                f"{control.get('readers_filtered')} против "
                f"{control.get('readers_full_scan')} читателей, потеряно "
                f"{', '.join(control.get('lost_by_filter') or []) or '—'}")
        for blind in (observed(reg, "blind", kind=list) or []):
            out.append(f"[СЛЕПОТА] {blind}")
    div = observed(doc, "tail_value_divergence", kind=dict)
    if div is None:
        out.append("[РАСХОЖДЕНИЕ ЗНАЧЕНИЙ] НЕ ИЗМЕРЕНО — перепись собрана без "
                   "этого шага; это НЕ «значения совпадают» и НЕ «вреда нет»")
    elif str(div.get("status")) == "UNMEASURED":
        out.append(f"[РАСХОЖДЕНИЕ ЗНАЧЕНИЙ] НЕ ИЗМЕРЕНО: {div.get('reason')}")
    else:
        vals = observed(div, "value_counts", kind=dict)
        out.append(
            f"[РАСХОЖДЕНИЕ ЗНАЧЕНИЙ] вердикт {div.get('verdict')} · стоящих "
            f"решающих чтений {div.get('costed_total')} в "
            f"{div.get('documents_costing')} документ(ах) "
            + ("· учёт по исходам НЕ ИЗМЕРЕН" if vals is None else
               f"· значения РАСХОДЯТСЯ у {vals.get(VALUE_DIFFER)}, совпадают "
               f"у {vals.get(VALUE_AGREE)}, расходятся ТОЛЬКО текстом у "
               f"{vals.get(VALUE_TEXT_ONLY)} (напр. `5000000` против "
               f"`5000000.0` — разница печати, не значения), значение не "
               f"литерал у {vals.get(VALUE_OPAQUE)}"))
        out.append(
            f"[РАСХОЖДЕНИЕ ЗНАЧЕНИЙ · РОД] у {div.get('kinds_differ')} чтений "
            f"пути несут значения РАЗНОГО рода (число против перечня и т. п.) "
            f"— такой хвост не многозначен, а несогласован: правым не может "
            f"быть ни один читатель")
        reach = observed(div, "reach_counts", kind=dict)
        if reach is None:
            out.append("[РАСХОЖДЕНИЕ ЗНАЧЕНИЙ · ДОСТИЖИМОСТЬ] НЕ ИЗМЕРЕНА — "
                       "это НЕ «вердикт недостижим»")
        else:
            out.append(
                f"[РАСХОЖДЕНИЕ ЗНАЧЕНИЙ · ДОСТИЖИМОСТЬ] подстановка способна "
                f"дойти до вердикта у {reach.get(REACH_LIVE)} чтений; у "
                f"{reach.get(REACH_ISOLATED)} она не доходит ПО ПОСТРОЕНИЮ "
                f"(`{div.get('isolation_guard')}` уводит `SPA_DATA_DIR` "
                f"всякого теста без метки `{div.get('isolation_marker')}`); "
                f"вне тела теста {reach.get(REACH_NO_TEST)}; файл не разобран "
                f"{reach.get(REACH_FILE_UNPARSED)} — прогон подстановки дал бы "
                f"здесь ноль, и этот ноль был бы свойством ФИКСТУРЫ")
        sample = observed(div, "diverging_sample", kind=list)
        if sample is None:
            out.append("[РАСХОЖДЕНИЕ ЗНАЧЕНИЙ · ОБРАЗЕЦ] перечня нет в "
                       "документе — это НЕ «расхождений нет»")
        else:
            for item in sample[:max_rows]:
                out.append(
                    f"[РАСХОЖДЕНИЕ ЗНАЧЕНИЙ · ОБРАЗЕЦ] {item.get('census')}: "
                    f"{item.get('file')}:{item.get('line')} поле "
                    f"`{item.get('field')}` → путей {item.get('paths')}, "
                    f"различных значений {item.get('distinct_value')}, "
                    f"роды {'/'.join(item.get('kinds') or []) or '—'}, "
                    f"достижимость {item.get('reach')}")
        for blind in (observed(div, "blind", kind=list) or []):
            out.append(f"[СЛЕПОТА] {blind}")
    opened = observed(doc, "open_class_counter_census", kind=dict)
    if opened is None:
        out.append("[ОТКРЫТЫЙ СЧЁТЧИК] НЕ ИЗМЕРЕНО — перепись собрана без "
                   "этого шага; это НЕ «открытых счётчиков нет»")
    elif str(opened.get("status")) == "UNMEASURED":
        out.append(f"[ОТКРЫТЫЙ СЧЁТЧИК] НЕ ИЗМЕРЕНО "
                   f"[{opened.get('unmeasured_class')}]: {opened.get('reason')}")
    else:
        origins = observed(opened, "key_origin_counts", kind=dict)
        out.append(
            f"[ОТКРЫТЫЙ СЧЁТЧИК] вердикт {opened.get('verdict')} · счётчиков "
            f"{opened.get('counters_total')} в {opened.get('files_scanned')} "
            f"файл(ах) {', '.join(opened.get('dirs') or [])} "
            + ("· происхождение ключа НЕ ИЗМЕРЕНО" if origins is None else
               f"· ключ из артефакта у {origins.get(KEY_ARTIFACT)}, из "
               f"объявленного перечня у {origins.get(KEY_DECLARED)}, литерал "
               f"у {origins.get(KEY_LITERAL)}, НЕ РАЗОБРАН у "
               f"{origins.get(KEY_UNRESOLVED)}"))
        out.append(
            f"[ОТКРЫТЫЙ СЧЁТЧИК · СВЕРКА] из {opened.get('key_from_artifact')} "
            f"счётчиков с ключом из артефакта принадлежность проверена у "
            f"{opened.get('membership_checked')}; ОТКРЫТ ЛЮБОЙ СТРОКЕ "
            f"{opened.get('open_to_an_unnamed_class')}, из них через `str()` "
            f"поверх возможного отсутствия — {opened.get('open_via_str_over_absence')} "
            f"(известный случай ADR-459 был ОДНИМ из них)")
        out.append(
            f"[ОТКРЫТЫЙ СЧЁТЧИК · ТРЕТИЙ ИСХОД] происхождение ключа не "
            f"разобрано у {opened.get('key_unresolved')} счётчик(ов) — это НЕ "
            f"«ключ безопасен»; файлов не прочитано "
            f"{len(opened.get('files_unreadable') or [])}")
        control = observed(opened, "control", kind=dict) or {}
        out.append(
            f"[ОТКРЫТЫЙ СЧЁТЧИК · КОНТРОЛЬ] объявленное правило нашло "
            f"{control.get('known_case_open')} из 2 счётчиков ИЗВЕСТНОГО "
            f"случая и дало {control.get('clean_false_positives')} ложных на "
            f"отрицательной половине сцены — без обеих половин ноль был бы "
            f"свойством формы, а не населения")
        for item in (observed(opened, "open_sample", kind=list) or [])[:max_rows]:
            out.append(
                f"[ОТКРЫТЫЙ СЧЁТЧИК · ОБРАЗЕЦ] {item.get('file')}:"
                f"{item.get('line')} ({item.get('owner')}) "
                f"`{item.get('counter')}[{item.get('key')}]` форма "
                f"{item.get('form')}"
                + (" · ключ через `str()` поверх отсутствия"
                   if item.get("str_over_absence") else ""))
        for blind in (observed(opened, "blind", kind=list) or []):
            out.append(f"[СЛЕПОТА] {blind}")
    harm = observed(doc, "open_counter_reader_harm", kind=dict)
    if harm is None:
        out.append("[ЧИТАТЕЛЬ СЧЁТЧИКА] НЕ ИЗМЕРЕНО — перепись собрана без "
                   "этого шага; это НЕ «вредящих читателей нет»")
    elif str(harm.get("status")) == "UNMEASURED":
        out.append(f"[ЧИТАТЕЛЬ СЧЁТЧИКА] НЕ ИЗМЕРЕНО "
                   f"[{harm.get('unmeasured_class')}]: {harm.get('reason')}")
    else:
        verdicts = observed(harm, "reader_verdicts", kind=dict) or {}
        gaps = observed(harm, "unmeasured_reader_reasons", kind=dict) or {}
        forms = observed(harm, "split_by_form", kind=dict) or {}
        out.append(
            f"[ЧИТАТЕЛЬ СЧЁТЧИКА] из {harm.get('population')} открытых "
            f"счётчиков незнакомый класс молча становится ДРУГИМ ИСХОДОМ у "
            f"{verdicts.get(READER_SPLITS_DECLARED)}; лишней строкой отчёта — "
            f"у {verdicts.get(READER_WHOLESALE_ONLY)}; читатель НЕ ИЗМЕРЕН у "
            f"{verdicts.get(READER_UNRESOLVED)} "
            f"(убежал из области {gaps.get(READER_GAP_ESCAPES)}, ключ чтения "
            f"не разобран {gaps.get(READER_GAP_DYNAMIC)}, чтения нет вовсе "
            f"{gaps.get(READER_GAP_NO_READ)})")
        out.append(
            f"[ЧИТАТЕЛЬ СЧЁТЧИКА · ЧЕМ ДОКАЗАН] счётчик прочитан объявленным "
            f"ключом у {forms.get(SPLIT_AT_COUNTER)}, класс сравнён с "
            f"объявленным у {forms.get(SPLIT_AT_CLASS)}, класс уехал полем и "
            f"сравнён там у {forms.get(SPLIT_VIA_FIELD)} "
            f"(только полем — у {harm.get('splits_only_via_field')}: это "
            f"САМОЕ СЛАБОЕ звено доказательства, связь идёт по имени поля)")
        out.append(
            f"[ЧИТАТЕЛЬ СЧЁТЧИКА · ПОТОЛОК СВЕРХУ] население взято у соседа и "
            f"завышено: у {harm.get('census_key_literal_by_unpacking')} "
            f"счётчик(ов) ключ на деле ЛИТЕРАЛ, разобранный кортежем "
            f"(сосед связывает имя всей правой частью); из них с доказанным "
            f"расколом {harm.get('harm_on_a_key_that_is_a_literal')}, то есть "
            f"вред без них — {harm.get('harm_net_of_unpacking')}")
        control = observed(harm, "control", kind=dict) or {}
        out.append(
            f"[ЧИТАТЕЛЬ СЧЁТЧИКА · КОНТРОЛЬ] правило доказало раскол у "
            f"{control.get('known_case_split')} из 2 счётчиков ИЗВЕСТНОГО "
            f"случая всеми тремя формами и дало "
            f"{control.get('clean_false_harm')} ложных вреда на отрицательной "
            f"половине сцены")
        for item in (observed(harm, "harm_sample", kind=list) or [])[:max_rows]:
            out.append(
                f"[ЧИТАТЕЛЬ СЧЁТЧИКА · ОБРАЗЕЦ] {item.get('file')}:"
                f"{item.get('line')} ({item.get('owner')}) "
                f"`{item.get('counter')}[{item.get('key')}]` → раскол "
                f"`{item.get('split')}`")
        for blind in (observed(harm, "blind", kind=list) or []):
            out.append(f"[СЛЕПОТА] {blind}")
    step = observed(doc, "escaped_counter_one_step", kind=dict)
    if step is None:
        out.append("[ОДИН ШАГ] НЕ ИЗМЕРЕНО — перепись собрана без этого шага; "
                   "это НЕ «убежавших счётчиков нет»")
    elif str(step.get("status")) == "UNMEASURED":
        out.append(f"[ОДИН ШАГ] НЕ ИЗМЕРЕНО "
                   f"[{step.get('unmeasured_class')}]: {step.get('reason')}")
    else:
        outcomes = observed(step, "one_step_outcomes", kind=dict) or {}
        routes = observed(step, "routes", kind=dict) or {}
        reasons = observed(step, "unresolved_reasons", kind=dict) or {}
        out.append(
            f"[ОДИН ШАГ] из {step.get('population')} счётчиков, убежавших из "
            f"области, ОДИН шаг межпроцедурного разбора доводит до "
            f"расколотого читателя {outcomes.get(ONE_STEP_SPLITS)}, до "
            f"безвредного — {outcomes.get(ONE_STEP_WHOLESALE)}; остаётся "
            f"третьим исходом {step.get('still_unmeasured')}")
        out.append(
            f"[ОДИН ШАГ · МАРШРУТ] возвратом уходит "
            f"{routes.get(ROUTE_RETURNED)}, аргументом в функцию ЭТОГО файла "
            f"{routes.get(ROUTE_ARGUMENT_LOCAL)}, в чужой вызов "
            f"{routes.get(ROUTE_ARGUMENT_FOREIGN)}, сперва в КОНТЕЙНЕР "
            f"{routes.get(ROUTE_CONTAINER)}, не уходит вовсе "
            f"{routes.get(ROUTE_NOT_A_DEPARTURE)} — приём «счётчик возвращён, "
            f"читатель у зовущего» покрывает не всё население, и это замер, "
            f"а не оценка")
        out.append(
            f"[ОДИН ШАГ · ПОЧЕМУ НЕ ДОШЁЛ] уехал сперва полем "
            f"{reasons.get(STEP_GAP_CONTAINER)} · возврат никуда не связан "
            f"{reasons.get(STEP_GAP_RESULT_UNBOUND)} · зовущий читает "
            f"неразрешимым ключом {reasons.get(READER_GAP_DYNAMIC)} · убежал "
            f"СНОВА {reasons.get(STEP_GAP_ESCAPES_AGAIN)} · никуда не уехал "
            f"{reasons.get(STEP_GAP_NOT_A_DEPARTURE)} · маршрут не разобран "
            f"{reasons.get(STEP_GAP_ROUTE_UNKNOWN)}")
        out.append(
            f"[ОДИН ШАГ · ПОТОЛОК СОСЕДА] население 66 завышено СВЕРХУ на "
            f"{step.get('does_not_leave_the_scope_at_all')}: столько "
            f"счётчиков проверены на истинность или напечатаны целиком и НЕ "
            f"уезжают никуда — уезжающих на деле "
            f"{step.get('departing_population_net')}")
        out.append(
            f"[ОДИН ШАГ · ПРОВОДКА ЖИВА] до следующей области шаг дошёл и "
            f"разобрал там читателя у {step.get('next_scope_reached')} "
            f"счётчик(ов): ноль разрешённых — свойство НАСЕЛЕНИЯ, а не "
            f"непроведённого шага, и эти два нуля обязаны быть различимы")
        control = observed(step, "control", kind=dict) or {}
        out.append(
            f"[ОДИН ШАГ · КОНТРОЛЬ] правило разрешило "
            f"{control.get('known_case_resolved')} из 2 счётчиков "
            f"положительной сцены ОБЕИМИ формами побега "
            f"({len(control.get('routes') or [])} маршрут(а)) и дало "
            f"{control.get('clean_false_splits')} ложных расколов на "
            f"отрицательной, разведя её "
            f"{len(control.get('clean_refusal_names') or [])} РАЗНЫМИ "
            f"именами отказа")
        for item in (observed(step, "unresolved_sample", kind=list)
                     or [])[:max_rows]:
            out.append(
                f"[ОДИН ШАГ · ОБРАЗЕЦ] {item.get('file')}:{item.get('line')} "
                f"({item.get('owner')}) `{item.get('counter')}` — "
                f"{item.get('gap')}")
        for blind in (observed(step, "blind", kind=list) or []):
            out.append(f"[СЛЕПОТА] {blind}")
    field_step = observed(doc, "container_counter_field_step", kind=dict)
    if field_step is None:
        out.append("[ПОЛЕМ] НЕ ИЗМЕРЕНО — перепись собрана без этого шага; "
                   "это НЕ «счётчиков, уехавших контейнером, нет»")
    elif str(field_step.get("status")) == "UNMEASURED":
        out.append(f"[ПОЛЕМ] НЕ ИЗМЕРЕНО "
                   f"[{field_step.get('unmeasured_class')}]: "
                   f"{field_step.get('reason')}")
    else:
        outcomes = observed(field_step, "field_step_outcomes", kind=dict) or {}
        why = observed(field_step, "unresolved_reasons", kind=dict) or {}
        forms = observed(field_step, "forms", kind=dict) or {}
        out.append(
            f"[ПОЛЕМ] из {field_step.get('population')} счётчиков, уехавших "
            f"КОНТЕЙНЕРОМ, ОДИН шаг переноса полем доводит до расколотого "
            f"читателя {outcomes.get(ONE_STEP_SPLITS)}, до безвредного — "
            f"{outcomes.get(ONE_STEP_WHOLESALE)}; остаётся третьим исходом "
            f"{field_step.get('still_unmeasured')}")
        out.append(
            f"[ПОЛЕМ · ПОЧЕМУ НЕ ДОШЁЛ] контейнер без имени поля "
            f"{why.get(FIELD_GAP_NO_FIELD_NAME)} · имя поля неоднозначно "
            f"{why.get(FIELD_GAP_AMBIGUOUS_FIELD)} · контейнер не покидает "
            f"область {why.get(FIELD_GAP_CONTAINER_NOT_RETURNED)} · зовущего "
            f"нет в файле {why.get(STEP_GAP_NO_CALLER)} · результат никуда не "
            f"связан {why.get(STEP_GAP_RESULT_UNBOUND)} · зовущий не читает "
            f"ЭТО поле {why.get(FIELD_GAP_FIELD_NEVER_READ)} · поле прочитано "
            f"и уехало СНОВА {why.get(STEP_GAP_ESCAPES_AGAIN)}")
        out.append(
            f"[ПОЛЕМ · ФОРМА] словарь возвращён прямо "
            f"{forms.get(FIELD_FORM_DIRECT)} · словарь связан именем и "
            f"возвращён {forms.get(FIELD_FORM_BOUND)} · счётчик положен "
            f"подпиской в возвращаемое отображение "
            f"{forms.get(FIELD_FORM_SUBSCRIPT)} — приём соседа разбирает "
            f"только первые две, третья названа своим правилом")
        out.append(
            f"[ПОЛЕМ · ПРОВОДКА ЖИВА] до области зовущего шаг дошёл у "
            f"{field_step.get('next_scope_reached')} счётчик(ов), и у "
            f"{field_step.get('reader_parsed_at_next_scope')} разобрал там "
            f"ЧИТАТЕЛЯ: это два разных достижения, и складывать их в одно "
            f"значило бы выдать половину проводки за целую")
        control = observed(field_step, "control", kind=dict) or {}
        out.append(
            f"[ПОЛЕМ · КОНТРОЛЬ] правило разрешило "
            f"{control.get('known_case_resolved')} из {len(_FIELD_FORMS)} "
            f"счётчиков положительной сцены ВСЕМИ "
            f"{len(control.get('forms') or [])} формами переноса и дало "
            f"{control.get('clean_false_splits')} ложных расколов на "
            f"отрицательной, разведя её "
            f"{len(control.get('clean_refusal_names') or [])} РАЗНЫМИ "
            f"именами отказа")
        for item in (observed(field_step, "unresolved_sample", kind=list)
                     or [])[:max_rows]:
            out.append(
                f"[ПОЛЕМ · ОБРАЗЕЦ] {item.get('file')}:{item.get('line')} "
                f"({item.get('owner')}) `{item.get('counter')}` — "
                f"{item.get('gap')}")
        for blind in (observed(field_step, "blind", kind=list) or []):
            out.append(f"[СЛЕПОТА] {blind}")
    doc_step = observed(doc, "document_field_reader_in_file", kind=dict)
    if doc_step is None:
        out.append("[ПО ИМЕНИ ПОЛЯ] НЕ ИЗМЕРЕНО — перепись собрана без этого "
                   "шага; это НЕ «счётчиков, уехавших в документ, нет»")
    elif str(doc_step.get("status")) == "UNMEASURED":
        out.append(f"[ПО ИМЕНИ ПОЛЯ] НЕ ИЗМЕРЕНО "
                   f"[{doc_step.get('unmeasured_class')}]: "
                   f"{doc_step.get('reason')}")
    else:
        outcomes = observed(doc_step, "doc_step_outcomes", kind=dict) or {}
        why = observed(doc_step, "unresolved_reasons", kind=dict) or {}
        forms = observed(doc_step, "read_forms", kind=dict) or {}
        out.append(
            f"[ПО ИМЕНИ ПОЛЯ] из {doc_step.get('population')} счётчиков, "
            f"уехавших в ДОКУМЕНТ, разбор по имени поля через границу функции "
            f"доводит до расколотого читателя {outcomes.get(ONE_STEP_SPLITS)}, "
            f"до безвредного — {outcomes.get(ONE_STEP_WHOLESALE)}; остаётся "
            f"третьим исходом {doc_step.get('still_unmeasured')}")
        out.append(
            f"[ПО ИМЕНИ ПОЛЯ · ПОЧЕМУ НЕ ДОШЁЛ] имён поля больше одного "
            f"{why.get(DOC_GAP_MANY_FIELDS)} · ключ пишет больше одной "
            f"области {why.get(DOC_GAP_FIELD_WRITTEN_TWICE)} · ключа не "
            f"читает в файле никто {why.get(DOC_GAP_NO_READER_IN_FILE)} · "
            f"поле прочитано и уехало СНОВА "
            f"{why.get(STEP_GAP_ESCAPES_AGAIN)} · ключ чтения не разрешается "
            f"{why.get(READER_GAP_DYNAMIC)}")
        out.append(
            f"[ПО ИМЕНИ ПОЛЯ · ФОРМА ЧТЕНИЯ] подписка "
            f"{forms.get(DOC_READ_SUBSCRIPT)} · `.get` "
            f"{forms.get(DOC_READ_GET)} · объявленный читатель `"
            f"{DOC_READ_HELPER}` {forms.get(DOC_READ_OBSERVED)} — третья "
            f"форма найдена ЗАПУСКОМ и она здесь ГЛАВНАЯ: без неё 17 из "
            f"{doc_step.get('population')} получили бы отказ «поля не читает "
            f"никто», и среди них поимённо названный ADR-463 "
            f"`key_origin_counts`")
        out.append(
            f"[ПО ИМЕНИ ПОЛЯ · ПРОВОДКА ЖИВА] имя поля однозначно в файле у "
            f"{doc_step.get('field_name_unique_in_file')} счётчик(ов), и у "
            f"{doc_step.get('reader_of_that_field_found')} читатель этого "
            f"имени НАЙДЕН: это два разных достижения, и складывать их в одно "
            f"значило бы выдать половину проводки за целую")
        control = observed(doc_step, "control", kind=dict) or {}
        out.append(
            f"[ПО ИМЕНИ ПОЛЯ · КОНТРОЛЬ] правило разрешило "
            f"{control.get('known_case_resolved')} счётчик(ов) положительной "
            f"сцены ВСЕМИ {len(control.get('read_forms') or [])} формами "
            f"чтения и дало {control.get('clean_false_splits')} ложных "
            f"расколов на отрицательной, разведя её "
            f"{len(control.get('clean_refusal_names') or [])} РАЗНЫМИ именами "
            f"отказа — в том числе на счётчике с ГОТОВЫМ читателем, чьё имя "
            f"поля пишут две области")
        for item in (observed(doc_step, "harm_sample", kind=list)
                     or [])[:max_rows]:
            out.append(
                f"[ПО ИМЕНИ ПОЛЯ · РАСКОЛ] {item.get('file')}:"
                f"{item.get('line')} ({item.get('owner')}) "
                f"`{item.get('counter')}` поле `{item.get('field')}` — "
                f"{item.get('split')}")
        for blind in (observed(doc_step, "blind", kind=list) or []):
            out.append(f"[СЛЕПОТА] {blind}")
    surface = doc.get("renamed_copy_surface") or []
    out.append(
        f"[ГРАНИЦА ПРАВИЛА ИМЕНИ] сторожей, читающих состояние репозитория и не "
        f"упоминающих дерево-предмет ни разу: {len(surface)} — у них копия своя "
        f"ПО ПОСТРОЕНИЮ; это доказанный МИНИМУМ переименованных копий, не потолок"
        + (f"; напр. {', '.join(surface[:3])}" if surface else ""))
    out.append("НЕ ДОКЛАДЫВАЕТ: вредит ли найденная копия сегодня; общее ли "
               "происхождение у совпавшего значения; является ли "
               "`subject_unproven` совпадением — свидетель односторонний")
    return out


def format_report(doc: dict, *, max_rows: int = 5) -> List[str]:
    """Отрисовка для шага 0-офис. Второй копии правила отрисовки здесь НЕТ:
    ветка офиса делегирует сюда, а эта функция — в ``report``."""
    lines = report(doc, max_rows=max_rows)
    if str(doc.get("status")) == "FINDING":
        lines[0] = f"⚠️ {lines[0]}"
    return lines


def run(root: str | Path = _ROOT, *, dest: Optional[Path] = None,
        data_dir: Optional[Path] = None, write: bool = True,
        now: Optional[dt.datetime] = None) -> dict:
    """Один прогон переписи для ступени моста.

    **Гейта такта здесь нет, и это замер, а не поблажка.** Зов есть разбор AST
    в одном процессе; цена названа в ADR-417. Недельный такт не купил бы
    ничего, а завёл бы ровно ту вторую копию правила о сроке, которую сосед
    (`tact_gate_census`) и ищет.
    """
    root = Path(root)
    target = (Path(dest) if dest is not None
              else (Path(data_dir) if data_dir is not None else root / "data") / ARTIFACT)
    try:
        # Журнал зонда лежит В ДЕРЕВЕ (рядом с кодом), а не в `data/`: он
        # есть замер исходников, и `data_dir` его не касается.
        doc = measure(root, now=now, probe_ledger=root / PROBE_LEDGER,
                      data_dir=(Path(data_dir) if data_dir is not None
                                else root / "data"))
    except NotMeasured as exc:
        doc = {
            "generated_at": (now or _utcnow()).isoformat(),
            "generated_by": PRODUCER,
            "invoked_by": call_provenance(tree_root=root),
            "status": "UNMEASURED",
            "reason": str(exc),
        }
    if write:
        atomic_save(doc, str(target))
    return {"measured": doc.get("status") != "UNMEASURED", "doc": doc,
            "artifact": str(target)}


def main(argv: Optional[List[str]] = None) -> int:
    ap = argparse.ArgumentParser(
        description="перепись «одно правило — две копии»: исполнитель против сторожа (G41 п. 1)")
    ap.add_argument("--root", default=str(_ROOT))
    ap.add_argument("--out", default=None)
    ap.add_argument("--no-write", action="store_true")
    args = ap.parse_args(argv)

    outcome = run(Path(args.root),
                  dest=Path(args.out) if args.out else None,
                  write=not args.no_write)
    doc = outcome["doc"]
    for line in report(doc):
        print(line)
    return {"UNMEASURED": 2, "FINDING": 1}.get(str(doc.get("status")), 0)


if __name__ == "__main__":
    raise SystemExit(main())
